import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import compression from 'compression';
import morgan from 'morgan';
import dotenv from 'dotenv';
import rateLimit from 'express-rate-limit';

import { PrismaClient } from '@prisma/client';
import authRoutes from './routes/auth.routes.js';
import shopRoutes from './routes/shop.routes.js';
import customerRoutes from './routes/customer.routes.js';
import orderRoutes from './routes/order.routes.js';
import fileRoutes from './routes/file.routes.js';
import printerRoutes from './routes/printer.routes.js';
import pricingRoutes from './routes/pricing.routes.js';
import paymentRoutes from './routes/payment.routes.js';
import adminRoutes from './routes/admin.routes.js';
import agentRoutes from './routes/agent.routes.js';
import { errorHandler } from './middleware/errorHandler.js';
import { logger } from './utils/logger.js';

dotenv.config();

export const prisma = new PrismaClient({
  log: process.env.NODE_ENV === 'development' ? ['query', 'error', 'warn'] : ['error'],
});

const app = express();
const PORT = process.env.PORT || 5000;

// Security
app.use(helmet());
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:5173',
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
});
app.use('/api/', limiter);

// Body parsing
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

// Compression
app.use(compression());

// Logging
app.use(morgan('combined', {
  stream: { write: (message) => logger.info(message.trim()) },
}));

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// API Routes
app.use('/api/v1/auth', authRoutes);
app.use('/api/v1/shops', shopRoutes);
app.use('/api/v1/customers', customerRoutes);
app.use('/api/v1/orders', orderRoutes);
app.use('/api/v1/files', fileRoutes);
app.use('/api/v1/printers', printerRoutes);
app.use('/api/v1/pricing', pricingRoutes);
app.use('/api/v1/payments', paymentRoutes);
app.use('/api/v1/admin', adminRoutes);
app.use('/api/v1/agent', agentRoutes);

// Error handling
app.use(errorHandler);

// Start server
const start = async () => {
  try {
    await prisma.$connect();
    logger.info('Database connected successfully');

    app.listen(PORT, () => {
      logger.info(`Server running on port ${PORT}`);
      console.log(`Server running on http://localhost:${PORT}`);
    });
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
};

start();

// Graceful shutdown
process.on('SIGINT', async () => {
  await prisma.$disconnect();
  process.exit(0);
});

export default app;

import winston from 'winston';

const { combine, timestamp, printf, colorize, errors } = winston.format;

const logFormat = printf(({ level, message, timestamp, stack }) => {
  return `${timestamp} [${level}]: ${stack || message}`;
});

export const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'development' ? 'debug' : 'info',
  format: combine(
    timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    errors({ stack: true }),
    logFormat
  ),
  transports: [
    new winston.transports.Console({
      format: combine(colorize(), logFormat),
    }),
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

import { logger } from '../utils/logger.js';

export class AppError extends Error {
  constructor(message, statusCode, code) {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = true;
  }
}

export const errorHandler = (err, req, res, next) => {
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      success: false,
      message: err.message,
      code: err.code,
    });
  }

  logger.error('Unexpected error:', err);

  return res.status(500).json({
    success: false,
    message: 'Internal server error',
    code: 'INTERNAL_ERROR',
  });
};

export const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

import jwt from 'jsonwebtoken';
import { prisma } from '../server.js';
import { AppError } from './errorHandler.js';

export const authenticate = async (req, res, next) => {
  try {
    const token = req.headers.authorization?.replace('Bearer ', '');

    if (!token) {
      throw new AppError('Authentication required', 401, 'AUTH_REQUIRED');
    }

    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    const user = await prisma.user.findUnique({
      where: { id: decoded.userId },
      select: { id: true, email: true, name: true, role: true, shopId: true, status: true },
    });

    if (!user || user.status !== 'ACTIVE') {
      throw new AppError('Invalid or expired token', 401, 'INVALID_TOKEN');
    }

    req.user = user;
    req.shopId = user.shopId;
    next();
  } catch (error) {
    if (error instanceof AppError) {
      return next(error);
    }
    next(new AppError('Invalid token', 401, 'INVALID_TOKEN'));
  }
};

export const authorize = (...roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      return next(new AppError('Insufficient permissions', 403, 'FORBIDDEN'));
    }
    next();
  };
};

export const shopAccess = async (req, res, next) => {
  try {
    const shopId = req.params.shopId || req.body.shopId || req.query.shopId;

    if (shopId && shopId !== req.shopId) {
      throw new AppError('Access denied to this shop', 403, 'SHOP_ACCESS_DENIED');
    }

    next();
  } catch (error) {
    next(error);
  }
};

import { body, param, query, validationResult } from 'express-validator';
import { AppError } from './errorHandler.js';

export const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const messages = errors.array().map((e) => e.msg);
    return next(new AppError(messages.join(', '), 400, 'VALIDATION_ERROR'));
  }
  next();
};

export const authValidation = {
  register: [
    body('shopName').trim().notEmpty().withMessage('Shop name is required'),
    body('ownerName').trim().notEmpty().withMessage('Owner name is required'),
    body('email').isEmail().withMessage('Valid email is required'),
    body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
    body('mobileNumber').optional().isMobilePhone('any').withMessage('Invalid mobile number'),
    validate,
  ],
  login: [
    body('email').isEmail().withMessage('Valid email is required'),
    body('password').notEmpty().withMessage('Password is required'),
    validate,
  ],
};

export const orderValidation = {
  create: [
    body('customerId').optional().isUUID().withMessage('Invalid customer ID'),
    body('customerName').optional().trim().notEmpty(),
    body('customerMobile').optional().isMobilePhone('any'),
    validate,
  ],
  updateSettings: [
    param('id').isUUID().withMessage('Invalid order ID'),
    body('files').isArray().withMessage('Files array is required'),
    validate,
  ],
  approve: [
    param('id').isUUID().withMessage('Invalid order ID'),
    body('printerId').optional().isUUID().withMessage('Invalid printer ID'),
    validate,
  ],
};

export const printerValidation = {
  create: [
    body('name').trim().notEmpty().withMessage('Printer name is required'),
    body('category').isIn(['BW_LASER', 'COLOR_LASER', 'INKJET', 'PHOTO', 'LARGE_FORMAT']),
    body('supportedPaperSizes').isArray().withMessage('Supported paper sizes required'),
    validate,
  ],
};

export const pricingValidation = {
  create: [
    body('paperSize').isIn(['A4', 'A3', 'LEGAL', 'LETTER', 'CUSTOM']),
    body('colorMode').isIn(['BLACK_WHITE', 'COLOR']),
    body('duplex').isIn(['SINGLE', 'DUPLEX']),
    body('perSheetPrice').isFloat({ min: 0 }).withMessage('Price must be positive'),
    validate,
  ],
};

export const paginationValidation = [
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be 1-100'),
  validate,
];

import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { prisma } from '../server.js';
import { AppError } from '../middleware/errorHandler.js';

const generateToken = (userId, expiresIn = process.env.JWT_EXPIRES_IN || '7d') => {
  return jwt.sign({ userId }, process.env.JWT_SECRET, { expiresIn });
};

const generateRefreshToken = (userId) => {
  return jwt.sign({ userId }, process.env.JWT_SECRET, {
    expiresIn: process.env.JWT_REFRESH_EXPIRES_IN || '30d',
  });
};

export const authService = {
  async register(data) {
    const existingUser = await prisma.user.findUnique({
      where: { email: data.email },
    });

    if (existingUser) {
      throw new AppError('Email already registered', 400, 'EMAIL_EXISTS');
    }

    const passwordHash = await bcrypt.hash(data.password, 12);

    const shop = await prisma.shop.create({
      data: {
        name: data.shopName,
        ownerName: data.ownerName,
        slug: data.shopName.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, ''),
        email: data.email,
        contactNumber: data.mobileNumber,
        users: {
          create: {
            name: data.ownerName,
            email: data.email,
            mobileNumber: data.mobileNumber,
            passwordHash,
            role: 'SHOP_OWNER',
          },
        },
        branding: {
          create: {},
        },
      },
      include: { users: true },
    });

    const user = shop.users[0];
    const token = generateToken(user.id);
    const refreshToken = generateRefreshToken(user.id);

    return {
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
        shopId: shop.id,
        shopName: shop.name,
      },
      token,
      refreshToken,
    };
  },

  async login(data) {
    const user = await prisma.user.findUnique({
      where: { email: data.email },
      include: { shop: { select: { id: true, name: true, status: true } } },
    });

    if (!user) {
      throw new AppError('Invalid email or password', 401, 'INVALID_CREDENTIALS');
    }

    if (user.status !== 'ACTIVE') {
      throw new AppError('Account is disabled', 403, 'ACCOUNT_DISABLED');
    }

    if (user.shop.status !== 'ACTIVE' && user.shop.status !== 'TRIAL') {
      throw new AppError('Shop is suspended', 403, 'SHOP_SUSPENDED');
    }

    const isPasswordValid = await bcrypt.compare(data.password, user.passwordHash);
    if (!isPasswordValid) {
      throw new AppError('Invalid email or password', 401, 'INVALID_CREDENTIALS');
    }

    await prisma.user.update({
      where: { id: user.id },
      data: { lastLogin: new Date() },
    });

    const token = generateToken(user.id);
    const refreshToken = generateRefreshToken(user.id);

    return {
      user: {
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role,
        shopId: user.shop.id,
        shopName: user.shop.name,
      },
      token,
      refreshToken,
    };
  },

  async getProfile(userId) {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        name: true,
        email: true,
        mobileNumber: true,
        role: true,
        lastLogin: true,
        shop: {
          select: {
            id: true,
            name: true,
            slug: true,
            logo: true,
            subscription: true,
          },
        },
      },
    });

    if (!user) {
      throw new AppError('User not found', 404, 'USER_NOT_FOUND');
    }

    return user;
  },
};

import { prisma } from '../server.js';
import { AppError } from '../middleware/errorHandler.js';
import { logger } from '../utils/logger.js';

const generateOrderNumber = async (shopId) => {
  const today = new Date();
  const dateStr = today.toISOString().slice(0, 10).replace(/-/g, '');

  const count = await prisma.order.count({
    where: {
      shopId,
      createdAt: {
        gte: new Date(today.getFullYear(), today.getMonth(), today.getDate()),
      },
    },
  });

  return `PX${dateStr}${String(count + 1).padStart(4, '0')}`;
};

export const orderService = {
  async createOrder(shopId, customerId, data) {
    const publicOrderNumber = await generateOrderNumber(shopId);

    const order = await prisma.order.create({
      data: {
        publicOrderNumber,
        shopId,
        customerId: customerId || null,
        status: 'UPLOADED',
        paymentStatus: 'UNPAID',
      },
    });

    logger.info(`Order created: ${publicOrderNumber} for shop ${shopId}`);
    return order;
  },

  async getOrder(orderId, shopId) {
    const order = await prisma.order.findFirst({
      where: { id: orderId, shopId },
      include: {
        customer: true,
        files: {
          include: {
            printInstructions: true,
            analysisResult: true,
          },
        },
        payments: true,
        priceSnapshot: true,
        operator: {
          select: { id: true, name: true, email: true },
        },
      },
    });

    if (!order) {
      throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    return order;
  },

  async getOrderByPublicNumber(publicOrderNumber, shopId) {
    const order = await prisma.order.findFirst({
      where: { publicOrderNumber, shopId },
      include: {
        customer: true,
        files: {
          include: {
            printInstructions: true,
          },
        },
        payments: true,
        priceSnapshot: true,
      },
    });

    if (!order) {
      throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    return order;
  },

  async updateOrderStatus(orderId, shopId, status, userId = null) {
    const order = await prisma.order.findFirst({
      where: { id: orderId, shopId },
    });

    if (!order) {
      throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    const updateData = { status };

    if (status === 'APPROVED') {
      updateData.approvedAt = new Date();
      updateData.operatorId = userId;
    } else if (status === 'PRINTING') {
      updateData.printingAt = new Date();
    } else if (status === 'COMPLETED') {
      updateData.completedAt = new Date();
    } else if (status === 'CANCELLED') {
      updateData.cancelledAt = new Date();
    }

    const updated = await prisma.order.update({
      where: { id: orderId },
      data: updateData,
    });

    logger.info(`Order ${order.publicOrderNumber} status changed to ${status}`);
    return updated;
  },

  async getOrderQueue(shopId, filters = {}) {
    const where = { shopId };

    if (filters.status) {
      where.status = filters.status;
    }

    if (filters.paymentStatus) {
      where.paymentStatus = filters.paymentStatus;
    }

    if (filters.dateFrom || filters.dateTo) {
      where.createdAt = {};
      if (filters.dateFrom) where.createdAt.gte = new Date(filters.dateFrom);
      if (filters.dateTo) where.createdAt.lte = new Date(filters.dateTo);
    }

    if (filters.search) {
      where.OR = [
        { publicOrderNumber: { contains: filters.search, mode: 'insensitive' } },
        { customer: { name: { contains: filters.search, mode: 'insensitive' } } },
        { customer: { mobileNumber: { contains: filters.search } } },
      ];
    }

    const page = parseInt(filters.page) || 1;
    const limit = parseInt(filters.limit) || 20;
    const skip = (page - 1) * limit;

    const [orders, total] = await Promise.all([
      prisma.order.findMany({
        where,
        include: {
          customer: {
            select: { id: true, name: true, mobileNumber: true },
          },
          files: {
            select: { id: true, fileName: true, pageCount: true },
          },
          priceSnapshot: {
            select: { finalTotal: true },
          },
        },
        orderBy: { createdAt: 'desc' },
        skip,
        take: limit,
      }),
      prisma.order.count({ where }),
    ]);

    return {
      orders,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
      },
    };
  },

  async searchOrders(shopId, query) {
    return prisma.order.findMany({
      where: {
        shopId,
        OR: [
          { publicOrderNumber: { contains: query, mode: 'insensitive' } },
          { customer: { name: { contains: query, mode: 'insensitive' } } },
          { customer: { mobileNumber: { contains: query } } },
          { files: { some: { fileName: { contains: query, mode: 'insensitive' } } } },
        ],
      },
      include: {
        customer: {
          select: { id: true, name: true, mobileNumber: true },
        },
        files: {
          select: { id: true, fileName: true, pageCount: true },
        },
      },
      orderBy: { createdAt: 'desc' },
      take: 20,
    });
  },

  async getDashboardStats(shopId) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const [
      todayOrders,
      todayRevenue,
      waitingApproval,
      printingNow,
      completedToday,
      failedToday,
    ] = await Promise.all([
      prisma.order.count({
        where: { shopId, createdAt: { gte: today } },
      }),
      prisma.order.aggregate({
        where: {
          shopId,
          createdAt: { gte: today },
          paymentStatus: 'PAID',
        },
        _sum: { totalAmount: true },
      }),
      prisma.order.count({
        where: { shopId, status: 'WAITING_APPROVAL' },
      }),
      prisma.order.count({
        where: { shopId, status: 'PRINTING' },
      }),
      prisma.order.count({
        where: {
          shopId,
          status: 'COMPLETED',
          completedAt: { gte: today },
        },
      }),
      prisma.order.count({
        where: { shopId, status: 'FAILED' },
      }),
    ]);

    return {
      todayOrders,
      todayRevenue: todayRevenue._sum.totalAmount || 0,
      waitingApproval,
      printingNow,
      completedToday,
      failedToday,
    };
  },
};

import fs from 'fs/promises';
import path from 'path';
import { v4 as uuidv4 } from 'uuid';
import { prisma } from '../server.js';
import { AppError } from '../middleware/errorHandler.js';
import { logger } from '../utils/logger.js';

const UPLOAD_DIR = process.env.UPLOAD_DIR || './uploads';
const MAX_FILE_SIZE = parseInt(process.env.MAX_FILE_SIZE) || 104857600;

const getShopUploadDir = (shopId, orderId) => {
  return path.join(UPLOAD_DIR, 'shops', shopId, 'orders', orderId);
};

export const fileService = {
  async uploadFile(orderId, shopId, file) {
    const order = await prisma.order.findFirst({
      where: { id: orderId, shopId },
    });

    if (!order) {
      throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    if (file.size > MAX_FILE_SIZE) {
      throw new AppError('File size exceeds limit', 400, 'FILE_TOO_LARGE');
    }

    const allowedTypes = [
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-powerpoint',
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'image/jpeg',
      'image/png',
      'image/webp',
    ];

    if (!allowedTypes.includes(file.mimetype)) {
      throw new AppError('Unsupported file type', 400, 'UNSUPPORTED_FILE_TYPE');
    }

    const fileId = uuidv4();
    const uploadDir = getShopUploadDir(shopId, orderId);
    const originalDir = path.join(uploadDir, 'original');

    await fs.mkdir(originalDir, { recursive: true });

    const ext = path.extname(file.originalname);
    const fileName = `${fileId}${ext}`;
    const filePath = path.join(originalDir, fileName);

    await fs.writeFile(filePath, file.buffer);

    const orderFile = await prisma.orderFile.create({
      data: {
        orderId,
        fileName: file.originalname,
        fileType: ext.replace('.', '').toUpperCase(),
        originalPath: filePath,
        fileSize: file.size,
        pageCount: 0,
      },
    });

    logger.info(`File uploaded: ${file.originalname} for order ${order.publicOrderNumber}`);

    return orderFile;
  },

  async analyzeFile(fileId) {
    const file = await prisma.orderFile.findUnique({
      where: { id: fileId },
    });

    if (!file) {
      throw new AppError('File not found', 404, 'FILE_NOT_FOUND');
    }

    let analysis = {
      pageCount: 0,
      paperSize: 'A4',
      portraitPages: 0,
      landscapePages: 0,
      colorPageCount: 0,
      blankPageCount: 0,
      imageResolution: null,
      unsupportedFonts: [],
      isPasswordProtected: false,
      isCorrupted: false,
    };

    try {
      if (file.fileType === 'PDF') {
        analysis = await this.analyzePdf(file.originalPath);
      } else if (['DOC', 'DOCX', 'PPT', 'PPTX', 'XLS', 'XLSX'].includes(file.fileType)) {
        analysis = await this.analyzeOfficeDocument(file.originalPath, file.fileType);
      } else if (['JPG', 'JPEG', 'PNG', 'WEBP'].includes(file.fileType)) {
        analysis = await this.analyzeImage(file.originalPath);
      }
    } catch (error) {
      logger.error(`Analysis failed for file ${fileId}:`, error);
      analysis.isCorrupted = true;
    }

    const fileAnalysis = await prisma.fileAnalysis.create({
      data: {
        orderFileId: fileId,
        ...analysis,
      },
    });

    await prisma.orderFile.update({
      where: { id: fileId },
      data: {
        pageCount: analysis.pageCount,
        portraitPages: analysis.portraitPages,
        landscapePages: analysis.landscapePages,
        colorPageCount: analysis.colorPageCount,
        blankPageCount: analysis.blankPageCount,
        isPasswordProtected: analysis.isPasswordProtected,
        isCorrupted: analysis.isCorrupted,
      },
    });

    return fileAnalysis;
  },

  async analyzePdf(filePath) {
    const pdfBuffer = await fs.readFile(filePath);
    const pdfjsLib = await import('pdfjs-dist/legacy/build/pdf.js');

    const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(pdfBuffer) });
    const pdfDoc = await loadingTask.promise;
    const numPages = pdfDoc.numPages;

    let portraitPages = 0;
    let landscapePages = 0;
    let colorPageCount = 0;
    let blankPageCount = 0;

    for (let i = 1; i <= numPages; i++) {
      const page = await pdfDoc.getPage(i);
      const viewport = page.getViewport({ scale: 1.0 });

      if (viewport.width > viewport.height) {
        landscapePages++;
      } else {
        portraitPages++;
      }

      try {
        const textContent = await page.getTextContent();
        if (textContent.items.length === 0) {
          blankPageCount++;
        }
      } catch {
        blankPageCount++;
      }
    }

    return {
      pageCount: numPages,
      paperSize: 'A4',
      portraitPages,
      landscapePages,
      colorPageCount,
      blankPageCount,
      imageResolution: null,
      unsupportedFonts: [],
      isPasswordProtected: false,
      isCorrupted: false,
    };
  },

  async analyzeOfficeDocument(filePath, fileType) {
    // Office documents will be converted to PDF first for analysis
    // This is a placeholder - actual conversion uses LibreOffice
    return {
      pageCount: 1,
      paperSize: 'A4',
      portraitPages: 1,
      landscapePages: 0,
      colorPageCount: 0,
      blankPageCount: 0,
      imageResolution: null,
      unsupportedFonts: [],
      isPasswordProtected: false,
      isCorrupted: false,
    };
  },

  async analyzeImage(filePath) {
    const sharp = (await import('sharp')).default;
    const metadata = await sharp(filePath).metadata();

    return {
      pageCount: 1,
      paperSize: 'A4',
      portraitPages: metadata.height > metadata.width ? 1 : 0,
      landscapePages: metadata.width >= metadata.height ? 1 : 0,
      colorPageCount: metadata.channels > 1 ? 1 : 0,
      blankPageCount: 0,
      imageResolution: {
        width: metadata.width,
        height: metadata.height,
        density: metadata.density,
      },
      unsupportedFonts: [],
      isPasswordProtected: false,
      isCorrupted: false,
    };
  },

  async deleteFile(fileId, shopId) {
    const file = await prisma.orderFile.findFirst({
      where: { id: fileId },
      include: { order: { select: { shopId: true } } },
    });

    if (!file || file.order.shopId !== shopId) {
      throw new AppError('File not found', 404, 'FILE_NOT_FOUND');
    }

    // Soft delete - keep file on disk for recovery
    await prisma.orderFile.delete({ where: { id: fileId } });

    logger.info(`File deleted: ${file.fileName}`);
    return { success: true };
  },

  async getFilesByOrder(orderId, shopId) {
    const order = await prisma.order.findFirst({
      where: { id: orderId, shopId },
    });

    if (!order) {
      throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    return prisma.orderFile.findMany({
      where: { orderId },
      include: {
        printInstructions: true,
        analysisResult: true,
      },
    });
  },
};

import { prisma } from '../server.js';
import { AppError } from '../middleware/errorHandler.js';

export const pricingService = {
  async calculatePrice(shopId, printInstructions) {
    const rules = await prisma.pricingRule.findMany({
      where: { shopId, isActive: true },
    });

    let subtotal = 0;
    const breakdown = [];

    for (const instruction of printInstructions) {
      const sheetCount = this.calculateSheetCount(instruction);
      const rule = this.findMatchingRule(rules, instruction);

      if (!rule) {
        throw new AppError(
          `No pricing rule found for ${instruction.paperSize} ${instruction.colorMode} ${instruction.duplex}`,
          400,
          'PRICING_RULE_MISSING'
        );
      }

      const unitPrice = rule.perSheetPrice;
      const lineTotal = sheetCount * unitPrice * instruction.copies;

      subtotal += lineTotal;
      breakdown.push({
        instructionId: instruction.id,
        paperSize: instruction.paperSize,
        colorMode: instruction.colorMode,
        duplex: instruction.duplex,
        sheetCount,
        copies: instruction.copies,
        unitPrice,
        lineTotal,
      });
    }

    return {
      subtotal,
      totalDiscount: 0,
      totalTax: 0,
      finalTotal: subtotal,
      breakdown,
    };
  },

  calculateSheetCount(instruction) {
    const pageCount = this.getPageCountFromRange(instruction.pageRange);
    const pagesPerSheet = instruction.nUpLayout || 1;

    let sheets = Math.ceil(pageCount / pagesPerSheet);

    if (instruction.duplex === 'DUPLEX') {
      sheets = Math.ceil(sheets / 2);
    }

    return sheets;
  },

  getPageCountFromRange(pageRange) {
    if (!pageRange || pageRange === 'all') return 100; // Default, should be actual count

    let count = 0;
    const parts = pageRange.split(',');

    for (const part of parts) {
      if (part.includes('-')) {
        const [start, end] = part.split('-').map(Number);
        count += end - start + 1;
      } else {
        count += 1;
      }
    }

    return count;
  },

  findMatchingRule(rules, instruction) {
    return rules.find(
      (rule) =>
        rule.paperSize === instruction.paperSize &&
        rule.colorMode === instruction.colorMode &&
        rule.duplex === instruction.duplex
    );
  },

  async getShopPricing(shopId) {
    return prisma.pricingRule.findMany({
      where: { shopId },
      orderBy: [{ paperSize: 'asc' }, { colorMode: 'asc' }, { duplex: 'asc' }],
    });
  },

  async createPricingRule(shopId, data) {
    const existing = await prisma.pricingRule.findFirst({
      where: {
        shopId,
        paperSize: data.paperSize,
        colorMode: data.colorMode,
        duplex: data.duplex,
      },
    });

    if (existing) {
      throw new AppError('Pricing rule already exists for this combination', 400, 'RULE_EXISTS');
    }

    return prisma.pricingRule.create({
      data: {
        shopId,
        paperSize: data.paperSize,
        colorMode: data.colorMode,
        duplex: data.duplex,
        perSheetPrice: data.perSheetPrice,
        perPagePrice: data.perPagePrice,
        minimumCharge: data.minimumCharge || 0,
      },
    });
  },

  async updatePricingRule(ruleId, shopId, data) {
    const rule = await prisma.pricingRule.findFirst({
      where: { id: ruleId, shopId },
    });

    if (!rule) {
      throw new AppError('Pricing rule not found', 404, 'RULE_NOT_FOUND');
    }

    return prisma.pricingRule.update({
      where: { id: ruleId },
      data: {
        perSheetPrice: data.perSheetPrice ?? rule.perSheetPrice,
        perPagePrice: data.perPagePrice ?? rule.perPagePrice,
        minimumCharge: data.minimumCharge ?? rule.minimumCharge,
        isActive: data.isActive ?? rule.isActive,
      },
    });
  },

  async deletePricingRule(ruleId, shopId) {
    const rule = await prisma.pricingRule.findFirst({
      where: { id: ruleId, shopId },
    });

    if (!rule) {
      throw new AppError('Pricing rule not found', 404, 'RULE_NOT_FOUND');
    }

    await prisma.pricingRule.delete({ where: { id: ruleId } });
    return { success: true };
  },

  async savePriceSnapshot(orderId, pricing) {
    return prisma.priceSnapshot.create({
      data: {
        orderId,
        unitPrices: pricing.breakdown,
        subtotal: pricing.subtotal,
        totalDiscount: pricing.totalDiscount,
        totalTax: pricing.totalTax,
        finalTotal: pricing.finalTotal,
      },
    });
  },

  async estimateCompletionTime(shopId, orderData) {
    const activeOrders = await prisma.order.count({
      where: {
        shopId,
        status: { in: ['WAITING_APPROVAL', 'PRINTING'] },
      },
    });

    const totalPages = orderData.files?.reduce((sum, f) => sum + (f.pageCount || 0), 0) || 0;
    const estimatedMinutes = Math.ceil(activeOrders * 2 + totalPages * 0.05);

    return {
      estimatedMinutes: Math.max(estimatedMinutes, 5),
      queuePosition: activeOrders + 1,
    };
  },
};

import { prisma } from '../server.js';
import { AppError } from '../middleware/errorHandler.js';
import { logger } from '../utils/logger.js';

export const printerService = {
  async getPrinters(shopId) {
    return prisma.printer.findMany({
      where: { shopId },
      include: {
        agent: {
          select: { id: true, deviceName: true, status: true },
        },
      },
      orderBy: { priority: 'desc' },
    });
  },

  async createPrinter(shopId, data) {
    return prisma.printer.create({
      data: {
        shopId,
        name: data.name,
        displayName: data.displayName || data.name,
        category: data.category,
        supportedPaperSizes: data.supportedPaperSizes || ['A4'],
        duplexSupport: data.duplexSupport || false,
        isDefault: data.isDefault || false,
        priority: data.priority || 0,
        agentId: data.agentId,
      },
    });
  },

  async updatePrinter(printerId, shopId, data) {
    const printer = await prisma.printer.findFirst({
      where: { id: printerId, shopId },
    });

    if (!printer) {
      throw new AppError('Printer not found', 404, 'PRINTER_NOT_FOUND');
    }

    return prisma.printer.update({
      where: { id: printerId },
      data: {
        name: data.name ?? printer.name,
        displayName: data.displayName ?? printer.displayName,
        category: data.category ?? printer.category,
        supportedPaperSizes: data.supportedPaperSizes ?? printer.supportedPaperSizes,
        duplexSupport: data.duplexSupport ?? printer.duplexSupport,
        isDefault: data.isDefault ?? printer.isDefault,
        priority: data.priority ?? printer.priority,
        status: data.status ?? printer.status,
      },
    });
  },

  async deletePrinter(printerId, shopId) {
    const printer = await prisma.printer.findFirst({
      where: { id: printerId, shopId },
    });

    if (!printer) {
      throw new AppError('Printer not found', 404, 'PRINTER_NOT_FOUND');
    }

    const activeJobs = await prisma.printJob.count({
      where: {
        printerId,
        status: { in: ['WAITING', 'DOWNLOADING', 'PREPARING', 'PRINTING'] },
      },
    });

    if (activeJobs > 0) {
      throw new AppError('Cannot delete printer with active jobs', 400, 'PRINTER_BUSY');
    }

    await prisma.printer.delete({ where: { id: printerId } });
    return { success: true };
  },

  async recommendPrinter(shopId, printInstruction) {
    const printers = await prisma.printer.findMany({
      where: {
        shopId,
        status: 'ONLINE',
      },
      include: {
        _count: {
          select: {
            printJobs: {
              where: {
                status: { in: ['WAITING', 'DOWNLOADING', 'PREPARING', 'PRINTING'] },
              },
            },
          },
        },
      },
    });

    if (printers.length === 0) {
      throw new AppError('No online printers available', 400, 'NO_PRINTERS');
    }

    const scored = printers.map((printer) => {
      let score = 0;

      // Paper size support
      if (printer.supportedPaperSizes.includes(printInstruction.paperSize)) {
        score += 30;
      }

      // Duplex support
      if (printInstruction.duplex === 'DUPLEX' && printer.duplexSupport) {
        score += 20;
      }

      // Category match
      if (printInstruction.colorMode === 'COLOR' && printer.category === 'COLOR_LASER') {
        score += 25;
      } else if (printInstruction.colorMode === 'BLACK_WHITE' && printer.category === 'BW_LASER') {
        score += 25;
      }

      // Queue length (fewer is better)
      score -= printer._count.printJobs * 5;

      // Priority
      score += printer.priority;

      // Default printer bonus
      if (printer.isDefault) {
        score += 10;
      }

      return { printer, score };
    });

    scored.sort((a, b) => b.score - a.score);

    const recommended = scored[0].printer;

    return {
      printer: recommended,
      reason: this.getRecommendationReason(recommended, printInstruction),
      alternatives: scored.slice(1, 4).map((s) => ({
        printer: s.printer,
        score: s.score,
      })),
    };
  },

  getRecommendationReason(printer, instruction) {
    const reasons = [];

    if (printer.supportedPaperSizes.includes(instruction.paperSize)) {
      reasons.push(`Supports ${instruction.paperSize}`);
    }

    if (instruction.duplex === 'DUPLEX' && printer.duplexSupport) {
      reasons.push('Supports Duplex');
    }

    if (instruction.colorMode === 'COLOR') {
      reasons.push('Color printer');
    } else {
      reasons.push('B/W printer');
    }

    if (printer.status === 'ONLINE') {
      reasons.push('Currently Online');
    }

    return reasons.join(', ');
  },

  async getPrinterStatus(printerId, shopId) {
    const printer = await prisma.printer.findFirst({
      where: { id: printerId, shopId },
      include: {
        printJobs: {
          where: {
            status: { in: ['WAITING', 'DOWNLOADING', 'PREPARING', 'PRINTING'] },
          },
          orderBy: { createdAt: 'asc' },
        },
      },
    });

    if (!printer) {
      throw new AppError('Printer not found', 404, 'PRINTER_NOT_FOUND');
    }

    return {
      ...printer,
      queueLength: printer.printJobs.length,
      queue: printer.printJobs,
    };
  },

  async updatePrinterStatus(printerId, status, heartbeat = null) {
    return prisma.printer.update({
      where: { id: printerId },
      data: {
        status,
        ...(heartbeat && { lastHeartbeat: new Date() }),
      },
    });
  },
};

