  const result = await orderService.getOrderQueue(req.shopId, req.query);
  res.json({ success: true, data: result });
}));

// Search orders
router.get('/search', asyncHandler(async (req, res) => {
  const { q } = req.query;
  if (!q) {
    return res.json({ success: true, data: [] });
  }
  const orders = await orderService.searchOrders(req.shopId, q);
  res.json({ success: true, data: orders });
}));

// Create order
router.post('/', orderValidation.create, asyncHandler(async (req, res) => {
  let customerId = req.body.customerId;

  if (!customerId && req.body.customerMobile) {
    let customer = await prisma.customer.findFirst({
      where: {
        shopId: req.shopId,
        mobileNumber: req.body.customerMobile,
      },
    });

    if (!customer) {
      customer = await prisma.customer.create({
        data: {
          shopId: req.shopId,
          name: req.body.customerName || 'Guest',
          mobileNumber: req.body.customerMobile,
        },
      });
    }
    customerId = customer.id;
  }

  if (!customerId) {
    const customer = await prisma.customer.create({
      data: {
        shopId: req.shopId,
        name: 'Guest',
        mobileNumber: '0000000000',
      },
    });
    customerId = customer.id;
  }

  const order = await orderService.createOrder(req.shopId, customerId, req.body);
  res.status(201).json({ success: true, data: order });
}));

