  const { status } = req.body;
  const order = await orderService.updateOrderStatus(
    req.params.id,
    req.shopId,
    status,
    req.user.id
  );
  res.json({ success: true, data: order });
}));

// Approve order
router.post('/:id/approve', orderValidation.approve, asyncHandler(async (req, res) => {
  const order = await orderService.getOrder(req.params.id, req.shopId);

  if (order.status !== 'WAITING_APPROVAL') {
    throw new AppError('Order is not waiting for approval', 400, 'INVALID_STATUS');
  }

  let printerId = req.body.printerId;

  if (!printerId) {
    const firstInstruction = order.files[0]?.printInstructions[0];
    if (firstInstruction) {
      const recommendation = await printerService.recommendPrinter(req.shopId, firstInstruction);
      printerId = recommendation.printer.id;
    }
  }

  await orderService.updateOrderStatus(req.params.id, req.shopId, 'APPROVED', req.user.id);

  if (printerId) {
    await prisma.printInstruction.updateMany({
      where: {
        orderId: req.params.id,
      },
      data: {
        assignedPrinterId: printerId,
        processingStatus: 'COMPLETED',
      },
    });
  }

  const updatedOrder = await orderService.getOrder(req.params.id, req.shopId);
  res.json({ success: true, data: updatedOrder });
}));

// Hold order
router.post('/:id/hold', asyncHandler(async (req, res) => {
  const { reason } = req.body;
  const order = await orderService.updateOrderStatus(
    req.params.id,
    req.shopId,
    'HOLD',
    req.user.id
  );

  await prisma.auditLog.create({
    data: {
      shopId: req.shopId,
      userId: req.user.id,
      action: 'ORDER_HOLD',
      entity: 'Order',
      entityId: req.params.id,
      details: { reason },
    },
  });

  res.json({ success: true, data: order });
}));

// Reject order
router.post('/:id/reject', asyncHandler(async (req, res) => {
  const { reason } = req.body;
  const order = await orderService.updateOrderStatus(
    req.params.id,
    req.shopId,
    'CANCELLED',
    req.user.id
  );

  await prisma.auditLog.create({
    data: {
      shopId: req.shopId,
      userId: req.user.id,
      action: 'ORDER_REJECTED',
      entity: 'Order',
      entityId: req.params.id,
      details: { reason },
    },
  });

  res.json({ success: true, data: order });
}));

// Calculate price for order
router.post('/:id/calculate-price', asyncHandler(async (req, res) => {
  const order = await orderService.getOrder(req.params.id, req.shopId);

  const allInstructions = order.files.flatMap((f) => f.printInstructions);

  if (allInstructions.length === 0) {
    return res.json({
      success: true,
      data: { subtotal: 0, finalTotal: 0, breakdown: [] },
    });
  }

  const pricing = await pricingService.calculatePrice(req.shopId, allInstructions);

  await pricingService.savePriceSnapshot(order.id, pricing);

  await prisma.order.update({
    where: { id: order.id },
    data: {
      totalAmount: pricing.finalTotal,
      status: 'WAITING_APPROVAL',
    },
  });

  res.json({ success: true, data: pricing });
}));

export default router;

import { Router } from 'express';
import multer from 'multer';
import { fileService } from '../services/file.service.js';
import { authenticate } from '../middleware/auth.js';
import { asyncHandler } from '../middleware/errorHandler.js';

const router = Router();

const storage = multer.memoryStorage();
const upload = multer({
  storage,
  limits: {
    fileSize: parseInt(process.env.MAX_FILE_SIZE) || 104857600,
  },
  fileFilter: (req, file, cb) => {
    const allowedTypes = [
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-powerpoint',
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'image/jpeg',
      'image/png',
      'image/webp',
    ];

    if (allowedTypes.includes(file.mimetype)) {
      cb(null, true);
    } else {
      cb(new Error('Unsupported file type'), false);
    }
  },
});

router.use(authenticate);

router.post('/upload/:orderId', upload.array('files', 100), asyncHandler(async (req, res) => {
  const { orderId } = req.params;
  const uploadedFiles = [];

  for (const file of req.files) {
    const orderFile = await fileService.uploadFile(orderId, req.shopId, file);
    uploadedFiles.push(orderFile);
  }

  // Analyze files in background
  for (const file of uploadedFiles) {
    fileService.analyzeFile(file.id).catch((err) => {
      console.error(`Analysis failed for file ${file.id}:`, err);
    });
  }

  res.status(201).json({
    success: true,
    message: `${uploadedFiles.length} file(s) uploaded successfully`,
    data: uploadedFiles,
  });
}));

router.get('/order/:orderId', asyncHandler(async (req, res) => {
  const files = await fileService.getFilesByOrder(req.params.orderId, req.shopId);
  res.json({ success: true, data: files });
}));

router.get('/:fileId/analyze', asyncHandler(async (req, res) => {
  const analysis = await fileService.analyzeFile(req.params.fileId);
  res.json({ success: true, data: analysis });
}));

router.delete('/:fileId', asyncHandler(async (req, res) => {
  const result = await fileService.deleteFile(req.params.fileId, req.shopId);
  res.json({ success: true, data: result });
}));

export default router;

