import { Router } from 'express';
import { prisma } from '../server.js';
import { authenticate } from '../middleware/auth.js';
import { asyncHandler, AppError } from '../middleware/errorHandler.js';

const router = Router();

router.use(authenticate);

router.get('/order/:orderId', asyncHandler(async (req, res) => {
  const payments = await prisma.payment.findMany({
    where: { orderId: req.params.orderId },
    orderBy: { createdAt: 'desc' },
  });

  res.json({ success: true, data: payments });
}));

router.post('/create', asyncHandler(async (req, res) => {
  const { orderId, method, amount } = req.body;

  const order = await prisma.order.findFirst({
    where: { id: orderId, shopId: req.shopId },
  });

  if (!order) {
    throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
  }

  const payment = await prisma.payment.create({
    data: {
      orderId,
      method,
      amount,
      status: 'PENDING',
    },
  });

  res.status(201).json({ success: true, data: payment });
}));

router.post('/verify', asyncHandler(async (req, res) => {
  const { paymentId, gatewayReference, status } = req.body;

  const payment = await prisma.payment.findUnique({
    where: { id: paymentId },
  });

  if (!payment) {
    throw new AppError('Payment not found', 404, 'PAYMENT_NOT_FOUND');
  }

  const updatedPayment = await prisma.payment.update({
    where: { id: paymentId },
    data: {
      status: status || 'SUCCESS',
      gatewayReference,
    },
  });

  if (status === 'SUCCESS') {
    await prisma.order.update({
      where: { id: payment.orderId },
      data: {
        paymentStatus: 'PAID',
        status: 'WAITING_APPROVAL',
      },
    });
  }

  res.json({ success: true, data: updatedPayment });
}));

router.post('/cash/:orderId', asyncHandler(async (req, res) => {
  const order = await prisma.order.findFirst({
    where: { id: req.params.orderId, shopId: req.shopId },
  });

  if (!order) {
    throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
  }

  const payment = await prisma.payment.create({
    data: {
      orderId: req.params.orderId,
      method: 'CASH',
      amount: order.totalAmount,
      status: 'SUCCESS',
    },
  });

  await prisma.order.update({
    where: { id: req.params.orderId },
    data: {
      paymentStatus: 'PAID',
      status: 'WAITING_APPROVAL',
    },
  });

  res.json({ success: true, data: payment });
}));

export default router;

import { Router } from 'express';
import { prisma } from '../server.js';
import { authenticate, authorize } from '../middleware/auth.js';
import { asyncHandler } from '../middleware/errorHandler.js';

const router = Router();

router.use(authenticate);
router.use(authorize('SHOP_OWNER', 'MANAGER'));

router.get('/audit-logs', asyncHandler(async (req, res) => {
  const { page = 1, limit = 50 } = req.query;
  const skip = (parseInt(page) - 1) * parseInt(limit);

  const [logs, total] = await Promise.all([
    prisma.auditLog.findMany({
      where: { shopId: req.shopId },
      include: {
        user: { select: { name: true, email: true } },
      },
      orderBy: { createdAt: 'desc' },
      skip,
      take: parseInt(limit),
    }),
    prisma.auditLog.count({
      where: { shopId: req.shopId },
    }),
  ]);

  res.json({
    success: true,
    data: {
      logs,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total,
        totalPages: Math.ceil(total / parseInt(limit)),
      },
    },
  });
}));

router.get('/reports/revenue', asyncHandler(async (req, res) => {
  const { startDate, endDate } = req.query;

  const start = startDate ? new Date(startDate) : new Date(new Date().setDate(new Date().getDate() - 30));
  const end = endDate ? new Date(endDate) : new Date();

  const revenue = await prisma.order.aggregate({
    where: {
      shopId: req.shopId,
      paymentStatus: 'PAID',
      createdAt: { gte: start, lte: end },
    },
    _sum: { totalAmount: true },
    _count: true,
  });

  const dailyRevenue = await prisma.$queryRaw`
    SELECT
      DATE(created_at) as date,
      SUM(total_amount) as revenue,
      COUNT(*) as orders
    FROM orders
    WHERE shop_id = ${req.shopId}
      AND payment_status = 'PAID'
      AND created_at >= ${start}
      AND created_at <= ${end}
    GROUP BY DATE(created_at)
    ORDER BY date ASC
  `;

  res.json({
    success: true,
    data: {
      totalRevenue: revenue._sum.totalAmount || 0,
      totalOrders: revenue._count,
      daily: dailyRevenue,
    },
  });
}));

router.get('/reports/printers', asyncHandler(async (req, res) => {
  const printers = await prisma.printer.findMany({
    where: { shopId: req.shopId },
    include: {
      _count: {
        select: {
          printJobs: {
            where: { status: 'COMPLETED' },
          },
        },
      },
    },
  });

  res.json({ success: true, data: printers });
}));

router.get('/users', asyncHandler(async (req, res) => {
  const users = await prisma.user.findMany({
    where: { shopId: req.shopId },
    select: {
      id: true,
      name: true,
      email: true,
      mobileNumber: true,
      role: true,
      status: true,
      lastLogin: true,
      createdAt: true,
    },
    orderBy: { createdAt: 'desc' },
  });

  res.json({ success: true, data: users });
}));

router.post('/users', asyncHandler(async (req, res) => {
  const { name, email, mobileNumber, password, role } = req.body;
  const bcrypt = await import('bcryptjs');

  const passwordHash = await bcrypt.hash(password, 12);

  const user = await prisma.user.create({
    data: {
      shopId: req.shopId,
      name,
      email,
      mobileNumber,
      passwordHash,
      role: role || 'OPERATOR',
    },
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
    },
  });

  res.status(201).json({ success: true, data: user });
}));

router.put('/users/:id', asyncHandler(async (req, res) => {
  const user = await prisma.user.findFirst({
    where: { id: req.params.id, shopId: req.shopId },
  });

  if (!user) {
    return res.status(404).json({ success: false, message: 'User not found' });
  }

  const updated = await prisma.user.update({
    where: { id: req.params.id },
    data: {
      name: req.body.name ?? user.name,
      role: req.body.role ?? user.role,
      status: req.body.status ?? user.status,
    },
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      status: true,
    },
  });

  res.json({ success: true, data: updated });
}));

router.delete('/users/:id', asyncHandler(async (req, res) => {
  if (req.params.id === req.user.id) {
    return res.status(400).json({ success: false, message: 'Cannot delete yourself' });
  }

  await prisma.user.update({
    where: { id: req.params.id },
    data: { status: 'INACTIVE' },
  });

  res.json({ success: true, message: 'User deactivated' });
}));

export default router;

import { Router } from 'express';
import { prisma } from '../server.js';
import { printerService } from '../services/printer.service.js';
import { asyncHandler, AppError } from '../middleware/errorHandler.js';
import { logger } from '../utils/logger.js';

const router = Router();

// Agent authentication middleware
const authenticateAgent = async (req, res, next) => {
  try {
    const agentToken = req.headers['x-agent-token'];
    const agentId = req.headers['x-agent-id'];

    if (!agentToken || !agentId) {
      throw new AppError('Agent authentication required', 401, 'AGENT_AUTH_REQUIRED');
    }

    const agent = await prisma.windowsPrintAgent.findUnique({
      where: { id: agentId },
    });

    if (!agent) {
      throw new AppError('Agent not found', 404, 'AGENT_NOT_FOUND');
    }

    req.agent = agent;
    req.shopId = agent.shopId;
    next();
  } catch (error) {
    next(error);
  }
};

// Register agent
router.post('/register', asyncHandler(async (req, res) => {
  const { deviceName, operatingSystem, version, shopId, secret } = req.body;

  if (secret !== process.env.PRINT_AGENT_SECRET) {
    throw new AppError('Invalid agent secret', 401, 'INVALID_SECRET');
  }

  const agent = await prisma.windowsPrintAgent.create({
    data: {
      shopId,
      deviceName,
      operatingSystem: operatingSystem || 'Windows',
      version,
      status: 'ONLINE',
      lastHeartbeat: new Date(),
    },
  });

  logger.info(`Print Agent registered: ${agent.deviceName} for shop ${shopId}`);

  res.status(201).json({
    success: true,
    data: {
      agentId: agent.id,
      shopId: agent.shopId,
    },
  });
}));

// Heartbeat
router.post('/heartbeat', authenticateAgent, asyncHandler(async (req, res) => {
  await prisma.windowsPrintAgent.update({
    where: { id: req.agent.id },
    data: {
      lastHeartbeat: new Date(),
      status: 'ONLINE',
    },
  });

  res.json({ success: true, data: { status: 'ok' } });
}));

// Fetch pending jobs
router.get('/jobs', authenticateAgent, asyncHandler(async (req, res) => {
  const jobs = await prisma.printJob.findMany({
    where: {
      agentId: req.agent.id,
      status: { in: ['WAITING', 'READY'] },
    },
    include: {
      printInstruction: {
        include: {
          order: {
            select: {
              id: true,
              publicOrderNumber: true,
              customerNotes: true,
            },
          },
        },
      },
      printer: {
        select: {
          id: true,
          name: true,
          displayName: true,
        },
      },
    },
    orderBy: { createdAt: 'asc' },
  });

  res.json({ success: true, data: jobs });
}));

// Update job status
router.put('/jobs/:jobId/status', authenticateAgent, asyncHandler(async (req, res) => {
  const { status, errorMessage } = req.body;

  const job = await prisma.printJob.findFirst({
    where: {
      id: req.params.jobId,
      agentId: req.agent.id,
    },
  });

  if (!job) {
    throw new AppError('Job not found', 404, 'JOB_NOT_FOUND');
  }

  const updateData = { status };

  if (status === 'PRINTING') {
    updateData.startedAt = new Date();
  } else if (status === 'COMPLETED') {
    updateData.completedAt = new Date();
  } else if (status === 'FAILED') {
    updateData.errorMessage = errorMessage;
    updateData.retryCount = { increment: 1 };
  }

  const updatedJob = await prisma.printJob.update({
    where: { id: req.params.jobId },
    data: updateData,
  });

  // Update order status if job completed
  if (status === 'COMPLETED') {
    const instruction = await prisma.printInstruction.findUnique({
      where: { id: job.printInstructionId },
    });

    if (instruction) {
      const allJobs = await prisma.printJob.findMany({
        where: { printInstructionId: instruction.id },
      });

      const allCompleted = allJobs.every((j) => j.status === 'COMPLETED');
      if (allCompleted) {
        await prisma.order.update({
          where: { id: instruction.orderId },
          data: { status: 'COMPLETED', completedAt: new Date() },
        });
      }
    }
  }

  res.json({ success: true, data: updatedJob });
}));

// Report printer status
router.post('/printers/:printerId/status', authenticateAgent, asyncHandler(async (req, res) => {
  const { status, queueLength } = req.body;

  await printerService.updatePrinterStatus(req.params.printerId, status, new Date());

  if (queueLength !== undefined) {
    await prisma.printer.update({
      where: { id: req.params.printerId },
      data: { currentQueueLength: queueLength },
    });
  }

  res.json({ success: true });
}));

// Get agents for shop
router.get('/list/:shopId', asyncHandler(async (req, res) => {
  const agents = await prisma.windowsPrintAgent.findMany({
    where: { shopId: req.params.shopId },
    include: {
      printers: true,
    },
  });

  res.json({ success: true, data: agents });
}));

export default router;

