import { createContext, useContext, useState, useEffect } from 'react';
import { authAPI } from '../services/api';

const AuthContext = createContext(null);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('token');
    const savedUser = localStorage.getItem('user');

    if (token && savedUser) {
      setUser(JSON.parse(savedUser));
    }
    setLoading(false);
  }, []);

  const login = async (email, password) => {
    const response = await authAPI.login({ email, password });
    const { user: userData, token } = response.data;

    localStorage.setItem('token', token);
    localStorage.setItem('user', JSON.stringify(userData));
    setUser(userData);

    return userData;
  };

  const register = async (data) => {
    const response = await authAPI.register(data);
    const { user: userData, token } = response.data;

    localStorage.setItem('token', token);
    localStorage.setItem('user', JSON.stringify(userData));
    setUser(userData);

    return userData;
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
  };

  const isOwner = user?.role === 'SHOP_OWNER';
  const isManager = user?.role === 'MANAGER' || isOwner;
  const isOperator = user?.role === 'OPERATOR' || isManager;

  return (
    <AuthContext.Provider
      value={{
        user,
        loading,
        login,
        register,
        logout,
        isOwner,
        isManager,
        isOperator,
        isAuthenticated: !!user,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

import { createContext, useContext, useState, useEffect } from 'react';
import { shopAPI } from '../services/api';
import { useAuth } from './AuthContext';

const ShopContext = createContext(null);

export const useShop = () => {
  const context = useContext(ShopContext);
  if (!context) {
    throw new Error('useShop must be used within ShopProvider');
  }
  return context;
};

export const ShopProvider = ({ children }) => {
  const { isAuthenticated } = useAuth();
  const [shop, setShop] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (isAuthenticated) {
      fetchShop();
    }
  }, [isAuthenticated]);

  const fetchShop = async () => {
    setLoading(true);
    try {
      const response = await shopAPI.getCurrent();
      setShop(response.data);
    } catch (error) {
      console.error('Failed to fetch shop:', error);
    } finally {
      setLoading(false);
    }
  };

  const updateShop = async (data) => {
    const response = await shopAPI.update(data);
    setShop(response.data);
    return response.data;
  };

  const updateBranding = async (data) => {
    const response = await shopAPI.updateBranding(data);
    setShop((prev) => ({
      ...prev,
      branding: response.data,
    }));
    return response.data;
  };

  return (
    <ShopContext.Provider
      value={{
        shop,
        loading,
        updateShop,
        updateBranding,
        refreshShop: fetchShop,
      }}
    >
      {children}
    </ShopContext.Provider>
  );
};

import { Routes, Route, Navigate } from 'react-router-dom';
