import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Typography, Paper, List, ListItem, ListItemIcon, ListItemText, IconButton, Button, CircularProgress } from '@mui/material';
import { CloudUpload, Delete, Description, Image, Slideshow } from '@mui/icons-material';
import { useDropzone } from 'react-dropzone';
import { orderAPI, fileAPI } from '../../services/api';
import toast from 'react-hot-toast';

export default function UploadPage() {
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);

  const onDrop = (acceptedFiles) => {
    setFiles((prev) => [...prev, ...acceptedFiles]);
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    maxSize: 104857600,
  });

  const removeFile = (index) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  };

  const handleUpload = async () => {
    if (files.length === 0) return;
    setUploading(true);
    try {
      const orderResponse = await orderAPI.create({});
      const orderId = orderResponse.data.id;
      await fileAPI.upload(orderId, files);
      toast.success('Files uploaded successfully');
      navigate(`/configure/${orderId}`);
    } catch (err) {
      toast.error(err.message || 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  const getFileIcon = (name) => {
    if (name.endsWith('.pdf')) return <Description />;
    if (['.jpg', '.jpeg', '.png', '.webp'].some((ext) => name.endsWith(ext))) return <Image />;
    if (['.ppt', '.pptx'].some((ext) => name.endsWith(ext))) return <Slideshow />;
    return <Description />;
  };

  const formatSize = (bytes) => {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(1) + ' MB';
  };

  return (
    <Box>
      <Typography variant="h5" sx={{ fontWeight: 600, mb: 3 }}>
        Upload Files
      </Typography>

      <Paper
        {...getRootProps()}
        sx={{
          p: 4,
          mb: 3,
          border: '2px dashed',
          borderColor: isDragActive ? 'primary.main' : 'grey.300',
          cursor: 'pointer',
          textAlign: 'center',
        }}
      >
        <input {...getInputProps()} />
        <CloudUpload sx={{ fontSize: 48, color: 'primary.main', mb: 1 }} />
        <Typography>
          {isDragActive ? 'Drop files here' : 'Drag & drop or click to browse'}
        </Typography>
      </Paper>

      {files.length > 0 && (
        <>
          <List>
            {files.map((file, index) => (
              <ListItem
                key={index}
                secondaryAction={
                  <IconButton onClick={() => removeFile(index)} color="error">
                    <Delete />
                  </IconButton>
                }
              >
                <ListItemIcon>{getFileIcon(file.name)}</ListItemIcon>
                <ListItemText primary={file.name} secondary={formatSize(file.size)} />
              </ListItem>
            ))}
          </List>

          <Box sx={{ mt: 3, display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
            <Button variant="outlined" onClick={() => setFiles([])}>
              Clear All
            </Button>
            <Button
              variant="contained"
              onClick={handleUpload}
              disabled={uploading}
              startIcon={uploading ? <CircularProgress size={20} /> : null}
            >
              {uploading ? 'Uploading...' : `Upload ${files.length} File(s)`}
            </Button>
          </Box>
        </>
      )}
    </Box>
  );
}
