import { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CircularProgress,
  Stepper,
  Step,
  StepLabel,
  StepContent,
} from '@mui/material';
import { CheckCircle, HourlyEmpty, RadioButtonUnchecked } from '@mui/icons-material';
import { orderAPI } from '../../services/api';

const statusSteps = [
  { label: 'Uploaded', status: 'UPLOADED' },
  { label: 'Payment Received', status: 'WAITING_PAYMENT' },
  { label: 'Waiting for Approval', status: 'WAITING_APPROVAL' },
  { label: 'Approved', status: 'APPROVED' },
  { label: 'Printing', status: 'PRINTING' },
  { label: 'Completed', status: 'COMPLETED' },
];

export default function OrderTrackingPage() {
  const { orderNumber } = useParams();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadOrder();
    const interval = setInterval(loadOrder, 10000);
    return () => clearInterval(interval);
  }, [orderNumber]);

  const loadOrder = async () => {
    try {
      const res = await orderAPI.search(orderNumber);
      if (res.data.length > 0) {
        setOrder(res.data[0]);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const getActiveStep = () => {
    if (!order) return 0;
    const statusOrder = ['UPLOADED', 'PROCESSING', 'WAITING_PAYMENT', 'WAITING_APPROVAL', 'APPROVED', 'PRINTING', 'COMPLETED'];
    return statusOrder.indexOf(order.status);
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" py={8}>
        <CircularProgress />
      </Box>
    );
  }

  if (!order) {
    return (
      <Box textAlign="center" py={8}>
        <Typography variant="h6">Order not found</Typography>
        <Typography color="text.secondary">
          Please check your order number and try again
        </Typography>
      </Box>
    );
  }

  return (
    <Box maxWidth={600} mx="auto">
      <Typography variant="h5" sx={{ fontWeight: 600, mb: 1 }}>
        Order Tracking
      </Typography>
      <Typography color="text.secondary" sx={{ mb: 3 }}>
        Order #{order.publicOrderNumber}
      </Typography>

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 600, mb: 3 }}>
            Order Status
          </Typography>

          <Stepper activeStep={getActiveStep()} orientation="vertical">
            {statusSteps.map((step, index) => (
              <Step key={step.label}>
                <StepLabel
                  StepIconComponent={() => {
                    if (index < getActiveStep()) {
                      return <CheckCircle color="success" />;
                    }
                    if (index === getActiveStep()) {
                      return <CircularProgress size={24} />;
                    }
                    return <RadioButtonUnchecked color="disabled" />;
                  }}
                >
                  <Typography
                    sx={{
                      fontWeight: index === getActiveStep() ? 600 : 400,
                      color: index <= getActiveStep() ? 'text.primary' : 'text.secondary',
                    }}
                  >
                    {step.label}
                  </Typography>
                </StepLabel>
              </Step>
            ))}
          </Stepper>
        </CardContent>
      </Card>

      <Card>
        <CardContent>
          <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
            Order Details
          </Typography>
          <Box display="flex" justifyContent="space-between" mb={1}>
            <Typography color="text.secondary">Files</Typography>
            <Typography>{order.files?.length || 0}</Typography>
          </Box>
          <Box display="flex" justifyContent="space-between" mb={1}>
            <Typography color="text.secondary">Total Pages</Typography>
            <Typography>{order.files?.reduce((sum, f) => sum + (f.pageCount || 0), 0) || 0}</Typography>
          </Box>
          <Box display="flex" justifyContent="space-between" mb={1}>
            <Typography color="text.secondary">Amount</Typography>
            <Typography sx={{ fontWeight: 600 }}>
              ₹{(order.priceSnapshot?.finalTotal || order.totalAmount || 0).toFixed(2)}
            </Typography>
          </Box>
          <Box display="flex" justifyContent="space-between">
            <Typography color="text.secondary">Status</Typography>
            <Typography
              sx={{
                fontWeight: 600,
                color: order.status === 'COMPLETED' ? 'success.main' :
                       order.status === 'FAILED' ? 'error.main' : 'primary.main',
              }}
            >
              {order.status?.replace(/_/g, ' ')}
            </Typography>
          </Box>
        </CardContent>
      </Card>
    </Box>
  );
}
