import { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  IconButton,
  Tooltip,
  CircularProgress,
} from '@mui/material';
import { Add, Edit, Delete, CheckCircle, Error as ErrorIcon } from '@mui/icons-material';
import { printerAPI } from '../../services/api';
import toast from 'react-hot-toast';

const categories = [
  { value: 'BW_LASER', label: 'B/W Laser' },
  { value: 'COLOR_LASER', label: 'Color Laser' },
  { value: 'INKJET', label: 'Inkjet' },
  { value: 'PHOTO', label: 'Photo Printer' },
  { value: 'LARGE_FORMAT', label: 'Large Format' },
];

export default function PrintersPage() {
  const [printers, setPrinters] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    displayName: '',
    category: 'BW_LASER',
    supportedPaperSizes: ['A4'],
    duplexSupport: false,
    isDefault: false,
  });

  useEffect(() => {
    loadPrinters();
  }, []);

  const loadPrinters = async () => {
    try {
      const res = await printerAPI.getAll();
      setPrinters(res.data);
    } catch (err) {
      toast.error('Failed to load printers');
    } finally {
      setLoading(false);
    }
  };

  const handleOpenDialog = (printer = null) => {
    if (printer) {
      setEditingPrinter(printer);
      setFormData({
        name: printer.name,
        displayName: printer.displayName || '',
        category: printer.category,
        supportedPaperSizes: printer.supportedPaperSizes || ['A4'],
        duplexSupport: printer.duplexSupport,
        isDefault: printer.isDefault,
      });
    } else {
      setEditingPrinter(null);
      setFormData({
        name: '',
        displayName: '',
        category: 'BW_LASER',
        supportedPaperSizes: ['A4'],
        duplexSupport: false,
        isDefault: false,
      });
    }
    setDialogOpen(true);
  };

  const handleSave = async () => {
    try {
      if (editingPrinter) {
        await printerAPI.update(editingPrinter.id, formData);
        toast.success('Printer updated');
      } else {
        await printerAPI.create(formData);
        toast.success('Printer added');
      }
      setDialogOpen(false);
      loadPrinters();
    } catch (err) {
      toast.error(err.message || 'Failed to save printer');
    }
  };

  const handleDelete = async (printerId) => {
    if (!confirm('Are you sure you want to delete this printer?')) return;
    try {
      await printerAPI.delete(printerId);
      toast.success('Printer deleted');
      loadPrinters();
    } catch (err) {
      toast.error(err.message || 'Failed to delete printer');
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" py={8}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          Printers
        </Typography>
        <Button variant="contained" startIcon={<Add />} onClick={() => handleOpenDialog()}>
          Add Printer
        </Button>
      </Grid>

      <Grid container spacing={2}>
        {printers.map((printer) => (
          <Grid item xs={12} md={6} lg={4} key={printer.id}>
            <Card>
              <CardContent>
                <Box display="flex" justifyContent="space-between" alignItems="flex-start">
                  <Box>
                    <Typography variant="h6" sx={{ fontWeight: 600 }}>
                      {printer.displayName || printer.name}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      {printer.name}
                    </Typography>
                  </Box>
                  <Chip
                    icon={printer.status === 'ONLINE' ? <CheckCircle /> : <ErrorIcon />}
                    label={printer.status}
                    color={printer.status === 'ONLINE' ? 'success' : 'error'}
                    size="small"
                  />
                </Box>

                <Box mt={2} display="flex" gap={1} flexWrap="wrap">
                  <Chip label={categories.find((c) => c.value === printer.category)?.label} size="small" />
                  {printer.duplexSupport && <Chip label="Duplex" size="small" color="primary" variant="outlined" />}
                  {printer.isDefault && <Chip label="Default" size="small" color="secondary" />}
                </Box>

                <Box mt={2}>
                  <Typography variant="caption" color="text.secondary">
                    Paper: {printer.supportedPaperSizes?.join(', ')}
                  </Typography>
                </Box>

                {printer.agent && (
                  <Box mt={1}>
                    <Typography variant="caption" color="text.secondary">
                      Agent: {printer.agent.deviceName}
                    </Typography>
                  </Box>
                )}

                <Box mt={2} display="flex" gap={1}>
                  <Tooltip title="Edit">
                    <IconButton size="small" onClick={() => handleOpenDialog(printer)}>
                      <Edit />
                    </IconButton>
                  </Tooltip>
                  <Tooltip title="Delete">
                    <IconButton size="small" color="error" onClick={() => handleDelete(printer.id)}>
                      <Delete />
                    </IconButton>
                  </Tooltip>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Add/Edit Dialog */}
      <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>{editingPrinter ? 'Edit Printer' : 'Add Printer'}</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="Printer Name (Windows)"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            sx={{ mt: 1, mb: 2 }}
          />
          <TextField
            fullWidth
            label="Display Name"
            value={formData.displayName}
            onChange={(e) => setFormData({ ...formData, displayName: e.target.value })}
            placeholder="e.g., Front Counter Canon"
            sx={{ mb: 2 }}
          />
          <FormControl fullWidth sx={{ mb: 2 }}>
            <InputLabel>Category</InputLabel>
            <Select
              value={formData.category}
              label="Category"
              onChange={(e) => setFormData({ ...formData, category: e.target.value })}
            >
              {categories.map((cat) => (
                <MenuItem key={cat.value} value={cat.value}>
                  {cat.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <Box display="flex" gap={2}>
            <FormControlLabel
              control={
                <Switch
                  checked={formData.duplexSupport}
                  onChange={(e) => setFormData({ ...formData, duplexSupport: e.target.checked })}
                />
              }
              label="Duplex Support"
            />
            <FormControlLabel
              control={
                <Switch
                  checked={formData.isDefault}
                  onChange={(e) => setFormData({ ...formData, isDefault: e.target.checked })}
                />
              }
              label="Default Printer"
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={handleSave}>
            {editingPrinter ? 'Update' : 'Add'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}
