import fs from 'fs/promises';
import path from 'path';
import { PDFDocument } from 'pdf-lib';
import { prisma } from '../server.js';
import { AppError } from '../middleware/errorHandler.js';
import { logger } from '../utils/logger.js';

export const printProcessingService = {
  async generatePrintReadyPdf(orderId) {
    const order = await prisma.order.findUnique({
      where: { id: orderId },
      include: {
        files: {
          include: {
            printInstructions: true,
          },
        },
      },
    });

    if (!order) {
      throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    logger.info(`Generating print-ready PDF for order ${order.publicOrderNumber}`);

    const printReadyFiles = [];

    for (const file of order.files) {
      for (const instruction of file.printInstructions) {
        try {
          const printReadyPath = await this.processInstruction(file, instruction);
          printReadyFiles.push({
            instructionId: instruction.id,
            filePath: printReadyPath,
            printerId: instruction.assignedPrinterId,
          });
        } catch (error) {
          logger.error(`Failed to process instruction ${instruction.id}:`, error);
          await prisma.printInstruction.update({
            where: { id: instruction.id },
            data: { processingStatus: 'FAILED' },
          });
        }
      }
    }

    return printReadyFiles;
  },

  async processInstruction(file, instruction) {
    logger.info(`Processing instruction: ${instruction.pageRange} for ${file.fileName}`);

    await prisma.printInstruction.update({
      where: { id: instruction.id },
      data: { processingStatus: 'ANALYZING' },
    });

    // Read the original PDF
    const pdfBuffer = await fs.readFile(file.originalPath);
    const pdfDoc = await PDFDocument.load(pdfBuffer);

    // Apply page range
    const pages = this.parsePageRange(instruction.pageRange, pdfDoc.getPageCount());

    // Apply N-up layout
    let processedDoc;
    if (instruction.nUpLayout > 1) {
      processedDoc = await this.applyNUp(pdfDoc, pages, instruction.nUpLayout, instruction);
    } else {
      processedDoc = await this.extractPages(pdfDoc, pages);
    }

    // Apply scaling
    if (instruction.scaling && instruction.scaling !== 100) {
      await this.applyScaling(processedDoc, instruction.scaling);
    }

    // Apply binding margin
    if (instruction.bindingMargin && instruction.bindingMargin !== 'NONE') {
      await this.applyBindingMargin(processedDoc, instruction.bindingMargin);
    }

    // Apply watermark
    if (instruction.watermark) {
      await this.applyWatermark(processedDoc, instruction.watermark);
    }

    // Apply header/footer
    if (instruction.header || instruction.footer) {
      await this.applyHeaderFooter(processedDoc, instruction.header, instruction.footer);
    }

    // Save the print-ready PDF
    const printReadyBytes = await processedDoc.save();
    const printReadyPath = path.join(
      path.dirname(file.originalPath),
      'print-ready',
      `${instruction.id}_printready.pdf`
    );

    await fs.mkdir(path.dirname(printReadyPath), { recursive: true });
    await fs.writeFile(printReadyPath, printReadyBytes);

    // Update instruction with print-ready path
    await prisma.printInstruction.update({
      where: { id: instruction.id },
      data: {
        printReadyPdfPath: printReadyPath,
        processingStatus: 'COMPLETED',
      },
    });

    // Calculate final sheet count
    const sheetCount = this.calculateSheetCount(pages.length, instruction.nUpLayout, instruction.duplex);
    await prisma.printInstruction.update({
      where: { id: instruction.id },
      data: { finalSheetCount: sheetCount },
    });

    logger.info(`Instruction ${instruction.id} processed: ${sheetCount} sheets`);
    return printReadyPath;
  },

  parsePageRange(pageRange, totalPages) {
    if (!pageRange || pageRange === 'all') {
      return Array.from({ length: totalPages }, (_, i) => i);
    }

    const pages = [];
    const parts = pageRange.split(',');

    for (const part of parts) {
      const trimmed = part.trim();
      if (trimmed.includes('-')) {
        const [start, end] = trimmed.split('-').map(Number);
        for (let i = start; i <= Math.min(end, totalPages); i++) {
          pages.push(i - 1);
        }
      } else {
        const pageNum = parseInt(trimmed);
        if (pageNum >= 1 && pageNum <= totalPages) {
          pages.push(pageNum - 1);
        }
      }
    }

    return [...new Set(pages)].sort((a, b) => a - b);
  },

  calculateSheetCount(pageCount, nUp, duplex) {
    let sheets = Math.ceil(pageCount / nUp);
    if (duplex === 'DUPLEX') {
      sheets = Math.ceil(sheets / 2);
    }
    return sheets;
  },

  async extractPages(pdfDoc, pages) {
    const newDoc = await PDFDocument.create();
    const copiedPages = await newDoc.copyPages(pdfDoc, pages);
    copiedPages.forEach((page) => newDoc.addPage(page));
    return newDoc;
  },

  async applyNUp(pdfDoc, pages, nUp, instruction) {
    const newDoc = await PDFDocument.create();
    const copiedPages = await newDoc.copyPages(pdfDoc, pages);

    // Determine layout
    let cols, rows;
    switch (nUp) {
      case 2: cols = 1; rows = 2; break;
      case 4: cols = 2; rows = 2; break;
      case 6: cols = 2; rows = 3; break;
      case 8: cols = 2; rows = 4; break;
      case 9: cols = 3; rows = 3; break;
      case 16: cols = 4; rows = 4; break;
      default: cols = 1; rows = 1;
    }

    // Create pages with multiple content
    for (let i = 0; i < copiedPages.length; i += nUp) {
      const page = newDoc.addPage([595.28, 841.89]); // A4 size

      for (let j = 0; j < nUp && i + j < copiedPages.length; j++) {
        const col = j % cols;
        const row = Math.floor(j / cols);

        const cellWidth = page.getWidth() / cols;
        const cellHeight = page.getHeight() / rows;

        const x = col * cellWidth;
        const y = page.getHeight() - (row + 1) * cellHeight;

        // Embed the page
        const [embeddedPage] = await newDoc.embedPdf(pdfDoc, [pages[i + j]]);
        page.drawPage(embeddedPage, {
          x,
          y,
          width: cellWidth,
          height: cellHeight,
        });
      }
    }

    return newDoc;
  },

  async applyScaling(pdfDoc, scaling) {
    const scale = scaling / 100;
    const pages = pdfDoc.getPages();

    for (const page of pages) {
      const { width, height } = page.getSize();
      page.setSize({
        width: width * scale,
        height: height * scale,
      });
    }
  },

  async applyBindingMargin(pdfDoc, margin) {
    const pages = pdfDoc.getPages();
    const marginSize = 20; // points

    for (const page of pages) {
      const { width, height } = page.getSize();

      switch (margin) {
        case 'LEFT':
          page.setMediaBox([marginSize, 0, width, height]);
          break;
        case 'RIGHT':
          page.setMediaBox([0, 0, width - marginSize, height]);
          break;
        case 'TOP':
          page.setMediaBox([0, marginSize, width, height]);
          break;
      }
    }
  },

  async applyWatermark(pdfDoc, watermarkText) {
    const pages = pdfDoc.getPages();

    for (const page of pages) {
      const { width, height } = page.getSize();
      page.drawText(watermarkText, {
        x: width / 2 - 50,
        y: height / 2,
        size: 50,
        opacity: 0.3,
      });
    }
  },

  async applyHeaderFooter(pdfDoc, header, footer) {
    const pages = pdfDoc.getPages();

    for (let i = 0; i < pages.length; i++) {
      const page = pages[i];
      const { width, height } = page.getSize();

      if (header) {
        page.drawText(header, {
          x: 50,
          y: height - 30,
          size: 10,
        });
      }

      if (footer) {
        page.drawText(`${footer} - Page ${i + 1}`, {
          x: 50,
          y: 20,
          size: 10,
        });
      }
    }
  },

  async applyDuplexLayout(pdfDoc, instruction) {
    // Duplex layout is handled by the printer driver
    // This is a placeholder for future booklet/saddle-stitch implementation
    return pdfDoc;
  },

  async generatePreview(orderId) {
    const order = await prisma.order.findUnique({
      where: { id: orderId },
      include: {
        files: {
          include: {
            printInstructions: true,
          },
        },
      },
    });

    if (!order) {
      throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    const previews = [];

    for (const file of order.files) {
      for (const instruction of file.printInstructions) {
        // Generate preview for each instruction
        const previewPath = await this.generateInstructionPreview(file, instruction);
        previews.push({
          instructionId: instruction.id,
          previewPath,
        });
      }
    }

    return previews;
  },

  async generateInstructionPreview(file, instruction) {
    // Preview generation using pdf.js or sharp
    // This is a simplified version
    const previewDir = path.join(path.dirname(file.originalPath), 'preview');
    await fs.mkdir(previewDir, { recursive: true });

    const previewPath = path.join(previewDir, `${instruction.id}_preview.png`);

    // In production, this would use pdf.js to render pages
    // For now, return the original file path as placeholder
    return file.originalPath;
  },
};

import { prisma } from '../server.js';
import { logger } from '../utils/logger.js';

export const notificationService = {
  async create(shopId, type, title, message, data = null) {
    const notification = await prisma.notification.create({
      data: {
        shopId,
        type,
        title,
        message,
        data,
      },
    });

    logger.info(`Notification created: ${type} for shop ${shopId}`);
    return notification;
  },

  async getNotifications(shopId, unreadOnly = false) {
    const where = { shopId };
    if (unreadOnly) {
      where.isRead = false;
    }

    return prisma.notification.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: 50,
    });
  },

  async markAsRead(notificationId, shopId) {
    return prisma.notification.update({
      where: { id: notificationId, shopId },
      data: { isRead: true },
    });
  },

  async markAllAsRead(shopId) {
    return prisma.notification.updateMany({
      where: { shopId, isRead: false },
      data: { isRead: true },
    });
  },

  async getUnreadCount(shopId) {
    return prisma.notification.count({
      where: { shopId, isRead: false },
    });
  },

  // Convenience methods
  async notifyNewOrder(shopId, order) {
    return this.create(
      shopId,
      'NEW_ORDER',
      'New Order Received',
      `Order #${order.publicOrderNumber} has been placed`,
      { orderId: order.id, orderNumber: order.publicOrderNumber }
    );
  },

  async notifyPaymentReceived(shopId, order) {
    return this.create(
      shopId,
      'PAYMENT_RECEIVED',
      'Payment Received',
      `Payment received for order #${order.publicOrderNumber}`,
      { orderId: order.id, amount: order.totalAmount }
    );
  },

  async notifyOrderApproved(shopId, order) {
    return this.create(
      shopId,
      'ORDER_APPROVED',
      'Order Approved',
      `Order #${order.publicOrderNumber} has been approved`,
      { orderId: order.id }
    );
