      shopId,
      'PRINTING_STARTED',
      'Printing Started',
      `Order #${order.publicOrderNumber} is now printing`,
      { orderId: order.id }
    );
  },

  async notifyReadyForPickup(shopId, order) {
    return this.create(
      shopId,
      'READY_FOR_PICKUP',
      'Ready for Pickup',
      `Order #${order.publicOrderNumber} is ready for pickup`,
      { orderId: order.id }
    );
  },

  async notifyPrinterOffline(shopId, printer) {
    return this.create(
      shopId,
      'PRINTER_OFFLINE',
      'Printer Offline',
      `Printer ${printer.displayName || printer.name} is offline`,
      { printerId: printer.id }
