import winston from 'winston';

const { combine, timestamp, printf, colorize, errors } = winston.format;

const logFormat = printf(({ level, message, timestamp, stack }) => {
  return `${timestamp} [${level}]: ${stack || message}`;
});

export const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'development' ? 'debug' : 'info',
  format: combine(
    timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    errors({ stack: true }),
    logFormat
  ),
  transports: [
    new winston.transports.Console({
      format: combine(colorize(), logFormat),
    }),
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

import { WebSocketServer } from 'ws';
import { logger } from './logger.js';

class WebSocketService {
  constructor() {
    this.wss = null;
    this.clients = new Map(); // shopId -> Set of connections
  }

  initialize(server) {
    this.wss = new WebSocketServer({ server, path: '/ws' });

    this.wss.on('connection', (ws, req) => {
      logger.info('WebSocket connection established');

      ws.on('message', (data) => {
        try {
          const message = JSON.parse(data);
          this.handleMessage(ws, message);
        } catch (error) {
          logger.error('Invalid WebSocket message:', error);
        }
      });

      ws.on('close', () => {
        this.removeClient(ws);
        logger.info('WebSocket connection closed');
      });

      ws.on('error', (error) => {
        logger.error('WebSocket error:', error);
      });
    });

    logger.info('WebSocket server initialized');
  }

  handleMessage(ws, message) {
    switch (message.type) {
      case 'AUTHENTICATE':
        this.authenticateClient(ws, message);
        break;
      case 'SUBSCRIBE_ORDER':
        this.subscribeToOrder(ws, message.orderId);
        break;
      default:
        logger.warn(`Unknown message type: ${message.type}`);
    }
  }

  authenticateClient(ws, message) {
    const { shopId, token } = message;

    if (!shopId || !token) {
      ws.send(JSON.stringify({ type: 'AUTH_ERROR', message: 'Missing credentials' }));
      return;
    }

    // In production, verify the token
    ws.shopId = shopId;
    ws.isAuthenticated = true;

    if (!this.clients.has(shopId)) {
      this.clients.set(shopId, new Set());
    }
    this.clients.get(shopId).add(ws);

    ws.send(JSON.stringify({ type: 'AUTH_SUCCESS', shopId }));
    logger.info(`WebSocket client authenticated for shop ${shopId}`);
  }

  subscribeToOrder(ws, orderId) {
    if (!ws.isAuthenticated) {
      ws.send(JSON.stringify({ type: 'ERROR', message: 'Not authenticated' }));
      return;
    }

    ws.subscribedOrders = ws.subscribedOrders || new Set();
    ws.subscribedOrders.add(orderId);

    ws.send(JSON.stringify({ type: 'SUBSCRIBED', orderId }));
  }

  removeClient(ws) {
    if (ws.shopId && this.clients.has(ws.shopId)) {
      this.clients.get(ws.shopId).delete(ws);
      if (this.clients.get(ws.shopId).size === 0) {
        this.clients.delete(ws.shopId);
      }
    }
  }

  // Send notification to all clients in a shop
  broadcastToShop(shopId, event, data) {
    const clients = this.clients.get(shopId);
    if (!clients) return;

    const message = JSON.stringify({ type: event, data, timestamp: new Date().toISOString() });

    for (const client of clients) {
      if (client.readyState === 1) { // WebSocket.OPEN
        client.send(message);
      }
    }
  }

  // Send notification to specific order subscribers
  broadcastToOrder(shopId, orderId, event, data) {
    const clients = this.clients.get(shopId);
    if (!clients) return;

    const message = JSON.stringify({
      type: event,
      orderId,
      data,
      timestamp: new Date().toISOString(),
    });

    for (const client of clients) {
      if (client.readyState === 1 && client.subscribedOrders?.has(orderId)) {
        client.send(message);
      }
    }
  }

  // Convenience methods
  notifyNewOrder(shopId, order) {
    this.broadcastToShop(shopId, 'NEW_ORDER', order);
  }

  notifyOrderStatusChange(shopId, orderId, status) {
    this.broadcastToOrder(shopId, orderId, 'ORDER_STATUS_CHANGE', { status });
  }

  notifyPaymentReceived(shopId, orderId, amount) {
    this.broadcastToOrder(shopId, orderId, 'PAYMENT_RECEIVED', { amount });
  }

  notifyPrintStarted(shopId, orderId) {
    this.broadcastToOrder(shopId, orderId, 'PRINT_STARTED', {});
  }

  notifyPrintCompleted(shopId, orderId) {
    this.broadcastToOrder(shopId, orderId, 'PRINT_COMPLETED', {});
  }

  notifyPrinterStatusChange(shopId, printerId, status) {
    this.broadcastToShop(shopId, 'PRINTER_STATUS_CHANGE', { printerId, status });
  }

  getConnectedClients(shopId) {
    return this.clients.get(shopId)?.size || 0;
  }
}

export const wsService = new WebSocketService();

