  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

api.interceptors.response.use(
  (response) => response.data,
  (error) => {
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      window.location.href = '/login';
    }
    return Promise.reject(error.response?.data || error);
  }
);

// Auth API
export const authAPI = {
  login: (data) => api.post('/auth/login', data),
  register: (data) => api.post('/auth/register', data),
  getProfile: () => api.get('/auth/profile'),
};

// Shop API
export const shopAPI = {
  getCurrent: () => api.get('/shops/current'),
  update: (data) => api.put('/shops/current', data),
  updateBranding: (data) => api.put('/shops/current/branding', data),
};

// Order API
export const orderAPI = {
  create: (data) => api.post('/orders', data),
  getById: (id) => api.get(`/orders/${id}`),
  getQueue: (params) => api.get('/orders/queue', { params }),
  search: (q) => api.get('/orders/search', { params: { q } }),
  getDashboard: () => api.get('/orders/dashboard'),
  updateStatus: (id, status) => api.put(`/orders/${id}/status`, { status }),
  approve: (id, data) => api.post(`/orders/${id}/approve`, data),
  hold: (id, data) => api.post(`/orders/${id}/hold`, data),
