  delete: (fileId) => api.delete(`/files/${fileId}`),
};

// Printer API
export const printerAPI = {
  getAll: () => api.get('/printers'),
  create: (data) => api.post('/printers', data),
  getById: (id) => api.get(`/printers/${id}`),
  update: (id, data) => api.put(`/printers/${id}`, data),
  delete: (id) => api.delete(`/printers/${id}`),
  recommend: (id, params) => api.get(`/printers/${id}/recommend`, { params }),
};

// Pricing API
export const pricingAPI = {
  getAll: () => api.get('/pricing'),
  create: (data) => api.post('/pricing', data),
  update: (id, data) => api.put(`/pricing/${id}`, data),
  delete: (id) => api.delete(`/pricing/${id}`),
  calculate: (data) => api.post('/pricing/calculate', data),
  estimateTime: (params) => api.get('/pricing/estimate-time', { params }),
};

// Payment API
export const paymentAPI = {
  getByOrder: (orderId) => api.get(`/payments/order/${orderId}`),
  create: (data) => api.post('/payments/create', data),
  verify: (data) => api.post('/payments/verify', data),
  cashPayment: (orderId) => api.post(`/payments/cash/${orderId}`),
};

// Customer API
export const customerAPI = {
  getAll: () => api.get('/customers'),
  search: (q) => api.get('/customers/search', { params: { q } }),
  create: (data) => api.post('/customers', data),
  getById: (id) => api.get(`/customers/${id}`),
  update: (id, data) => api.put(`/customers/${id}`, data),
};

// Admin API
export const adminAPI = {
  getAuditLogs: (params) => api.get('/admin/audit-logs', { params }),
  getRevenueReport: (params) => api.get('/admin/reports/revenue', { params }),
  getPrinterReport: () => api.get('/admin/reports/printers'),
  getUsers: () => api.get('/admin/users'),
  createUser: (data) => api.post('/admin/users', data),
  updateUser: (id, data) => api.put(`/admin/users/${id}`, data),
  deleteUser: (id) => api.delete(`/admin/users/${id}`),
};

export default api;

