import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Typography,
  Button,
  Card,
  CardContent,
  Grid,
  Paper,
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  Description as DocIcon,
  Image as PhotoIcon,
  Slideshow as PptIcon,
  CreditCard as IdIcon,
} from '@mui/icons-material';
import { useDropzone } from 'react-dropzone';
import { useAuth } from '../../contexts/AuthContext';
import { orderAPI, fileAPI } from '../../services/api';
import toast from 'react-hot-toast';

const quickActions = [
  { label: 'Documents', icon: <DocIcon sx={{ fontSize: 40 }} />, color: '#1976d2' },
  { label: 'Photos', icon: <PhotoIcon sx={{ fontSize: 40 }} />, color: '#388e3c' },
  { label: 'PowerPoint', icon: <PptIcon sx={{ fontSize: 40 }} />, color: '#f57c00' },
  { label: 'ID Cards', icon: <IdIcon sx={{ fontSize: 40 }} />, color: '#7b1fa2' },
];

export default function HomePage() {
  const navigate = useNavigate();
  const { isAuthenticated } = useAuth();
  const [uploading, setUploading] = useState(false);

  const onDrop = async (acceptedFiles) => {
    if (acceptedFiles.length === 0) return;

    setUploading(true);
    try {
      const orderResponse = await orderAPI.create({});
      const orderId = orderResponse.data.id;

      await fileAPI.upload(orderId, acceptedFiles);

      toast.success(`${acceptedFiles.length} file(s) uploaded`);
      navigate(`/configure/${orderId}`);
    } catch (err) {
      toast.error(err.message || 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'application/pdf': ['.pdf'],
      'application/msword': ['.doc'],
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': ['.docx'],
      'application/vnd.ms-powerpoint': ['.ppt'],
      'application/vnd.openxmlformats-officedocument.presentationml.presentation': ['.pptx'],
      'application/vnd.ms-excel': ['.xls'],
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'],
      'image/jpeg': ['.jpg', '.jpeg'],
      'image/png': ['.png'],
      'image/webp': ['.webp'],
    },
    maxSize: 104857600,
  });

  return (
    <Box>
      {/* Hero Section */}
      <Box textAlign="center" mb={6}>
        <Typography variant="h3" sx={{ fontWeight: 700, mb: 2 }}>
          Print Made Simple
        </Typography>
        <Typography variant="h6" color="text.secondary" sx={{ mb: 4, maxWidth: 600, mx: 'auto' }}>
          Upload your files, configure print settings, and get them printed automatically.
          No technical knowledge required.
        </Typography>
      </Box>

      {/* Upload Area */}
      <Paper
        {...getRootProps()}
        sx={{
          p: 6,
          mb: 4,
          border: '2px dashed',
          borderColor: isDragActive ? 'primary.main' : 'grey.300',
          bgcolor: isDragActive ? 'primary.50' : 'background.paper',
          cursor: 'pointer',
          transition: 'all 0.2s',
          textAlign: 'center',
          '&:hover': {
            borderColor: 'primary.main',
            bgcolor: 'primary.50',
          },
        }}
      >
        <input {...getInputProps()} />
        <UploadIcon sx={{ fontSize: 64, color: 'primary.main', mb: 2 }} />
        <Typography variant="h5" sx={{ fontWeight: 600, mb: 1 }}>
          {isDragActive ? 'Drop your files here' : 'Drag & Drop Files'}
        </Typography>
        <Typography color="text.secondary" sx={{ mb: 2 }}>
          or click to browse files
        </Typography>
        <Typography variant="caption" color="text.secondary">
          Supports PDF, DOC, DOCX, PPT, PPTX, XLS, XLSX, JPG, PNG, WEBP (Max 100MB)
        </Typography>
      </Paper>

      {/* Quick Actions */}
      <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
        Quick Start
      </Typography>
      <Grid container spacing={2}>
        {quickActions.map((action) => (
          <Grid item xs={6} md={3} key={action.label}>
            <Card
              sx={{
                cursor: 'pointer',
                textAlign: 'center',
                transition: 'transform 0.2s',
                '&:hover': { transform: 'translateY(-4px)' },
              }}
            >
              <CardContent sx={{ py: 3 }}>
                <Box sx={{ color: action.color, mb: 1 }}>{action.icon}</Box>
                <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                  {action.label}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Features */}
      <Box mt={6}>
        <Typography variant="h5" sx={{ fontWeight: 600, mb: 3, textAlign: 'center' }}>
          Why Use Patel AutoPrint?
        </Typography>
        <Grid container spacing={3}>
          {[
            { title: 'Live Preview', desc: 'See exactly how your document will print before ordering' },
            { title: 'Instant Pricing', desc: 'Get real-time price updates as you configure settings' },
            { title: 'Smart Settings', desc: 'Auto-detect orientation, color pages, and paper size' },
            { title: 'Quick Reorder', desc: 'Print again with one click using saved presets' },
          ].map((feature) => (
            <Grid item xs={12} md={3} key={feature.title}>
              <Card sx={{ height: '100%' }}>
                <CardContent>
                  <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
                    {feature.title}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {feature.desc}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </Box>
    </Box>
  );
}

