import { Box, Container, AppBar, Toolbar, Typography, IconButton, Menu, MenuItem, Button } from '@mui/material';
import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';

export default function CustomerLayout() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [anchorEl, setAnchorEl] = useState(null);

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'background.default' }}>
      <AppBar position="static" sx={{ bgcolor: 'white', color: 'text.primary', boxShadow: 1 }}>
        <Toolbar>
          <Typography
            variant="h6"
            sx={{ fontWeight: 700, cursor: 'pointer', color: 'primary.main' }}
            onClick={() => navigate('/')}
          >
            Patel AutoPrint
          </Typography>

          <Box sx={{ flexGrow: 1 }} />

          {user ? (
            <>
              <Button
                color="inherit"
                onClick={() => navigate(user.role === 'SHOP_OWNER' || user.role === 'MANAGER' || user.role === 'OPERATOR' ? '/admin' : '/')}
              >
                {user.role === 'SHOP_OWNER' || user.role === 'MANAGER' || user.role === 'OPERATOR' ? 'Dashboard' : 'My Orders'}
              </Button>
              <Button color="inherit" onClick={logout}>
                Logout
              </Button>
            </>
          ) : (
            <Button color="inherit" onClick={() => navigate('/login')}>
              Login
            </Button>
          )}
        </Toolbar>
      </AppBar>

      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Outlet />
      </Container>
    </Box>
  );
}

