export type FileType = 'pdf' | 'docx' | 'pptx' | 'xlsx' | 'jpg' | 'png' | 'jpeg' | 'webp';

export type PaperSize = 'A4' | 'A3' | 'Legal' | 'Letter';

export type Orientation = 'auto' | 'portrait' | 'landscape';

export type ColorMode = 'bw' | 'color';

export type PrintStyle = 'single' | 'duplex';

export type NupLayout = 1 | 2 | 4 | 6 | 8 | 9 | 16;

export type SlidePerPage = 1 | 2 | 3 | 4 | 6 | 9;

export type ImagePerPage = 1 | 2 | 4 | 6 | 9 | 16;

export type ImageFit = 'fit' | 'fill' | 'stretch' | 'aspect';

export type PageRange = 'all' | 'odd' | 'even' | 'custom';

export type FlipDirection = 'long-edge' | 'short-edge';

export type OrderStatus = 'pending' | 'approved' | 'printing' | 'completed' | 'rejected';

export type PaymentStatus = 'unpaid' | 'paid' | 'refunded';

export type IdCardType = 'aadhaar' | 'pan' | 'driving-licence' | 'voter-id' | 'passport';

export type IdCardLayout = 'front-back' | 'single';

export interface PrintSection {
  id: string;
  pageStart: number;
  pageEnd: number;
  colorMode: ColorMode;
  printStyle: PrintStyle;
  pagesPerSheet: NupLayout;
}

export interface IdCardConfig {
  cardType: IdCardType;
  layout: IdCardLayout;
  hasFront: boolean;
  hasBack: boolean;
}

export interface ImageLayoutConfig {
  photosPerPage: ImagePerPage;
  fit: ImageFit;
  borderless: boolean;
  spacing: number;
  margins: boolean;
  autoRotate: boolean;
  centerImage: boolean;
}

export interface SlideLayoutConfig {
  slidesPerPage: SlidePerPage;
}

export interface FilePrintSettings {
  paperSize: PaperSize;
  orientation: Orientation;
  colorMode: ColorMode;
  printStyle: PrintStyle;
  copies: number;
  pageRange: PageRange;
  customPageRange?: string;
  pagesPerSheet: NupLayout;
  sections: PrintSection[];
  flipDirection?: FlipDirection;
  idCardConfig?: IdCardConfig;
  imageLayout?: ImageLayoutConfig;
  slideLayout?: SlideLayoutConfig;
}

export interface UploadedFile {
  id: string;
  orderId: string;
  originalName: string;
  storagePath: string;
  fileType: FileType;
  size: number;
  pageCount: number;
  colorPageCount: number;
  orientation: Orientation;
  suggestedPaperSize: PaperSize;
  hasMixedOrientation: boolean;
  settings: FilePrintSettings;
  previewUrls: string[];
}

export interface Order {
  id: string;
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  files: UploadedFile[];
  totalPages: number;
  totalColorPages: number;
  totalSheets: number;
  totalPrice: number;
  status: OrderStatus;
  paymentStatus: PaymentStatus;
  paymentMethod?: string;
  discount: number;
  tax: number;
  notes: string;
  createdAt: string;
  updatedAt: string;
  approvedAt?: string;
  printedAt?: string;
}

export interface PriceBreakdown {
  basePrice: number;
  colorSurcharge: number;
  duplexDiscount: number;
  nupDiscount: number;
  copiesMultiplier: number;
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  breakdown: {
    label: string;
    amount: number;
  }[];
}

export interface FileAnalysis {
  pageCount: number;
  colorPageCount: number;
  blankPageCount: number;
  landscapePageCount: number;
  orientation: Orientation;
  hasMixedOrientation: boolean;
  suggestedPaperSize: PaperSize;
  estimatedSheets: number;
  estimatedCost: number;
  pages: PageAnalysis[];
}

export interface PageAnalysis {
  pageNumber: number;
  isColor: boolean;
  isBlank: boolean;
  isLandscape: boolean;
}

export interface AdminSearchResult {
  orders: Order[];
  total: number;
  query: string;
}

export interface PrintJob {
  id: string;
  orderId: string;
  fileId: string;
  sectionId?: string;
  pages: number[];
  colorMode: ColorMode;
  printStyle: PrintStyle;
  paperSize: PaperSize;
  flipDirection: FlipDirection;
  copies: number;
  status: string;
  assignedPrinter?: string;
  pdfPath?: string;
}

export const PAPER_SIZES: Record<PaperSize, { width: number; height: number; label: string }> = {
