display.text:
import express from 'express';
import cors from 'cors';
import path from 'path';
import multer from 'multer';
import { v4 as uuidv4 } from 'uuid';
import { store } from './store';
import { analyzeFile } from './services/analyzer';
import { calculatePrice, calculateSheets } from './services/pricing';
import { determineFlipDirection } from './services/duplex';
import { routeJob } from './services/printer';
import {
  Order,
  UploadedFile,
  FilePrintSettings,
  OrderStatus,
  PaymentStatus,
  PrintJob,
  FileType,
  FileAnalysis,
} from '../shared/types';
import fs from 'fs';

const app = express();
const PORT = process.env.PORT || 3000;

app.use(cors());
app.use(express.json({ limit: '50mb' }));
app.use(express.static(path.join(__dirname, '../client')));
app.use('/uploads', express.static(path.join(__dirname, '../../uploads')));

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    const uploadDir = path.join(__dirname, '../../uploads');
    if (!fs.existsSync(uploadDir)) {
      fs.mkdirSync(uploadDir, { recursive: true });
    }
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const ext = path.extname(file.originalname);
    cb(null, `${uuidv4()}${ext}`);
  },
});

const upload = multer({
  storage,
  limits: { fileSize: 100 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    const allowed: Record<string, FileType> = {
      'application/pdf': 'pdf',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
      'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
      'image/jpeg': 'jpeg',
      'image/png': 'png',
      'image/jpg': 'jpg',
      'image/webp': 'webp',
    };
    if (allowed[file.mimetype]) {
      cb(null, true);
    } else {
      cb(new Error('Unsupported file type'));
    }
  },
});

const mimeToType: Record<string, FileType> = {
  'application/pdf': 'pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'image/jpeg': 'jpeg',
  'image/png': 'png',
  'image/jpg': 'jpg',
  'image/webp': 'webp',
};

app.post('/api/upload', upload.array('files', 50), async (req, res) => {
  try {
    const files = req.files as Express.Multer.File[];
    const customerName = req.body.customerName || 'Unknown';
    const customerEmail = req.body.customerEmail || '';
    const customerPhone = req.body.customerPhone || '';

    const orderId = uuidv4();
    const uploadedFiles: UploadedFile[] = [];

    for (const file of files) {
      const fileId = uuidv4();
      const fileType = mimeToType[file.mimetype] || 'pdf';
      const analysis: FileAnalysis = await analyzeFile(file.path, fileType);

      const settings: FilePrintSettings = {
        paperSize: analysis.suggestedPaperSize,
        orientation: 'auto',
        colorMode: analysis.colorPageCount > 0 ? 'color' : 'bw',
        printStyle: 'single',
        copies: 1,
        pageRange: 'all',
        pagesPerSheet: 1,
        sections: [],
      };

      if (fileType === 'pptx') {
        settings.slideLayout = { slidesPerPage: 1 };
      }
      if (['jpg', 'jpeg', 'png', 'webp'].includes(fileType)) {
        settings.imageLayout = { photosPerPage: 1, fit: 'fit', borderless: false, spacing: 2, margins: true, autoRotate: true, centerImage: true };
      }

      const fileRecord: UploadedFile = {
        id: fileId,
        orderId,
        originalName: file.originalname,
        storagePath: file.path,
        fileType,
        size: file.size,
        pageCount: analysis.pageCount,
        colorPageCount: analysis.colorPageCount,
        orientation: analysis.orientation,
        suggestedPaperSize: analysis.suggestedPaperSize,
        hasMixedOrientation: analysis.hasMixedOrientation,
        settings,
        previewUrls: [],
      };

      uploadedFiles.push(fileRecord);
    }

    let totalPages = 0;
    let totalColorPages = 0;
    let totalSheets = 0;

    for (const f of uploadedFiles) {
      totalPages += f.pageCount;
      totalColorPages += f.colorPageCount;
      const s = calculateSheets(f.pageCount, f.colorPageCount, f.settings);
      totalSheets += s.totalSheets;
    }

    const order: Order = {
      id: orderId,
      customerName,
      customerEmail,
      customerPhone,
      files: uploadedFiles,
      totalPages,
      totalColorPages,
      totalSheets,
      totalPrice: 0,
      status: 'pending',
      paymentStatus: 'unpaid',
      discount: 0,
      tax: 0,
      notes: '',
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    store.createOrder(order);
    res.json({ success: true, order });
  } catch (err: any) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.put('/api/orders/:orderId/settings', (req, res) => {
  try {
    const { orderId } = req.params;
    const { fileId, settings } = req.body;

    const order = store.getOrder(orderId);
    if (!order) {
      return res.status(404).json({ success: false, error: 'Order not found' });
    }

    const file = order.files.find((f) => f.id === fileId);
    if (!file) {
      return res.status(404).json({ success: false, error: 'File not found' });
    }

    const deepMerge = (target: any, source: any) => {
      for (const key of Object.keys(source)) {
        if (source[key] && typeof source[key] === 'object' && !Array.isArray(source[key])) {
          target[key] = target[key] || {};
          deepMerge(target[key], source[key]);
        } else {
          target[key] = source[key];
        }
      }
    };

    deepMerge(file.settings, settings);
    file.settings.flipDirection = determineFlipDirection(
      file.orientation,
      file.settings.paperSize,
      file.settings.pagesPerSheet,
      file.settings.orientation
    );

    let totalSheets = 0;
    let totalPrice = 0;
    for (const f of order.files) {
      const s = calculateSheets(f.pageCount, f.colorPageCount, f.settings);
      totalSheets += s.totalSheets;
      const price = calculatePrice(s.totalSheets, s.colorSheets, f.settings);
      totalPrice += price.total;
    }

    order.totalSheets = totalSheets;
    order.totalPrice = totalPrice;
    order.updatedAt = new Date().toISOString();

    store.updateOrder(orderId, {
      totalSheets,
      totalPrice,
      updatedAt: order.updatedAt,
    });

    res.json({ success: true, order });
  } catch (err: any) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get('/api/orders/:orderId', (req, res) => {
  const order = store.getOrder(req.params.orderId);
  if (!order) {
    return res.status(404).json({ success: false, error: 'Order not found' });
  }
  res.json({ success: true, order });
});

app.post('/api/orders/:orderId/confirm', (req, res) => {
  try {
    const { orderId } = req.params;
    const { paymentMethod } = req.body;

    const order = store.getOrder(orderId);
    if (!order) {
      return res.status(404).json({ success: false, error: 'Order not found' });
    }

    store.updateOrder(orderId, {
      status: 'pending',
      paymentStatus: 'paid',
      paymentMethod,
      updatedAt: new Date().toISOString(),
    });

    for (const file of order.files) {
      const job: PrintJob = {
        id: uuidv4(),
        orderId,
        fileId: file.id,
        pages: Array.from({ length: file.pageCount }, (_, i) => i + 1),
        colorMode: file.settings.colorMode,
        printStyle: file.settings.printStyle,
        paperSize: file.settings.paperSize,
        flipDirection: file.settings.flipDirection || 'long-edge',
        copies: file.settings.copies,
        status: 'pending',
      };

      const routed = routeJob(job);
      store.addPrintJob(routed);

      if (file.settings.sections.length > 0) {
        for (const section of file.settings.sections) {
          const sectionJob: PrintJob = {
            id: uuidv4(),
            orderId,
            fileId: file.id,
            sectionId: section.id,
            pages: Array.from({ length: section.pageEnd - section.pageStart + 1 }, (_, i) => section.pageStart + i),
            colorMode: section.colorMode,
            printStyle: section.printStyle,
            paperSize: file.settings.paperSize,
            flipDirection: determineFlipDirection(
              file.orientation,
              file.settings.paperSize,
              section.pagesPerSheet
            ),
            copies: file.settings.copies,
            status: 'pending',
          };
          const routedSection = routeJob(sectionJob);
          store.addPrintJob(routedSection);
        }
      }
    }

    res.json({ success: true, order: store.getOrder(orderId) });
  } catch (err: any) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get('/api/admin/orders', (req, res) => {
  const { search, status } = req.query;
  let orders = store.getAllOrders();

  if (search) {
    orders = store.searchOrders(search as string);
  }

  if (status) {
    orders = orders.filter((o) => o.status === status);
  }

  res.json({ success: true, orders });
});

app.put('/api/admin/orders/:orderId/status', (req, res) => {
  try {
    const { orderId } = req.params;
    const { status } = req.body;

    const order = store.updateOrder(orderId, {
      status: status as OrderStatus,
      ...(status === 'approved' ? { approvedAt: new Date().toISOString() } : {}),
      ...(status === 'completed' ? { printedAt: new Date().toISOString() } : {}),
    });

    if (!order) {
      return res.status(404).json({ success: false, error: 'Order not found' });
    }

    const jobs = store.getPrintJobsForOrder(orderId);
    for (const job of jobs) {
      if (status === 'approved') {
        store.updatePrintJob(job.id, { status: 'printing' });
      } else if (status === 'completed') {
        store.updatePrintJob(job.id, { status: 'completed' });
      } else if (status === 'rejected') {
        store.updatePrintJob(job.id, { status: 'rejected' });
      }
    }

    res.json({ success: true, order });
  } catch (err: any) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get('/api/admin/orders/:orderId/print-jobs', (req, res) => {
  const jobs = store.getPrintJobsForOrder(req.params.orderId);
  res.json({ success: true, jobs });
});

app.post('/api/orders/:orderId/reprint', (req, res) => {
  try {
    const { orderId } = req.params;
    const order = store.getOrder(orderId);
    if (!order) {
      return res.status(404).json({ success: false, error: 'Order not found' });
    }

    const existingJobs = store.getPrintJobsForOrder(orderId);
    for (const job of existingJobs) {
      store.updatePrintJob(job.id, { status: 'pending' });
      const routed = routeJob({ ...job, status: 'printing' });
      store.updatePrintJob(job.id, { status: 'printing', assignedPrinter: routed.assignedPrinter });
    }

    store.updateOrder(orderId, { status: 'printing', updatedAt: new Date().toISOString() });
    res.json({ success: true, message: 'Reprint initiated' });
  } catch (err: any) {
    res.status(500).json({ success: false, error: err.message });
  }
});

app.get('/api/orders/:orderId/price', (req, res) => {
  const order = store.getOrder(req.params.orderId);
  if (!order) {
    return res.status(404).json({ success: false, error: 'Order not found' });
  }

  const breakdowns = order.files.map((f) => {
    const s = calculateSheets(f.pageCount, f.colorPageCount, f.settings);
    const price = calculatePrice(s.totalSheets, s.colorSheets, f.settings);
    return { fileId: f.id, fileName: f.originalName, ...s, price };
  });

  res.json({ success: true, breakdowns, total: order.totalPrice });
});

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

app.listen(PORT, () => {
  console.log(`Print Shop Server running on http://localhost:${PORT}`);
});

