import { Order, PrintJob } from '../shared/types';
import * as fs from 'fs';
import * as path from 'path';

const DATA_DIR = path.join(__dirname, '../../data');
const ORDERS_FILE = path.join(DATA_DIR, 'orders.json');
const JOBS_FILE = path.join(DATA_DIR, 'jobs.json');

function ensureDataDir() {
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }
}

function readJSON(filePath: string): any[] {
  try {
    if (fs.existsSync(filePath)) {
      const data = fs.readFileSync(filePath, 'utf-8');
      return JSON.parse(data);
    }
  } catch { }
  return [];
}

function writeJSON(filePath: string, data: any[]) {
  ensureDataDir();
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
}

class Store {
  private orders: Map<string, Order> = new Map();
  private printJobs: Map<string, PrintJob> = new Map();

  constructor() {
    this.load();
  }

  private load() {
    const orders = readJSON(ORDERS_FILE);
    for (const o of orders) {
      this.orders.set(o.id, o);
    }
    const jobs = readJSON(JOBS_FILE);
    for (const j of jobs) {
      this.printJobs.set(j.id, j);
    }
  }

  private saveOrders() {
    writeJSON(ORDERS_FILE, Array.from(this.orders.values()));
  }

  private saveJobs() {
    writeJSON(JOBS_FILE, Array.from(this.printJobs.values()));
  }

  createOrder(order: Order): Order {
    this.orders.set(order.id, order);
    this.saveOrders();
    return order;
  }

  getOrder(id: string): Order | undefined {
    return this.orders.get(id);
  }

  getAllOrders(): Order[] {
    return Array.from(this.orders.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  updateOrder(id: string, updates: Partial<Order>): Order | undefined {
    const order = this.orders.get(id);
    if (!order) return undefined;
    Object.assign(order, updates, { updatedAt: new Date().toISOString() });
    this.saveOrders();
    return order;
  }

  searchOrders(query: string): Order[] {
    const q = query.toLowerCase();
    return this.getAllOrders().filter(
      (o) =>
        o.id.toLowerCase().includes(q) ||
        o.customerName.toLowerCase().includes(q) ||
        o.customerPhone.includes(q) ||
        o.customerEmail.toLowerCase().includes(q)
    );
  }

  addPrintJob(job: PrintJob): PrintJob {
    this.printJobs.set(job.id, job);
    this.saveJobs();
    return job;
  }

  getPrintJobsForOrder(orderId: string): PrintJob[] {
    return Array.from(this.printJobs.values()).filter((j) => j.orderId === orderId);
  }

  updatePrintJob(id: string, updates: Partial<PrintJob>): PrintJob | undefined {
    const job = this.printJobs.get(id);
    if (!job) return undefined;
    Object.assign(job, updates);
    this.saveJobs();
    return job;
  }
}

export const store = new Store();

