import { useState, useCallback } from 'react';
import {
  Container,
  Box,
  Stepper,
  Step,
  StepLabel,
  Typography,
  Paper,
  Button,
  TextField,
  Grid,
  Card,
  CardContent,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  RadioGroup,
  FormControlLabel,
  Radio,
  Divider,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Alert,
  CircularProgress,
  IconButton,
} from '@mui/material';
import {
  CloudUpload,
  Delete,
  Receipt,
  CheckCircle,
  ShoppingCart,
  NavigateNext,
  NavigateBefore,
  ContentCopy,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../services/api';

const steps = ['Upload Files', 'Configure Settings', 'Review & Pay', 'Order Confirmed'];

const paperSizes = ['A4', 'A3', 'A5', 'Letter', 'Legal'];
const orientations = ['portrait', 'landscape'];
const colorModes = ['color', 'bw'];
const pagesPerSheetOptions = [1, 2, 4, 6, 9, 16];

function Step1Upload({ files, setFiles, customerInfo, setCustomerInfo }) {
  const [uploading, setUploading] = useState(false);

  const handleDrop = useCallback((e) => {
    e.preventDefault();
    const droppedFiles = Array.from(e.dataTransfer.files);
    setFiles((prev) => [...prev, ...droppedFiles]);
  }, [setFiles]);

  const handleFileInput = (e) => {
    const selectedFiles = Array.from(e.target.files);
    setFiles((prev) => [...prev, ...selectedFiles]);
  };

  const removeFile = (index) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  };

  return (
    <Box>
      <Typography variant="h6" gutterBottom>Upload Your Files</Typography>
      <Paper
        onDrop={handleDrop}
        onDragOver={(e) => e.preventDefault()}
        sx={{
          p: 4,
          textAlign: 'center',
          border: '2px dashed #bdbdbd',
          cursor: 'pointer',
          mb: 3,
          '&:hover': { borderColor: 'primary.main', bgcolor: 'action.hover' },
        }}
        onClick={() => document.getElementById('file-input').click()}
      >
        <input
          id="file-input"
          type="file"
          multiple
          hidden
          onChange={handleFileInput}
          accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png"
        />
        <CloudUpload sx={{ fontSize: 48, color: 'text.secondary', mb: 1 }} />
        <Typography variant="h6" color="text.secondary">
          Drag & drop files here or click to browse
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Supports PDF, DOC, DOCX, TXT, JPG, PNG
        </Typography>
      </Paper>

      {files.length > 0 && (
        <Box sx={{ mb: 3 }}>
          <Typography variant="subtitle1" gutterBottom>Selected Files ({files.length})</Typography>
          {files.map((file, index) => (
            <Paper key={index} sx={{ p: 1.5, mb: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <Typography variant="body2">{file.name}</Typography>
              <Typography variant="caption" color="text.secondary">
                {(file.size / 1024).toFixed(1)} KB
                <IconButton size="small" onClick={() => removeFile(index)} sx={{ ml: 1 }}>
                  <Delete fontSize="small" />
                </IconButton>
              </Typography>
            </Paper>
          ))}
        </Box>
      )}

      <Divider sx={{ my: 3 }} />

      <Typography variant="h6" gutterBottom>Customer Information</Typography>
      <Grid container spacing={2}>
        <Grid size={{ xs: 12, sm: 6 }}>
          <TextField
            fullWidth
            label="Your Name"
            value={customerInfo.name}
            onChange={(e) => setCustomerInfo({ ...customerInfo, name: e.target.value })}
            required
          />
        </Grid>
        <Grid size={{ xs: 12, sm: 6 }}>
          <TextField
            fullWidth
            label="Phone Number"
            value={customerInfo.phone}
            onChange={(e) => setCustomerInfo({ ...customerInfo, phone: e.target.value })}
            required
          />
        </Grid>
        <Grid size={{ xs: 12 }}>
          <TextField
            fullWidth
            label="Email (optional)"
            value={customerInfo.email}
            onChange={(e) => setCustomerInfo({ ...customerInfo, email: e.target.value })}
          />
        </Grid>
      </Grid>
    </Box>
  );
}

function Step2Configure({ files, fileSettings, setFileSettings }) {
  const [activeTab, setActiveTab] = useState(0);

  const updateSetting = (fileIndex, key, value) => {
    setFileSettings((prev) => ({
      ...prev,
      [fileIndex]: {
        ...prev[fileIndex],
        [key]: value,
      },
    }));
  };

  const getDefaultSettings = (index) => ({
    paperSize: 'A4',
    orientation: 'portrait',
    colorMode: 'bw',
    duplex: false,
    copies: 1,
    pagesPerSheet: 1,
    pageRange: '',
    ...(fileSettings[index] || {}),
  });

  return (
    <Box>
      <Typography variant="h6" gutterBottom>Configure Print Settings</Typography>
      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}>
        {files.map((file, index) => (
          <Button
            key={index}
            onClick={() => setActiveTab(index)}
            variant={activeTab === index ? 'contained' : 'text'}
            sx={{ minWidth: 120, mb: 1 }}
          >
            {file.name.substring(0, 20)}
          </Button>
        ))}
      </Box>

      {files.length > 0 && (
        <Card>
          <CardContent>
            <Typography variant="subtitle1" gutterBottom>
              Settings for: {files[activeTab]?.name}
            </Typography>
            <Grid container spacing={2}>
              <Grid size={{ xs: 12, sm: 6 }}>
                <FormControl fullWidth>
                  <InputLabel>Paper Size</InputLabel>
                  <Select
                    value={getDefaultSettings(activeTab).paperSize}
                    label="Paper Size"
                    onChange={(e) => updateSetting(activeTab, 'paperSize', e.target.value)}
                  >
                    {paperSizes.map((size) => (
                      <MenuItem key={size} value={size}>{size}</MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <FormControl fullWidth>
                  <InputLabel>Orientation</InputLabel>
                  <Select
                    value={getDefaultSettings(activeTab).orientation}
                    label="Orientation"
                    onChange={(e) => updateSetting(activeTab, 'orientation', e.target.value)}
                  >
                    {orientations.map((o) => (
                      <MenuItem key={o} value={o}>{o.charAt(0).toUpperCase() + o.slice(1)}</MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <FormControl fullWidth>
                  <InputLabel>Color Mode</InputLabel>
                  <Select
                    value={getDefaultSettings(activeTab).colorMode}
                    label="Color Mode"
                    onChange={(e) => updateSetting(activeTab, 'colorMode', e.target.value)}
                  >
                    <MenuItem value="color">Color</MenuItem>
                    <MenuItem value="bw">Black & White</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <TextField
                  fullWidth
                  type="number"
                  label="Copies"
                  value={getDefaultSettings(activeTab).copies}
                  onChange={(e) => updateSetting(activeTab, 'copies', parseInt(e.target.value) || 1)}
                  inputProps={{ min: 1 }}
                />
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <FormControl fullWidth>
                  <InputLabel>Pages Per Sheet</InputLabel>
                  <Select
                    value={getDefaultSettings(activeTab).pagesPerSheet}
                    label="Pages Per Sheet"
                    onChange={(e) => updateSetting(activeTab, 'pagesPerSheet', e.target.value)}
                  >
                    {pagesPerSheetOptions.map((n) => (
                      <MenuItem key={n} value={n}>{n}</MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <TextField
                  fullWidth
                  label="Page Range (e.g. 1-5, 8)"
                  value={getDefaultSettings(activeTab).pageRange}
                  onChange={(e) => updateSetting(activeTab, 'pageRange', e.target.value)}
                  placeholder="Leave empty for all pages"
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <FormControlLabel
                  control={
                    <RadioGroup
                      row
                      value={getDefaultSettings(activeTab).duplex ? 'duplex' : 'simplex'}
                      onChange={(e) => updateSetting(activeTab, 'duplex', e.target.value === 'duplex')}
                    >
                      <FormControlLabel value="simplex" control={<Radio />} label="Single-sided" />
                      <FormControlLabel value="duplex" control={<Radio />} label="Double-sided (Duplex)" />
                    </RadioGroup>
                  }
                  label=""
                />
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      )}
    </Box>
  );
}

function Step3Review({ order, paymentMethod, setPaymentMethod }) {
  return (
    <Box>
      <Typography variant="h6" gutterBottom>Review & Payment</Typography>

      {order?.breakdowns && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="subtitle1" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
              <Receipt sx={{ mr: 1 }} /> Price Breakdown
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>File</TableCell>
                    <TableCell align="right">Pages</TableCell>
                    <TableCell align="right">Copies</TableCell>
                    <TableCell align="right">Amount</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {order.breakdowns.map((b, i) => (
                    <TableRow key={i}>
                      <TableCell>{b.fileName}</TableCell>
                      <TableCell align="right">{b.pages}</TableCell>
                      <TableCell align="right">{b.copies}</TableCell>
                      <TableCell align="right">{'\u20B9'}{b.amount?.toFixed(2)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
            <Divider sx={{ my: 2 }} />
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography variant="h6">Total</Typography>
              <Typography variant="h6">{'\u20B9'}{order.total?.toFixed(2)}</Typography>
            </Box>
          </CardContent>
        </Card>
      )}

      <Typography variant="subtitle1" gutterBottom>Payment Method</Typography>
      <Paper sx={{ p: 3 }}>
        <RadioGroup
          value={paymentMethod}
          onChange={(e) => setPaymentMethod(e.target.value)}
        >
          <FormControlLabel value="cash" control={<Radio />} label="Cash" />
          <FormControlLabel value="card" control={<Radio />} label="Card" />
          <FormControlLabel value="upi" control={<Radio />} label="UPI" />
          <FormControlLabel value="online" control={<Radio />} label="Online Transfer" />
        </RadioGroup>
      </Paper>
    </Box>
  );
}

function Step4Confirmation({ order }) {
  const [copied, setCopied] = useState(false);

  const copyOrderId = () => {
    navigator.clipboard.writeText(order._id);
    setCopied(true);
    toast.success('Order ID copied!');
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Box sx={{ textAlign: 'center', py: 4 }}>
      <CheckCircle sx={{ fontSize: 80, color: 'success.main', mb: 2 }} />
      <Typography variant="h5" gutterBottom>Order Placed Successfully!</Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        Your order has been received and is being processed.
      </Typography>

      <Card sx={{ maxWidth: 400, mx: 'auto', mb: 3 }}>
        <CardContent>
          <Typography variant="body2" color="text.secondary">Order ID</Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1 }}>
            <Typography variant="h6" sx={{ fontFamily: 'monospace' }}>
              {order?._id?.substring(0, 12)}...
            </Typography>
            <IconButton onClick={copyOrderId} size="small">
              {copied ? <CheckCircle fontSize="small" /> : <ContentCopy fontSize="small" />}
            </IconButton>
          </Box>
          <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
            Status: <strong>{order?.status}</strong>
          </Typography>
        </CardContent>
      </Card>

      <Alert severity="info" sx={{ maxWidth: 400, mx: 'auto', mb: 2 }}>
        Save your Order ID to track the status. You can also use the Order Tracking page.
      </Alert>
    </Box>
  );
}

export default function CustomerPortal() {
  const [activeStep, setActiveStep] = useState(0);
  const [files, setFiles] = useState([]);
  const [customerInfo, setCustomerInfo] = useState({ name: '', phone: '', email: '' });
  const [fileSettings, setFileSettings] = useState({});
  const [uploadedOrder, setUploadedOrder] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('cash');
  const [loading, setLoading] = useState(false);

  const handleUpload = async () => {
    if (files.length === 0) {
      toast.error('Please select files to upload');
      return;
    }
    if (!customerInfo.name || !customerInfo.phone) {
      toast.error('Please fill in name and phone number');
      return;
    }
    setLoading(true);
    try {
      const formData = new FormData();
      files.forEach((file) => formData.append('files', file));
      formData.append('customerName', customerInfo.name);
      formData.append('customerPhone', customerInfo.phone);
      formData.append('customerEmail', customerInfo.email);

      const result = await api.post('/upload', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      if (result.success) {
        setUploadedOrder(result.order);
        toast.success('Files uploaded successfully!');
        setActiveStep(1);
      }
    } catch (err) {
      toast.error(err.message || 'Upload failed');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveSettings = async () => {
    if (!uploadedOrder) return;
    setLoading(true);
    try {
      for (const [fileIndex, settings] of Object.entries(fileSettings)) {
        const fileId = uploadedOrder.files?.[fileIndex]?._id;
        if (fileId) {
          await api.put(`/orders/${uploadedOrder._id}/settings`, {
            fileId,
            settings,
          });
        }
      }
      toast.success('Settings saved!');
      setActiveStep(2);
    } catch (err) {
      toast.error(err.message || 'Failed to save settings');
    } finally {
      setLoading(false);
    }
  };

  const handleGetPrice = async () => {
    if (!uploadedOrder) return null;
    setLoading(true);
    try {
      const result = await api.get(`/orders/${uploadedOrder._id}/price`);
      if (result.success) {
        setUploadedOrder((prev) => ({
          ...prev,
          breakdowns: result.breakdowns,
          total: result.total,
        }));
        return result;
      }
    } catch (err) {
      toast.error(err.message || 'Failed to get price');
    } finally {
      setLoading(false);
    }
    return null;
  };

  const handlePlaceOrder = async () => {
    if (!uploadedOrder || !paymentMethod) {
      toast.error('Please select a payment method');
      return;
    }
    setLoading(true);
    try {
      const result = await api.post(`/orders/${uploadedOrder._id}/confirm`, {
        paymentMethod,
      });
      if (result.success) {
        setUploadedOrder(result.order);
        toast.success('Order placed successfully!');
        setActiveStep(3);
      }
    } catch (err) {
      toast.error(err.message || 'Failed to place order');
    } finally {
      setLoading(false);
    }
  };

  const handleNext = async () => {
    if (activeStep === 0) {
      await handleUpload();
    } else if (activeStep === 1) {
      await handleSaveSettings();
    } else if (activeStep === 2) {
      await handleGetPrice();
      await handlePlaceOrder();
    }
  };

  const handleBack = () => {
    setActiveStep((prev) => prev - 1);
  };

  const handleNewOrder = () => {
    setActiveStep(0);
    setFiles([]);
    setCustomerInfo({ name: '', phone: '', email: '' });
    setFileSettings({});
    setUploadedOrder(null);
    setPaymentMethod('cash');
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }}>
      <Typography variant="h4" align="center" gutterBottom>
        Patel AutoPrint
      </Typography>
      <Typography variant="body1" align="center" color="text.secondary" sx={{ mb: 4 }}>
        Print Shop - Self Service Portal
      </Typography>

      <Stepper activeStep={activeStep} sx={{ mb: 4 }}>
        {steps.map((label) => (
          <Step key={label}>
            <StepLabel>{label}</StepLabel>
          </Step>
        ))}
      </Stepper>

      <Paper sx={{ p: 3, minHeight: 400 }}>
        {activeStep === 0 && (
          <Step1Upload
            files={files}
            setFiles={setFiles}
            customerInfo={customerInfo}
            setCustomerInfo={setCustomerInfo}
          />
        )}
        {activeStep === 1 && (
          <Step2Configure
            files={uploadedOrder?.files || files}
            fileSettings={fileSettings}
            setFileSettings={setFileSettings}
          />
        )}
        {activeStep === 2 && (
          <Step3Review
            order={uploadedOrder}
            paymentMethod={paymentMethod}
            setPaymentMethod={setPaymentMethod}
          />
        )}
        {activeStep === 3 && (
          <Step4Confirmation order={uploadedOrder} />
        )}

        <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 3 }}>
          <Button
            disabled={activeStep === 0 || activeStep === 3 || loading}
            onClick={handleBack}
            startIcon={<NavigateBefore />}
          >
            Back
          </Button>
          {activeStep < 3 && (
            <Button
              variant="contained"
              onClick={handleNext}
              disabled={loading}
              endIcon={loading ? <CircularProgress size={20} /> : <NavigateNext />}
            >
              {activeStep === 0 ? 'Upload & Analyze' :
               activeStep === 1 ? 'Review & Price' :
               'Place Order'}
            </Button>
          )}
          {activeStep === 3 && (
            <Button variant="contained" onClick={handleNewOrder} startIcon={<ShoppingCart />}>
              Place New Order
            </Button>
          )}
        </Box>
      </Paper>
    </Container>
  );
}

import { useState } from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import {
  Box,
  Drawer,
  AppBar,
  Toolbar,
  Typography,
  List,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  IconButton,
  Button,
  Divider,
  Avatar,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import {
  Menu as MenuIcon,
  Dashboard as DashboardIcon,
  ShoppingCart as OrdersIcon,
  Print as PrintIcon,
  Settings as SettingsIcon,
  Storefront as StoreIcon,
  Logout as LogoutIcon,
  Assessment as AssessmentIcon,
} from '@mui/icons-material';
import { useAuth } from '../../contexts/AuthContext';

const DRAWER_WIDTH = 240;

const menuItems = [
  { text: 'Dashboard', icon: <DashboardIcon />, path: '/admin' },
  { text: 'Orders', icon: <OrdersIcon />, path: '/admin/orders' },
  { text: 'Printers', icon: <PrintIcon />, path: '/admin/printers' },
  { text: 'Pricing', icon: <AssessmentIcon />, path: '/admin/settings' },
];

export default function AdminLayout() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const drawer = (
    <Box>
      <Box sx={{ p: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
        <Avatar sx={{ bgcolor: 'primary.main' }}>
          {user?.name?.[0]?.toUpperCase() || 'A'}
        </Avatar>
        <Box>
          <Typography variant="subtitle2">{user?.name || 'Admin'}</Typography>
          <Typography variant="caption" color="text.secondary">
            {user?.email || 'admin@patel.com'}
          </Typography>
        </Box>
      </Box>
      <Divider />
      <List>
        {menuItems.map((item) => (
          <ListItem key={item.text} disablePadding>
            <ListItemButton
              selected={location.pathname === item.path}
              onClick={() => {
                navigate(item.path);
                if (isMobile) setMobileOpen(false);
              }}
            >
              <ListItemIcon>{item.icon}</ListItemIcon>
              <ListItemText primary={item.text} />
            </ListItemButton>
          </ListItem>
        ))}
      </List>
      <Divider />
      <List>
        <ListItem disablePadding>
          <ListItemButton onClick={handleLogout}>
            <ListItemIcon><LogoutIcon /></ListItemIcon>
            <ListItemText primary="Logout" />
          </ListItemButton>
        </ListItem>
      </List>
    </Box>
  );

  return (
    <Box sx={{ display: 'flex' }}>
      <AppBar
        position="fixed"
        sx={{
          width: { md: `calc(100% - ${DRAWER_WIDTH}px)` },
          ml: { md: `${DRAWER_WIDTH}px` },
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            edge="start"
            onClick={() => setMobileOpen(!mobileOpen)}
            sx={{ mr: 2, display: { md: 'none' } }}
          >
            <MenuIcon />
          </IconButton>
          <Typography variant="h6" noWrap sx={{ flexGrow: 1 }}>
            Patel AutoPrint - Admin
          </Typography>
          <Button
            color="inherit"
            startIcon={<StoreIcon />}
            onClick={() => navigate('/')}
          >
            View Store
          </Button>
        </Toolbar>
      </AppBar>

      {/* Mobile drawer */}
      <Drawer
        variant="temporary"
        open={mobileOpen}
        onClose={() => setMobileOpen(false)}
        ModalProps={{ keepMounted: true }}
        sx={{
          display: { xs: 'block', md: 'none' },
          '& .MuiDrawer-paper': { width: DRAWER_WIDTH },
        }}
      >
        {drawer}
      </Drawer>

      {/* Desktop drawer */}
      <Drawer
        variant="permanent"
        sx={{
          display: { xs: 'none', md: 'block' },
          '& .MuiDrawer-paper': { width: DRAWER_WIDTH, boxSizing: 'border-box' },
        }}
        open
      >
