  const platform = os.platform();

  try {
    if (platform === 'win32') {
      return discoverWindowsPrinters();
    } else if (platform === 'linux') {
      return discoverLinuxPrinters();
    } else if (platform === 'darwin') {
      return discoverMacPrinters();
    }
  } catch (err) {
    console.error('Printer discovery error:', err.message);
  }

  return [];
}

function discoverWindowsPrinters() {
  try {
    const output = execSync('Get-Printer | ConvertTo-Json', {
      encoding: 'utf-8',
      shell: 'powershell',
      timeout: 10000,
    });

    const printers = JSON.parse(output);
    const printerList = Array.isArray(printers) ? printers : [printers];

    return printerList
      .filter(p => p.Type !== 'Local' || p.Shared)
      .map(p => ({
        name: p.Name,
        ip: p.PortName || '',
        colorSupport: p.ColorSupported || false,
        duplexSupport: true,
        paperSizes: ['A4'],
        status: p.PrinterStatus === 0 ? 'ONLINE' : 'OFFLINE',
      }));
  } catch (err) {
    console.error('Windows printer discovery failed:', err.message);
    return [];
  }
}

function discoverLinuxPrinters() {
  try {
    const output = execSync('lpstat -p 2>/dev/null || echo ""', {
      encoding: 'utf-8',
      timeout: 10000,
    });

    const lines = output.trim().split('\n').filter(l => l.startsWith('printer'));
    return lines.map(line => {
      const match = line.match(/printer (\S+) is/);
      if (!match) return null;
      return {
        name: match[1],
        ip: '',
        colorSupport: false,
        duplexSupport: true,
        paperSizes: ['A4'],
        status: line.includes('idle') ? 'ONLINE' : 'OFFLINE',
      };
    }).filter(Boolean);
  } catch (err) {
    console.error('Linux printer discovery failed:', err.message);
    return [];
  }
}

function discoverMacPrinters() {
  try {
    const output = execSync('lpstat -p 2>/dev/null || echo ""', {
      encoding: 'utf-8',
      timeout: 10000,
    });

    const lines = output.trim().split('\n').filter(l => l.startsWith('printer'));
    return lines.map(line => {
      const match = line.match(/printer (\S+) is/);
      if (!match) return null;
      return {
        name: match[1],
        ip: '',
        colorSupport: false,
        duplexSupport: true,
        paperSizes: ['A4'],
        status: line.includes('idle') ? 'ONLINE' : 'OFFLINE',
      };
    }).filter(Boolean);
  } catch (err) {
    console.error('Mac printer discovery failed:', err.message);
    return [];
  }
}

function routeJob(job, printers) {
  if (!printers || printers.length === 0) {
    return { ...job, assignedPrinter: null };
  }

  let selectedPrinter;

  if (job.colorMode === 'bw') {
    selectedPrinter = printers.find(p => !p.colorSupport && p.status === 'ONLINE');
  } else {
    selectedPrinter = printers.find(p => p.colorSupport && p.status === 'ONLINE');
  }

  if (!selectedPrinter) {
    selectedPrinter = printers.find(p => p.status === 'ONLINE');
  }

  if (!selectedPrinter) {
    selectedPrinter = printers[0];
  }

  return {
    ...job,
    assignedPrinter: selectedPrinter.name,
  };
}

module.exports = { discoverPrinters, routeJob };

