                    <Button
                      variant="contained"
                      color="error"
                      startIcon={<RejectIcon />}
                      onClick={() => handleStatusChange('rejected')}
                    >
                      Reject
                    </Button>
                  </>
                )}
                {order.status === 'confirmed' && (
                  <Button
                    variant="contained"
                    startIcon={<PrintIcon />}
                    onClick={() => handleStatusChange('printing')}
