}

import { useState, useCallback, useEffect } from 'react';
import {
  Container,
  Box,
  Stepper,
  Step,
  StepLabel,
  Typography,
  Paper,
  Button,
  TextField,
  Grid,
  Card,
  CardContent,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  RadioGroup,
  FormControlLabel,
  Radio,
  Divider,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Alert,
  CircularProgress,
  IconButton,
  Chip,
  Collapse,
} from '@mui/material';
import {
  CloudUpload,
  Delete,
  Receipt,
  CheckCircle,
  ShoppingCart,
  NavigateNext,
  NavigateBefore,
  ContentCopy,
  ExpandMore,
  ExpandLess,
  Add,
  Remove,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../services/api';

const steps = ['Upload Files', 'Configure Settings', 'Review & Pay', 'Order Confirmed'];

const paperSizes = ['A4', 'A3', 'Letter', 'Legal'];
const orientations = ['auto', 'portrait', 'landscape'];
const colorModes = ['auto', 'color', 'bw'];
const pagesPerSheetOptions = [1, 2, 4, 6, 9, 16];

function Step1Upload({ files, setFiles, customerInfo, setCustomerInfo }) {
  const handleDrop = useCallback((e) => {
    e.preventDefault();
    const droppedFiles = Array.from(e.dataTransfer.files);
    setFiles((prev) => [...prev, ...droppedFiles]);
  }, [setFiles]);

  const handleFileInput = (e) => {
    const selectedFiles = Array.from(e.target.files);
    setFiles((prev) => [...prev, ...selectedFiles]);
  };

  const removeFile = (index) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  };

  return (
    <Box>
      <Typography variant="h6" gutterBottom>Upload Your Files</Typography>
      <Paper
        onDrop={handleDrop}
        onDragOver={(e) => e.preventDefault()}
        sx={{
          p: 4,
          textAlign: 'center',
          border: '2px dashed #bdbdbd',
          cursor: 'pointer',
          mb: 3,
          '&:hover': { borderColor: 'primary.main', bgcolor: 'action.hover' },
        }}
        onClick={() => document.getElementById('file-input').click()}
      >
        <input
          id="file-input"
          type="file"
          multiple
          hidden
          onChange={handleFileInput}
          accept=".pdf,.docx,.pptx,.xlsx,.jpg,.jpeg,.png,.webp"
        />
        <CloudUpload sx={{ fontSize: 48, color: 'text.secondary', mb: 1 }} />
        <Typography variant="h6" color="text.secondary">
          Drag & drop files here or click to browse
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Supports PDF, DOCX, PPTX, XLSX, JPG, PNG, WebP
        </Typography>
      </Paper>

      {files.length > 0 && (
        <Box sx={{ mb: 3 }}>
          <Typography variant="subtitle1" gutterBottom>Selected Files ({files.length})</Typography>
          {files.map((file, index) => (
            <Paper key={index} sx={{ p: 1.5, mb: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <Typography variant="body2" sx={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {file.name}
              </Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography variant="caption" color="text.secondary">
                  {(file.size / 1024).toFixed(1)} KB
                </Typography>
                <IconButton size="small" onClick={() => removeFile(index)}>
                  <Delete fontSize="small" />
                </IconButton>
              </Box>
            </Paper>
          ))}
        </Box>
      )}

      <Divider sx={{ my: 3 }} />

      <Typography variant="h6" gutterBottom>Customer Information</Typography>
      <Grid container spacing={2}>
        <Grid size={{ xs: 12, sm: 6 }}>
          <TextField
            fullWidth
            label="Your Name"
            value={customerInfo.name}
            onChange={(e) => setCustomerInfo({ ...customerInfo, name: e.target.value })}
            required
          />
        </Grid>
        <Grid size={{ xs: 12, sm: 6 }}>
          <TextField
            fullWidth
            label="Phone Number"
            value={customerInfo.phone}
            onChange={(e) => setCustomerInfo({ ...customerInfo, phone: e.target.value })}
            required
          />
        </Grid>
        <Grid size={{ xs: 12 }}>
          <TextField
            fullWidth
            label="Email (optional)"
            value={customerInfo.email}
            onChange={(e) => setCustomerInfo({ ...customerInfo, email: e.target.value })}
          />
        </Grid>
      </Grid>
    </Box>
  );
}

function Step2Configure({ files, fileSettings, setFileSettings }) {
  const [activeTab, setActiveTab] = useState(0);

  const getSettings = (fileIndex) => {
    const dbSettings = files[fileIndex]?.settings || {};
    const localSettings = fileSettings[fileIndex] || {};
    return { ...dbSettings, ...localSettings };
  };

  const updateSetting = (fileIndex, key, value) => {
    setFileSettings((prev) => ({
      ...prev,
      [fileIndex]: {
        ...prev[fileIndex],
        [key]: value,
      },
    }));
  };

  const addSection = (fileIndex) => {
    const current = getSettings(fileIndex);
    const sections = current.sections || [];
    const totalPages = files[fileIndex]?.pageCount || 1;
    const lastSection = sections[sections.length - 1];
    const startPage = lastSection ? lastSection.endPage + 1 : 1;
    if (startPage > totalPages) {
      toast.error('No more pages available');
      return;
    }
    const newSections = [...sections, {
      id: Date.now(),
      startPage,
      endPage: totalPages,
      paperSize: 'A4',
      colorMode: 'bw',
      printStyle: 'single',
      copies: 1,
      pagesPerSheet: 1,
    }];
    updateSetting(fileIndex, 'sections', newSections);
  };

  const updateSection = (fileIndex, sectionIndex, key, value) => {
    const current = getSettings(fileIndex);
    const sections = [...(current.sections || [])];
    sections[sectionIndex] = { ...sections[sectionIndex], [key]: value };
    updateSetting(fileIndex, 'sections', sections);
  };

  const removeSection = (fileIndex, sectionIndex) => {
    const current = getSettings(fileIndex);
    const sections = (current.sections || []).filter((_, i) => i !== sectionIndex);
    updateSetting(fileIndex, 'sections', sections);
  };

  return (
    <Box>
      <Typography variant="h6" gutterBottom>Configure Print Settings</Typography>
      <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mb: 2 }}>
        {files.map((file, index) => (
          <Button
            key={index}
            onClick={() => setActiveTab(index)}
            variant={activeTab === index ? 'contained' : 'outlined'}
            size="small"
          >
            {file.originalName?.substring(0, 25) || file.name?.substring(0, 25)}
          </Button>
        ))}
      </Box>

      {files.length > 0 && (
        <Card>
          <CardContent>
            <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 600 }}>
              {files[activeTab]?.originalName || files[activeTab]?.name}
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 2 }}>
              {files[activeTab]?.pageCount || '?'} pages, {files[activeTab]?.colorPageCount || 0} color pages
            </Typography>

            <Grid container spacing={2}>
              <Grid size={{ xs: 12, sm: 6 }}>
                <FormControl fullWidth size="small">
                  <InputLabel>Paper Size</InputLabel>
                  <Select
                    value={getSettings(activeTab).paperSize || 'A4'}
                    label="Paper Size"
                    onChange={(e) => updateSetting(activeTab, 'paperSize', e.target.value)}
                  >
                    {paperSizes.map((size) => (
                      <MenuItem key={size} value={size}>{size}</MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <FormControl fullWidth size="small">
                  <InputLabel>Orientation</InputLabel>
                  <Select
                    value={getSettings(activeTab).orientation || 'auto'}
                    label="Orientation"
                    onChange={(e) => updateSetting(activeTab, 'orientation', e.target.value)}
                  >
                    {orientations.map((o) => (
                      <MenuItem key={o} value={o}>{o.charAt(0).toUpperCase() + o.slice(1)}</MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <FormControl fullWidth size="small">
                  <InputLabel>Color Mode</InputLabel>
                  <Select
                    value={getSettings(activeTab).colorMode || 'auto'}
                    label="Color Mode"
                    onChange={(e) => updateSetting(activeTab, 'colorMode', e.target.value)}
                  >
                    {colorModes.map((m) => (
                      <MenuItem key={m} value={m}>{m === 'auto' ? 'Auto Detect' : m === 'color' ? 'Color' : 'Black & White'}</MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <TextField
                  fullWidth
                  size="small"
                  type="number"
                  label="Copies"
                  value={getSettings(activeTab).copies || 1}
                  onChange={(e) => updateSetting(activeTab, 'copies', parseInt(e.target.value) || 1)}
                  inputProps={{ min: 1 }}
                />
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <FormControl fullWidth size="small">
                  <InputLabel>Pages Per Sheet</InputLabel>
                  <Select
                    value={getSettings(activeTab).pagesPerSheet || 1}
                    label="Pages Per Sheet"
                    onChange={(e) => updateSetting(activeTab, 'pagesPerSheet', parseInt(e.target.value))}
                  >
                    {pagesPerSheetOptions.map((n) => (
                      <MenuItem key={n} value={n}>{n === 1 ? '1 (Full page)' : `${n} pages per sheet`}</MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid size={{ xs: 12, sm: 6 }}>
                <TextField
                  fullWidth
                  size="small"
                  label="Page Range"
                  value={getSettings(activeTab).pageRange || ''}
                  onChange={(e) => updateSetting(activeTab, 'pageRange', e.target.value)}
                  placeholder="e.g. 1-5, 8, 10-12"
                  helperText="Leave empty for all pages"
                />
              </Grid>
              <Grid size={{ xs: 12 }}>
                <FormControl fullWidth size="small">
                  <InputLabel>Print Style</InputLabel>
                  <Select
                    value={getSettings(activeTab).printStyle || 'single'}
                    label="Print Style"
                    onChange={(e) => updateSetting(activeTab, 'printStyle', e.target.value)}
                  >
                    <MenuItem value="single">Single-sided (Simplex)</MenuItem>
                    <MenuItem value="duplex">Double-sided (Duplex)</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
            </Grid>

            <Divider sx={{ my: 2 }} />

            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
              <Typography variant="subtitle2">Print Sections</Typography>
              <Button size="small" startIcon={<Add />} onClick={() => addSection(activeTab)}>
                Add Section
              </Button>
            </Box>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
              Split file into sections with different settings per page range
            </Typography>

            {(getSettings(activeTab).sections || []).length > 0 ? (
              (getSettings(activeTab).sections || []).map((section, si) => (
                <Paper key={section.id || si} variant="outlined" sx={{ p: 2, mb: 1 }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                    <Typography variant="caption" fontWeight={600}>Section {si + 1}</Typography>
                    <IconButton size="small" onClick={() => removeSection(activeTab, si)}>
                      <Remove fontSize="small" />
                    </IconButton>
                  </Box>
                  <Grid container spacing={1}>
                    <Grid size={{ xs: 6, sm: 3 }}>
                      <TextField
                        fullWidth size="small" label="Start Page" type="number"
                        value={section.startPage}
                        onChange={(e) => updateSection(activeTab, si, 'startPage', parseInt(e.target.value) || 1)}
                        inputProps={{ min: 1 }}
                      />
                    </Grid>
                    <Grid size={{ xs: 6, sm: 3 }}>
                      <TextField
                        fullWidth size="small" label="End Page" type="number"
                        value={section.endPage}
                        onChange={(e) => updateSection(activeTab, si, 'endPage', parseInt(e.target.value) || 1)}
                        inputProps={{ min: 1 }}
                      />
                    </Grid>
                    <Grid size={{ xs: 6, sm: 3 }}>
                      <FormControl fullWidth size="small">
                        <InputLabel>Color</InputLabel>
                        <Select
                          value={section.colorMode || 'bw'}
                          label="Color"
                          onChange={(e) => updateSection(activeTab, si, 'colorMode', e.target.value)}
                        >
                          <MenuItem value="bw">B/W</MenuItem>
                          <MenuItem value="color">Color</MenuItem>
                        </Select>
                      </FormControl>
                    </Grid>
                    <Grid size={{ xs: 6, sm: 3 }}>
                      <FormControl fullWidth size="small">
                        <InputLabel>Style</InputLabel>
                        <Select
                          value={section.printStyle || 'single'}
                          label="Style"
                          onChange={(e) => updateSection(activeTab, si, 'printStyle', e.target.value)}
                        >
                          <MenuItem value="single">Simplex</MenuItem>
                          <MenuItem value="duplex">Duplex</MenuItem>
                        </Select>
                      </FormControl>
                    </Grid>
                  </Grid>
                </Paper>
              ))
            ) : (
              <Alert severity="info" sx={{ py: 0 }}>
                No sections — entire file uses the same settings above. Add sections for different settings per page range.
              </Alert>
            )}
          </CardContent>
        </Card>
      )}
    </Box>
  );
}

function Step3Review({ order, paymentMethod, setPaymentMethod, priceData, loadingPrice }) {
  if (loadingPrice) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 6 }}>
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Calculating price...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h6" gutterBottom>Review & Payment</Typography>

      {priceData?.breakdowns && priceData.breakdowns.length > 0 && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="subtitle1" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
              <Receipt sx={{ mr: 1 }} /> Price Breakdown
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>File</TableCell>
                    <TableCell align="right">Pages</TableCell>
                    <TableCell align="right">Sheets</TableCell>
                    <TableCell align="right">Copies</TableCell>
                    <TableCell align="right">Amount</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {priceData.breakdowns.map((b, i) => (
                    <TableRow key={i}>
                      <TableCell sx={{ maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {b.fileName}
                      </TableCell>
                      <TableCell align="right">{b.pageCount}</TableCell>
                      <TableCell align="right">{b.totalSheets}</TableCell>
                      <TableCell align="right">{b.copies}</TableCell>
                      <TableCell align="right">{'\u20B9'}{b.amount?.toFixed(2)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
            <Divider sx={{ my: 2 }} />
            <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
              <Typography variant="h6">Total</Typography>
              <Typography variant="h6" color="primary">{'\u20B9'}{priceData.total?.toFixed(2)}</Typography>
            </Box>
          </CardContent>
        </Card>
      )}

      {!priceData?.breakdowns && (
        <Alert severity="info" sx={{ mb: 3 }}>
          Price will be calculated based on your print settings.
        </Alert>
      )}

      <Typography variant="subtitle1" gutterBottom>Payment Method</Typography>
      <Paper sx={{ p: 2 }}>
        <RadioGroup
          value={paymentMethod}
          onChange={(e) => setPaymentMethod(e.target.value)}
          row
        >
          <FormControlLabel value="cash" control={<Radio />} label="Cash" />
          <FormControlLabel value="card" control={<Radio />} label="Card" />
          <FormControlLabel value="upi" control={<Radio />} label="UPI" />
          <FormControlLabel value="online" control={<Radio />} label="Online Transfer" />
        </RadioGroup>
      </Paper>
    </Box>
  );
}

function Step4Confirmation({ order }) {
  const [copied, setCopied] = useState(false);

  const copyOrderId = () => {
    navigator.clipboard.writeText(order.id);
    setCopied(true);
    toast.success('Order ID copied!');
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Box sx={{ textAlign: 'center', py: 4 }}>
      <CheckCircle sx={{ fontSize: 80, color: 'success.main', mb: 2 }} />
      <Typography variant="h5" gutterBottom>Order Placed Successfully!</Typography>
      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        Your order has been received and is being processed.
      </Typography>

      <Card sx={{ maxWidth: 400, mx: 'auto', mb: 3 }}>
        <CardContent>
          <Typography variant="body2" color="text.secondary">Order ID</Typography>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1 }}>
            <Typography variant="body1" sx={{ fontFamily: 'monospace', fontSize: 13, wordBreak: 'break-all' }}>
              {order.id}
            </Typography>
            <IconButton onClick={copyOrderId} size="small">
              {copied ? <CheckCircle fontSize="small" /> : <ContentCopy fontSize="small" />}
            </IconButton>
          </Box>
          <Chip
            label={order.status}
            color={order.status === 'APPROVED' ? 'success' : 'warning'}
            size="small"
            sx={{ mt: 1 }}
          />
        </CardContent>
      </Card>

      <Alert severity="info" sx={{ maxWidth: 400, mx: 'auto', mb: 2 }}>
        Save your Order ID to track the status. You can also use the Order Tracking page.
      </Alert>
    </Box>
  );
}

export default function CustomerPortal() {
  const [activeStep, setActiveStep] = useState(0);
  const [files, setFiles] = useState([]);
  const [customerInfo, setCustomerInfo] = useState({ name: '', phone: '', email: '' });
  const [fileSettings, setFileSettings] = useState({});
  const [uploadedOrder, setUploadedOrder] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('cash');
  const [loading, setLoading] = useState(false);
  const [priceData, setPriceData] = useState(null);
  const [loadingPrice, setLoadingPrice] = useState(false);

  const handleUpload = async () => {
    if (files.length === 0) {
      toast.error('Please select files to upload');
      return;
    }
    if (!customerInfo.name || !customerInfo.phone) {
      toast.error('Please fill in name and phone number');
      return;
    }
    setLoading(true);
    try {
      const formData = new FormData();
      files.forEach((file) => formData.append('files', file));
      formData.append('customerName', customerInfo.name);
      formData.append('customerPhone', customerInfo.phone);
      formData.append('customerEmail', customerInfo.email);

      const result = await api.post('/guest/upload', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      if (result.success) {
        setUploadedOrder(result.data);
        toast.success(`${result.data.files?.length || 0} file(s) uploaded and analyzed!`);
        setActiveStep(1);
      }
    } catch (err) {
      toast.error(err.message || 'Upload failed');
    } finally {
      setLoading(false);
    }
  };

  const handleSaveSettings = async () => {
    if (!uploadedOrder) return;
    setLoading(true);
    try {
      for (const [fileIndex, settings] of Object.entries(fileSettings)) {
        const fileId = uploadedOrder.files?.[fileIndex]?.id;
        if (fileId) {
          await api.put(`/guest/orders/${uploadedOrder.id}/settings`, {
            fileId,
            settings: {
              ...uploadedOrder.files?.[fileIndex]?.settings,
              ...settings,
            },
          });
        }
      }

      const updatedOrder = await api.get(`/guest/orders/${uploadedOrder.id}`);
      if (updatedOrder.success) {
        setUploadedOrder(updatedOrder.data);
      }

      toast.success('Settings saved!');
      setActiveStep(2);
    } catch (err) {
      toast.error(err.message || 'Failed to save settings');
    } finally {
      setLoading(false);
    }
  };

  const fetchPrice = async () => {
    if (!uploadedOrder) return;
    setLoadingPrice(true);
    try {
      const result = await api.get(`/guest/orders/${uploadedOrder.id}/price`);
      if (result.success) {
        setPriceData(result.data);
      }
    } catch (err) {
      toast.error(err.message || 'Failed to get price');
    } finally {
      setLoadingPrice(false);
    }
  };

  useEffect(() => {
    if (activeStep === 2 && uploadedOrder) {
      fetchPrice();
    }
  }, [activeStep, uploadedOrder?.id]);

  const handlePlaceOrder = async () => {
    if (!uploadedOrder || !paymentMethod) {
      toast.error('Please select a payment method');
      return;
    }
    setLoading(true);
    try {
      const result = await api.post(`/guest/orders/${uploadedOrder.id}/confirm`, {
        paymentMethod,
      });
      if (result.success) {
        setUploadedOrder(result.data);
        toast.success('Order placed successfully!');
        setActiveStep(3);
      }
    } catch (err) {
      toast.error(err.message || 'Failed to place order');
    } finally {
      setLoading(false);
    }
  };

  const handleNext = async () => {
    if (activeStep === 0) {
      await handleUpload();
    } else if (activeStep === 1) {
      await handleSaveSettings();
    } else if (activeStep === 2) {
      await handlePlaceOrder();
    }
  };

  const handleBack = () => {
    setActiveStep((prev) => prev - 1);
  };

  const handleNewOrder = () => {
    setActiveStep(0);
    setFiles([]);
    setCustomerInfo({ name: '', phone: '', email: '' });
    setFileSettings({});
    setUploadedOrder(null);
    setPaymentMethod('cash');
    setPriceData(null);
  };

  return (
    <Container maxWidth="md" sx={{ py: 4 }}>
      <Typography variant="h4" align="center" gutterBottom sx={{ fontWeight: 700 }}>
        Patel AutoPrint
      </Typography>
      <Typography variant="body1" align="center" color="text.secondary" sx={{ mb: 4 }}>
        Print Shop - Self Service Portal
      </Typography>

      <Stepper activeStep={activeStep} sx={{ mb: 4 }}>
        {steps.map((label) => (
          <Step key={label}>
            <StepLabel>{label}</StepLabel>
          </Step>
        ))}
      </Stepper>

      <Paper sx={{ p: 3, minHeight: 400 }}>
        {activeStep === 0 && (
          <Step1Upload
            files={files}
            setFiles={setFiles}
            customerInfo={customerInfo}
            setCustomerInfo={setCustomerInfo}
          />
        )}
        {activeStep === 1 && (
          <Step2Configure
            files={uploadedOrder?.files || files}
            fileSettings={fileSettings}
            setFileSettings={setFileSettings}
          />
        )}
        {activeStep === 2 && (
          <Step3Review
            order={uploadedOrder}
            paymentMethod={paymentMethod}
            setPaymentMethod={setPaymentMethod}
            priceData={priceData}
            loadingPrice={loadingPrice}
          />
        )}
        {activeStep === 3 && (
          <Step4Confirmation order={uploadedOrder} />
        )}

        <Box sx={{ display: 'flex', justifyContent: 'space-between', mt: 3 }}>
          <Button
            disabled={activeStep === 0 || activeStep === 3 || loading}
            onClick={handleBack}
            startIcon={<NavigateBefore />}
          >
            Back
          </Button>
          {activeStep < 3 && (
            <Button
              variant="contained"
              onClick={handleNext}
              disabled={loading || (activeStep === 2 && loadingPrice)}
              endIcon={loading ? <CircularProgress size={20} /> : <NavigateNext />}
            >
              {activeStep === 0 ? 'Upload & Analyze' :
               activeStep === 1 ? 'Save & Get Price' :
               loading ? 'Placing Order...' : 'Place Order'}
            </Button>
          )}
          {activeStep === 3 && (
            <Button variant="contained" onClick={handleNewOrder} startIcon={<ShoppingCart />}>
              Place New Order
            </Button>
          )}
        </Box>
      </Paper>
    </Container>
  );
}

