const fs = require('fs');
const fsPromises = require('fs/promises');
const path = require('path');
const { PDFDocument } = require('pdf-lib');

async function processOrder(orderId, prisma) {
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: {
      files: true,
    },
  });

  if (!order) {
    throw new Error('Order not found');
  }

  console.log(`Processing order ${orderId}`);

  const results = [];

  for (const file of order.files) {
    const settings = file.settings || {};
    const pages = settings.pageRange === 'all' || !settings.pageRange
      ? null
      : parsePageRange(settings.pageRange, file.pageCount);

    try {
      const printReadyPath = await processFile(file, pages, settings);
      results.push({
        fileId: file.id,
        filePath: printReadyPath,
      });
    } catch (err) {
      console.error(`Failed to process file ${file.id}:`, err);
    }
  }

  return results;
}

async function processFile(file, pageRange, settings) {
  const ext = path.extname(file.originalName).toLowerCase();

  if (ext === '.pdf') {
    return processPDF(file, pageRange, settings);
  }

  // For non-PDF files, return the original path
  return file.storagePath;
}

async function processPDF(file, pageRange, settings) {
  const pdfBuffer = await fsPromises.readFile(file.storagePath);
  const pdfDoc = await PDFDocument.load(pdfBuffer);
  const totalPages = pdfDoc.getPageCount();

  const pages = pageRange || Array.from({ length: totalPages }, (_, i) => i);

  let processedDoc;

  const pagesPerSheet = settings.pagesPerSheet || 1;
  if (pagesPerSheet > 1) {
    processedDoc = await applyNUp(pdfDoc, pages, pagesPerSheet);
  } else {
    processedDoc = await extractPages(pdfDoc, pages);
  }

  // Apply scaling
  if (settings.scaling && settings.scaling !== 100) {
    applyScaling(processedDoc, settings.scaling);
  }

  // Save the print-ready PDF
  const printReadyBytes = await processedDoc.save();
  const printReadyDir = path.join(path.dirname(file.storagePath), 'print-ready');
  await fsPromises.mkdir(printReadyDir, { recursive: true });
  const printReadyPath = path.join(printReadyDir, `${file.id}_printready.pdf`);
  await fsPromises.writeFile(printReadyPath, printReadyBytes);

  return printReadyPath;
}

function parsePageRange(pageRange, totalPages) {
  if (!pageRange || pageRange === 'all') {
    return Array.from({ length: totalPages }, (_, i) => i);
  }

  const pages = [];
  const parts = pageRange.split(',');

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed.includes('-')) {
      const [start, end] = trimmed.split('-').map(Number);
      for (let i = start; i <= Math.min(end, totalPages); i++) {
        pages.push(i - 1);
      }
    } else {
      const pageNum = parseInt(trimmed);
      if (pageNum >= 1 && pageNum <= totalPages) {
        pages.push(pageNum - 1);
      }
    }
  }

  return [...new Set(pages)].sort((a, b) => a - b);
}

function calculateSheetCount(pageCount, nUp, duplex) {
  let sheets = Math.ceil(pageCount / nUp);
  if (duplex === 'duplex') {
    sheets = Math.ceil(sheets / 2);
  }
  return sheets;
}

async function extractPages(pdfDoc, pages) {
  const newDoc = await PDFDocument.create();
  const copiedPages = await newDoc.copyPages(pdfDoc, pages);
  copiedPages.forEach((page) => newDoc.addPage(page));
  return newDoc;
}

async function applyNUp(pdfDoc, pages, nUp) {
  const newDoc = await PDFDocument.create();

  let cols, rows;
  switch (nUp) {
    case 2: cols = 1; rows = 2; break;
    case 4: cols = 2; rows = 2; break;
    case 6: cols = 2; rows = 3; break;
    case 8: cols = 2; rows = 4; break;
    case 9: cols = 3; rows = 3; break;
    case 16: cols = 4; rows = 4; break;
    default: cols = 1; rows = 1;
  }

  for (let i = 0; i < pages.length; i += nUp) {
    const page = newDoc.addPage([595.28, 841.89]); // A4 size

    for (let j = 0; j < nUp && i + j < pages.length; j++) {
      const col = j % cols;
      const row = Math.floor(j / cols);

      const cellWidth = page.getWidth() / cols;
      const cellHeight = page.getHeight() / rows;

      const x = col * cellWidth;
      const y = page.getHeight() - (row + 1) * cellHeight;

      try {
        const [embeddedPage] = await newDoc.embedPdf(pdfDoc, [pages[i + j]]);
        page.drawPage(embeddedPage, {
          x,
          y,
          width: cellWidth,
          height: cellHeight,
        });
      } catch (err) {
        console.error(`Failed to embed page ${pages[i + j]}:`, err);
      }
    }
  }

  return newDoc;
}

function applyScaling(pdfDoc, scaling) {
  const scale = scaling / 100;
  const pages = pdfDoc.getPages();

  for (const page of pages) {
    const { width, height } = page.getSize();
    page.setSize({
      width: width * scale,
      height: height * scale,
    });
  }
}

module.exports = { processOrder, processFile, processPDF, parsePageRange, calculateSheetCount };

