app.get('/api/guest/orders/:id/price', asyncHandler(async (req, res) => {
  const order = await prisma.order.findUnique({
    where: { id: req.params.id },
    include: { files: true },
  });
  if (!order) throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');

  const breakdowns = [];
  let grandTotal = 0;

  for (const file of order.files) {
    const s = file.settings || {};
    const { totalSheets, colorSheets } = calculateSheets(file.pageCount, file.colorPageCount, s);
    const price = calculatePrice(totalSheets, colorSheets, s);
    breakdowns.push({
      fileId: file.id,
      fileName: file.originalName,
      pageCount: file.pageCount,
      colorPages: file.colorPageCount,
      totalSheets,
      colorSheets,
      copies: s.copies || 1,
      amount: price.total,
      breakdown: price.breakdown,
    });
    grandTotal += price.total;
  }

  await prisma.order.update({
    where: { id: order.id },
    data: { totalPrice: grandTotal },
  });

  res.json({ success: true, data: { breakdowns, total: grandTotal } });
}));

