function calculateSheets(totalPages, colorPages, settings) {
  const pagesPerPhysicalSheet = settings.pagesPerSheet || 1;
  const effectivePages = Math.ceil(totalPages / pagesPerPhysicalSheet);

  let totalSheets;
  if (settings.printStyle === 'duplex') {
    totalSheets = Math.ceil(effectivePages / 2);
  } else {
    totalSheets = effectivePages;
  }

  const isColorMode = settings.colorMode === 'color';
  if (isColorMode) {
    return { totalSheets, colorSheets: totalSheets, bwSheets: 0 };
  }

  const colorRatio = totalPages > 0 ? colorPages / totalPages : 0;
  const colorSheets = Math.ceil(totalSheets * colorRatio);
  const bwSheets = totalSheets - colorSheets;

  return { totalSheets, colorSheets, bwSheets };
}

