        } else {
          pages = parsePageRange(printJob.pages, file.pageCount);
        }
      } catch {
        pages = parsePageRange(printJob.pages, file.pageCount);
      }

      const settings = {
        pagesPerSheet: 1,
        paperSize: printJob.paperSize,
