const http = require('http');
const fs = require('fs');
const path = require('path');

function makeRequest(method, urlPath, body, token) {
  return new Promise((resolve, reject) => {
    const data = body ? (typeof body === 'string' ? body : JSON.stringify(body)) : null;
    const headers = {};
    if (token) headers['Authorization'] = 'Bearer ' + token;
    if (data && !Buffer.isBuffer(data)) {
      headers['Content-Type'] = 'application/json';
      headers['Content-Length'] = Buffer.byteLength(data);
    }
    const req = http.request({ hostname: 'localhost', port: 5000, path: urlPath, method, headers }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => { try { resolve({ s: res.statusCode, b: JSON.parse(d) }); } catch { resolve({ s: res.statusCode, raw: d.substring(0, 500) }); } });
    });
    req.on('error', reject);
    if (data) req.write(data);
    req.end();
  });
}

function uploadMultipart(filePath, urlPath, token) {
  return new Promise((resolve, reject) => {
    const boundary = '----Boundary' + Date.now();
    const fileName = path.basename(filePath);
    const fileData = fs.readFileSync(filePath);
    let head = '--' + boundary + '\r\nContent-Disposition: form-data; name=\"files\"; filename=\"' + fileName + '\"\r\nContent-Type: application/octet-stream\r\n\r\n';
    let tail = '\r\n--' + boundary + '--\r\n';
    const body = Buffer.concat([Buffer.from(head), fileData, Buffer.from(tail)]);
    const headers = { 'Content-Type': 'multipart/form-data; boundary=' + boundary, 'Content-Length': body.length };
    if (token) headers['Authorization'] = 'Bearer ' + token;
    const req = http.request({ hostname: 'localhost', port: 5000, path: urlPath, method: 'POST', headers }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => { try { resolve({ s: res.statusCode, b: JSON.parse(d) }); } catch { resolve({ s: res.statusCode, raw: d.substring(0, 500) }); } });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

