const http = require('http');
const fs = require('fs');
const path = require('path');
const { PDFDocument } = require('pdf-lib');

function apiReq(method, urlPath, body, token) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const headers = {};
    if (token) headers['Authorization'] = 'Bearer ' + token;
    if (data) { headers['Content-Type'] = 'application/json'; headers['Content-Length'] = Buffer.byteLength(data); }
    const r = http.request({ hostname: 'localhost', port: 5000, path: urlPath, method, headers }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch { resolve({ raw: d.substring(0, 500) }); } });
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}

function uploadGuest(filePath) {
  return new Promise((resolve, reject) => {
    const boundary = '----Boundary' + Date.now();
    const fileName = path.basename(filePath);
    const fileData = fs.readFileSync(filePath);
    const head = '--' + boundary + '\r\nContent-Disposition: form-data; name="files"; filename="' + fileName + '"\r\nContent-Type: application/octet-stream\r\n\r\n';
    const tail = '\r\n--' + boundary + '--\r\n';
    const body = Buffer.concat([Buffer.from(head), fileData, Buffer.from(tail)]);
    const req = http.request({ hostname: 'localhost', port: 5000, path: '/api/guest/upload', method: 'POST',
      headers: { 'Content-Type': 'multipart/form-data; boundary=' + boundary, 'Content-Length': body.length }
    }, (res) => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => { try { resolve(JSON.parse(d)); } catch { resolve({ raw: d.substring(0, 500) }); } });
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

(async () => {
  // Create a 5-page PDF
  const pdfPath = path.join(__dirname, 'uploads', 'duplex_test.pdf');
  const doc = await PDFDocument.create();
  for (var i = 0; i < 5; i++) {
    var page = doc.addPage([612, 792]);
    page.drawText('Page ' + (i+1) + ' - Duplex Test', { x: 72, y: 700, size: 24 });
  }
  fs.writeFileSync(pdfPath, await doc.save());
  console.log('Created 5-page duplex test PDF');

  // 1. Upload
  var up = await uploadGuest(pdfPath);
  if (!up.success) { console.log('UPLOAD FAILED:', JSON.stringify(up)); return; }
  var orderId = up.data.id;
  var fileId = up.data.files[0].id;
  console.log('1. Upload OK - Order:', orderId, '- Pages:', up.data.files[0].pageCount);

  // 2. Settings with duplex + 2 copies
  var sr = await apiReq('PUT', '/api/guest/orders/' + orderId + '/settings', {
    fileId: fileId,
    settings: { paperSize: 'A4', colorMode: 'bw', copies: 2, pageRange: 'all', pagesPerSheet: 1, printStyle: 'duplex' }
  });
  console.log('2. Settings:', sr.success);

  // 3. Price
  var pr = await apiReq('GET', '/api/guest/orders/' + orderId + '/price');
  console.log('3. Price: Rs', pr.data.total, '- sheets:', pr.data.breakdowns[0].totalSheets, '- duplex discount applied');

  // 4. Confirm
  var cr = await apiReq('POST', '/api/guest/orders/' + orderId + '/confirm', { paymentMethod: 'cash' });
  var pj = cr.data.printJobs[0];
  console.log('4. Confirm OK - printer:', pj.assignedPrinter, '- style:', pj.printStyle, '- copies:', pj.copies);

  // 5. Print (admin)
  var login = await apiReq('POST', '/api/auth/login', { email: 'admin@patelautoprint.com', password: 'admin123' });
  var dr = await apiReq('PUT', '/api/admin/orders/' + orderId + '/status', { status: 'PRINTING' }, login.data.token);
  console.log('5. Print:', dr.data.printResults[0].success, '-', dr.data.printResults[0].message);
})().catch(e => console.error('FAIL:', e.message));

