const FormData = require('form-data');
const http = require('http');
const fs = require('fs');

// Create a 6-page test PDF (enough for 2 sections of 3 pages each + N-up 2)
const pdf = Buffer.from('%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Kids[3 0 R 4 0 R 5 0 R 6 0 R 7 0 R 8 0 R]/Count 6>>endobj\n3 0 obj<</Type/Page/MediaBox[0 0 612 792]/Parent 2 0 R>>endobj\n4 0 obj<</Type/Page/MediaBox[0 0 612 792]/Parent 2 0 R>>endobj\n5 0 obj<</Type/Page/MediaBox[0 0 612 792]/Parent 2 0 R>>endobj\n6 0 obj<</Type/Page/MediaBox[0 0 612 792]/Parent 2 0 R>>endobj\n7 0 obj<</Type/Page/MediaBox[0 0 612 792]/Parent 2 0 R>>endobj\n8 0 obj<</Type/Page/MediaBox[0 0 612 792]/Parent 2 0 R>>endobj\nxref\n0 9\n0000000000 65535 f \n0000000009 00000 n \n0000000058 00000 n \n0000000135 00000 n \n0000000195 00000 n \n0000000255 00000 n \n0000000315 00000 n \n0000000375 00000 n \n0000000435 00000 n \ntrailer<</Size 9/Root 1 0 R>>\nstartxref\n495\n%%EOF');

// Upload
const form = new FormData();
form.append('files', pdf, { filename: 'test6.pdf', contentType: 'application/pdf' });
form.append('customerName', 'Test User');
form.append('customerPhone', '9999999999');

function req(method, path, data) {
  return new Promise((resolve, reject) => {
    const opts = { hostname: 'localhost', port: 5000, method, path };
    if (data && !(data instanceof FormData)) {
      opts.headers = { 'Content-Type': 'application/json' };
    }
    const r = http.request(opts, (res) => {
      let body = '';
      res.on('data', (c) => body += c);
      res.on('end', () => {
        try { resolve(JSON.parse(body)); } catch(e) { resolve(body); }
      });
    });
    r.on('error', reject);
    if (data instanceof FormData) {
      r.setHeader('Content-Type', 'multipart/form-data; boundary=' + data.getBoundary());
      data.pipe(r);
    } else if (data) {
      r.write(JSON.stringify(data));
      r.end();
    } else {
      r.end();
    }
  });
}

async function main() {
  try {
    // 1. Upload
    const upload = await req('POST', '/api/guest/upload', form);
    console.log('1. Upload:', upload.success, 'Order:', upload.data?.id);
    const orderId = upload.data.id;
    const fileId = upload.data.files[0].id;

    // 2. Save settings with N-up=2 + 2 sections
    const settings = {
      pagesPerSheet: 2,
      printStyle: 'duplex',
      copies: 2,
      sections: [
        { id: 1, startPage: 1, endPage: 3, colorMode: 'bw', printStyle: 'duplex', pagesPerSheet: 2, copies: 1 },
        { id: 2, startPage: 4, endPage: 6, colorMode: 'color', printStyle: 'single', pagesPerSheet: 1, copies: 1 }
      ]
    };
    const save = await req('PUT', '/api/guest/orders/' + orderId + '/settings', { fileId, settings });
    console.log('2. Settings saved:', save.success);

    // 3. Get order to confirm
    const order = await req('GET', '/api/guest/orders/' + orderId);
    console.log('3. File settings:', order.data?.files?.[0]?.settings?.pagesPerSheet, 
      'sections:', order.data?.files?.[0]?.settings?.sections?.length);

    // 4. Confirm
    const confirm = await req('POST', '/api/guest/orders/' + orderId + '/confirm', { paymentMethod: 'cash' });
    console.log('4. Confirmed:', confirm.success, 'PrintJobs:', confirm.data?.printJobs?.length, 
      'Status:', confirm.data?.order?.status);

    // 5. Verify print jobs
    const printJobs = confirm.data?.printJobs || [];
    printJobs.forEach((pj, i) => {
      const pages = JSON.parse(pj.pages);
      console.log('   Job', i, '- pages:', pages, 'style:', pj.printStyle, 'color:', pj.colorMode);
    });

    console.log('\\n=== ALL TESTS PASSED ===');
  } catch (err) {
    console.error('FAILED:', err);
  }
}

main();
"

