display.text:
const PAPER_SIZES = {
  A4: { width: 210, height: 297, label: 'A4 (210×297 mm)' },
  A3: { width: 297, height: 420, label: 'A3 (297×420 mm)' },
  Legal: { width: 215.9, height: 355.6, label: 'Legal (8.5×14 in)' },
  Letter: { width: 215.9, height: 279.4, label: 'Letter (8.5×11 in)' },
};

const DEFAULT_PRICING = {
  bwPerSheet: 2,
  colorPerSheet: 10,
  duplexDiscountPercent: 20,
  nupDiscountPercent: 15,
  taxPercent: 18,
  defaultDiscount: 0,
  paperSurcharges: {
    A3: 5,
    Legal: 3,
    Letter: 0,
  },
};

function calculatePrice(totalSheets, colorSheets, settings, config = DEFAULT_PRICING) {
  const bwSheets = totalSheets - colorSheets;
  const paperSize = settings.paperSize || 'A4';

  const baseBwPrice = bwSheets * config.bwPerSheet;
  const baseColorPrice = colorSheets * config.colorPerSheet;
  const paperSurcharge = (config.paperSurcharges[paperSize] || 0) * totalSheets;

  const r2 = (n) => Math.round(n * 100) / 100;

  const isDuplex = settings.printStyle === 'duplex';
  const isNup = settings.pagesPerSheet > 1;

  let duplexDiscount = 0;
  if (isDuplex) {
    duplexDiscount = r2((baseBwPrice + baseColorPrice) * (config.duplexDiscountPercent / 100));
  }

  let nupDiscount = 0;
  if (isNup) {
    nupDiscount = r2((baseBwPrice + baseColorPrice) * (config.nupDiscountPercent / 100));
  }

  const subtotal = r2(baseBwPrice + baseColorPrice + paperSurcharge);
  const afterDuplex = r2(subtotal - duplexDiscount);
  const afterNup = r2(afterDuplex - nupDiscount);
  const copiesMultiplier = settings.copies || 1;
  const beforeDiscount = r2(afterNup * copiesMultiplier);
  const discountAmount = r2(beforeDiscount * (config.defaultDiscount / 100));
  const afterDiscount = r2(beforeDiscount - discountAmount);
  const tax = r2(afterDiscount * (config.taxPercent / 100));
  const total = r2(afterDiscount + tax);

  const breakdown = [
    { label: `B/W Sheets (${bwSheets} × ₹${config.bwPerSheet})`, amount: baseBwPrice },
    { label: `Color Sheets (${colorSheets} × ₹${config.colorPerSheet})`, amount: baseColorPrice },
  ];

  if (paperSurcharge > 0) {
    breakdown.push({ label: `Paper Surcharge (${paperSize})`, amount: paperSurcharge });
  }

  if (isDuplex) {
    breakdown.push({ label: `Duplex Discount (-${config.duplexDiscountPercent}%)`, amount: -duplexDiscount });
  }

  if (isNup) {
    breakdown.push({ label: `N-up Discount (-${config.nupDiscountPercent}%)`, amount: -nupDiscount });
  }

  if (settings.copies > 1) {
    breakdown.push({ label: `Copies (×${settings.copies})`, amount: beforeDiscount - subtotal });
  }

  if (config.defaultDiscount > 0) {
    breakdown.push({ label: `Discount (-${config.defaultDiscount}%)`, amount: -discountAmount });
  }

  breakdown.push({ label: `Tax (${config.taxPercent}%)`, amount: tax });

  return {
    basePrice: r2(baseBwPrice + baseColorPrice),
    colorSurcharge: baseColorPrice,
    duplexDiscount: r2(duplexDiscount),
    nupDiscount: r2(nupDiscount),
    copiesMultiplier,
    subtotal: beforeDiscount,
    discount: discountAmount,
    tax,
    total,
    breakdown: breakdown.map(b => ({ ...b, amount: r2(b.amount) })),
  };
}

function calculateSheets(totalPages, colorPages, settings) {
  const pagesPerPhysicalSheet = settings.pagesPerSheet || 1;
  const effectivePages = Math.ceil(totalPages / pagesPerPhysicalSheet);

  let totalSheets;
  if (settings.printStyle === 'duplex') {
    totalSheets = Math.ceil(effectivePages / 2);
  } else {
    totalSheets = effectivePages;
  }

  if (settings.colorMode === 'color') {
    return { totalSheets, colorSheets: totalSheets, bwSheets: 0 };
  }

  if (settings.colorMode === 'bw') {
    return { totalSheets, colorSheets: 0, bwSheets: totalSheets };
  }

  const colorRatio = totalPages > 0 ? colorPages / totalPages : 0;
  const colorSheets = Math.ceil(totalSheets * colorRatio);
  const bwSheets = totalSheets - colorSheets;

  return { totalSheets, colorSheets, bwSheets };
}

module.exports = { calculatePrice, calculateSheets, PAPER_SIZES, DEFAULT_PRICING };

