const DEFAULT_PRICING = {
  bwPerPage: 1,
  colorPerPage: 5,
  colorDuplexPerPage: 10,
  taxPercent: 18,
};

function calculatePrice(totalPages, colorPages, settings, config = DEFAULT_PRICING) {
  const bwPages = totalPages - colorPages;
  const r2 = (n) => Math.round(n * 100) / 100;

  const isColorDuplex = settings.colorMode === 'color' && settings.printStyle === 'duplex';

  let colorRate;
  if (isColorDuplex) {
    colorRate = config.colorDuplexPerPage;
  } else {
    colorRate = config.colorPerPage;
  }

  const isNup = settings.pagesPerSheet > 1;
  const effectiveBwPages = isNup ? Math.ceil(bwPages / settings.pagesPerSheet) : bwPages;
  const effectiveColorPages = isNup ? Math.ceil(colorPages / settings.pagesPerSheet) : colorPages;

  const baseBwPrice = effectiveBwPages * config.bwPerPage;
  const baseColorPrice = effectiveColorPages * colorRate;
  const subtotal = r2(baseBwPrice + baseColorPrice);
  const copiesMultiplier = settings.copies || 1;
  const beforeDiscount = r2(subtotal * copiesMultiplier);
  const tax = r2(beforeDiscount * (config.taxPercent / 100));
  const total = r2(beforeDiscount + tax);

  const breakdown = [{ label: `B/W Pages (${effectiveBwPages} × ₹${config.bwPerPage})`, amount: baseBwPrice }];

  if (effectiveColorPages > 0) {
    const rateLabel = isColorDuplex ? `₹${config.colorDuplexPerPage}` : `₹${config.colorPerPage}`;
    breakdown.push({ label: `Color Pages (${effectiveColorPages} × ${rateLabel})`, amount: baseColorPrice });
  }

  if (isNup) {
    breakdown.push({ label: `N-up (${settings.pagesPerSheet} per sheet)`, amount: 0 });
  }

  if (settings.copies > 1) {
    breakdown.push({ label: `Copies (×${settings.copies})`, amount: beforeDiscount - subtotal });
  }

  breakdown.push({ label: `Tax (${config.taxPercent}%)`, amount: tax });

  return {
    basePrice: r2(baseBwPrice + baseColorPrice),
    subtotal: beforeDiscount,
    discount: 0,
    tax,
    total,
    breakdown: breakdown.map(b => ({ ...b, amount: r2(b.amount) })),
  };
}

function calculatePriceSimple(totalPages, colorPages, settings, config) {
  return calculatePrice(totalPages, colorPages, settings, config);
}

module.exports = { calculatePrice, calculatePriceSimple, DEFAULT_PRICING };

