const FormData = require('form-data');
const { PDFDocument } = require('pdf-lib');
function req(m,p,d,a) {
  return new Promise((res,rej)=>{
    const o={hostname:'localhost',port:5000,method:m,path:p,headers:{}};
    if(d instanceof FormData) Object.assign(o.headers,d.getHeaders());
    else if(d) o.headers['Content-Type']='application/json';
    if(a) o.headers['Authorization']='Bearer '+a;
    const r=http.request(o,(resp)=>{let b='';resp.on('data',c=>b+=c);resp.on('end',()=>{try{res(JSON.parse(b))}catch(e){res(b)}})});
    r.on('error',rej);
    if(d instanceof FormData) d.pipe(r);
    else if(d){r.write(JSON.stringify(d));r.end();}else r.end();
  });
}
async function main(){
  const login=await req('POST','/api/auth/login',{email:'admin@patelautoprint.com',password:'admin123'});
  const t=login.data?.token;
  // 6-page PDF
