  const form=new FormData();
  form.append('files',Buffer.from(await doc.save()),{filename:'test6.pdf',contentType:'application/pdf'});
  form.append('customerName','Test');form.append('customerPhone','9999999999');
  const up=await req('POST','/api/guest/upload',form);
