  const oid=up.data.id,fid=up.data.files[0].id;

  // Save with 4 sections as user described
  const save=await req('PUT','/api/guest/orders/'+oid+'/settings',{
    fileId:fid,
    settings:{
      pagesPerSheet:1,printStyle:'single',copies:1,
      sections:[
        {id:1,startPage:1,endPage:2,colorMode:'bw',printStyle:'single',pagesPerSheet:1,copies:1},
        {id:2,startPage:3,endPage:4,colorMode:'bw',printStyle:'duplex',pagesPerSheet:1,copies:1},
        {id:3,startPage:5,endPage:5,colorMode:'bw',printStyle:'single',pagesPerSheet:1,copies:1},
        {id:4,startPage:6,endPage:6,colorMode:'color',printStyle:'single',pagesPerSheet:1,copies:1}
      ]
    }
  });
  console.log('2. Sections saved:',save.success);

  // Check price
  const price=await req('GET','/api/guest/orders/'+oid+'/price');
  console.log('3. Price: ₹'+price.data?.total?.toFixed(2));
  price.data?.breakdowns?.forEach(b=>{
    b.sections?.forEach(sec=>console.log('   '+sec.label+': ₹'+sec.amount?.toFixed(2)));
  });

  // Confirm
