Now I understand the pricing. The current pricing is per-page:
- B&W: ₹1 per page (regardless of single/duplex)
- Color single: ₹5 per page
- Color duplex: ₹10 per page

The user wants per-sheet pricing:
- B&W: ₹1 per sheet
- Color single: ₹5 per sheet
- Color duplex: ₹10 per sheet

So I need to change the pricing calculation to first compute the number of sheets from the page count, then apply the sheet rate.

For single-sided: sheets = pages (or pages / n-up if N-up is used)
For duplex: sheets = ceil(pages / 2) (or pages / n-up / 2 if N-up is used)

Let me fix pricing.js:

```js
function calculatePrice(totalPages, colorPages, settings, config = DEFAULT_PRICING) {
  const bwPages = totalPages - colorPages;
  const isNup = (settings.pagesPerSheet || 1) > 1;
  const copies = settings.copies || 1;

  // Calculate sheets per page type
  const calcSheets = (pages, isColor) => {
    let nupAdjusted = isNup ? Math.ceil(pages / settings.pagesPerSheet) : pages;
    if (settings.printStyle === 'duplex') {
      return Math.ceil(nupAdjusted / 2);
    }
    return nupAdjusted;
  };

  const bwSheets = calcSheets(bwPages, false);
  const colorSheets = calcSheets(colorPages, true);

  const isColorDuplex = settings.colorMode === 'color' && settings.printStyle === 'duplex';
  let colorRate;
  if (isColorDuplex) {
    colorRate = config.colorDuplexPerPage; // ₹10 per sheet
  } else {
    colorRate = config.colorPerPage; // ₹5 per sheet
  }

  const baseBwPrice = bwSheets * config.bwPerPage; // ₹1 per sheet
  const baseColorPrice = colorSheets * colorRate;
  const subtotal = baseBwPrice + baseColorPrice;
  const total = Math.round(subtotal * copies * 100) / 100;

  // breakdown labels
  const breakdown = [{ label: `B/W (${bwSheets} sheets × ₹${config.bwPerPage})`, amount: baseBwPrice }];
  if (colorSheets > 0) {
    const rateLabel = isColorDuplex ? `₹${config.colorDuplexPerPage}` : `₹${config.colorPerPage}`;
    breakdown.push({ label: `Color (${colorSheets} sheets × ${rateLabel})`, amount: baseColorPrice });
  }
  if (copies > 1) {
    breakdown.push({ label: `Copies (×${copies})`, amount: Math.round((subtotal * (copies - 1)) * 100) / 100 });
  }

  return {
    basePrice: baseBwPrice + baseColorPrice,
    subtotal: total,
    discount: 0,
    tax: 0,
    total,
    breakdown: breakdown.map(b => ({ ...b, amount: Math.round(b.amount * 100) / 100 })),
  };
}
```

