  let candidates;

  if (job.colorMode === 'bw') {
    candidates = printers.filter(p => !p.colorSupport && p.status === 'ONLINE');
  } else {
    candidates = printers.filter(p => p.colorSupport && p.status === 'ONLINE');
  }

  if (candidates.length === 0) {
    candidates = printers.filter(p => p.status === 'ONLINE');
  }

  if (candidates.length === 0) {
    candidates = printers;
  }

  // Round-robin across matching printers
  const selectedPrinter = candidates[routeIndex % candidates.length];
  routeIndex++;

  return {
    ...job,
    assignedPrinter: selectedPrinter.name,
  };
}

