const fs = require('fs');
const path = require('path');
const { PDFDocument } = require('@prisma/client') && require('pdf-lib') || require('pdf-lib');

async function main() {
  const base = 'http://localhost:5000/api';

  // 1. Create a 6-page test PDF
  const pdfDoc = await PDFDocument.create();
  for (let i = 0; i < 6; i++) {
    const page = pdfDoc.addPage([595, 842]);
    page.drawText(`PAGE ${i + 1}`, { x: 50, y: 400, size: 60 });
  }
  const pdfBytes = await pdfDoc.save();
  const tmpPath = path.join('C:\\temp', 'test6pages.pdf');
  fs.mkdirSync('C:\\temp', { recursive: true });
  fs.writeFileSync(tmpPath, pdfBytes);
  console.log('Created test PDF:', tmpPath);

  // 2. Upload via guest upload
  const formData = new FormData();
  formData.append('files', new Blob([fs.readFileSync(tmpPath)]), 'test6pages.pdf');
  formData.append('customerName', 'Test');
  formData.append('customerPhone', '9999999999');

  const uploadRes = await fetch(base + '/guest/upload', { method: 'POST', body: formData });
  const uploadData = await uploadRes.json();
  console.log('Upload success:', uploadData.success);
  const orderId = uploadData.data.id;
  const fileId = uploadData.data.files[0].id;
  console.log('Order ID:', orderId, 'File ID:', fileId);

  // 3. Set sections: [1 single, 2-3 duplex, 4 single, 5-6 duplex]
  const sections = [
    { id: 1, startPage: 1, endPage: 1, paperSize: 'A4', colorMode: 'bw', printStyle: 'single', copies: 1, pagesPerSheet: 1 },
    { id: 2, startPage: 2, endPage: 3, paperSize: 'A4', colorMode: 'bw', printStyle: 'duplex', copies: 1, pagesPerSheet: 1 },
    { id: 3, startPage: 4, endPage: 4, paperSize: 'A4', colorMode: 'bw', printStyle: 'single', copies: 1, pagesPerSheet: 1 },
    { id: 4, startPage: 5, endPage: 6, paperSize: 'A4', colorMode: 'bw', printStyle: 'duplex', copies: 1, pagesPerSheet: 1 },
  ];
  const settings = {
    paperSize: 'A4', orientation: 'auto', colorMode: 'bw', printStyle: 'single',
    copies: 1, pageRange: 'all', pagesPerSheet: 1, sections,
  };
  const settingsRes = await fetch(base + `/guest/orders/${orderId}/settings`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ fileId, settings }),
  });
  const settingsData = await settingsRes.json();
  console.log('Settings saved:', settingsData.success);

  // 4. Confirm order
  const confirmRes = await fetch(base + `/guest/orders/${orderId}/confirm`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ paymentMethod: 'cash' }),
  });
  const confirmData = await confirmRes.json();
  console.log('Confirm success:', confirmData.success);

  // 5. Count print jobs after confirm
  const token = await getAdminToken();
  let jobsRes = await fetch(base + `/admin/orders/${orderId}/print-jobs`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  let jobs = await jobsRes.json();
  console.log('Print jobs after confirm:', jobs.data.length);
  jobs.data.forEach(j => console.log(`  Section ${j.sectionIndex}: pages=${j.pages}, copies=${j.copies}, style=${j.printStyle}`));

  // 6. Start printing (admin status)
  const statusRes = await fetch(base + `/admin/orders/${orderId}/status`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
    body: JSON.stringify({ status: 'PRINTING' }),
  });
  const statusData = await statusRes.json();
  console.log('Status update success:', statusData.success);

  // 7. Count print jobs after printing
  jobsRes = await fetch(base + `/admin/orders/${orderId}/print-jobs`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  jobs = await jobsRes.json();
  console.log('Print jobs after printing:', jobs.data.length);
  jobs.data.forEach(j => console.log(`  Section ${j.sectionIndex}: pages=${j.pages}, copies=${j.copies}, style=${j.printStyle}, status=${j.status}`));

  console.log('DISPATCH RESULTS:', JSON.stringify(statusData.data.printResults, null, 2));
}

async function getAdminToken() {
  const res = await fetch('http://localhost:5000/api/auth/login', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: 'admin@patelautoprint.com', password: 'admin123' }),
  });
  const data = await res.json();
  if (!data.success) throw new Error('Login failed: ' + JSON.stringify(data));
  return data.data.token;
}

main().catch(e => { console.error(e); process.exit(1); });

