import toast from 'react-hot-toast';
import api from '../../services/api';
import OrderStatusBadge from '../../components/OrderStatusBadge';

export default function OrderDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [printJobs, setPrintJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [printers, setPrinters] = useState([]);
  const [selectedPrinter, setSelectedPrinter] = useState('');

  useEffect(() => {
    fetchOrder();
    fetchPrintJobs();
    fetchPrinters();
  }, [id]);

  const fetchOrder = async () => {
    try {
      const result = await api.get(`/admin/orders/${id}`);
      if (result.success) {
        setOrder(result.data);
      }
    } catch {
      toast.error('Failed to load order');
    } finally {
      setLoading(false);
    }
  };

  const fetchPrintJobs = async () => {
    try {
      const result = await api.get(`/admin/orders/${id}/print-jobs`);
      if (result.success) {
        setPrintJobs(result.data || []);
      }
    } catch {
      // Print jobs may not exist yet
    }
  };

  const fetchPrinters = async () => {
    try {
      const result = await api.get('/printers');
      if (result.success) {
        setPrinters(result.data?.printers || []);
        if (result.data?.printers?.length === 1) {
          setSelectedPrinter(result.data.printers[0].name);
        }
      }
    } catch {
      // ignore
    }
  };

  const handleStatusChange = async (newStatus) => {
    try {
      const body = { status: newStatus };
      if (newStatus === 'PRINTING' && selectedPrinter) {
        body.printerName = selectedPrinter;
      }
      await api.put(`/admin/orders/${id}/status`, body);
      toast.success(`Order ${newStatus.toLowerCase()}`);
      fetchOrder();
      fetchPrintJobs();
    } catch {
      toast.error('Failed to update status');
    }

