```

Wait, the PAPER_SIZES in duplex.js are in mm (A4: 210x297). For pdf-lib I need points (72 pt per inch; A4 = 595x842 pt). Let me define paper sizes in points for the contact sheet.

Let me use:
- A4 portrait = 595.28 x 841.89
- A3 = 841.89 x 1190.55
- Letter = 612 x 792
- Legal = 612 x 1008

For a contact sheet, portrait A4 is standard.

Let me write the function:

```js
async function createContactSheet(imageFiles, nUp, paperSize, jobId) {
    const n = nUp || 1;
    let cols, rows;
    switch (n) {
        case 2: cols = 2; rows = 1; break;
        case 4: cols = 2; rows = 2; break;
        case 6: cols = 3; rows = 2; break;
        case 8: cols = 4; rows = 2; break;
        case 9: cols = 3; rows = 3; break;
        case 16: cols = 4; rows = 4; break;
        default: cols = 1; rows = 1;
    }
    const pageDims = getPaperDims(paperSize); // {w, h} in points
    const newDoc = await PDFDocument.create();

    for (let i = 0; i < imageFiles.length; i += n) {
        const chunk = imageFiles.slice(i, i + n);
        const page = newDoc.addPage([pageDims.w, pageDims.h]);
        const cellW = pageDims.w / cols;
        const cellH = pageDims.h / rows;
        for (let j = 0; j < chunk.length; j++) {
            const col = j % cols;
            const rowFromTop = Math.floor(j / cols);
            const imgFile = chunk[j];
            try {
                const embedded = await embedImage(newDoc, imgFile.storagePath);
                const imgDims = embedded.width && embedded.height ? { w: embedded.width, h: embedded.height } : { w: cellW, h: cellH };
                // fit within cell with margin
                const margin = 8;
                const maxW = cellW - margin * 2;
                const maxH = cellH - margin * 2;
                const scale = Math.min(maxW / imgDims.w, maxH / imgDims.h);
                const drawW = imgDims.w * scale;
                const drawH = imgDims.h * scale;
                const x = col * cellW + (cellW - drawW) / 2;
                // pdf-lib y is from bottom; row 0 is top
                const y = pageDims.h - (rowFromTop + 1) * cellH + (cellH - drawH) / 2;
                page.drawImage(embedded, { x, y, width: drawW, height: drawH });
            } catch (err) {
                console.error(`Failed to embed image ${imgFile.storagePath}:`, err.message);
            }
        }
    }

    const bytes = await newDoc.save();
    const dir = path.join(path.dirname(imageFiles[0].storagePath), 'print-ready');
    await fsPromises.mkdir(dir, { recursive: true });
    const outPath = path.join(dir, `${jobId || 'contact'}_contact.pdf`);
    await fsPromises.writeFile(outPath, bytes);
    return outPath;
}
```

`embedImage`:
```js
async function embedImage(doc, filePath) {
    const ext = path.extname(filePath).toLowerCase();
    const data = await fsPromises.readFile(filePath);
    if (ext === '.jpg' || ext === '.jpeg') return await doc.embedJpg(data);
    if (ext === '.png') return await doc.embedPng(data);
    if (ext === '.webp') {
        const sharp = require('sharp');
        const png = await sharp(data).png().toBuffer();
        return await doc.embedPng(png);
    }
    throw new Error('Unsupported image type: ' + ext);
}
```

`getPaperDims`:
```js
function getPaperDims(paperSize) {
    switch (paperSize) {
        case 'A3': return { w: 841.89, h: 1190.55 };
        case 'Letter': return { w: 612, h: 792 };
        case 'Legal': return { w: 612, h: 1008 };
        default: return { w: 595.28, h: 841.89 }; // A4
    }
}
```

Now `processOne` detection. Let me modify `processOne` to check if pages is an array of file-ID strings.

```js
const parsed = JSON.parse(printJob.pages);
if (Array.isArray(parsed) && parsed.length > 0 && typeof parsed[0] === 'string') {
    // Contact sheet: parsed = array of image file IDs
    const imageFiles = parsed.map(id => order.files.find(f => f.id === id)).filter(Boolean);
    const printReadyPath = await createContactSheet(imageFiles, printJob.pagesPerSheet || 1, printJob.paperSize, printJob.id);
    const result = await dispatchPrintJob(printJob, printReadyPath);
    await prisma.printJob.update({...});
    return { printJobId: printJob.id, ...result };
}
```

But wait — the existing `processOne` parses `printJob.pages` and processes. I need to add this check BEFORE the normal page processing. Let me add it at the top of `processOne` (after finding the file).

Now server.js: create the contact sheet print job. In the status route:

```js
