const fs = require('fs');
const path = require('path');
const http = require('http');
const BASE = 'http://localhost:5000';

function req(method, urlPath, opts = {}) {
  return new Promise((resolve, reject) => {
    const r = http.request(BASE + urlPath, { method, headers: opts.headers || {} }, (res) => {
      let body = '';
      res.on('data', (c) => (body += c));
      res.on('end', () => { try { resolve({ status: res.statusCode, data: JSON.parse(body) }); } catch { resolve({ status: res.statusCode, data: body }); } });
    });
    r.on('error', reject);
    if (opts.body) r.write(opts.body);
    r.end();
  });
}
function buildMultipart(fields, files) {
  const boundary = '----e2e' + Date.now();
  const parts = []; const CRLF = '\r\n';
  for (const [k, v] of Object.entries(fields)) parts.push(Buffer.from(`--${boundary}${CRLF}Content-Disposition: form-data; name="${k}"${CRLF}${CRLF}${v}${CRLF}`));
  for (const f of files) { parts.push(Buffer.from(`--${boundary}${CRLF}Content-Disposition: form-data; name="files"; filename="${f.name}"${CRLF}Content-Type: application/octet-stream${CRLF}${CRLF}`)); parts.push(f.content); parts.push(Buffer.from(CRLF)); }
  parts.push(Buffer.from(`--${boundary}--${CRLF}`));
  return { body: Buffer.concat(parts), contentType: `multipart/form-data; boundary=${boundary}` };
}
