const { execFile } = require('child_process');
const officeExts = ['.docx', '.pptx', '.xlsx', '.doc', '.ppt', '.xls'];

// Native Windows printing for office files, exactly like the OS print dialog.
// Uses the file's registered print handler (Word/PowerPoint/Excel) so layout
// and formatting are preserved — no PDF conversion.
function printOfficeNative(filePath, printerName, copies) {
  return new Promise((resolve, reject) => {
    const verb = 'Print';
    // Start-Process -Verb Print sends the job to the default printer unless we
    // pass the printer name. We temporarily set the default printer to the
    // target one so the office app prints to the correct machine.
    const script = `
$printer = '${printerName.replace(/'/g, "''")}'
$file = '${filePath.replace(/'/g, "''")}'
$prev = (Get-Clipboard -ErrorAction SilentlyContinue)
$wsh = New-Object -ComObject WScript.Network
$original = $null
try { $original = (Get-WmiObject -Query "SELECT Default FROM Win32_Printer WHERE Default = TRUE" -ErrorAction SilentlyContinue).Name } catch {}
try { $wsh.SetDefaultPrinter($printer) } catch {}
Start-Process -FilePath $file -Verb Print -ErrorAction Stop
Start-Sleep -Seconds ${(copies || 1) * 2}
if ($original) { try { $wsh.SetDefaultPrinter($original) } catch {} }
`;
    execFile('powershell', ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', script], { timeout: 120000 }, (error, stdout, stderr) => {
      if (error) {
        reject(new Error(stderr || error.message));
      } else {
        resolve(stdout);
      }
    });
  });
}

