const fs = require('fs');
const http = require('http');
const BASE = 'http://localhost:5000';

function req(method, urlPath, opts = {}) {
  return new Promise((resolve, reject) => {
    const r = http.request(BASE + urlPath, { method, headers: opts.headers || {} }, (res) => {
      let body = '';
      res.on('data', (c) => (body += c));
      res.on('end', () => { try { resolve({ status: res.statusCode, data: JSON.parse(body) }); } catch { resolve({ status: res.statusCode, data: body }); } });
    });
    r.on('error', reject);
    if (opts.body) r.write(opts.body);
    r.end();
  });
}
function buildMultipart(fields, files) {
  const boundary = '----e2e' + Date.now();
  const parts = []; const CRLF = '\r\n';
  for (const [k, v] of Object.entries(fields)) parts.push(Buffer.from(`--${boundary}${CRLF}Content-Disposition: form-data; name="${k}"${CRLF}${CRLF}${v}${CRLF}`));
  for (const f of files) { parts.push(Buffer.from(`--${boundary}${CRLF}Content-Disposition: form-data; name="files"; filename="${f.name}"${CRLF}Content-Type: application/octet-stream${CRLF}${CRLF}`)); parts.push(f.content); parts.push(Buffer.from(CRLF)); }
  parts.push(Buffer.from(`--${boundary}--${CRLF}`));
  return { body: Buffer.concat(parts), contentType: `multipart/form-data; boundary=${boundary}` };
}

(async () => {
  // Use the test pptx (5 slides)
  const pptx = fs.readFileSync('C:/Users/mayank/AppData/Local/Temp/test.pptx');
  const mp = buildMultipart({ customerName: 'N-Up Test', customerPhone: '9999999999' }, [{ name: 'slides.pptx', content: pptx }]);
  const up = await req('POST', '/api/guest/upload', { body: mp.body, headers: { 'Content-Type': mp.contentType } });
  const order = up.data.data;
  console.log('UPLOAD order', order.id, 'pageCount', order.files[0].pageCount);

  // Settings: 4 slides per page, duplex
  for (const f of order.files) {
    const r = await req('PUT', `/api/guest/orders/${order.id}/settings`, {
      body: JSON.stringify({ fileId: f.id, settings: { ...f.settings, pagesPerSheet: 4, printStyle: 'duplex', colorMode: 'bw' } }),
      headers: { 'Content-Type': 'application/json' },
    });
    if (!r.data.success) console.log('SETTINGS FAIL', r.data);
  }
  console.log('SETTINGS: 4/page, duplex, bw');

  const login = await req('POST', '/api/auth/login', { body: JSON.stringify({ email: 'admin@patelautoprint.com', password: 'admin123' }), headers: { 'Content-Type': 'application/json' } });
  const token = login.data.data.token;

  const status = await req('PUT', `/api/admin/orders/${order.id}/status`, { body: JSON.stringify({ status: 'PRINTING' }), headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` } });
  console.log('STATUS:', status.data.success ? 'ok' : JSON.stringify(status.data));

  const ord = await req('GET', `/api/orders/${order.id}`, { headers: { Authorization: `Bearer ${token}` } });
  const jobs = ord.data.data.printJobs;
  console.log('PRINT JOBS:', jobs.length);
  jobs.forEach((j) => console.log('  job', j.id, 'pagesPerSheet', j.pagesPerSheet, 'printStyle', j.printStyle, 'colorMode', j.colorMode, 'status', j.status));
})().catch((e) => { console.error(e); process.exit(1); });

