// Convert office file (docx/pptx/xlsx) to PDF using LibreOffice headless
async function convertOfficeToPdf(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  if (!officeExts.includes(ext)) return filePath;

  const dir = path.dirname(filePath);
  const base = path.basename(filePath, ext);
  const tempDir = path.join(dir, 'print-ready');
  await fsPromises.mkdir(tempDir, { recursive: true });
  const outPdf = path.join(tempDir, `${base}.pdf`);

  // If already converted, return cached
  try {
    await fsPromises.access(outPdf);
    console.log(`Using cached PDF conversion: ${outPdf}`);
    return outPdf;
  } catch {}

  return new Promise((resolve, reject) => {
    console.log(`[convertOfficeToPdf] Converting ${filePath} to PDF via LibreOffice...`);
    const sofficePath = 'C:\\Program Files\\LibreOffice\\program\\soffice.exe';
    execFile(sofficePath, [
      '--headless',
      '--convert-to', 'pdf',
      '--outdir', tempDir,
      filePath
    ], { timeout: 180000, windowsHide: true }, (error, stdout, stderr) => {
      console.log(`[convertOfficeToPdf] LibreOffice exit code: ${error?.code ?? 0}, stdout: ${stdout}, stderr: ${stderr}`);
      if (error) {
        console.error('[convertOfficeToPdf] LibreOffice conversion failed:', stderr || error.message);
        reject(new Error(`LibreOffice conversion failed: ${stderr || error.message}`));
      } else {
        console.log(`[convertOfficeToPdf] Converted to PDF: ${outPdf}`);
        resolve(outPdf);
      }
    });
  });
}

