async function processFile(file, pageRange, settings, jobId) {
  const ext = path.extname(file.originalName).toLowerCase();

  if (ext === '.pdf') {
    return processPDF(file, pageRange, settings, jobId);
  }

  if (officeExts.includes(ext)) {
    console.log(`[processFile] Office file detected: ${file.originalName}, converting to PDF...`);
    const pdfPath = await convertOfficeToPdf(file.storagePath);
    // Create a temporary file object with the PDF path for processPDF
    const pdfFile = { ...file, storagePath: pdfPath, pageCount: file.pageCount };
    return processPDF(pdfFile, pageRange, settings, jobId);
  }

  return file.storagePath;
}

