async function applyNUp(pdfDoc, pages, nUp, paperSize) {
  const newDoc = await PDFDocument.create();
  const srcOrient = sourceOrientation(pdfDoc);
  const dims = paperDims(paperSize || 'A4');

  // Grid selection based on source orientation
  // For landscape: maximize columns, for portrait: maximize rows
  let cols, rows;
  if (srcOrient === 'landscape') {
    switch (nUp) {
      case 2: cols = 1; rows = 2; break;   // portrait page, stacked
      case 4: cols = 2; rows = 2; break;   // landscape page, 2×2
      case 6: cols = 3; rows = 2; break;   // landscape page, 3×2
      case 8: cols = 4; rows = 2; break;   // landscape page, 4×2
      case 9: cols = 3; rows = 3; break;   // landscape page, 3×3
      case 16: cols = 4; rows = 4; break;  // landscape page, 4×4
      default: cols = 1; rows = 1;
    }
  } else {
    // Portrait source
    switch (nUp) {
      case 2: cols = 2; rows = 1; break;   // landscape page, side by side
      case 4: cols = 2; rows = 2; break;   // portrait page, 2×2
      case 6: cols = 2; rows = 3; break;   // portrait page, 2×3
      case 8: cols = 2; rows = 4; break;   // portrait page, 2×4
      case 9: cols = 3; rows = 3; break;   // portrait page, 3×3
      case 16: cols = 4; rows = 4; break;  // portrait page, 4×4
      default: cols = 1; rows = 1;
    }
  }

  // Output page orientation:
  // 2-up: flip (landscape→portrait for stacking, portrait→landscape for side-by-side)
  // nUp≥4: match source
  const pageLandscape = nUp === 2 ? srcOrient !== 'landscape' : srcOrient === 'landscape';
  const pageW = pageLandscape ? Math.max(dims.w, dims.h) : Math.min(dims.w, dims.h);
  const pageH = pageLandscape ? Math.min(dims.w, dims.h) : Math.max(dims.w, dims.h);

  for (let i = 0; i < pages.length; i += nUp) {
    const page = newDoc.addPage([pageW, pageH]);

    for (let j = 0; j < nUp && i + j < pages.length; j++) {
      const col = j % cols;
      const row = Math.floor(j / cols);
      const cellW = page.getWidth() / cols;
      const cellH = page.getHeight() / rows;
      const x = col * cellW;
      const y = page.getHeight() - (row + 1) * cellH;

      try {
        const [embeddedPage] = await newDoc.embedPdf(pdfDoc, [pages[i + j]]);
        const scale = Math.min(cellW / embeddedPage.width, cellH / embeddedPage.height);
        const drawW = embeddedPage.width * scale;
        const drawH = embeddedPage.height * scale;
        page.drawPage(embeddedPage, {
          x: x + (cellW - drawW) / 2,
          y: y + (cellH - drawH) / 2,
          width: drawW,
          height: drawH,
        });
      } catch (err) {
        console.error(`Failed to embed page ${pages[i + j]}:`, err);
      }
    }
  }

