const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function test() {
  const src = await prisma.orderFile.findFirst({
    where: { fileType: 'pptx', size: { gt: 1000000 } }
  });
  if (!src) { console.log('No real PPTX found'); return; }
  console.log('Using:', src.originalName, src.size, 'bytes');

  for (const nUp of [2, 4]) {
    console.log(`\n--- Testing ${nUp}-up ---`);
    const order = await prisma.order.create({
      data: {
        customerId: 'a49c4f5a-9f2b-4377-9ea9-57763623a34e',
        shopId: 'c8cae036-c21c-4a01-b54a-d79e37859dce',
        token: Math.floor(Math.random() * 1000),
        status: 'APPROVED', paymentStatus: 'PAID', totalPrice: 1, approvedAt: new Date(),
        files: { create: [{
          originalName: src.originalName, storagePath: src.storagePath,
          fileType: src.fileType, size: src.size, pageCount: src.pageCount || 20,
          colorPageCount: 0, orientation: 'landscape',
          settings: { copies: 1, sections: [], colorMode: 'bw', pageRange: 'all', paperSize: 'A4', printStyle: 'simplex', orientation: 'landscape', pagesPerSheet: nUp },
          shopId: 'c8cae036-c21c-4a01-b54a-d79e37859dce'
        }] }
      }, include: { files: true }
    });

    const fileId = order.files[0].id;
    await prisma.printJob.create({
      data: {
        orderId: order.id, fileId, sectionIndex: 0,
        pages: JSON.stringify([...Array(Math.min(10, src.pageCount || 10)).keys()]),
        colorMode: 'bw', printStyle: 'simplex', paperSize: 'A4',
        pagesPerSheet: nUp, flipDirection: 'short-edge', copies: 1,
        status: 'PENDING', assignedPrinter: '1 no', shopId: 'c8cae036-c21c-4a01-b54a-d79e37859dce'
      }
    });

    const { processAndDispatchOrder } = require('./src/services/printProcessor');
    const results = await processAndDispatchOrder(order.id, prisma);
    console.log('Result:', JSON.stringify(results[0], null, 2));
  }
}

test().catch(e => { console.error('ERROR:', e.message || e); console.error(e.stack); }).finally(() => process.exit(0));

