// Admin confirms a print job — changes READY → CONFIRMED so agent will print
app.put('/api/admin/print-jobs/:jobId/confirm', authenticate, asyncHandler(async (req, res) => {
  const { jobId } = req.params;

  const job = await prisma.printJob.findUnique({
    where: { id: jobId },
    include: { file: { select: { originalName: true } } },
  });

  if (!job) throw new AppError('Print job not found', 404, 'NOT_FOUND');
  if (job.status !== 'READY') {
    throw new AppError(`Job is ${job.status}, can only confirm READY jobs`, 400, 'INVALID_STATUS');
  }

  await prisma.printJob.update({
    where: { id: jobId },
    data: { status: 'CONFIRMED' },
  });

  res.json({ success: true, message: `Job confirmed — agent will print: ${job.file.originalName}` });
}));

