const http = require('http');
const fs = require('fs');
const path = require('path');

const boundary = '----TestBoundary123';
const filePath = process.argv[2] || 'uploads/multipage_test.pdf';
const fileName = path.basename(filePath);
const fileData = fs.readFileSync(filePath);

let body = '';
body += `--${boundary}\r\nContent-Disposition: form-data; name="customerName"\r\n\r\nConfirm Test\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="customerPhone"\r\n\r\n8888888888\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="notes"\r\n\r\nTest admin confirm flow\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="files"; filename="${fileName}"\r\nContent-Type: application/pdf\r\n\r\n`;
const bodyStart = Buffer.from(body, 'utf-8');
const bodyEnd = Buffer.from(`\r\n--${boundary}--\r\n`, 'utf-8');
const fullBody = Buffer.concat([bodyStart, fileData, bodyEnd]);

const req = http.request({
  hostname: 'localhost', port: 5000, path: '/api/guest/upload', method: 'POST',
  headers: { 'Content-Type': `multipart/form-data; boundary=${boundary}`, 'Content-Length': fullBody.length },
}, (res) => {
  let data = '';
  res.on('data', d => data += d);
  res.on('end', () => {
    const j = JSON.parse(data);
    console.log(j.data.id);
  });
});
req.write(fullBody);
req.end();

