const http = require('http');
const fs = require('fs');
const path = require('path');
const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

const boundary = '----TestBoundary123';
const filePath = 'uploads/multipage_test.pdf';
const fileName = path.basename(filePath);
const fileData = fs.readFileSync(filePath);

let body = '';
body += `--${boundary}\r\nContent-Disposition: form-data; name="customerName"\r\n\r\nFlipTest\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="customerPhone"\r\n\r\n6666666666\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="notes"\r\n\r\n2up duplex flip test\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="files"; filename="${fileName}"\r\nContent-Type: application/pdf\r\n\r\n`;
const bodyStart = Buffer.from(body, 'utf-8');
const bodyEnd = Buffer.from(`\r\n--${boundary}--\r\n`, 'utf-8');
const fullBody = Buffer.concat([bodyStart, fileData, bodyEnd]);

function req(method, p, b, cb) {
  const r = http.request({ hostname:'localhost', port:5000, path:p, method, headers:{ 'Content-Type': b?'application/json':'multipart/form-data; boundary='+boundary, 'Content-Length': b?Buffer.byteLength(b):fullBody.length } }, res => {
    let d=''; res.on('data',c=>d+=c); res.on('end',()=>cb(JSON.parse(d)));
  });
  r.write(b||fullBody); r.end();
}

async function main() {
  // 1. Upload
  const upload = await new Promise(res => req('POST', '/api/guest/upload', null, res => res));
  const orderId = upload.data.id;
  const fileId = upload.data.files[0].id;
  console.log('Uploaded order', orderId, 'file', fileId);

  // 2. Set 2-up duplex settings on the file
  await prisma.orderFile.update({
    where: { id: fileId },
    data: { settings: { paperSize:'A4', orientation:'auto', colorMode:'bw', printStyle:'duplex', copies:1, pageRange:'all', pagesPerSheet:2 } }
  });
  console.log('Set 2-up duplex settings');

  // 3. Approve (PRINTING) -> creates print jobs with flipDirection
  const token = 'admin-token';
  // login first to get token
  const login = await new Promise(res => {
    const r = http.request({ hostname:'localhost', port:5000, path:'/api/auth/login', method:'POST', headers:{'Content-Type':'application/json'} }, res2 => { let d=''; res2.on('data',c=>d+=c); res2.on('end',()=>res(JSON.parse(d))); });
    r.write(JSON.stringify({email:'admin@patelautoprint.com', password:'admin123'})); r.end();
  });
  const headers = { 'Content-Type':'application/json', 'Authorization':'Bearer '+login.data.token };
  const statusRes = await new Promise(res => {
    const r = http.request({ hostname:'localhost', port:5000, path:'/api/admin/orders/'+orderId+'/status', method:'PUT', headers }, res2 => { let d=''; res2.on('data',c=>d+=c); res2.on('end',()=>res(JSON.parse(d))); });
    r.write(JSON.stringify({ status:'PRINTING', bwPrinterName:'1 no', colorPrinterName:'1 no' })); r.end();
  });
  console.log('Approved:', statusRes.success);

  // 4. Check print job flipDirection
  const jobs = await prisma.printJob.findMany({ where:{ orderId }, select:{ id:true, flipDirection:true, printStyle:true, pagesPerSheet:true, status:true } });
  jobs.forEach(j => console.log('  Job', j.id, '| flip='+j.flipDirection, '| style='+j.printStyle, '| nUp='+j.pagesPerSheet, '| status='+j.status));

  await prisma.$disconnect();
}
main().catch(e=>{ console.error(e); process.exit(1); });

