const http = require('http');
const fs = require('fs');
const path = require('path');
const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

function httpReq(method, p, body, timeoutMs) {
  return new Promise((resolve, reject) => {
    const r = http.request({ hostname:'localhost', port:5000, path:p, method,
      headers: body ? {'Content-Type':'application/json','Content-Length':Buffer.byteLength(body)} : {} }, res => {
      let d=''; res.on('data',c=>d+=c); res.on('end',()=>resolve({status:res.statusCode,body:d}));
    });
    r.setTimeout(timeoutMs||8000, ()=>r.destroy(new Error('HTTP timeout')));
    r.on('error', reject);
    if (body) r.write(body);
    r.end();
  });
}

const boundary = '----TestBoundary123';
const filePath = 'uploads/multipage_test.pdf';
const fileName = path.basename(filePath);
const fileData = fs.readFileSync(filePath);
let body = '';
body += `--${boundary}\r\nContent-Disposition: form-data; name="customerName"\r\n\r\nFlipTest2\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="customerPhone"\r\n\r\n6666666666\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="notes"\r\n\r\n2up duplex\r\n`;
body += `--${boundary}\r\nContent-Disposition: form-data; name="files"; filename="${fileName}"\r\nContent-Type: application/pdf\r\n\r\n`;
const fullBody = Buffer.concat([Buffer.from(body), fileData, Buffer.from(`\r\n--${boundary}--\r\n`)]);

(async () => {
  try {
    console.log('STEP1: upload');
    const up = await httpReq('POST','/api/guest/upload', fullBody, 20000);
    const orderId = JSON.parse(up.body).data.id;
    const fileId = JSON.parse(up.body).data.files[0].id;
    console.log('  orderId=', orderId, 'fileId=', fileId);

    console.log('STEP2: set 2-up duplex settings');
    await prisma.orderFile.update({ where:{id:fileId}, data:{ settings:{ paperSize:'A4', orientation:'auto', colorMode:'bw', printStyle:'duplex', copies:1, pageRange:'all', pagesPerSheet:2 } } });

    console.log('STEP3: login');
    const login = await httpReq('POST','/api/auth/login', JSON.stringify({email:'admin@patelautoprint.com',password:'admin123'}), 8000);
    const token = JSON.parse(login.body).data.token;

    console.log('STEP4: approve PRINTING');
    const appr = await httpReq('PUT','/api/admin/orders/'+orderId+'/status', JSON.stringify({status:'PRINTING',bwPrinterName:'1 no',colorPrinterName:'1 no'}), 15000);
    console.log('  approve resp:', appr.body.substring(0,200));

    console.log('STEP5: read print job flipDirection');
    const jobs = await prisma.printJob.findMany({ where:{orderId}, select:{flipDirection:true, printStyle:true, pagesPerSheet:true, status:true} });
    jobs.forEach(j=>console.log('  flip='+j.flipDirection, 'style='+j.printStyle, 'nUp='+j.pagesPerSheet, 'status='+j.status));

    await prisma.$disconnect();
    console.log('DONE');
    process.exit(0);
  } catch (e) {
    console.error('ERROR:', e.message);
    await prisma.$disconnect().catch(()=>{});
    process.exit(1);
  }
})();

