const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

(async () => {
  try {
    // find a recent 2-up portrait job
    const job = await prisma.printJob.findFirst({
      where: { pagesPerSheet: 2, printStyle: 'duplex' },
      orderBy: { id: 'desc' },
      include: { file: true },
    });
    if (!job) { console.log('no 2-up duplex job found'); return; }
    console.log('job', job.id, 'flip=', job.flipDirection, 'srcOrient=', job.file.orientation);

    const printReadyDir = path.join(path.dirname(job.file.storagePath), 'print-ready');
    const files = fs.readdirSync(printReadyDir);
    const match = files.find(f => f.includes(job.id) && f.endsWith('_printready.pdf'));
    if (!match) { console.log('no print-ready file'); return; }
    const fpath = path.join(printReadyDir, match);
    console.log('file:', fpath);
    const buf = fs.readFileSync(fpath);
    const doc = await PDFDocument.load(buf);
    const p0 = doc.getPage(0);
    const w = p0.getWidth(), h = p0.getHeight();
    console.log('output page0 dims: ', Math.round(w), 'x', Math.round(h), '=>', w > h ? 'LANDSCAPE' : 'PORTRAIT');
  } catch (e) {
    console.error('ERR', e.message);
  } finally {
    await prisma.$disconnect();
  }
})();

