    console.log('approve:', appr.body.substring(0,150));

    const jobs = await prisma.printJob.findMany({ where:{orderId:oid}, select:{flipDirection:true, printStyle:true, pagesPerSheet:true, status:true} });
    jobs.forEach(j=>console.log('  flip='+j.flipDirection, 'style='+j.printStyle, 'nUp='+j.pagesPerSheet, 'status='+j.status));
    await prisma.$disconnect();
    process.exit(0);
  } catch(e) { console.error('ERR', e.message); await prisma.$disconnect().catch(()=>{}); process.exit(1); }
})();

