// cleanup.js - Run before seed to ensure single shop
const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function cleanup() {
    const shops = await prisma.shop.findMany({ orderBy: { createdAt: 'asc' } });

    if (shops.length <= 1) return; // Nothing to clean

    console.log(`Found ${shops.length} shops. Merging into one...`);

    // Keep the first shop (or the one with the most data)
    const keepShop = shops[0];
    const removeShops = shops.slice(1);

    // Move all users to the kept shop
    for (const shop of removeShops) {
        const users = await prisma.user.findMany({ where: { shopId: shop.id } });
        for (const user of users) {
            // Check if email already exists in target shop
            const existing = await prisma.user.findUnique({
                where: { shopId_email: { shopId: keepShop.id, email: user.email } }
            });
            if (!existing) {
                await prisma.user.update({
                    where: { id: user.id },
                    data: { shopId: keepShop.id }
                });
            }
            // If email exists, delete the duplicate user
            else {
                await prisma.user.delete({ where: { id: user.id } });
            }
        }
    }

    // Move all customers
    for (const shop of removeShops) {
        const customers = await prisma.customer.findMany({ where: { shopId: shop.id } });
        for (const customer of customers) {
            await prisma.customer.update({
                where: { id: customer.id },
                data: { shopId: keepShop.id }
            });
        }
    }

    // Move all orders (and their files/printJobs via cascade)
    for (const shop of removeShops) {
        // Actually, we can't just move orders because of token uniqueness
        // Let's just re-assign them without token conflict by regenerating tokens
        const orders = await prisma.order.findMany({ 
            where: { shopId: shop.id },
            include: { files: true, printJobs: true }
        });

        for (const order of orders) {
            // Get a new token for the target shop
            const maxToken = await prisma.order.findFirst({
                where: { shopId: keepShop.id },
                orderBy: { token: 'desc' }
            });
            const newToken = (maxToken?.token || 0) + 1;

            await prisma.order.update({
                where: { id: order.id },
                data: { shopId: keepShop.id, token: newToken }
            });
        }
    }

    // Move printers
    for (const shop of removeShops) {
        const printers = await prisma.printer.findMany({ where: { shopId: shop.id } });
        for (const printer of printers) {
            await prisma.printer.update({
                where: { id: printer.id },
                data: { shopId: keepShop.id }
            });
        }
    }

    // Move pricing rules
    for (const shop of removeShops) {
        const rules = await prisma.pricingRule.findMany({ where: { shopId: shop.id } });
        for (const rule of rules) {
            await prisma.pricingRule.update({
                where: { id: rule.id },
                data: { shopId: keepShop.id }
            });
        }
    }

    // Delete empty shops
    for (const shop of removeShops) {
        await prisma.shop.delete({ where: { id: shop.id } });
    }

    console.log(`Merged ${removeShops.length} shops into ${keepShop.id}`);
}

module.exports = cleanup;
```

