  if (existingShops > 0) {
    console.log('Database already seeded, skipping.');
    return;
  }

  console.log('Seeding database...');

  // Create a demo shop
  const shop = await prisma.shop.create({
    data: {
      name: 'Patel AutoPrint',
      settings: {
        currency: 'INR',
        timeZone: 'Asia/Kolkata',
      },
    },
  });

