    data: {
      shopId: shop.id,
      name: 'Mayank Patel',
      email: 'admin@patelautoprint.com',
      passwordHash,
      role: 'OWNER',
    },
  });

  console.log(`Owner created: ${owner.name} (${owner.email})`);

