  DialogActions,
  InputAdornment,
  LinearProgress,
  Avatar,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  Delete as DeleteIcon,
  Receipt as ReceiptIcon,
  CheckCircle as CheckCircleIcon,
  ShoppingCart as ShoppingCartIcon,
  NavigateNext as NavigateNextIcon,
  NavigateBefore as NavigateBeforeIcon,
  ContentCopy as ContentCopyIcon,
  Add as AddIcon,
  Remove as RemoveIcon,
  PhotoCamera as PhotoCameraIcon,
  Description as FileDescriptionIcon,
  Warning as WarningIcon,
  Info as InfoIcon,
  Timer as TimerIcon,
  AttachMoney as MoneyIcon,
  LocalPrintshop as LocalPrintshopIcon,
  Badge as BadgeIcon,
  AccountCircle as AccountCircleIcon,
  Phone as PhoneIcon,
  Email as EmailIcon,
  Search as SearchIcon,
  Close as CloseIcon,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../services/api';
import { getFileType, analyzeFile } from '../utils/fileAnalysis';
import { isSupportedFileType } from '../utils/fileValidation';
import { getFileHandler, SUPPORTED_FILE_TYPES } from '../utils/fileHandlers';
import { calculatePrice } from '../utils/pricing';

const steps = ['Upload', 'Configure', 'Review & Pay', 'Done'];

const paperSizes = ['A4', 'A3', 'Letter', 'Legal'];
const orientations = ['auto', 'portrait', 'landscape'];
const colorModes = ['bw', 'color'];
const pagesPerSheetOptions = [1, 2, 4, 6, 9, 16];

const animationStyles = {
  fadeIn: {
    animation: 'fadeIn 0.3s ease-in',
    '@keyframes fadeIn': {
      from: { opacity: 0, transform: 'translateY(10px)' },
      to: { opacity: 1, transform: 'translateY(0)' },
    },
  },
  slideUp: {
    animation: 'slideUp 0.3s ease-out',
    '@keyframes slideUp': {
      from: { opacity: 0, transform: 'translateY(20px)' },
      to: { opacity: 1, transform: 'translateY(0)' },
    },
  },
  pulse: {
    animation: 'pulse 2s infinite',
    '@keyframes pulse': {
      '0%': { boxShadow: '0 0 0 0 rgba(25, 118, 210, 0.7)' },
      '70%': { boxShadow: '0 0 0 10px rgba(25, 118, 210, 0)' },
      '100%': { boxShadow: '0 0 0 0 rgba(25, 118, 210, 0)' },
    },
  },
};

function isImageFile(file) {
  const name = (file?.originalName || file?.name || '').toLowerCase();
  return /\.(jpg|jpeg|png|webp)$/.test(name);
}

function Step1Upload({ files, setFiles, customerInfo, setCustomerInfo }) {
  const [dragActive, setDragActive] = useState(false);
  const uploadInputRef = useRef(null);

  const handleDrop = useCallback((e) => {
    e.preventDefault();
    setDragActive(false);
    const droppedFiles = Array.from(e.dataTransfer.files);
    const validFiles = droppedFiles.filter(file => isSupportedFileType(file.name));
    const invalidFiles = droppedFiles.filter(file => !isSupportedFileType(file.name));

    if (invalidFiles.length > 0) {
      toast.error(`${invalidFiles.length} invalid file type(s). Supported: ${SUPPORTED_FILE_TYPES.join(', ')}`);
    }

    setFiles((prev) => [...prev, ...validFiles]);
    if (validFiles.length > 0) {
      toast.success(`${validFiles.length} file(s) uploaded successfully`);
    }
  }, [setFiles]);

  const handleFileInput = useCallback((e) => {
    const selectedFiles = Array.from(e.target.files);
    setFiles((prev) => [...prev, ...selectedFiles]);
  }, [setFiles]);

  const removeFile = useCallback((index) => {
    setFiles((prev) => prev.filter((_, i) => i !== index));
  }, [setFiles]);

  const copyToClipboard = useCallback((text, label) => {
    navigator.clipboard.writeText(text);
    toast.success(`${label} copied to clipboard`);
  }, []);

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
          <UploadIcon sx={{ fontSize: 32, color: 'primary.main' }} />
          <Typography variant="h6" fontWeight={600}>Step 1: Upload Files</Typography>
        </Box>
        <Chip 
          icon={<InfoIcon />} 
          label={`${SUPPORTED_FILE_TYPES.join(', ')}`} 
          variant="outlined" 
          size="small" 
          color="info"
        />
      </Box>

      <Paper
        onDrop={handleDrop}
        onDragOver={(e) => {
          e.preventDefault();
          setDragActive(true);
        }}
        onDragLeave={(e) => {
          e.preventDefault();
          setDragActive(false);
        }}
        onClick={() => uploadInputRef.current?.click()}
        sx={{
          p: { xs: 3, sm: 5 },
          textAlign: 'center',
          border: dragActive ? '2px solid' : '2px dashed',
          borderColor: dragActive ? 'primary.main' : '#bdbdbd',
          cursor: 'pointer',
          mb: 3,
          bgcolor: dragActive ? 'action.hover' : 'background.paper',
          transition: 'all 0.3s ease',
          transform: dragActive ? 'scale(1.02)' : 'scale(1)',
          boxShadow: dragActive ? 6 : 1,
          '&:hover': { 
            borderColor: 'primary.main', 
            bgcolor: 'action.hover' 
          },
        }}
      >
        <input
          ref={uploadInputRef}
          id="file-input"
          type="file"
          multiple
          hidden
          onChange={handleFileInput}
          accept={".pdf,.docx,.pptx,.xlsx,.jpg,.jpeg,.png,.webp"
        }
        />

        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
          <Box 
            sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center',
              width: { xs: 64, sm: 80 },
              height: { xs: 64, sm: 80 },
              borderRadius: '50%',
              bgcolor: dragActive ? 'primary.light' : 'action.hover',
              mb: 1,
              transition: 'all 0.3s ease'
            }}
          >
            <UploadIcon sx={{ fontSize: { xs: 36, sm: 48 }, color: dragActive ? 'primary.main' : 'text.secondary' }} />
          </Box>
          <Typography variant="h6" color="text.primary" fontWeight={500}>
            {dragActive ? 'Drop files here' : 'Drag & drop files here'}
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 1 }}>
            or <Box component="span" sx={{ color: 'primary.main', fontWeight: 500 }}>click to browse</Box>
          </Typography>
          <Typography variant="caption" color="text.secondary" sx={{ fontSize: { xs: '0.75rem', sm: '0.875rem' } }}>
            Supported files: {SUPPORTED_FILE_TYPES.join(', ')}
          </Typography>
        </Box>
      </Paper>

      {files.length > 0 && (
        <Fade in={true} timeout={500}>
          <Box sx={{ mb: 4 }}>
            <Typography variant="subtitle2" fontWeight={600} gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <FileDescriptionIcon fontSize="small" color="primary" />
              Uploaded Files ({files.length})
            </Typography>
            <Grid container spacing={2}>
              {files.map((file, index) => (
                <Grid item xs={12} sm={6} md={4} key={index}>
                  <Paper
                    elevation={2}
                    sx={{ 
                      p: 2, 
                      display: 'flex', 
                      flexDirection: 'column', 
                      gap: 1,
                      borderRadius: 2,
                      transition: 'all 0.2s ease',
                      '&:hover': {
                        transform: 'translateY(-2px)',
                        boxShadow: 4,
                      }
                    }}
                  >
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                      <Typography variant="body2" fontWeight={500} sx={{ flex: 1, mr: 1, overflow: 'hidden', textOverflow: 'ellipsis' }}>
                        {file.name}
                      </Typography>
                      <IconButton 
                        size="small" 
                        color="error" 
                        onClick={() => removeFile(index)}
                        sx={{ opacity: 0.7, '&:hover': { opacity: 1 } }}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Box>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                      <Typography variant="caption" color="text.secondary">
                        {(file.size / 1024 / 1024).toFixed(2)} MB
                      </Typography>
                      <Chip
                        size="small"
                        label={isImageFile(file) ? 'Image' : file.name.split('.').pop().toUpperCase()}
                        color={isImageFile(file) ? 'success' : 'default'}
                        variant="filled"
                        sx={{ fontSize: '0.7rem' }}
                      />
                    </Box>
                  </Paper>
                </Grid>
              ))}
            </Grid>
          </Box>
        </Fade>
      )}

      <Divider sx={{ my: 3 }} />

      <Box>
        <Typography variant="subtitle1" fontWeight={600} gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <AccountCircleIcon fontSize="small" color="primary" />
          Customer Information
        </Typography>
        <Grid container spacing={2}>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              size="small"
              label="Your Name"
              value={customerInfo.name}
              onChange={(e) => setCustomerInfo({ ...customerInfo, name: e.target.value })}
              required
              InputProps={{ startAdornment: <InputAdornment position="start"><AccountCircleIcon fontSize="small" sx={{ color: 'text.secondary' }} /></InputAdornment> }}
              placeholder="e.g., John Doe"
            />
          </Grid>
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              size="small"
              label="Phone Number"
              value={customerInfo.phone}
              onChange={(e) => setCustomerInfo({ ...customerInfo, phone: e.target.value })}
              required
              InputProps={{ startAdornment: <InputAdornment position="start"><PhoneIcon fontSize="small" sx={{ color: 'text.secondary' }} /></InputAdornment> }}
              placeholder="e.g., +1234567890"
            />
          </Grid>
        </Grid>
      </Box>
    </Box>
  );
}

