// ORDER MANAGEMENT
// ============================================

model Customer {
  id        String   @id @default(cuid())
  shopId    String
  name      String
  phone     String?
  email     String?
  orders    Order[]
  createdAt DateTime @default(now())

  shop      Shop     @relation(fields: [shopId], references: [id])

  @@unique([shopId, phone])
  @@index([shopId])
}

model Order {
  id              String   @id @default(cuid())
  shopId          String
  token           Int      // Sequential per shop (#1, #2, #3...)
  customerId      String?
  status          OrderStatus @default(PENDING)
  paymentStatus   PaymentStatus @default(UNPAID)
  paymentMethod   String?  // cash, upi, card, online
  paymentRef      String?  // UPI ref, transaction ID

  // Pricing
  subtotal        Float    @default(0)
  tax             Float    @default(0)
  discount        Float    @default(0)
  total           Float    @default(0)

  // Notes
  customerNotes   String?
  adminNotes      String?

  // Timestamps
  createdAt       DateTime @default(now())
  approvedAt      DateTime?
  printingAt      DateTime?
  completedAt     DateTime?
  cancelledAt     DateTime?
  cancelledReason String?

  shop            Shop     @relation(fields: [shopId], references: [id])
  customer        Customer? @relation(fields: [customerId], references: [id])
  files           File[]
  printJobs       PrintJob[]

  @@unique([shopId, token])
  @@index([shopId, status])
  @@index([shopId, createdAt])
  @@index([token])
}

enum OrderStatus {
  PENDING
  APPROVED
  PRINTING
  COMPLETED
  CANCELLED
  FAILED
}

enum PaymentStatus {
  UNPAID
  PAID
  REFUNDED
}

model File {
  id            String   @id @default(cuid())
  orderId       String
  shopId        String
  originalName  String
  storageKey    String   // S3 key
  fileType      String   // pdf, docx, jpg, etc.
  size          Int      // bytes
  pageCount     Int      @default(0)
  colorPageCount Int     @default(0)
  orientation   String   @default("portrait")
  analysis      Json     // Full analysis result

  // Relations
  order         Order    @relation(fields: [orderId], references: [id])
  shop          Shop     @relation(fields: [shopId], references: [id])
  printJobs     PrintJob[]

  createdAt     DateTime @default(now())

  @@index([orderId])
  @@index([shopId])
}

model PrintJob {
  id              String   @id @default(cuid())
  orderId         String
  fileId          String
  shopId          String
  printerId       String?

  sectionIndex    Int      @default(0)
  pages           String   // JSON array [1,2,3,5-10]
  colorMode       String   @default("bw") // bw, color, auto
  printStyle      String   @default("single") // single, duplex
  paperSize       String   @default("A4")
  pagesPerSheet   Int      @default(1)
  flipDirection   String   @default("long-edge")
  copies          Int      @default(1)

  status          JobStatus @default(PENDING)
  errorMessage    String?

  // Agent tracking
  downloadedAt    DateTime?
  printedAt       DateTime?
  agentMachineId  String?

  createdAt       DateTime @default(now())
  updatedAt       DateTime @updatedAt

  order           Order    @relation(fields: [orderId], references: [id])
  file            File     @relation(fields: [fileId], references: [id])
  printer         Printer? @relation(fields: [printerId], references: [id])
  shop            Shop     @relation(fields: [shopId], references: [id])

  @@index([orderId])
  @@index([shopId, status])
  @@index([printerId])
