### **Desktop Agent API** (Critical - for .exe)

```typescript
// apps/api/src/modules/agent/agent.routes.ts

export async function agentRoutes(app: FastifyInstance) {

  // Agent registers on first run
  app.post('/register', async (req, reply) => {
    const { machineName, activationKey, osInfo } = req.body;

    // Validate activation key
    const shop = await prisma.shop.findUnique({ 
      where: { activationKey } 
    });

    if (!shop) throw new Error('Invalid activation key');
    if (shop.isActivated) throw new Error('Key already used');

    // Generate machine ID + API key
    const machineId = crypto.randomUUID();
    const apiKey = crypto.randomBytes(32).toString('hex');

    const agent = await prisma.agent.create({
      data: {
        shopId: shop.id,
        machineName,
        machineId,
        apiKey,
        osInfo,
      },
    });

    // Mark shop as activated
    await prisma.shop.update({
      where: { id: shop.id },
      data: { isActivated: true, activatedAt: new Date() },
    });

    return { machineId, apiKey, shopName: shop.name };
  });

  // Agent heartbeat (every 30s)
  app.post('/heartbeat', { preHandler: [agentAuth] }, async (req, reply) => {
    const { agent } = req;

    await prisma.agent.update({
      where: { id: agent.id },
      data: { lastHeartbeatAt: new Date(), ipAddress: req.ip },
    });

    // Return pending jobs count + any config updates
    const pendingJobs = await prisma.printJob.count({
      where: { shopId: agent.shopId, status: 'READY' },
    });

    return { 
      pendingJobs, 
      serverTime: Date.now(),
      configVersion: '1.0.0' 
    };
  });

  // Fetch pending jobs for agent
  app.get('/jobs', { preHandler: [agentAuth] }, async (req, reply) => {
    const { agent } = req;

    const jobs = await prisma.printJob.findMany({
      where: { 
        shopId: agent.shopId, 
        status: 'READY',
      },
      include: { file: true, printer: true },
      orderBy: { createdAt: 'asc' },
      take: 10,
    });

    return jobs;
  });

  // Job file download URL (signed S3 URL)
  app.get('/jobs/:id/file', { preHandler: [agentAuth] }, async (req, reply) => {
    const { id } = req.params;
    const { agent } = req;

    const job = await prisma.printJob.findFirst({
      where: { id, shopId: agent.shopId },
      include: { file: true },
    });

    if (!job) throw new Error('Job not found');

    // Generate signed URL (expires in 5 min)
    const signedUrl = await s3.getSignedUrl('getObject', {
      Bucket: env.S3_BUCKET,
      Key: job.file.storageKey,
      Expires: 300,
    });

    // Update status
    await prisma.printJob.update({
      where: { id },
      data: { status: 'DOWNLOADING', downloadedAt: new Date() },
    });

    return { downloadUrl: signedUrl, fileName: job.file.originalName };
  });

  // Update job status (printing, completed, failed)
  app.put('/jobs/:id/status', { preHandler: [agentAuth] }, async (req, reply) => {
    const { id } = req.params;
    const { status, errorMessage } = req.body;
    const { agent } = req;

    const data: any = { status, agentMachineId: agent.machineId };

    if (status === 'PRINTING') data.printingAt = new Date();
    if (status === 'COMPLETED') data.printedAt = new Date();
    if (errorMessage) data.errorMessage = errorMessage;

    await prisma.printJob.update({ where: { id }, data });

    // If completed, update printer counter
    if (status === 'COMPLETED') {
      await prisma.printer.update({
        where: { id: job.printerId },
        data: { 
          totalPrints: { increment: 1 },
          totalPages: { increment: job.pages },
          lastPrintAt: new Date(),
        },
      });
    }

    return { success: true };
  });

  // Log agent activity
  app.post('/logs', { preHandler: [agentAuth] }, async (req, reply) => {
    const { agent } = req;
    const { level, message, metadata } = req.body;

    // Store in time-series DB or log aggregator
    await auditLogger.log({
      shopId: agent.shopId,
      action: 'agent.log',
      level,
      message,
      metadata,
    });

    return { success: true };
  });
}

// Agent auth middleware
async function agentAuth(req: FastifyRequest, reply: FastifyReply) {
  const apiKey = req.headers['x-api-key'] as string;
  if (!apiKey) return reply.code(401).send({ error: 'No API key' });

  const agent = await prisma.agent.findUnique({ where: { apiKey } });
  if (!agent || !agent.isActive) return reply.code(401).send({ error: 'Invalid key' });

  req.agent = agent;
}
