## 🔄 Job Processing Queue (BullMQ)

```typescript
// apps/api/src/queues/order.queue.ts

import { Queue, Worker } from 'bullmq';

// Order processing queue
export const orderQueue = new Queue('orders', { connection: redis });

// Worker (runs in separate process)
export const orderWorker = new Worker('orders', async (job) => {
  const { orderId, action } = job.data;

  switch (action) {
    case 'PROCESS':
      return await processOrder(orderId);
    case 'SPLIT_PRINT_JOBS':
      return await splitPrintJobs(orderId);
    case 'DISPATCH_TO_AGENT':
      return await dispatchToAgent(orderId);
    case 'SEND_WHATSAPP_UPDATE':
      return await sendWhatsAppUpdate(orderId);
  }
}, { connection: redis, concurrency: 10 });

async function processOrder(orderId: string) {
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: { files: true, shop: true },
  });

  // Analyze files
  for (const file of order.files) {
    if (!file.analysis) {
      const analysis = await analyzeFile(file.storageKey);
      await prisma.file.update({
        where: { id: file.id },
        data: { analysis, pageCount: analysis.pages, colorPageCount: analysis.colorPages },
      });
    }
  }

  // Calculate pricing
  await calculateOrderTotal(orderId);

  // Auto-approve if configured
  const settings = order.shop.settings as any;
  if (settings.autoApprove) {
    await prisma.order.update({
      where: { id: orderId },
      data: { status: 'APPROVED', approvedAt: new Date() },
    });

    // Dispatch to agent
    await orderQueue.add('dispatch', { orderId, action: 'DISPATCH_TO_AGENT' });
  }

  // Notify shop via WebSocket
  await notifyShop(order.shopId, 'order.new', { orderId });
}
