## 🔌 WebSocket Real-time (Socket.io)

```typescript
// apps/api/src/sockets/shop.socket.ts

export function setupSockets(io: Server) {

  // Shop namespace (admin dashboard)
  const shopNsp = io.of('/shop');

  shopNsp.use(async (socket, next) => {
    const token = socket.handshake.auth.token;
    try {
      const decoded = jwt.verify(token, env.JWT_SECRET);
      socket.shopId = decoded.shopId;
      socket.join(`shop:${decoded.shopId}`);
      next();
    } catch (err) {
      next(new Error('Auth failed'));
    }
  });

  shopNsp.on('connection', (socket) => {
    console.log(`Shop ${socket.shopId} connected`);

    // Subscribe to order updates
    socket.on('order:subscribe', (orderId) => {
      socket.join(`order:${orderId}`);
    });

    // Agent heartbeat via WS (alternative to HTTP)
    socket.on('agent:heartbeat', async (data) => {
      await prisma.agent.update({
        where: { machineId: data.machineId },
        data: { lastHeartbeatAt: new Date() },
      });
    });
  });

  // Notify helpers
  global.notifyShop = (shopId: string, event: string, data: any) => {
    shopNsp.to(`shop:${shopId}`).emit(event, data);
  };

  global.notifyOrder = (orderId: string, event: string, data: any) => {
    shopNsp.to(`order:${orderId}`).emit(event, data);
  };
}
