      activationKey,
      activationUrl: `${req.protocol}://${req.get('host')}/activate/${activationKey}`,
    },
  });
}));

// Get all shops with stats (super-admin dashboard)
app.get('/api/admin/shops', authenticate, asyncHandler(async (req, res) => {
  const shops = await prisma.shop.findMany({
    include: {
      _count: {
        select: {
          orders: true,
          printers: true,
          users: true,
        },
      },
      agents: {
        where: { isActive: true },
        select: { lastHeartbeatAt: true },
      },
    },
    orderBy: { createdAt: 'desc' },
  });

  res.json({ success: true, data: shops });
}));

// Validate activation key (agent first-run)
app.post('/api/activate', asyncHandler(async (req, res) => {
  const { activationKey, machineName, osInfo } = req.body;

  if (!activationKey) throw new AppError('Activation key required', 400, 'MISSING_KEY');

  const shop = await prisma.shop.findUnique({
    where: { activationKey },
  });

  if (!shop) throw new AppError('Invalid activation key', 404, 'INVALID_KEY');
  if (shop.isActivated) throw new AppError('Key already used', 400, 'KEY_USED');

  // Generate machine ID and API key
  const machineId = uuidv4();
  const apiKey = uuidv4().replace(/-/g, '') + uuidv4().replace(/-/g, '');

  // Create agent
  const agent = await prisma.agent.create({
    data: {
      shopId: shop.id,
      machineName: machineName || 'COUNTER-1',
      machineId,
      apiKey,
      osInfo,
    },
  });

  // Activate shop
  await prisma.shop.update({
    where: { id: shop.id },
    data: { isActivated: true, activatedAt: new Date() },
  });

  res.json({
    success: true,
    data: {
      machineId,
      apiKey,
      shopName: shop.name,
      shopId: shop.id,
    },
  });
}));

// Agent heartbeat
app.post('/api/agent/heartbeat', asyncHandler(async (req, res) => {
  const apiKey = req.headers['x-api-key'] || req.body.apiKey;
  if (!apiKey) throw new AppError('API key required', 401, 'MISSING_API_KEY');

  const agent = await prisma.agent.findUnique({
    where: { apiKey },
  });

  if (!agent || !agent.isActive) throw new AppError('Invalid API key', 401, 'INVALID_KEY');

  // Update heartbeat
  await prisma.agent.update({
    where: { id: agent.id },
    data: { lastHeartbeatAt: new Date(), ipAddress: req.ip },
  });

  // Check subscription
  const shop = await prisma.shop.findUnique({
    where: { id: agent.shopId },
    select: { subscriptionStatus: true, subscriptionEndsAt: true },
  });

  // Get pending job count
  const pendingJobs = await prisma.printJob.count({
    where: { shopId: agent.shopId, status: 'READY' },
  });

  res.json({
    success: true,
    data: {
      pendingJobs,
      serverTime: Date.now(),
      subscriptionStatus: shop?.subscriptionStatus,
      subscriptionEndsAt: shop?.subscriptionEndsAt,
    },
  });
}));

// Agent fetch jobs (authenticated with API key)
app.get('/api/agent/v2/jobs', asyncHandler(async (req, res) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey) throw new AppError('API key required', 401, 'MISSING_API_KEY');

  const agent = await prisma.agent.findUnique({
    where: { apiKey },
  });

  if (!agent || !agent.isActive) throw new AppError('Invalid API key', 401, 'INVALID_KEY');

  // Check subscription
  const shop = await prisma.shop.findUnique({
    where: { id: agent.shopId },
    select: { subscriptionStatus: true, subscriptionEndsAt: true },
  });

  if (shop?.subscriptionStatus === 'EXPIRED' || shop?.subscriptionStatus === 'SUSPENDED') {
    throw new AppError('Subscription expired. Please renew.', 403, 'SUBSCRIPTION_EXPIRED');
  }

  // Fetch ready jobs
  const jobs = await prisma.printJob.findMany({
    where: {
      shopId: agent.shopId,
      status: 'READY',
    },
    include: {
      file: { select: { id: true, originalName: true, fileType: true, storagePath: true } },
      order: { select: { id: true, token: true } },
      printer: { select: { id: true, name: true, ip: true } },
    },
    orderBy: { createdAt: 'asc' },
    take: 10,
  });

  res.json({ success: true, data: jobs });
}));

// Agent download file (authenticated with API key)
app.get('/api/agent/v2/jobs/:id/file', asyncHandler(async (req, res) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey) throw new AppError('API key required', 401, 'MISSING_API_KEY');

  const agent = await prisma.agent.findUnique({
    where: { apiKey },
  });

  if (!agent || !agent.isActive) throw new AppError('Invalid API key', 401, 'INVALID_KEY');

  const { id } = req.params;

  const job = await prisma.printJob.findUnique({
    where: { id },
    include: { file: true },
  });

  if (!job || job.shopId !== agent.shopId) throw new AppError('Job not found', 404, 'NOT_FOUND');

  // Update status
  await prisma.printJob.update({
    where: { id },
    data: { status: 'DOWNLOADING', downloadedAt: new Date(), agentMachineId: agent.machineId },
  });

  // Find print-ready file
  const printReadyDir = path.join(path.dirname(job.file.storagePath), 'print-ready');
  let filePath = job.file.storagePath;

  try {
    const files = await fsPromises.readdir(printReadyDir);
    const match = files.find(f => f.includes(id) && f.endsWith('_printready.pdf'));
    if (match) filePath = path.join(printReadyDir, match);
  } catch {}

  if (!filePath || !fs.existsSync(filePath)) {
    throw new AppError('Print file not ready yet', 404, 'FILE_NOT_READY');
  }

  res.sendFile(filePath);
}));

// Agent update job status
app.put('/api/agent/v2/jobs/:id/status', asyncHandler(async (req, res) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey) throw new AppError('API key required', 401, 'MISSING_API_KEY');

  const agent = await prisma.agent.findUnique({
    where: { apiKey },
  });

  if (!agent || !agent.isActive) throw new AppError('Invalid API key', 401, 'INVALID_KEY');

  const { id } = req.params;
  const { status, errorMessage } = req.body;

  const job = await prisma.printJob.findUnique({ where: { id } });
  if (!job || job.shopId !== agent.shopId) throw new AppError('Job not found', 404, 'NOT_FOUND');

  const updateData = { status, agentMachineId: agent.machineId };
  if (status === 'PRINTING') updateData.printingAt = new Date();
  if (status === 'COMPLETED') updateData.printedAt = new Date();
  if (errorMessage) updateData.errorMessage = errorMessage;

  await prisma.printJob.update({ where: { id }, data: updateData });

  // Update printer counter
  if (status === 'COMPLETED' && job.printerId) {
    await prisma.prisma.update({
      where: { id: job.printerId },
      data: { totalPrints: { increment: 1 }, totalPages: { increment: 1 }, lastPrintAt: new Date() },
    });
  }

  // Check if all jobs for the order are done
  const orderJobs = await prisma.printJob.findMany({ where: { orderId: job.orderId } });
  const allDone = orderJobs.every(j => j.status === 'COMPLETED' || j.status === 'FAILED');
  if (allDone) {
    const hasFailed = orderJobs.some(j => j.status === 'FAILED');
    await prisma.order.update({
      where: { id: job.orderId },
      data: { status: hasFailed ? 'FAILED' : 'COMPLETED', completedAt: new Date() },
    });
  }

  res.json({ success: true });
}));

// ============================================
// NOTIFICATIONS
// ============================================

// Get notifications for a shop
app.get('/api/notifications', authenticate, asyncHandler(async (req, res) => {
  const shopId = req.user.shopId;

  const notifications = await prisma.notification.findMany({
    where: { shopId },
    orderBy: { createdAt: 'desc' },
    take: 50,
  });

  const unreadCount = await prisma.notification.count({
    where: { shopId, isRead: false },
  });

  res.json({ success: true, data: notifications, unreadCount });
}));

// Mark notification as read
app.put('/api/notifications/:id/read', authenticate, asyncHandler(async (req, res) => {
  const { id } = req.params;
  await prisma.notification.update({
    where: { id },
    data: { isRead: true, readAt: new Date() },
  });
  res.json({ success: true });
}));

// ============================================
// DASHBOARD STATS
// ============================================

// Get shop dashboard stats
app.get('/api/dashboard/stats', authenticate, asyncHandler(async (req, res) => {
  const shopId = req.user.shopId;
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const [
    todayOrders,
    todayRevenue,
    pendingOrders,
    printingOrders,
    completedToday,
    totalCustomers,
    activePrinters,
  ] = await Promise.all([
    prisma.order.count({ where: { shopId, createdAt: { gte: today } } }),
    prisma.order.aggregate({
      where: { shopId, status: 'COMPLETED', completedAt: { gte: today } },
      _sum: { total: true },
    }),
    prisma.order.count({ where: { shopId, status: 'PENDING' } }),
    prisma.order.count({ where: { shopId, status: 'PRINTING' } }),
    prisma.order.count({
      where: { shopId, status: 'COMPLETED', completedAt: { gte: today } },
    }),
    prisma.customer.count({ where: { shopId } }),
    prisma.printer.count({ where: { shopId, status: 'ONLINE' } }),
  ]);

  // Hourly stats for chart
  const hourlyStats = [];
  for (let i = 0; i < 24; i++) {
    const hourStart = new Date(today);
    hourStart.setHours(i, 0, 0, 0);
    const hourEnd = new Date(today);
    hourEnd.setHours(i + 1, 0, 0, 0);

    const count = await prisma.order.count({
      where: {
        shopId,
        createdAt: { gte: hourStart, lt: hourEnd },
      },
    });
    hourlyStats.push({ hour: i, count });
  }

  res.json({
    success: true,
    data: {
      todayOrders,
      todayRevenue: todayRevenue._sum.total || 0,
      pendingOrders,
      printingOrders,
      completedToday,
      totalCustomers,
      activePrinters,
      hourlyStats,
    },
  });
}));

// ============================================
// SUBSCRIPTION & PLANS
// ============================================

// Get available plans
app.get('/api/plans', asyncHandler(async (req, res) => {
  const plans = await prisma.plan.findMany({
    where: { isActive: true },
    orderBy: { priceMonthly: 'asc' },
  });
  res.json({ success: true, data: plans });
}));

// Update shop subscription (admin only)
app.put('/api/admin/shops/:id/subscription', authenticate, asyncHandler(async (req, res) => {
  const { id } = req.params;
  const { planId, status, endsAt } = req.body;

  const shop = await prisma.shop.update({
    where: { id },
    data: {
      planId,
      subscriptionStatus: status,
      subscriptionEndsAt: endsAt ? new Date(endsAt) : undefined,
    },
  });

  res.json({ success: true, data: shop });
}));

// ============================================
// ENHANCED ORDER ENDPOINTS
// ============================================

// Update order status with printer selection + agent dispatch
app.put('/api/admin/orders/:id/dispatch', authenticate, asyncHandler(async (req, res) => {
  const { id } = req.params;
  const { printerId, agentMachineId } = req.body;

  const order = await prisma.order.findUnique({
    where: { id },
    include: { printJobs: true },
  });

  if (!order || order.shopId !== req.user.shopId) {
    throw new AppError('Order not found', 404, 'NOT_FOUND');
  }

  // Update print jobs with selected printer
  if (printerId) {
    await prisma.printJob.updateMany({
      where: { orderId: id },
      data: { printerId, status: 'READY' },
    });
  }

  // Update order
  await prisma.order.update({
    where: { id },
    data: { status: 'PRINTING', printingAt: new Date() },
  });

  // Create notification for agent
  await prisma.notification.create({
    data: {
      shopId: req.user.shopId,
      type: 'order.dispatch',
      title: `Order #${order.token} ready to print`,
      message: `${order.printJobs.length} job(s) dispatched to printer`,
      data: { orderId: id },
    },
  });

  // Notify via WebSocket
  const wss = app.get('wss');
  if (wss) {
    wss.clients.forEach(client => {
      if (client.readyState === 1) {
        client.send(JSON.stringify({
          type: 'order.dispatch',
          orderId: id,
          printerId,
        }));
      }
    });
  }

  res.json({ success: true, message: 'Order dispatched to printer' });
}));

// Get order queue with filters (for print queue page)
app.get('/api/admin/queue', authenticate, asyncHandler(async (req, res) => {
  const shopId = req.user.shopId;
  const { status, page = 1, limit = 20, search } = req.query;

  const where = {
    shopId,
    ...(status && status !== 'all' ? { status } : {}),
    ...(search ? {
      OR: [
        { token: isNaN(Number(search)) ? undefined : Number(search) },
        { customer: { name: { contains: search as string, mode: 'insensitive' } } },
        { customer: { phone: { contains: search as string } } },
      ].filter(Boolean),
    } : {}),
  };

  const [orders, total] = await Promise.all([
    prisma.order.findMany({
      where,
      include: {
        customer: true,
        files: true,
        printJobs: { include: { printer: true } },
      },
      orderBy: { createdAt: 'desc' },
      skip: (Number(page) - 1) * Number(limit),
      take: Number(limit),
    }),
    prisma.order.count({ where }),
  ]);

  res.json({
    success: true,
    data: orders,
    pagination: {
      page: Number(page),
      limit: Number(limit),
      total,
      pages: Math.ceil(total / Number(limit)),
    },
  });
}));

// ============================================
// CATCH ALL - SPA ROUTES (must be last)
// ============================================

if (fs.existsSync(FRONTEND_DIST)) {
  app.get('*', (req, res) => {
    res.sendFile(path.join(FRONTEND_DIST, 'index.html'));
  });
}

