    if (autoResponses.length <= 1) return;
    setAutoResponses(prev => prev.filter((_, i) => i !== index));
  };

  const addAutoResponse = () => {
    setAutoResponses(prev => [...prev, { trigger: '', message: '', enabled: true }]);
  };

