const WebSocket = require('C:/Users/mayank/Documents/New OpenCode Project/patel-autoprint/desktop/node_modules/ws');
const ws = new WebSocket(process.argv[2]);
let id = 0;
const events = [];
const send = (method, params = {}) => ws.send(JSON.stringify({ id: ++id, method, params }));
const onEvent = (method, fn) => ws.on('message', (d) => { const m = JSON.parse(d.toString()); if (m.method === method) fn(m.params); });
ws.on('open', () => {
  send('Runtime.enable');
  send('Log.enable');
  send('Page.enable');
  onEvent('Runtime.exceptionThrown', (p) => events.push('EXCEPTION: ' + JSON.stringify(p.exceptionDetails && p.exceptionDetails.exception ? p.exceptionDetails.exception.description : p.exceptionDetails.text)));
  onEvent('Runtime.consoleAPICalled', (p) => events.push('CONSOLE.' + p.type + ': ' + p.args.map(a => a.value || a.description || '').join(' ')));
  onEvent('Log.entryAdded', (p) => events.push('LOG.' + p.entry.level + ': ' + p.entry.text));
  onEvent('Runtime.loadEventFired', () => {});
  setTimeout(() => { send('Page.reload', { ignoreCache: true }); }, 1000);
  setTimeout(() => {
    console.log('EVENTS:\n' + (events.length ? events.join('\n') : '(none)'));
    const expr = "JSON.stringify({rootChildren: document.getElementById('root') ? document.getElementById('root').childElementCount : 'NO ROOT', resources: performance.getEntriesByType('resource').map(r => r.name).filter(n => n.includes('assets')).join('|')})";
    send('Runtime.evaluate', { expression: expr, returnByValue: true });
  }, 4000);
});
