const wsUrl = process.argv[2];
const key = process.argv[3];
const apiUrl = process.argv[4] || 'http://localhost:5000';

const ws = new WebSocket(wsUrl);
let id = 0;
const pending = new Map();

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const msgId = ++id;
    pending.set(msgId, { resolve, reject });
    ws.send(JSON.stringify({ id: msgId, method, params }));
  });
}

ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
};

ws.onopen = async () => {
  try {
    await send('Runtime.enable');
    const sleep = (ms) => new Promise(r => setTimeout(r, ms));
    await sleep(1000);

    const evalJs = async (expr) => {
      const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
      return r.result && r.result.value;
    };

    let text = await evalJs('document.body.innerText');
    console.log('=== BODY TEXT (initial) ===');
    console.log(text);
    console.log('=== END ===');

    const fill = `
      (() => {
        const inputs = Array.from(document.querySelectorAll('input'));
        const urlInput = inputs.find(i => (i.placeholder || '').includes('patel-autoprint')) || inputs[0];
        const keyInput = inputs.find(i => (i.placeholder || '').includes('PATEL')) || inputs[1];
        const setVal = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        if (urlInput) { setVal.call(urlInput, '${apiUrl}'); urlInput.dispatchEvent(new Event('input', { bubbles: true })); }
        if (keyInput) { setVal.call(keyInput, '${key}'); keyInput.dispatchEvent(new Event('input', { bubbles: true })); }
        return { urlInput: !!urlInput, keyInput: !!keyInput };
      })()
    `;
    console.log('FILL RESULT:', JSON.stringify(await evalJs(fill)));
    await sleep(500);

    const click = `
      (() => {
        const btn = Array.from(document.querySelectorAll('button')).find(b => (b.textContent || '').trim().startsWith('Activate'));
        if (btn) { btn.click(); return true; }
        return false;
      })()
    `;
    console.log('CLICKED ACTIVATE:', await evalJs(click));
    await sleep(5000);

    text = await evalJs('document.body.innerText');
    console.log('=== BODY TEXT (after activate) ===');
    console.log(text.slice(0, 1500));
    console.log('=== END ===');

    const storage = await evalJs('JSON.stringify(window.localStorage)');
    console.log('=== localStorage ===');
    console.log(storage);
    process.exit(0);
  } catch (e) {
    console.error('ERROR:', e.message);
    process.exit(1);
  }
};

ws.onerror = (e) => {
  console.error('WS ERROR:', e.message || e);
  process.exit(1);
};

setTimeout(() => { console.error('TIMEOUT'); process.exit(1); }, 45000);

