          code: 'UNAUTHORIZED',
        });
      }

      req.user = {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
        shopId: user.shopId,
      };

      return next();
    }

    const apiKey = req.headers['x-api-key'];
    if (apiKey) {
      const agent = await prisma.agent.findFirst({
        where: { apiKey, isActive: true },
        include: { shop: true },
