const wsUrl = process.argv[2];
const ws = new WebSocket(wsUrl);
let id = 0;
const pending = new Map();

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const msgId = ++id;
    pending.set(msgId, { resolve, reject });
    ws.send(JSON.stringify({ id: msgId, method, params }));
  });
}

ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
};

ws.onopen = async () => {
  try {
    await send('Runtime.enable');
    const sleep = (ms) => new Promise(r => setTimeout(r, ms));
    const evalJs = async (expr) => {
      const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
      return r.result && r.result.value;
    };

    // Reload to simulate app restart
    await send('Page.enable');
    await send('Page.reload', { ignoreCache: true });
    await sleep(6000);

    let text = await evalJs('document.body.innerText');
    console.log('=== AFTER RELOAD (first 500) ===');
    console.log(text.slice(0, 500));
    console.log('=== END ===');

    // Check we're NOT on activation screen
    const onActivation = await evalJs('document.body.innerText.includes("Activate this machine")');
    console.log('ON ACTIVATION SCREEN?', onActivation);

    // Click "Daily Stats" nav
    const clickDaily = await evalJs(`
      (() => {
        const el = Array.from(document.querySelectorAll('*')).find(e => e.children.length === 0 && e.textContent.trim() === 'Daily Stats' && e.closest('a'));
        if (el) { el.closest('a').click(); return true; }
        return false;
      })()
    `);
    console.log('CLICKED Daily Stats:', clickDaily);
    await sleep(3000);
    text = await evalJs('document.body.innerText');
    console.log('=== DAILY STATS PAGE (first 600) ===');
    console.log(text.slice(0, 600));
    console.log('=== END ===');

    // Click "Start Agent"
    const clickStart = await evalJs(`
      (() => {
        const el = Array.from(document.querySelectorAll('button')).find(b => (b.textContent || '').trim().startsWith('Start Agent'));
        if (el) { el.click(); return true; }
        return false;
      })()
    `);
    console.log('CLICKED Start Agent:', clickStart);
    await sleep(4000);
    text = await evalJs('document.body.innerText');
    console.log('=== AFTER START AGENT (agent status region) ===');
    const idx = text.indexOf('Agent Status');
    console.log(text.slice(idx < 0 ? 0 : idx, (idx < 0 ? 600 : idx + 300)));
    console.log('=== END ===');
    process.exit(0);
  } catch (e) {
    console.error('ERROR:', e.message);
    process.exit(1);
  }
};

ws.onerror = (e) => {
  console.error('WS ERROR:', e.message || e);
  process.exit(1);
};

setTimeout(() => { console.error('TIMEOUT'); process.exit(1); }, 60000);

