const fs = require('fs');
const path = require('path');

const dir = process.argv[2];
const files = [];
(function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (/\.(tsx|ts)$/.test(e.name)) files.push(p);
  }
})(dir);

const IMPORT_RE = /import\s+(?:(\{[^}]*\})|([^;]*?))\s+from\s+['"][^'"]+['"]/g;
const LOCAL_RE = /\b(?:const|let|var|function)\s+([A-Za-z_$][\w$]*)/g;
const IMPORT_SPEC_RE = /([A-Za-z_$][\w$]*)(?:\s+as\s+([A-Za-z_$][\w$]*))?/g;

let problems = 0;
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  const defined = new Set();
  const imported = new Set();
  let m;
  IMPORT_RE.lastIndex = 0;
  while ((m = IMPORT_RE.exec(src))) {
    const spec = m[1] || m[2] || '';
    if (spec.startsWith('{')) {
      IMPORT_SPEC_RE.lastIndex = 0;
      let sm;
      while ((sm = IMPORT_SPEC_RE.exec(spec))) {
        if (!sm[1] || sm[1].includes(' ')) continue;
        imported.add(sm[2] || sm[1]);
      }
    } else if (spec) {
      imported.add(spec.trim());
    }
  }
  LOCAL_RE.lastIndex = 0;
  while ((m = LOCAL_RE.exec(src))) defined.add(m[1]);
  // destructured params and hooks
  for (const p of src.matchAll(/\bconst\s*\{([^}]*)\}\s*=\s*[A-Za-z_$][\w$]*/g)) {
    for (const part of p[1].split(',')) {
      const name = part.trim().split(':')[0].split('=')[0].trim();
      if (name) defined.add(name);
    }
  }
  // capitalized identifiers used
  const used = new Set(src.matchAll(/\b[A-Z][A-Za-z0-9_$]*\b/g).map((x) => x[0]));
  const missing = [];
  for (const u of used) {
    if (u === 'React') continue;
    if (defined.has(u) || imported.has(u)) continue;
    if (/^(HTML|Window|File|NodeJS|Promise|Error|Date|Number|String|Object|Array|Function|JSON|Math|Set|Map|FormData|Blob|Response|Request|Headers|URL|Event|KeyboardEvent|MouseEvent)/.test(u)) continue;
    missing.push(u);
  }
  if (missing.length) {
    problems++;
    console.log(`${path.relative(dir, f)}: UNUSED-IMPORT-OR-MISSING-GLOBAL -> ${missing.join(', ')}`);
  }
}
console.log(`\nChecked ${files.length} files, ${problems} files with potential issues.`);

