const fs = require('fs');
const path = require('path');

const dir = process.argv[2];
const files = [];
(function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (/\.(tsx|ts)$/.test(e.name)) files.push(p);
  }
})(dir);

let problems = 0;
for (const f of files) {
  const src = fs.readFileSync(f, 'utf8');
  const imported = new Set();
  const importBlocks = [...src.matchAll(/import\s+(\{[^}]*\}|[^;]+?)\s+from\s+['"][^'"]+['"]/g)];
  for (const blk of importBlocks) {
    const spec = blk[1].trim();
    if (spec.startsWith('{')) {
      for (const sm of spec.slice(1, -1).split(',')) {
        const t = sm.trim();
        if (!t) continue;
        const asMatch = t.match(/([\w$]+)\s+as\s+([\w$]+)/);
        imported.add(asMatch ? asMatch[2] : t.split(':')[0].split('=')[0].trim());
      }
    } else {
      imported.add(spec.split(/\s+as\s+/)[0].trim().split(/\s/).pop());
    }
  }
  // default import name
  for (const blk of importBlocks) {
    const spec = blk[1].trim();
    if (!spec.startsWith('{')) {
      const name = spec.match(/^([\w$]+)/);
      if (name) imported.add(name[1]);
    }
  }

  // JSX usages: <Xxx or <Xxx.xxx
  const used = new Set();
  for (const m of src.matchAll(/<([A-Z][\w$]*)(?:\.[\w$]+)?\b/g)) {
    used.add(m[1]);
  }

  const defined = new Set();
  for (const m of src.matchAll(/\b(?:const|let|var|function|class)\s+([A-Z][\w$]*)/g)) defined.add(m[1]);
  for (const m of src.matchAll(/\bconst\s*\{([^}]*)\}\s*=\s*useAppStore/g)) {
    for (const part of m[1].split(',')) {
      const name = part.trim().split(':')[0].split('=')[0].trim();
      if (name) defined.add(name);
    }
  }
  for (const m of src.matchAll(/import\s+\* as\s+([\w$]+)/g)) defined.add(m[1]);

  const missing = [...used].filter((u) => !imported.has(u) && !defined.has(u));
  if (missing.length) {
    problems++;
    console.log(`${path.relative(dir, f)}: MISSING -> ${missing.join(', ')}`);
  }
}
console.log(`\nChecked ${files.length} files, ${problems} files with missing JSX identifiers.`);

