const wsUrl = process.argv[2];
const ws = new WebSocket(wsUrl);
let id = 0;
const pending = new Map();
let exceptions = [];

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const msgId = ++id;
    pending.set(msgId, { resolve, reject });
    ws.send(JSON.stringify({ id: msgId, method, params }));
  });
}

ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);
  if (msg.method === 'Runtime.exceptionThrown') {
    const d = msg.params.exceptionDetails;
    const desc = d.exception && d.exception.description ? d.exception.description.split('\n')[0] : d.text;
    exceptions.push(desc);
  }
  if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') {
    const args = (msg.params.args || []).map(a => a.value !== undefined ? String(a.value) : (a.description || '')).join(' ');
    if (!args.includes('validateDOMNesting') && !args.includes('Tooltip')) exceptions.push('CONSOLE: ' + args.slice(0, 120));
  }
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
};

const clickByText = async (evalJs, text) => {
  return evalJs(`
    (() => {
      const candidates = Array.from(document.querySelectorAll('div,li,a,button,span')).filter(e => {
        const t = (e.textContent || '').trim();
        return t === '${text}' && e.children.length === 0;
      });
      for (const el of candidates) {
        const btn = el.closest('button,li,a,div[role="button"]');
        if (btn) { btn.click(); return true; }
      }
      return false;
    })()
  `);
};

ws.onopen = async () => {
  try {
    await send('Runtime.enable');
    await send('Page.enable');
    const sleep = (ms) => new Promise(r => setTimeout(r, ms));
    const evalJs = async (expr) => {
      const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true });
      return r.result && r.result.value;
    };

    await send('Page.reload', { ignoreCache: true });
    await sleep(7000);

    const pages = ['Print Queue', 'Passport Photos', 'Aadhaar / PAN', 'WhatsApp Bot', 'Daily Stats', 'Settings'];
    for (const p of pages) {
      exceptions = [];
      const ok = await clickByText(evalJs, p);
      await sleep(3500);
      const text = await evalJs('document.body.innerText');
      const hasContent = text && text.length > 80;
      const hasError = /error|failed|undefined is not|cannot read/i.test(text);
      console.log(`[${p}] clicked=${ok} content=${hasContent} errorText=${hasError} exceptions=${exceptions.length}`);
      if (exceptions.length) console.log('    -> ' + exceptions.slice(0, 3).join(' | '));
    }
    process.exit(0);
  } catch (e) {
    console.error('ERROR:', e.message);
    process.exit(1);
  }
};

ws.onerror = (e) => {
  console.error('WS ERROR:', e.message || e);
  process.exit(1);
};

setTimeout(() => { console.error('TIMEOUT'); process.exit(1); }, 90000);

