  InputAdornment,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import {
  Search as SearchIcon,
  Refresh as RefreshIcon,
  Visibility as ViewIcon,
  CheckCircle as ApproveIcon,
  Cancel as RejectIcon,
  Print as PrintIcon,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../../api';
import OrderStatusBadge from '../../components/OrderStatusBadge';

const statusFilters = [
  { value: '', label: 'All Status' },
  { value: 'PENDING', label: 'Pending' },
  { value: 'APPROVED', label: 'Approved' },
  { value: 'PRINTING', label: 'Printing' },
  { value: 'COMPLETED', label: 'Completed' },
  { value: 'REJECTED', label: 'Rejected' },
];

export default function OrderQueuePage() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [lastRefresh, setLastRefresh] = useState(new Date());
  const navigate = useNavigate();

  // Print dialog state
  const [printDialogOpen, setPrintDialogOpen] = useState(false);
  const [printOrderId, setPrintOrderId] = useState(null);
  const [bwPrinter, setBwPrinter] = useState('');
  const [colorPrinter, setColorPrinter] = useState('');
  const [printers, setPrinters] = useState([]);
  const [printDialogLoading, setPrintDialogLoading] = useState(false);

  const fetchOrders = useCallback(async () => {
    try {
      const params = new URLSearchParams();
      if (search) params.append('search', search);
      if (statusFilter) params.append('status', statusFilter);

      const result = await api.get(`/admin/orders?${params.toString()}`);
      if (result.success) {
        setOrders(result.data?.orders || []);
      }
      setLastRefresh(new Date());
    } catch {
      // Error handled by interceptor
    } finally {
      setLoading(false);
    }
  }, [search, statusFilter]);

  useEffect(() => {
    fetchOrders();
    const interval = setInterval(fetchOrders, 10000);
    return () => clearInterval(interval);
  }, [fetchOrders]);

  const handleStatusChange = async (orderId, newStatus) => {
    try {
      await api.put(`/admin/orders/${orderId}/status`, { status: newStatus });
      toast.success(`Order ${newStatus.toLowerCase()}`);
      fetchOrders();
    } catch {
      toast.error('Failed to update status');
    }
  };

  const handleReprint = async (orderId) => {
    try {
      await api.post(`/admin/orders/${orderId}/reprint`);
      toast.success('Reprint job sent');
    } catch {
      toast.error('Failed to reprint');
    }
  };

  // --- Print Dialog ---
  const openPrintDialog = async (orderId) => {
    setPrintOrderId(orderId);
    setPrintDialogOpen(true);
    setBwPrinter('');
    setColorPrinter('');
    setPrintDialogLoading(true);

    try {
      const [printersRes, settingsRes] = await Promise.all([
        api.get('/printers'),
        api.get('/settings/pricing'),
      ]);
      if (printersRes.success) {
        setPrinters(printersRes.data?.printers || []);
      }
      if (settingsRes.success && settingsRes.data) {
        setBwPrinter(settingsRes.data.defaultBwPrinter || '');
        setColorPrinter(settingsRes.data.defaultColorPrinter || '');
      }
    } catch {
      // ignore
    } finally {
      setPrintDialogLoading(false);
    }
  };

  const handlePrintConfirm = async () => {
    if (!printOrderId) return;
    try {
      const body = { status: 'PRINTING' };
      if (bwPrinter) body.bwPrinterName = bwPrinter;
      if (colorPrinter) body.colorPrinterName = colorPrinter;
      await api.put(`/admin/orders/${printOrderId}/status`, body);
      toast.success('Order approved & sent to print');
      setPrintDialogOpen(false);
      setPrintOrderId(null);
      fetchOrders();
    } catch {
      toast.error('Failed to send to print');
    }
  };

  const closePrintDialog = () => {
    setPrintDialogOpen(false);
    setPrintOrderId(null);
  };

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5">Order Queue</Typography>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="caption" color="text.secondary">
            Last refresh: {lastRefresh.toLocaleTimeString()}
          </Typography>
          <IconButton onClick={fetchOrders} size="small">
            <RefreshIcon />
          </IconButton>
        </Box>
      </Box>

      <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
        <TextField
          fullWidth
          size="small"
          placeholder="Search by Token, Name, Phone..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
          }}
        />
        <FormControl sx={{ minWidth: 160 }} size="small">
          <InputLabel>Status</InputLabel>
          <Select
            value={statusFilter}
            label="Status"
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            {statusFilters.map((f) => (
              <MenuItem key={f.value} value={f.value}>{f.label}</MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
          <CircularProgress />
        </Box>
      ) : (
        <Box sx={{ overflowX: 'auto' }}>
          <TableContainer component={Paper}>
            <Table size="small" sx={{ minWidth: 800 }}>
            <TableHead>
              <TableRow>
                <TableCell>Token</TableCell>
                <TableCell>Customer</TableCell>
                <TableCell>Phone</TableCell>
                <TableCell>Files</TableCell>
                <TableCell>Amount</TableCell>
                <TableCell>Payment</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Time</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {orders.map((order) => (
                <TableRow key={order.id} hover>
                  <TableCell sx={{ fontWeight: 700, fontSize: 14 }}>
                    #{order.token || '-'}
                  </TableCell>
                  <TableCell>{order.customer?.name || 'Walk-in'}</TableCell>
                  <TableCell>{order.customer?.phone || '-'}</TableCell>
                  <TableCell>{order.files?.length || 0}</TableCell>
                  <TableCell>₹{order.totalPrice?.toFixed(2)}</TableCell>
                  <TableCell>
                    <Chip
                      label={order.paymentMethod || 'N/A'}
                      size="small"
                      variant="outlined"
                      sx={{ textTransform: 'capitalize' }}
                    />
                  </TableCell>
                  <TableCell><OrderStatusBadge status={order.status} /></TableCell>
                  <TableCell>
                    {new Date(order.createdAt).toLocaleString('en-IN', {
                      hour: '2-digit',
                      minute: '2-digit',
                      hour12: true,
                    })}
                  </TableCell>
                  <TableCell align="right">
                    <IconButton
                      size="small"
                      onClick={() => navigate(`/admin/orders/${order.id}`)}
                      title="View Details"
                    >
                      <ViewIcon fontSize="small" />
                    </IconButton>
                    {order.status === 'PENDING' && (
                      <>
                        <IconButton
                          size="small"
                          color="success"
                          onClick={() => openPrintDialog(order.id)}
                          title="Approve & Print"
                        >
                          <ApproveIcon fontSize="small" />
                        </IconButton>
                        <IconButton
                          size="small"
                          color="error"
                          onClick={() => handleStatusChange(order.id, 'REJECTED')}
                          title="Reject"
                        >
                          <RejectIcon fontSize="small" />
                        </IconButton>
                      </>
                    )}
                    {order.status === 'APPROVED' && (
                      <IconButton
                        size="small"
                        color="primary"
                        onClick={() => openPrintDialog(order.id)}
                        title="Start Printing"
                      >
                        <PrintIcon fontSize="small" />
                      </IconButton>
                    )}
                    {order.status === 'PRINTING' && (
                      <IconButton
                        size="small"
                        color="success"
                        onClick={() => handleStatusChange(order.id, 'COMPLETED')}
                        title="Mark Complete"
                      >
                        <ApproveIcon fontSize="small" />
                      </IconButton>
                    )}
                    {order.status === 'COMPLETED' && (
                      <IconButton
                        size="small"
                        color="warning"
                        onClick={() => handleReprint(order.id)}
                        title="Reprint"
                      >
                        <PrintIcon fontSize="small" />
                      </IconButton>
                    )}
                  </TableCell>
                </TableRow>
              ))}
              {orders.length === 0 && (
                <TableRow>
                  <TableCell colSpan={9} align="center">No orders found</TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
        </Box>
      )}

      {/* Print Dialog — select printers inline, no page redirect */}
      <Dialog open={printDialogOpen} onClose={closePrintDialog} maxWidth="sm" fullWidth>
        <DialogTitle>Select Printers</DialogTitle>
        <DialogContent>
          {printDialogLoading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
              <CircularProgress />
            </Box>
          ) : (
            <Box sx={{ pt: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
              <FormControl fullWidth size="small">
                <InputLabel>B/W Printer</InputLabel>
                <Select
                  value={bwPrinter}
                  label="B/W Printer"
                  onChange={(e) => setBwPrinter(e.target.value)}
                >
                  <MenuItem value=""><em>Auto (any B/W printer)</em></MenuItem>
                  {printers.filter((p) => !p.colorSupport).map((p) => (
                    <MenuItem key={p.id} value={p.name}>{p.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
              <FormControl fullWidth size="small">
                <InputLabel>Color Printer</InputLabel>
                <Select
                  value={colorPrinter}
                  label="Color Printer"
                  onChange={(e) => setColorPrinter(e.target.value)}
                >
                  <MenuItem value=""><em>Auto (any Color printer)</em></MenuItem>
                  {printers.filter((p) => p.colorSupport).map((p) => (
                    <MenuItem key={p.id} value={p.name}>{p.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closePrintDialog}>Cancel</Button>
          <Button variant="contained" color="success" onClick={handlePrintConfirm} startIcon={<PrintIcon />}>
            Print
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Box,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  Button,
  Divider,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  CircularProgress,
  Chip,
  Alert,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import {
  ArrowBack as BackIcon,
  CheckCircle as ApproveIcon,
  Cancel as RejectIcon,
  Print as PrintIcon,
  Refresh as ReprintIcon,
  Done as CompleteIcon,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../../api';
import OrderStatusBadge from '../../components/OrderStatusBadge';

export default function OrderDetailPage() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [printJobs, setPrintJobs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [printers, setPrinters] = useState([]);
  const [bwPrinter, setBwPrinter] = useState('');
  const [colorPrinter, setColorPrinter] = useState('');

  const isImageFile = (file) => {
    const t = (file.fileType || '').toLowerCase();
    return ['jpg', 'jpeg', 'png', 'webp'].includes(t);
  };

  // Compute totals of B/W pages and Color pages the customer wants to print
  const computePageSummary = (ord) => {
    let bwPages = 0;
    let colorPages = 0;
    if (!ord || !ord.files) return { bwPages, colorPages };

    const imageFiles = ord.files.filter(isImageFile);
    const docFiles = ord.files.filter((f) => !isImageFile(f));

    // Contact sheets: all images combine into sheets = ceil(count/nUp) * copies
    if (imageFiles.length > 0) {
      const nUp = imageFiles[0].settings?.pagesPerSheet || 1;
      const copies = imageFiles[0].settings?.copies || 1;
      const anyColor = imageFiles.some((f) => (f.settings?.colorMode || 'color') === 'color');
      const sheets = Math.ceil(imageFiles.length / nUp) * copies;
      if (anyColor) colorPages += sheets;
      else bwPages += sheets;
    }

    for (const file of docFiles) {
      const s = file.settings || {};
      const sections = s.sections || [];
      const copies = s.copies || 1;
      const totalFilePages = file.pageCount || 0;
      const totalColorPages = file.colorPageCount || 0;

      if (sections.length > 0) {
        for (const sec of sections) {
          const secPages = (sec.endPage || totalFilePages) - (sec.startPage || 1) + 1;
          const secMode = sec.colorMode || s.colorMode || 'bw';
          let secColor = 0;
          if (secMode === 'color') secColor = secPages;
          else if (secMode === 'auto' && totalFilePages > 0) {
            secColor = Math.round(secPages * (totalColorPages / totalFilePages));
          }
          bwPages += (secPages - secColor) * (sec.copies || copies);
          colorPages += secColor * (sec.copies || copies);
        }
      } else {
        let actualPages = totalFilePages;
        if (s.pageRange && s.pageRange !== 'all') {
          const nums = s.pageRange.split(',').flatMap((r) => {
            const [a, b] = r.trim().split('-').map(Number);
            if (b) return Array.from({ length: b - a + 1 }, (_, i) => a + i);
            return [a];
          }).filter((n) => n >= 1 && n <= totalFilePages);
          if (nums.length) actualPages = nums.length;
        }
        const mode = s.colorMode || 'bw';
        let colorCount = 0;
        if (mode === 'color') colorCount = actualPages;
        else if (mode === 'auto' && totalFilePages > 0) {
          colorCount = Math.round(actualPages * (totalColorPages / totalFilePages));
        }
        bwPages += (actualPages - colorCount) * copies;
        colorPages += colorCount * copies;
      }
    }
    return { bwPages, colorPages };
  };

  const pageSummary = computePageSummary(order);

  useEffect(() => {
    fetchOrder();
    fetchPrintJobs();
    fetchPrinters();
  }, [id]);

  const fetchOrder = async () => {
    try {
      const result = await api.get(`/admin/orders/${id}`);
      if (result.success) {
        setOrder(result.data);
      }
    } catch {
      toast.error('Failed to load order');
    } finally {
      setLoading(false);
    }
  };

  const fetchPrintJobs = async () => {
    try {
      const result = await api.get(`/admin/orders/${id}/print-jobs`);
      if (result.success) {
        setPrintJobs(result.data || []);
      }
    } catch {
      // Print jobs may not exist yet
    }
  };

  const fetchPrinters = async () => {
    try {
      const result = await api.get('/printers');
      if (result.success) {
        const list = result.data?.printers || [];
        setPrinters(list);
        const bw = list.filter((p) => !p.colorSupport);
        const color = list.filter((p) => p.colorSupport);
        if (bw.length === 1) setBwPrinter(bw[0].name);
        if (color.length === 1) setColorPrinter(color[0].name);
      }
    } catch {
      // ignore
    }
  };

  const handleStatusChange = async (newStatus) => {
    try {
      const body = { status: newStatus };
      if (newStatus === 'PRINTING') {
        if (bwPrinter) body.bwPrinterName = bwPrinter;
        if (colorPrinter) body.colorPrinterName = colorPrinter;
      }
      await api.put(`/admin/orders/${id}/status`, body);
      toast.success(`Order ${newStatus.toLowerCase()}`);
      fetchOrder();
      fetchPrintJobs();
    } catch {
      toast.error('Failed to update status');
    }
  };

  const handleReprint = async () => {
    try {
      const body = {};
      if (bwPrinter) body.bwPrinterName = bwPrinter;
      if (colorPrinter) body.colorPrinterName = colorPrinter;
      await api.post(`/admin/orders/${id}/reprint`, body);
      toast.success('Reprint job sent');
      fetchPrintJobs();
    } catch {
      toast.error('Failed to reprint');
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  if (!order) {
    return (
      <Alert severity="error" sx={{ mt: 2 }}>
        Order not found
      </Alert>
    );
  }

  return (
    <Box>
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 3, gap: 2 }}>
        <Button startIcon={<BackIcon />} onClick={() => navigate('/admin/orders')}>
          Back to Orders
        </Button>
        <Typography variant="h5">Order Details</Typography>
        <OrderStatusBadge status={order.status} />
      </Box>

      <Grid container spacing={3}>
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>Customer Information</Typography>
              <Divider sx={{ mb: 2 }} />
              <Grid container spacing={1}>
                <Grid item xs={6}>
                  <Typography variant="body2" color="text.secondary">Name</Typography>
                  <Typography variant="body1">{order.customer?.name || 'Walk-in'}</Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="body2" color="text.secondary">Phone</Typography>
                  <Typography variant="body1">{order.customer?.phone || '-'}</Typography>
                </Grid>
                <Grid item xs={12}>
                  <Typography variant="body2" color="text.secondary">Email</Typography>
                  <Typography variant="body1">{order.customer?.email || 'N/A'}</Typography>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>Order Information</Typography>
              <Divider sx={{ mb: 2 }} />
              <Grid container spacing={1}>
                <Grid item xs={6}>
                  <Typography variant="body2" color="text.secondary">Token</Typography>
                  <Typography variant="h4" color="primary" sx={{ fontWeight: 700 }}>
                    #{order.token || '-'}
                  </Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="body2" color="text.secondary">Payment</Typography>
                  <Chip label={order.paymentMethod || 'N/A'} size="small" sx={{ textTransform: 'capitalize' }} />
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="body2" color="text.secondary">Total Amount</Typography>
                  <Typography variant="h6" color="primary">₹{order.totalPrice?.toFixed(2)}</Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="body2" color="text.secondary">Created</Typography>
                  <Typography variant="body1">
                    {new Date(order.createdAt).toLocaleString('en-IN')}
                  </Typography>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>Print Summary</Typography>
              <Divider sx={{ mb: 2 }} />
              <Grid container spacing={2}>
                <Grid item xs={6}>
                  <Box sx={{ textAlign: 'center', p: 1.5, bgcolor: 'action.hover', borderRadius: 2 }}>
                    <Typography variant="h4" sx={{ fontWeight: 700 }}>{pageSummary.bwPages}</Typography>
                    <Typography variant="body2" color="text.secondary">B/W Pages</Typography>
                  </Box>
                </Grid>
                <Grid item xs={6}>
                  <Box sx={{ textAlign: 'center', p: 1.5, bgcolor: 'action.hover', borderRadius: 2 }}>
                    <Typography variant="h4" sx={{ fontWeight: 700, color: 'secondary.main' }}>{pageSummary.colorPages}</Typography>
                    <Typography variant="body2" color="text.secondary">Color Pages</Typography>
                  </Box>
                </Grid>
                <Grid item xs={12}>
                  <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                    Total pages to print: {pageSummary.bwPages + pageSummary.colorPages}
                    {order.files?.some(isImageFile) && ' (photos counted as contact-sheet sheets)'}
                  </Typography>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>Files</Typography>
              <Divider sx={{ mb: 2 }} />
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>File Name</TableCell>
                      <TableCell>Pages</TableCell>
                      <TableCell>Paper</TableCell>
                      <TableCell>Orientation</TableCell>
                      <TableCell>Color</TableCell>
                      <TableCell>Print Style</TableCell>
                      <TableCell>Copies</TableCell>
                      <TableCell>Pages/Sheet</TableCell>
                      <TableCell>Page Range</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {order.files?.map((file, i) => (
                      <TableRow key={file.id || i}>
                        <TableCell sx={{ maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                          {file.originalName}
                        </TableCell>
                        <TableCell>{file.pageCount}</TableCell>
                        <TableCell>{file.settings?.paperSize || 'A4'}</TableCell>
                        <TableCell sx={{ textTransform: 'capitalize' }}>{file.settings?.orientation || 'auto'}</TableCell>
                        <TableCell sx={{ textTransform: 'capitalize' }}>{file.settings?.colorMode || 'bw'}</TableCell>
                        <TableCell sx={{ textTransform: 'capitalize' }}>{file.settings?.printStyle || 'single'}</TableCell>
                        <TableCell>{file.settings?.copies || 1}</TableCell>
                        <TableCell>{file.settings?.pagesPerSheet || 1}</TableCell>
                        <TableCell>{file.settings?.pageRange || 'All'}</TableCell>
                      </TableRow>
                    ))}
                    {(!order.files || order.files.length === 0) && (
                      <TableRow>
                        <TableCell colSpan={9} align="center">No files</TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </CardContent>
          </Card>
        </Grid>

        {printJobs.length > 0 && (
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>Print Jobs</Typography>
                <Divider sx={{ mb: 2 }} />
                <TableContainer>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell>Job ID</TableCell>
                        <TableCell>Printer</TableCell>
                        <TableCell>Color Mode</TableCell>
                        <TableCell>Style</TableCell>
                        <TableCell>Copies</TableCell>
                        <TableCell>Status</TableCell>
                        <TableCell>Created</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {printJobs.map((job) => (
                        <TableRow key={job.id}>
                          <TableCell sx={{ fontFamily: 'monospace', fontSize: 12 }}>
                            {job.id?.substring(0, 8)}...
                          </TableCell>
                          <TableCell>{job.assignedPrinter || 'Unassigned'}</TableCell>
                          <TableCell sx={{ textTransform: 'capitalize' }}>{job.colorMode || '-'}</TableCell>
                          <TableCell sx={{ textTransform: 'capitalize' }}>{job.printStyle || '-'}</TableCell>
                          <TableCell>{job.copies || 1}</TableCell>
                          <TableCell>
                            <Chip label={job.status || 'PENDING'} size="small" color={job.status === 'COMPLETED' ? 'success' : 'default'} />
                          </TableCell>
                          <TableCell>{new Date(job.createdAt).toLocaleString('en-IN')}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </CardContent>
            </Card>
          </Grid>
        )}

        <Grid item xs={12}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>Actions</Typography>
              <Divider sx={{ mb: 2 }} />
              {printers.length > 0 && (
                <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', mb: 2 }}>
                  <FormControl size="small" sx={{ minWidth: 220 }}>
                    <InputLabel>B/W Printer</InputLabel>
                    <Select
                      value={bwPrinter}
                      label="B/W Printer"
                      onChange={(e) => setBwPrinter(e.target.value)}
                    >
                      <MenuItem value=""><em>Auto (any B/W)</em></MenuItem>
                      {printers.filter((p) => !p.colorSupport).map((p) => (
                        <MenuItem key={p.id} value={p.name}>{p.name}</MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                  <FormControl size="small" sx={{ minWidth: 220 }}>
                    <InputLabel>Color Printer</InputLabel>
                    <Select
                      value={colorPrinter}
                      label="Color Printer"
                      onChange={(e) => setColorPrinter(e.target.value)}
                    >
                      <MenuItem value=""><em>Auto (any Color)</em></MenuItem>
                      {printers.filter((p) => p.colorSupport).map((p) => (
                        <MenuItem key={p.id} value={p.name}>{p.name}</MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Box>
              )}
              <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                {order.status === 'PENDING' && (
                  <>
                    <Button
                      variant="contained"
                      color="success"
                      startIcon={<ApproveIcon />}
                      onClick={() => handleStatusChange('PRINTING')}
                    >
                      Approve & Print
                    </Button>
                    <Button
                      variant="contained"
                      color="error"
                      startIcon={<RejectIcon />}
                      onClick={() => handleStatusChange('REJECTED')}
                    >
                      Reject
                    </Button>
                  </>
                )}
                {order.status === 'APPROVED' && (
                  <Button
                    variant="contained"
                    startIcon={<PrintIcon />}
                    onClick={() => handleStatusChange('PRINTING')}
                  >
                    Start Printing
                  </Button>
                )}
                {order.status === 'PRINTING' && (
                  <Button
                    variant="contained"
                    color="success"
                    startIcon={<CompleteIcon />}
                    onClick={() => handleStatusChange('COMPLETED')}
                  >
                    Mark Complete
                  </Button>
                )}
                {order.status === 'COMPLETED' && (
                  <Button
                    variant="outlined"
                    startIcon={<ReprintIcon />}
                    onClick={handleReprint}
                  >
                    Reprint
                  </Button>
                )}
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
}

import { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Switch,
  FormControlLabel,
  CircularProgress,
  Alert,
  Chip,
} from '@mui/material';
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Print as PrintIcon,
  NetworkCheck as NetworkCheckIcon,
  Circle as CircleIcon,
  CheckCircle as CheckCircleIcon,
  Cancel as CancelIcon,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../../api';

const emptyPrinter = { name: '', ip: '', colorSupport: false, duplexSupport: false };

export default function PrintersPage() {
  const [printers, setPrinters] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingPrinter, setEditingPrinter] = useState(null);
  const [formData, setFormData] = useState(emptyPrinter);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    fetchPrinters();
  }, []);

  const fetchPrinters = async () => {
    try {
      const result = await api.get('/printers');
      if (result.success) {
        setPrinters(result.data?.printers || []);
      }
    } catch {
      // Error handled by interceptor
    } finally {
      setLoading(false);
    }
  };

  const handleOpenDialog = (printer = null) => {
    if (printer) {
      setEditingPrinter(printer);
      setFormData({
        name: printer.name,
        ip: printer.ip || '',
        colorSupport: printer.colorSupport,
        duplexSupport: printer.duplexSupport,
      });
    } else {
      setEditingPrinter(null);
      setFormData(emptyPrinter);
    }
    setDialogOpen(true);
  };

  const handleCloseDialog = () => {
    setDialogOpen(false);
    setEditingPrinter(null);
    setFormData(emptyPrinter);
  };

  const handleSave = async () => {
    if (!formData.name) {
      toast.error('Printer name is required');
      return;
    }
    setSaving(true);
    try {
      if (editingPrinter) {
        await api.put(`/printers/${editingPrinter.id}`, formData);
        toast.success('Printer updated');
      } else {
        await api.post('/printers', formData);
        toast.success('Printer added');
      }
      fetchPrinters();
      handleCloseDialog();
    } catch {
      toast.error('Failed to save printer');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (printer) => {
    if (!window.confirm(`Delete printer "${printer.name}"?`)) return;
    try {
      await api.delete(`/printers/${printer.id}`);
      toast.success('Printer deleted');
      fetchPrinters();
    } catch {
      toast.error('Failed to delete printer');
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 4 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <PrintIcon sx={{ fontSize: 32, color: 'primary.main' }} />
          <Typography variant="h5" fontWeight="600">Printers</Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => handleOpenDialog()}
          sx={{ borderRadius: 2, textTransform: 'none', px: 3 }}
        >
          Add Printer
        </Button>
      </Box>

      {printers.length === 0 ? (
        <Alert
          severity="info"
          sx={{
            borderRadius: 2,
            '& .MuiAlert-icon': { fontSize: 40, mr: 1 }
          }}
        >
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <PrintIcon sx={{ mr: 1, fontSize: 32 }} />
            No printers configured. Add a printer to get started.
          </Box>
        </Alert>
      ) : (
        <TableContainer
          component={Paper}
          sx={{
            borderRadius: 2,
            boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
            overflow: 'hidden'
          }}
        >
          <Table>
            <TableHead>
              <TableRow>
                <TableCell sx={{ fontWeight: 600, bgcolor: 'background.paper' }}>Name</TableCell>
                <TableCell sx={{ fontWeight: 600, bgcolor: 'background.paper' }}>IP Address</TableCell>
                <TableCell sx={{ fontWeight: 600, bgcolor: 'background.paper' }}>Status</TableCell>
                <TableCell align="center" sx={{ fontWeight: 600, bgcolor: 'background.paper' }}>Color</TableCell>
                <TableCell align="center" sx={{ fontWeight: 600, bgcolor: 'background.paper' }}>Duplex</TableCell>
                <TableCell align="right" sx={{ fontWeight: 600, bgcolor: 'background.paper' }}>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {printers.map((printer) => (
                <TableRow
                  key={printer.id}
                  hover={true}
                  sx={{
                    transition: 'all 0.2s ease',
                    '&:hover': {
                      bgcolor: 'action.hover',
                      transform: 'translateX(4px)'
                    }
                  }}
                >
                  <TableCell>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                      <PrintIcon color="primary" sx={{ fontSize: 24 }} />
                      <Typography variant="body1" fontWeight={500}>{printer.name}</Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <NetworkCheckIcon sx={{ fontSize: 18, color: 'text.secondary' }} />
                      <Typography variant="body2" sx={{ fontFamily: 'monospace', color: 'text.primary' }}>{printer.ip || '-'}</Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                      <Box
                        sx={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          minWidth: 80,
                          height: 32,
                          borderRadius: '20px',
                          bgcolor: printer.status === 'ONLINE' ? 'success.light' : 'error.light',
                          color: printer.status === 'ONLINE' ? 'success.dark' : 'error.dark',
                          px: 2,
                          fontWeight: 500,
                          fontSize: 12,
                        }}
                      >
                        {printer.status === 'ONLINE' && <CircleIcon sx={{ fontSize: 8, mr: 1 }} />}
                        {printer.status || 'UNKNOWN'}
                      </Box>
                    </Box>
                  </TableCell>
                  <TableCell align="center">
                    <Chip
                      size="small"
                      icon={printer.colorSupport ? <CheckCircleIcon sx={{ fontSize: 16 }} /> : <CancelIcon sx={{ fontSize: 16 }} />}
                      label={printer.colorSupport ? 'Enabled' : 'Disabled'}
                      color={printer.colorSupport ? 'success' : 'default'}
                      sx={{ borderRadius: 12, fontWeight: 500 }}
                    />
                  </TableCell>
                  <TableCell align="center">
                    <Chip
                      size="small"
                      icon={printer.duplexSupport ? <CheckCircleIcon sx={{ fontSize: 16 }} /> : <CancelIcon sx={{ fontSize: 16 }} />}
                      label={printer.duplexSupport ? 'Enabled' : 'Disabled'}
                      color={printer.duplexSupport ? 'success' : 'default'}
                      sx={{ borderRadius: 12, fontWeight: 500 }}
                    />
                  </TableCell>
                  <TableCell align="right">
                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 0.5 }}>
                      <IconButton
                        size="small"
                        onClick={() => handleOpenDialog(printer)}
                        sx={{
                          bgcolor: 'action.hover',
                          '&:hover': { bgcolor: 'primary.light', color: 'primary.main' }
                        }}
                      >
                        <EditIcon fontSize="small" />
                      </IconButton>
                      <IconButton
                        size="small"
                        color="error"
                        onClick={() => handleDelete(printer)}
                        sx={{
                          bgcolor: 'action.hover',
                          '&:hover': { bgcolor: 'error.light' }
                        }}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <Dialog open={dialogOpen} onClose={handleCloseDialog} maxWidth="sm" fullWidth>
        <DialogTitle>{editingPrinter ? 'Edit Printer' : 'Add Printer'}</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="Printer Name"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            margin="normal"
            required
          />
          <TextField
            fullWidth
            label="IP Address"
            value={formData.ip}
            onChange={(e) => setFormData({ ...formData, ip: e.target.value })}
            margin="normal"
            placeholder="e.g. 192.168.1.100"
          />
          <Box sx={{ mt: 2 }}>
            <FormControlLabel
              control={
                <Switch
                  checked={formData.colorSupport}
                  onChange={(e) => setFormData({ ...formData, colorSupport: e.target.checked })}
                />
              }
              label="Supports Color Printing"
            />
          </Box>
          <Box>
            <FormControlLabel
              control={
                <Switch
                  checked={formData.duplexSupport}
                  onChange={(e) => setFormData({ ...formData, duplexSupport: e.target.checked })}
                />
              }
              label="Supports Duplex (Double-sided)"
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Cancel</Button>
          <Button variant="contained" onClick={handleSave} disabled={saving}>
            {saving ? 'Saving...' : editingPrinter ? 'Update' : 'Add'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

import { useState, useEffect, useRef } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  TextField,
  Button,
  Grid,
  Divider,
  CircularProgress,
  Alert,
  Avatar,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import { Save as SaveIcon, Upload as UploadIcon } from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../../api';

const defaultPricing = {
  bwPerPage: 1,
  colorPerPage: 5,
  colorDuplexPerPage: 10,
};

export default function SettingsPage() {
  const [pricing, setPricing] = useState(defaultPricing);
  const [upiQrUrl, setUpiQrUrl] = useState('');
  const [defaultBwPrinter, setDefaultBwPrinter] = useState('');
  const [defaultColorPrinter, setDefaultColorPrinter] = useState('');
  const [printers, setPrinters] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [uploadingQr, setUploadingQr] = useState(false);
  const qrInputRef = useRef(null);

  useEffect(() => {
    fetchSettings();
    fetchPrinters();
  }, []);

  const fetchSettings = async () => {
    try {
      const result = await api.get('/settings/pricing');
      if (result.success && result.data) {
        setPricing({ ...defaultPricing, ...result.data });
        setUpiQrUrl(result.data.upiQrUrl || '');
        setDefaultBwPrinter(result.data.defaultBwPrinter || '');
        setDefaultColorPrinter(result.data.defaultColorPrinter || '');
      }
    } catch {
      // Use defaults
    } finally {
      setLoading(false);
    }
  };

  const fetchPrinters = async () => {
    try {
      const result = await api.get('/printers');
      if (result.success) {
        setPrinters(result.data?.printers || []);
      }
    } catch {
      // ignore
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await api.put('/settings/pricing', { ...pricing, upiQrUrl, defaultBwPrinter, defaultColorPrinter });
      toast.success('Settings saved');
    } catch {
      toast.error('Failed to save settings');
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (key, value) => {
    setPricing({ ...pricing, [key]: parseFloat(value) || 0 });
  };

  const handleQrUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadingQr(true);
    try {
      const formData = new FormData();
      formData.append('qr', file);
      const result = await api.post('/settings/upi-qr', formData);
      if (result.success) {
        setUpiQrUrl(result.data.url);
        toast.success('QR code uploaded');
      }
    } catch {
      toast.error('Failed to upload QR');
    } finally {
      setUploadingQr(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h5" gutterBottom>Shop Settings</Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        Configure pricing, payment, and shop preferences
      </Typography>

      <Card sx={{ maxWidth: 600, mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>Print Pricing (per sheet)</Typography>
          <Divider sx={{ mb: 2 }} />

          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="B&W (₹ per sheet)"
                type="number"
                value={pricing.bwPerPage}
                onChange={(e) => handleChange('bwPerPage', e.target.value)}
                inputProps={{ min: 0, step: 0.5 }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Color Single (₹ per sheet)"
                type="number"
                value={pricing.colorPerPage}
                onChange={(e) => handleChange('colorPerPage', e.target.value)}
                inputProps={{ min: 0, step: 0.5 }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Color Duplex (₹ per sheet)"
                type="number"
                value={pricing.colorDuplexPerPage}
                onChange={(e) => handleChange('colorDuplexPerPage', e.target.value)}
                inputProps={{ min: 0, step: 0.5 }}
              />
            </Grid>
          </Grid>

          <Alert severity="info" sx={{ mt: 2 }}>
            <strong>B&W:</strong> ₹{pricing.bwPerPage}/sheet (any style) &bull;
            <strong> Color:</strong> ₹{pricing.colorPerPage}/sheet (single) &bull;
            <strong> ₹{pricing.colorDuplexPerPage}/sheet</strong> (duplex)
            <br />Price is per sheet, not per page (duplex = 2 pages per sheet)
          </Alert>

          <Button
            variant="contained"
            startIcon={saving ? <CircularProgress size={20} /> : <SaveIcon />}
            onClick={handleSave}
            disabled={saving}
            sx={{ mt: 3 }}
          >
            {saving ? 'Saving...' : 'Save Pricing'}
          </Button>
        </CardContent>
      </Card>

      <Card sx={{ maxWidth: 600, mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>Default Printers</Typography>
          <Divider sx={{ mb: 2 }} />
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Select default printers. When approving orders from the queue, these will be pre-selected automatically.
          </Typography>

          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth size="small">
                <InputLabel>Default B/W Printer</InputLabel>
                <Select
                  value={defaultBwPrinter}
                  label="Default B/W Printer"
                  onChange={(e) => setDefaultBwPrinter(e.target.value)}
                >
                  <MenuItem value=""><em>None (auto-select)</em></MenuItem>
                  {printers.filter((p) => !p.colorSupport).map((p) => (
                    <MenuItem key={p.id} value={p.name}>{p.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth size="small">
                <InputLabel>Default Color Printer</InputLabel>
                <Select
                  value={defaultColorPrinter}
                  label="Default Color Printer"
                  onChange={(e) => setDefaultColorPrinter(e.target.value)}
                >
                  <MenuItem value=""><em>None (auto-select)</em></MenuItem>
                  {printers.filter((p) => p.colorSupport).map((p) => (
                    <MenuItem key={p.id} value={p.name}>{p.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      <Card sx={{ maxWidth: 600 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>UPI QR Code (Online Payment)</Typography>
          <Divider sx={{ mb: 2 }} />
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Upload your UPI QR code image. Customers will see this when they choose "UPI" payment.
          </Typography>

          {upiQrUrl && (
            <Box sx={{ display: 'flex', justifyContent: 'center', mb: 2 }}>
              <Avatar
                src={upiQrUrl}
                variant="rounded"
                sx={{ width: 200, height: 200 }}
              />
            </Box>
          )}

          <input
            ref={qrInputRef}
            type="file"
            hidden
            accept="image/*"
            onChange={handleQrUpload}
          />
          <Button
            variant="outlined"
            startIcon={uploadingQr ? <CircularProgress size={20} /> : <UploadIcon />}
            onClick={() => qrInputRef.current?.click()}
            disabled={uploadingQr}
          >
            {upiQrUrl ? 'Change QR Code' : 'Upload QR Code'}
          </Button>
        </CardContent>
      </Card>
    </Box>
  );
}

