The v1 agent logic maps correctly. Now let me implement the merge.

Plan:
1. Update `desktop/package.json`: add `pdf-to-printer` dep + `asarUnpack`.
2. Create `desktop/electron/agent.js` — the agent module (port of agent/index.js adapted for Electron + shared state + IPC events).
3. Update `desktop/electron/main.js` — instantiate agent, IPC handlers, persist credentials, auto-start, pass CORS (already there).
4. Update `desktop/electron/preload.js` — expose agent API.
5. Renderer:
   - `AuthContext.jsx` — on login start agent with creds; on logout clear.
   - `pages/admin/AgentPage.jsx` — agent status/log UI.
   - `AdminLayout.jsx` — add Agent tab + status chip in header.
   - `App.jsx` — add route for agent page.
6. Install deps, build, package, relaunch.

Let me also think about the flow when app opens and token exists (not logged out):
- main loads persisted creds and starts agent on app ready. Renderer also restores session from localStorage and could re-send creds. Fine (idempotent).

For the renderer to get agent status, use a small context or just poll via IPC in the AgentPage. I'll create a `useAgent` hook in the renderer that subscribes to `window.patelApp.agent.onStatus`.

Let me design the preload API:

```js
contextBridge.exposeInMainWorld('patelApp', {
  platform: ...,
  versions: ...,
  agent: {
    setCredentials: (apiUrl, token) => ipcRenderer.invoke('agent:set-credentials', { apiUrl, token }),
    clearCredentials: () => ipcRenderer.invoke('agent:clear-credentials'),
    start: () => ipcRenderer.invoke('agent:start'),
    stop: () => ipcRenderer.invoke('agent:stop'),
    getStatus: () => ipcRenderer.invoke('agent:get-status'),
    onStatus: (callback) => {
      const listener = (_e, data) => callback(data);
      ipcRenderer.on('agent:status', listener);
      return () => ipcRenderer.removeListener('agent:status', listener);
    },
  },
});
```

Main process agent module: I'll make it an EventEmitter. State includes a bounded log (array of {ts, level, msg}). Emit 'status' after any state change. Keep a single agent instance.

Persist creds to `userData/agent-credentials.json` (don't store password, only apiUrl+token).

Now the agent.js implementation. Let me write it carefully, porting v1 logic:

```js
const { EventEmitter } = require('events');
const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');
const { app } = require('electron');

const POLL_INTERVAL = 5000;
const MAX_LOG = 300;

class PrintAgent extends EventEmitter {
  constructor() {
    super();
    this.running = false;
    this.credentials = null;
    this.pollTimer = null;
    this.cacheDir = null;
    this.print = null;
    try { this.print = require('pdf-to-printer'); } catch { this.print = null; }
    this.state = {
      status: 'stopped', // stopped | starting | running | error
      lastPoll: null,
      lastError: null,
      processed: 0,
      completed: 0,
      failed: 0,
      current: null,
    };
    this.log = [];
  }

  log(level, msg) {
    const entry = { ts: Date.now(), level, msg };
    this.log.push(entry);
    if (this.log.length > MAX_LOG) this.log.splice(0, this.log.length - MAX_LOG);
    this.emit('status', this.snapshot());
  }

  snapshot() {
    return { ...this.state, log: this.log.slice(-100) };
  }

  configure(apiUrl, token) {
    this.credentials = { apiUrl: (apiUrl || '').replace(/\/+$/, ''), token };
  }

  ensureCacheDir() {
    if (!this.cacheDir) this.cacheDir = path.join(app.getPath('userData'), 'print-cache');
    if (!fs.existsSync(this.cacheDir)) fs.mkdirSync(this.cacheDir, { recursive: true });
  }

  apiRequest(method, urlPath, body, { binary = false } = {}) {
    const url = new URL(urlPath, this.credentials.apiUrl);
    const isHttps = url.protocol === 'https:';
    const client = isHttps ? https : http;
    return new Promise((resolve, reject) => {
      const headers = { 'Content-Type': 'application/json' };
      if (this.credentials.token) headers.Authorization = `Bearer ${this.credentials.token}`;
      const req = client.request({
        method,
        hostname: url.hostname,
        port: url.port || (isHttps ? 443 : 80),
        path: url.pathname + url.search,
        headers,
      }, (res) => {
        if (binary) {
          if (res.statusCode !== 200) {
            let data = '';
            res.on('data', (c) => data += c);
            res.on('end', () => reject(new Error(`Download failed (${res.statusCode}) ${data}`)));
            return;
          }
          const chunks = [];
          res.on('data', (c) => chunks.push(c));
          res.on('end', () => resolve(Buffer.concat(chunks)));
          return;
        }
        let data = '';
        res.on('data', (c) => data += c);
        res.on('end', () => {
          try { resolve(JSON.parse(data)); } catch { resolve({ success: false, message: data }); }
        });
      });
      req.on('error', reject);
      req.setTimeout(30000, () => { req.destroy(); reject(new Error('Request timeout')); });
      if (body) req.write(JSON.stringify(body));
      req.end();
    });
  }

  async downloadFile(jobId, destPath) {
    const buffer = await this.apiRequest('GET', `/api/agent/jobs/${jobId}/file`, null, { binary: true });
    fs.writeFileSync(destPath, buffer);
  }

  async reportStatus(jobId, status, message) {
    try {
      await this.apiRequest('PUT', `/api/agent/jobs/${jobId}/status`, { status, message });
    } catch (e) {
      this.log('error', `Failed to report job status: ${e.message}`);
    }
  }

  async pollOnce() {
    if (!this.credentials) { this.log('warn', 'Agent not configured'); return; }
    try {
      const result = await this.apiRequest('GET', '/api/agent/jobs');
      this.state.lastPoll = new Date().toISOString();
      if (!result.success) throw new Error(result.message || 'Poll failed');
      const jobs = result.data || [];
      for (const job of jobs) {
        if (!this.running) return;
        await this.processJob(job);
      }
    } catch (e) {
      this.state.lastError = e.message;
      this.log('error', `Poll error: ${e.message}`);
      if (e && (e.status === 401 || /401/.test(e.message))) {
        this.emit('auth-expired');
      }
    } finally {
      this.emit('status', this.snapshot());
    }
  }

  async processJob(job) {
    this.state.current = job.id;
    this.state.processed += 1;
    this.log('info', `Processing job ${job.id} (Order #${job.order?.token || 'N/A'}, ${job.copies || 1} copy, printer ${job.assignedPrinter || 'default'})`);
    this.emit('status', this.snapshot());

    this.ensureCacheDir();
    const filePath = path.join(this.cacheDir, `${job.id}.pdf`);
    try {
      await this.downloadFile(job.id, filePath);
      this.log('info', `Downloaded print-ready file for job ${job.id}`);
    } catch (e) {
      this.state.failed += 1;
      this.state.current = null;
      this.log('error', `Download failed: ${e.message}`);
      await this.reportStatus(job.id, 'FAILED', e.message);
      this.emit('status', this.snapshot());
      return;
    }

    if (!this.print) {
      this.log('warn', `[SIMULATED] Printing job ${job.id} (pdf-to-printer unavailable)`);
      await this.reportStatus(job.id, 'COMPLETED');
      this.state.completed += 1;
      this.state.current = null;
      try { fs.unlinkSync(filePath); } catch {}
      this.emit('status', this.snapshot());
      return;
    }

    try {
      const options = { printer: job.assignedPrinter, silent: true };
      if (job.copies && job.copies > 1) options.copies = job.copies;
      if (job.printStyle === 'duplex') {
        options.side = job.flipDirection === 'short-edge' ? 'duplexshort' : 'duplex';
      } else {
        options.side = 'simplex';
      }
      if (job.paperSize) options.paperSize = job.paperSize;
      this.log('info', `Sending to printer (${options.side}, ${options.copies || 1} copy, ${options.paperSize || 'A4'})`);
      await this.print.print(filePath, options);
      this.log('info', `Print sent for job ${job.id}`);
      await this.reportStatus(job.id, 'COMPLETED');
      this.state.completed += 1;
    } catch (e) {
      this.state.failed += 1;
      this.log('error', `Print failed for job ${job.id}: ${e.message}`);
      await this.reportStatus(job.id, 'FAILED', e.message);
    } finally {
      this.state.current = null;
      try { fs.unlinkSync(filePath); } catch {}
      this.emit('status', this.snapshot());
    }
  }

  start() {
    if (!this.credentials) { this.log('warn', 'Cannot start: no credentials'); return; }
    if (this.running) return;
    this.running = true;
    this.state.status = 'running';
    this.log('info', `Agent started (polling every ${POLL_INTERVAL / 1000}s)`);
    this.pollOnce();
    this.pollTimer = setInterval(() => this.pollOnce(), POLL_INTERVAL);
    this.emit('status', this.snapshot());
  }

  stop() {
    if (!this.running) return;
    this.running = false;
    if (this.pollTimer) clearInterval(this.pollTimer);
    this.pollTimer = null;
    this.state.status = 'stopped';
    this.log('info', 'Agent stopped');
    this.emit('status', this.snapshot());
  }

  setCredentialsAndStart(apiUrl, token) {
    this.configure(apiUrl, token);
    if (!this.running) this.start(); else this.pollOnce();
  }
}

module.exports = { PrintAgent };
