const { EventEmitter } = require('events');
const fs = require('fs');
const path = require('path');
const http = require('http');
const https = require('https');
const { app } = require('electron');

const POLL_INTERVAL = 5000;
const MAX_LOG = 300;

class PrintAgent extends EventEmitter {
  constructor() {
    super();
    this.running = false;
    this.polling = false;
    this.pollTimer = null;
    this.credentials = null;
    this.cacheDir = null;
    this.print = null;
    try {
      this.print = require('pdf-to-printer');
    } catch {
      this.print = null;
    }
    this.state = {
      status: 'stopped',
      lastPoll: null,
      lastError: null,
      processed: 0,
      completed: 0,
      failed: 0,
      current: null,
    };
    this.logEntries = [];
  }

  log(level, msg) {
    const entry = { ts: Date.now(), level, msg };
    this.logEntries.push(entry);
    if (this.logEntries.length > MAX_LOG) {
      this.logEntries.splice(0, this.logEntries.length - MAX_LOG);
    }
    this.emit('status', this.snapshot());
  }

  snapshot() {
    return { ...this.state, log: this.logEntries.slice(-100) };
  }

  configure(apiUrl, token) {
    if (apiUrl) {
      this.credentials = { apiUrl: String(apiUrl).replace(/\/+$/, ''), token };
    } else {
      this.credentials = null;
    }
  }

  ensureCacheDir() {
    if (!this.cacheDir) {
      this.cacheDir = path.join(app.getPath('userData'), 'print-cache');
    }
    if (!fs.existsSync(this.cacheDir)) {
      fs.mkdirSync(this.cacheDir, { recursive: true });
    }
  }

  apiRequest(method, urlPath, body, { binary = false } = {}) {
    const url = new URL(urlPath, this.credentials.apiUrl);
    const isHttps = url.protocol === 'https:';
    const client = isHttps ? https : http;

    return new Promise((resolve, reject) => {
      const headers = { 'Content-Type': 'application/json' };
      if (this.credentials.token) {
        headers.Authorization = `Bearer ${this.credentials.token}`;
      }

      const req = client.request(
        {
          method,
          hostname: url.hostname,
          port: url.port || (isHttps ? 443 : 80),
          path: url.pathname + url.search,
          headers,
        },
        (res) => {
          if (binary) {
            if (res.statusCode !== 200) {
              let data = '';
              res.on('data', (c) => (data += c));
              res.on('end', () =>
                reject(new Error(`Download failed (${res.statusCode}) ${data}`))
              );
              return;
            }
            const chunks = [];
            res.on('data', (c) => chunks.push(c));
            res.on('end', () => resolve(Buffer.concat(chunks)));
            return;
          }

          let data = '';
          res.on('data', (c) => (data += c));
          res.on('end', () => {
            let parsed;
            try {
              parsed = JSON.parse(data);
            } catch {
              parsed = { success: false, message: data };
            }
            if (res.statusCode >= 400) {
              const err = new Error(parsed.message || `HTTP ${res.statusCode}`);
              err.status = res.statusCode;
              reject(err);
              return;
            }
            resolve(parsed);
          });
        }
      );

      req.on('error', reject);
      req.setTimeout(60000, () => {
        req.destroy();
        reject(new Error('Request timeout'));
      });

      if (body) req.write(JSON.stringify(body));
      req.end();
    });
  }

  async downloadFile(jobId, destPath) {
    const buffer = await this.apiRequest('GET', `/api/agent/jobs/${jobId}/file`, null, {
      binary: true,
    });
    fs.writeFileSync(destPath, buffer);
  }

  async reportStatus(jobId, status, message) {
    try {
      await this.apiRequest('PUT', `/api/agent/jobs/${jobId}/status`, { status, message });
    } catch (e) {
      this.log('error', `Failed to report job status: ${e.message}`);
    }
  }

  async pollOnce() {
    if (!this.credentials) return;
    if (this.polling) return;
    this.polling = true;

    try {
      const result = await this.apiRequest('GET', '/api/agent/jobs');
      this.state.lastPoll = new Date().toISOString();
      if (!result.success) throw new Error(result.message || 'Poll failed');

      const jobs = result.data || [];
      for (const job of jobs) {
        if (!this.running) break;
        await this.processJob(job);
      }
    } catch (e) {
      this.state.lastError = e.message;
      this.log('error', `Poll error: ${e.message}`);
      if (e.status === 401) {
        this.emit('auth-expired');
      }
    } finally {
      this.polling = false;
      this.emit('status', this.snapshot());
    }
  }

  async processJob(job) {
    this.state.current = job.id;
    this.state.processed += 1;
    this.log(
      'info',
      `Processing job ${job.id} (Order #${job.order?.token || 'N/A'} | ${job.copies || 1} copy | printer ${job.assignedPrinter || 'default'})`
    );
    this.emit('status', this.snapshot());

    this.ensureCacheDir();
    const filePath = path.join(this.cacheDir, `${job.id}.pdf`);

    try {
      await this.downloadFile(job.id, filePath);
      this.log('info', `Downloaded print-ready file for job ${job.id}`);
    } catch (e) {
      this.state.failed += 1;
      this.state.current = null;
      this.log('error', `Download failed for job ${job.id}: ${e.message}`);
      await this.reportStatus(job.id, 'FAILED', e.message);
      this.emit('status', this.snapshot());
      return;
    }

    if (!this.print) {
      this.log('warn', `[SIMULATED] Printing job ${job.id} (pdf-to-printer unavailable)`);
      await this.reportStatus(job.id, 'COMPLETED');
      this.state.completed += 1;
      this.state.current = null;
      try {
        fs.unlinkSync(filePath);
      } catch {}
      this.emit('status', this.snapshot());
      return;
    }

    try {
      const options = { printer: job.assignedPrinter, silent: true };
      if (job.copies && job.copies > 1) options.copies = job.copies;
      if (job.printStyle === 'duplex') {
        options.side = job.flipDirection === 'short-edge' ? 'duplexshort' : 'duplex';
      } else {
        options.side = 'simplex';
      }
      if (job.paperSize) options.paperSize = job.paperSize;

      this.log(
        'info',
        `Sending to printer (${options.side}, ${options.copies || 1} copy, ${options.paperSize || 'A4'})`
      );
      await this.print.print(filePath, options);
      this.log('info', `Print sent for job ${job.id}`);
      await this.reportStatus(job.id, 'COMPLETED');
      this.state.completed += 1;
    } catch (e) {
      this.state.failed += 1;
      this.log('error', `Print failed for job ${job.id}: ${e.message}`);
      await this.reportStatus(job.id, 'FAILED', e.message);
    } finally {
      this.state.current = null;
      try {
        fs.unlinkSync(filePath);
      } catch {}
      this.emit('status', this.snapshot());
    }
  }

  start() {
    if (!this.credentials) {
      this.log('warn', 'Cannot start agent: not configured');
      return;
    }
    if (this.running) return;
    this.running = true;
    this.state.status = 'running';
    this.log('info', `Agent started (polling every ${POLL_INTERVAL / 1000}s)`);
    this.pollOnce();
    this.pollTimer = setInterval(() => this.pollOnce(), POLL_INTERVAL);
    this.emit('status', this.snapshot());
  }

  stop() {
    if (!this.running) return;
    this.running = false;
    if (this.pollTimer) {
      clearInterval(this.pollTimer);
      this.pollTimer = null;
    }
    this.state.status = 'stopped';
    this.log('info', 'Agent stopped');
    this.emit('status', this.snapshot());
  }
}

module.exports = { PrintAgent, POLL_INTERVAL };

const { app, BrowserWindow, shell, session, ipcMain, Tray, Menu, nativeImage } = require('electron');
const path = require('path');
const fs = require('fs');
const { PrintAgent } = require('./agent');

const isDev = !app.isPackaged;

let mainWindow = null;
let tray = null;
let isQuitting = false;

const agent = new PrintAgent();

function credsFile() {
  return path.join(app.getPath('userData'), 'agent-credentials.json');
}

function loadCredentials() {
  try {
    const p = credsFile();
    if (fs.existsSync(p)) return JSON.parse(fs.readFileSync(p, 'utf8'));
  } catch {}
  return null;
}

function saveCredentials(apiUrl, token) {
  try {
    fs.writeFileSync(credsFile(), JSON.stringify({ apiUrl, token }, null, 2));
  } catch {}
}

function clearCredentials() {
  try {
    if (fs.existsSync(credsFile())) fs.unlinkSync(credsFile());
  } catch {}
}

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 1100,
    minHeight: 700,
    show: false,
    title: 'Patel AutoPrint Admin',
    autoHideMenuBar: true,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
    },
  });

  if (isDev) {
    mainWindow.loadURL('http://localhost:5173');
  } else {
    mainWindow.loadFile(path.join(__dirname, '../dist/index.html'));
  }

  mainWindow.once('ready-to-show', () => {
    mainWindow?.show();
  });

  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    shell.openExternal(url);
    return { action: 'deny' };
  });

  // Close to tray: keep the agent running in the background.
  mainWindow.on('close', (e) => {
    if (!isQuitting) {
      e.preventDefault();
      mainWindow?.hide();
    }
  });

  mainWindow.on('closed', () => {
    mainWindow = null;
  });
}

function createTray() {
  const icon = nativeImage.createFromPath(path.join(__dirname, '../resources/tray.png'));
  tray = new Tray(icon.resize({ width: 16, height: 16 }));

  const contextMenu = Menu.buildFromTemplate([
    { label: 'Show Patel AutoPrint Admin', click: () => mainWindow?.show() },
    {
      label: 'Agent: ' + (agent.running ? 'Running' : 'Stopped'),
      enabled: false,
    },
    { type: 'separator' },
    {
      label: 'Start Agent',
      click: () => agent.start(),
    },
    {
      label: 'Stop Agent',
      click: () => agent.stop(),
    },
    { type: 'separator' },
    {
      label: 'Quit',
      click: () => {
        isQuitting = true;
        app.quit();
      },
    },
  ]);

  tray.setToolTip('Patel AutoPrint Admin');
  tray.setContextMenu(contextMenu);
  tray.on('double-click', () => mainWindow?.show());

  agent.on('status', () => {
    tray?.setToolTip(`Patel AutoPrint Admin - Agent ${agent.running ? 'Running' : 'Stopped'}`);
  });
}

function broadcastAgentStatus() {
  const win = mainWindow;
  if (win && !win.isDestroyed()) {
    win.webContents.send('agent:status', agent.snapshot());
  }
}

function registerIpc() {
  ipcMain.handle('agent:set-credentials', (_e, { apiUrl, token }) => {
    if (!apiUrl || !token) return { success: false, message: 'Missing credentials' };
    agent.configure(apiUrl, token);
    saveCredentials(apiUrl, token);
    agent.start();
    return { success: true };
  });

  ipcMain.handle('agent:clear-credentials', () => {
    agent.stop();
    agent.configure(null, null);
    clearCredentials();
    return { success: true };
  });

  ipcMain.handle('agent:start', () => {
    agent.start();
    return { success: true };
  });

  ipcMain.handle('agent:stop', () => {
    agent.stop();
    return { success: true };
  });

  ipcMain.handle('agent:get-status', () => agent.snapshot());
}

app.whenReady().then(() => {
  // The desktop app talks to the remote Patel AutoPrint backend from a
  // file:// origin. Chromium's CORS checks would block those requests, so we
  // inject permissive CORS headers into every backend response. webSecurity
  // stays enabled.
  session.defaultSession.webRequest.onHeadersReceived((details, callback) => {
    callback({
      responseHeaders: {
        ...details.responseHeaders,
        'Access-Control-Allow-Origin': ['*'],
        'Access-Control-Allow-Methods': ['GET, POST, PUT, DELETE, PATCH, OPTIONS'],
        'Access-Control-Allow-Headers': ['Content-Type, Authorization'],
      },
    });
  });

  registerIpc();

  agent.on('status', broadcastAgentStatus);
  agent.on('auth-expired', () => {
    agent.stop();
    clearCredentials();
    agent.configure(null, null);
    const win = mainWindow;
    if (win && !win.isDestroyed()) {
      win.webContents.send('agent:auth-expired');
    }
  });

  createWindow();
  createTray();

  // Restore last session so the agent auto-starts without re-login.
  const creds = loadCredentials();
  if (creds && creds.apiUrl && creds.token) {
    agent.configure(creds.apiUrl, creds.token);
    agent.start();
  }

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin' && isQuitting) app.quit();
});

app.on('before-quit', () => {
  isQuitting = true;
});

const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('patelApp', {
  platform: process.platform,
  versions: {
    electron: process.versions.electron,
    chrome: process.versions.chrome,
    node: process.versions.node,
  },
  agent: {
    setCredentials: (apiUrl, token) => ipcRenderer.invoke('agent:set-credentials', { apiUrl, token }),
    clearCredentials: () => ipcRenderer.invoke('agent:clear-credentials'),
    start: () => ipcRenderer.invoke('agent:start'),
    stop: () => ipcRenderer.invoke('agent:stop'),
    getStatus: () => ipcRenderer.invoke('agent:get-status'),
    onStatus: (callback) => {
      const listener = (_e, data) => callback(data);
      ipcRenderer.on('agent:status', listener);
      return () => ipcRenderer.removeListener('agent:status', listener);
    },
    onAuthExpired: (callback) => {
      const listener = () => callback();
      ipcRenderer.on('agent:auth-expired', listener);
      return () => ipcRenderer.removeListener('agent:auth-expired', listener);
    },
  },
});

import { createContext, useContext, useState, useEffect } from 'react';
import api from './api';
import { getApiUrl } from './settings';

const AuthContext = createContext(null);

function agentAvailable() {
  return typeof window !== 'undefined' && !!window.patelApp?.agent;
}

function agentSetCredentials(token) {
  if (agentAvailable()) {
    window.patelApp.agent.setCredentials(getApiUrl(), token);
  }
}

function agentClearCredentials() {
  if (agentAvailable()) {
    window.patelApp.agent.clearCredentials();
  }
}

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('token'));
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const initAuth = async () => {
      const savedToken = localStorage.getItem('token');
      const savedUser = localStorage.getItem('user');

      if (savedToken && savedUser) {
        try {
          setToken(savedToken);
          setUser(JSON.parse(savedUser));
          const result = await api.get('/auth/profile');
          if (result.success) {
            setUser(result.data);
            localStorage.setItem('user', JSON.stringify(result.data));
          }
          agentSetCredentials(savedToken);
        } catch {
          localStorage.removeItem('token');
          localStorage.removeItem('user');
          setToken(null);
          setUser(null);
        }
      }
      setLoading(false);
    };
    initAuth();

    if (agentAvailable()) {
      return window.patelApp.agent.onAuthExpired(() => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        setToken(null);
        setUser(null);
        window.location.hash = '#/login';
      });
    }
  }, []);

  const login = async (email, password) => {
    const result = await api.post('/auth/login', { email, password });
    if (result.success) {
      const { token: newToken, user: userData } = result.data;
      setToken(newToken);
      setUser(userData);
      localStorage.setItem('token', newToken);
      localStorage.setItem('user', JSON.stringify(userData));
      agentSetCredentials(newToken);
      return userData;
    }
    throw new Error(result.message || 'Login failed');
  };

  const logout = () => {
    setToken(null);
    setUser(null);
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    agentClearCredentials();
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        loading,
        login,
        logout,
        isAuthenticated: !!token && !!user,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Grid,
  Button,
  Chip,
  CircularProgress,
  Divider,
  Stack,
} from '@mui/material';
import {
  PlayArrow as StartIcon,
  Stop as StopIcon,
  Refresh as RefreshIcon,
  Memory as MemoryIcon,
  CheckCircle as CompletedIcon,
  Cancel as FailedIcon,
  Print as PrintIcon,
} from '@mui/icons-material';
import toast from 'react-hot-toast';

function agentAvailable() {
  return typeof window !== 'undefined' && !!window.patelApp?.agent;
}

function useAgentStatus() {
  const [status, setStatus] = useState(null);

  useEffect(() => {
    if (!agentAvailable()) return;
    window.patelApp.agent.getStatus().then(setStatus).catch(() => {});
    const unsubscribe = window.patelApp.agent.onStatus(setStatus);
    return unsubscribe;
  }, []);

  return status;
}

function StatCard({ label, value, icon, color }) {
  return (
    <Card>
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Box>
            <Typography variant="body2" color="text.secondary">{label}</Typography>
            <Typography variant="h5" sx={{ fontWeight: 600 }}>{value}</Typography>
          </Box>
          <Box sx={{ bgcolor: `${color}.light`, borderRadius: 2, p: 1.5, display: 'flex' }}>
            {icon}
          </Box>
        </Box>
      </CardContent>
    </Card>
  );
}

export default function AgentPage() {
  const status = useAgentStatus();
  const [starting, setStarting] = useState(false);
  const [stopping, setStopping] = useState(false);

  const running = status?.status === 'running';

  const handleStart = useCallback(async () => {
    setStarting(true);
    try {
      const res = await window.patelApp.agent.start();
      if (res && res.success === false) toast.error(res.message || 'Failed to start agent');
      else toast.success('Agent started');
    } catch {
      toast.error('Failed to start agent');
    } finally {
      setStarting(false);
    }
  }, []);

  const handleStop = useCallback(async () => {
    setStopping(true);
    try {
      await window.patelApp.agent.stop();
      toast.success('Agent stopped');
    } catch {
      toast.error('Failed to stop agent');
    } finally {
      setStopping(false);
    }
  }, []);

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <MemoryIcon sx={{ fontSize: 32, color: 'primary.main' }} />
          <Typography variant="h5" fontWeight="600">Print Agent</Typography>
          <Chip
            label={running ? 'Running' : 'Stopped'}
            color={running ? 'success' : 'default'}
            size="small"
            sx={{ ml: 1 }}
          />
        </Box>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button
            variant="contained"
            color="success"
            startIcon={starting ? <CircularProgress size={18} /> : <StartIcon />}
            onClick={handleStart}
            disabled={running || starting}
          >
            Start
          </Button>
          <Button
            variant="outlined"
            color="error"
            startIcon={stopping ? <CircularProgress size={18} /> : <StopIcon />}
            onClick={handleStop}
            disabled={!running || stopping}
          >
            Stop
          </Button>
        </Box>
      </Box>

      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        The agent automatically downloads approved print jobs from the cloud and sends them to
        your local printers. It keeps running even when this window is closed.
      </Typography>

      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard label="Jobs Processed" value={status?.processed ?? 0} icon={<PrintIcon sx={{ color: 'primary.main' }} />} color="primary" />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard label="Completed" value={status?.completed ?? 0} icon={<CompletedIcon sx={{ color: 'success.main' }} />} color="success" />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard label="Failed" value={status?.failed ?? 0} icon={<FailedIcon sx={{ color: 'error.main' }} />} color="error" />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <StatCard
            label="Last Poll"
            value={status?.lastPoll ? new Date(status.lastPoll).toLocaleTimeString('en-IN') : '-'}
            icon={<RefreshIcon sx={{ color: 'info.main' }} />}
            color="info"
          />
        </Grid>
      </Grid>

      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>Current Activity</Typography>
          <Divider sx={{ mb: 2 }} />
          {status?.current ? (
            <Typography variant="body1">
              Printing job <strong>{status.current}</strong>...
            </Typography>
          ) : (
            <Typography variant="body1" color="text.secondary">
              {running ? 'Idle - waiting for print jobs' : 'Agent is stopped'}
            </Typography>
          )}
          {status?.lastError && (
            <Typography variant="body2" color="error" sx={{ mt: 1 }}>
              Last error: {status.lastError}
            </Typography>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom>Agent Log</Typography>
          <Divider sx={{ mb: 2 }} />
          <Box
            sx={{
              bgcolor: 'grey.900',
              color: 'grey.100',
              borderRadius: 2,
              p: 2,
              maxHeight: 320,
              overflowY: 'auto',
              fontFamily: 'Consolas, monospace',
              fontSize: 12,
            }}
          >
            {(!status?.log || status.log.length === 0) && (
              <Typography variant="body2" sx={{ color: 'grey.500' }}>
                No activity yet.
              </Typography>
            )}
            {status?.log?.map((entry, i) => (
              <Box key={i} sx={{ whiteSpace: 'pre-wrap' }}>
                <span style={{ color: 'grey.500' }}>
                  {new Date(entry.ts).toLocaleTimeString('en-IN')}
                </span>{' '}
                <span style={{ color: entry.level === 'error' ? '#f44336' : entry.level === 'warn' ? '#ff9800' : '#4caf50' }}>
                  [{entry.level.toUpperCase()}]
                </span>{' '}
                {entry.msg}
              </Box>
            ))}
          </Box>
        </CardContent>
      </Card>
    </Box>
  );
}

