$base = "http://localhost:5000"
$ErrorActionPreference = "Continue"

function Call($method, $path, $body, $token) {
    $headers = @{}
    if ($token) { $headers["Authorization"] = "Bearer $token" }
    try {
        if ($null -ne $body) {
            $json = $body | ConvertTo-Json -Depth 10
            $r = Invoke-RestMethod -Method $method -Uri "$base$path" -Headers $headers -ContentType "application/json" -Body $json -TimeoutSec 15
        } else {
            $r = Invoke-RestMethod -Method $method -Uri "$base$path" -Headers $headers -TimeoutSec 15
        }
        return $r
    } catch {
        $resp = $_.Exception.Response
        if ($resp) {
            $sr = New-Object System.IO.StreamReader($resp.GetResponseStream())
            $body = $sr.ReadToEnd()
            $code = [int]$resp.StatusCode
            return @{ HTTP_ERROR = $code; BODY = $body }
        }
        return @{ ERROR = $_.Exception.Message }
    }
}

