$base = "http://localhost:5000"
function Call($method, $path, $body, $token) {
    $headers = @{}
    if ($token) { $headers["Authorization"] = "Bearer $token" }
    try {
        if ($null -ne $body) {
            $json = $body | ConvertTo-Json -Depth 10
            return (Invoke-RestMethod -Method $method -Uri "$base$path" -Headers $headers -ContentType "application/json" -Body $json -TimeoutSec 15)
        }
        return (Invoke-RestMethod -Method $method -Uri "$base$path" -Headers $headers -TimeoutSec 15)
    } catch {
        $resp = $_.Exception.Response
        if ($resp) {
            $sr = New-Object System.IO.StreamReader($resp.GetResponseStream())
            $code = [int]$resp.StatusCode
            $raw = $sr.ReadToEnd()
            try { return @{ HTTP_ERROR = $code; BODY = ($raw | ConvertFrom-Json) } } catch { return @{ HTTP_ERROR = $code; BODY = $raw } }
        }
        return @{ ERROR = $_.Exception.Message }
    }
}

