import axios from 'axios';
import toast from 'react-hot-toast';

const api = axios.create({
  baseURL: '/api',
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem('superadmin_token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

api.interceptors.response.use(
  (response) => response.data,
  (error) => {
    if (error.response) {
      if (error.response.status === 401) {
        localStorage.removeItem('superadmin_token');
        localStorage.removeItem('superadmin_user');
        if (window.location.pathname !== '/superadmin/login') {
          window.location.href = '/superadmin/login';
        }
      } else {
        const message = error.response.data?.message || 'An error occurred';
        toast.error(message);
      }
      return Promise.reject(error.response.data);
    }
    toast.error('Network error. Please check your connection.');
    return Promise.reject({ message: 'Network error' });
  }
);

export default api;

import React from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import ShopDetail from './pages/ShopDetail';

function RequireAuth({ children }) {
  const token = localStorage.getItem('superadmin_token');
  const user = localStorage.getItem('superadmin_user');
  const location = useLocation();
  if (!token || !user) {
    return <Navigate to="/superadmin/login" state={{ from: location }} replace />;
  }
  return children;
}

export default function App() {
  return (
    <Routes>
      <Route path="/superadmin/login" element={<Login />} />
      <Route
        path="/superadmin"
        element={
          <RequireAuth>
            <Dashboard />
          </RequireAuth>
        }
      />
      <Route
        path="/superadmin/shops/:id"
        element={
          <RequireAuth>
            <ShopDetail />
          </RequireAuth>
        }
      />
      <Route path="*" element={<Navigate to="/superadmin" replace />} />
    </Routes>
  );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Card, CardContent, TextField, Button, Typography, CircularProgress } from '@mui/material';
import toast from 'react-hot-toast';
import api from '../api';

export default function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await api.post('/auth/login', { email, password });
      const { token, user } = res.data;
      if (user.role !== 'SUPER_ADMIN') {
        toast.error('Access denied. Super admin only.');
        return;
      }
      localStorage.setItem('superadmin_token', token);
      localStorage.setItem('superadmin_user', JSON.stringify(user));
      toast.success('Welcome back!');
      navigate('/superadmin', { replace: true });
    } catch (err) {
      // error already toasted by interceptor
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', p: 2 }}>
      <Card sx={{ width: 400 }}>
        <CardContent sx={{ p: 4 }}>
          <Typography variant="h5" gutterBottom>
            Patel AutoPrint Admin
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
            Super admin sign in
          </Typography>
          <form onSubmit={handleSubmit}>
            <TextField
              label="Email"
              type="email"
              fullWidth
              required
              margin="normal"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              autoComplete="username"
            />
            <TextField
              label="Password"
              type="password"
              fullWidth
              required
              margin="normal"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
            />
            <Button
              type="submit"
              variant="contained"
              fullWidth
              size="large"
              sx={{ mt: 3 }}
              disabled={loading}
            >
              {loading ? <CircularProgress size={24} /> : 'Sign In'}
            </Button>
          </form>
        </CardContent>
      </Card>
    </Box>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Container,
  IconButton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Toolbar,
  Typography,
  Avatar,
  Menu,
  MenuItem,
  Chip,
  Paper,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Tooltip,
  Alert,
} from '@mui/material';
import {
  Refresh as RefreshIcon,
  Store as StoreIcon,
  ReceiptLong as OrdersIcon,
  Print as PrintersIcon,
  Description as JobsIcon,
  Logout as LogoutIcon,
  VpnKey as VpnKeyIcon,
  Search as SearchIcon,
  MoreVert as MoreVertIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import api from '../api';
import ShopFormDialog from '../components/ShopFormDialog';
import ChangePasswordDialog from '../components/ChangePasswordDialog';

const STATUS_COLORS = {
  ACTIVE: 'success',
  EXPIRING: 'warning',
  EXPIRED: 'error',
  SUSPENDED: 'error',
  CANCELLED: 'default',
};

function StatCard({ icon, label, value, color = 'primary' }) {
  return (
    <Card>
      <CardContent>
        <Stack direction="row" alignItems="center" spacing={2}>
          <Avatar sx={{ bgcolor: `${color}.main`, width: 48, height: 48 }}>
            {icon}
          </Avatar>
          <Box>
            <Typography variant="h5">{value}</Typography>
            <Typography variant="body2" color="text.secondary">
              {label}
            </Typography>
          </Box>
        </Stack>
      </CardContent>
    </Card>
  );
}

export default function Dashboard() {
  const navigate = useNavigate();
  const [stats, setStats] = useState(null);
  const [shops, setShops] = useState([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState('');
  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState(null);
  const [pwdOpen, setPwdOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [menuAnchor, setMenuAnchor] = useState(null);
  const [deleting, setDeleting] = useState(false);
  const [keyRegenId, setKeyRegenId] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      const [statsRes, shopsRes] = await Promise.all([
        api.get('/superadmin/stats'),
        api.get('/superadmin/shops', { params: { q: query || undefined } }),
      ]);
      setStats(statsRes.data);
      setShops(shopsRes.data);
    } catch (err) {
      // interceptor handles
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const t = setTimeout(() => load(), 400);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query]);

  const handleLogout = () => {
    localStorage.removeItem('superadmin_token');
    localStorage.removeItem('superadmin_user');
    navigate('/superadmin/login', { replace: true });
  };

  const handleDelete = async () => {
    setDeleting(true);
    try {
      await api.delete(`/superadmin/shops/${deleteTarget.id}`);
      toast.success(`Deleted "${deleteTarget.name}"`);
      setDeleteTarget(null);
      load();
    } catch (err) {
      // interceptor handles
    } finally {
      setDeleting(false);
    }
  };

  const copyKey = (key) => {
    navigator.clipboard?.writeText(key);
    toast.success('Agent key copied');
  };

  const regenerateKey = async (shop) => {
    setKeyRegenId(shop.id);
    try {
      const res = await api.post(`/superadmin/shops/${shop.id}/regenerate-key`);
      toast.success('Agent key rotated');
      copyKey(res.data.agentKey);
      load();
    } catch (err) {
      // interceptor handles
    } finally {
      setKeyRegenId(null);
    }
  };

  const subCounts = stats?.subscriptions || {};
  const totalShops = stats?.shops || 0;

  return (
    <Box sx={{ minHeight: '100vh' }}>
      <Toolbar sx={{ bgcolor: 'background.paper', borderBottom: '1px solid', borderColor: 'divider' }}>
        <Typography variant="h6" sx={{ flexGrow: 1 }}>
          Patel AutoPrint Admin
        </Typography>
        <Button startIcon={<RefreshIcon />} onClick={load}>
          Refresh
        </Button>
        <IconButton onClick={(e) => setMenuAnchor(e.currentTarget)}>
          <MoreVertIcon />
        </IconButton>
        <Menu
          anchorEl={menuAnchor}
          open={Boolean(menuAnchor)}
          onClose={() => setMenuAnchor(null)}
        >
          <MenuItem onClick={() => { setMenuAnchor(null); setPwdOpen(true); }}>
            Change password
          </MenuItem>
          <MenuItem onClick={() => { setMenuAnchor(null); handleLogout(); }}>
            <LogoutIcon sx={{ mr: 1 }} fontSize="small" /> Logout
          </MenuItem>
        </Menu>
      </Toolbar>

      <Container maxWidth="xl" sx={{ py: 3 }}>
        {loading && !stats ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}>
            <CircularProgress />
          </Box>
        ) : (
          <>
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={2} sx={{ mb: 3 }}>
              <Box sx={{ flexGrow: 1 }}>
                <StatCard icon={<StoreIcon />} label="Shops" value={stats?.shops ?? 0} color="primary" />
              </Box>
              <Box sx={{ flexGrow: 1 }}>
                <StatCard icon={<OrdersIcon />} label="Orders" value={stats?.orders ?? 0} color="secondary" />
              </Box>
              <Box sx={{ flexGrow: 1 }}>
                <StatCard icon={<PrintersIcon />} label="Printers" value={stats?.printers ?? 0} color="success" />
              </Box>
              <Box sx={{ flexGrow: 1 }}>
                <StatCard icon={<JobsIcon />} label="Print Jobs" value={stats?.printJobs ?? 0} color="warning" />
              </Box>
            </Stack>

            <Card sx={{ mb: 3 }}>
              <CardContent>
                <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>
                  Subscriptions
                </Typography>
                <Stack direction="row" spacing={2} flexWrap="wrap" useFlexGap>
                  <Chip label={`ACTIVE: ${subCounts.ACTIVE ?? 0}`} color="success" variant="outlined" />
                  <Chip label={`EXPIRING: ${subCounts.EXPIRING ?? 0}`} color="warning" variant="outlined" />
                  <Chip label={`EXPIRED: ${subCounts.EXPIRED ?? 0}`} color="error" variant="outlined" />
                  <Chip label={`SUSPENDED: ${subCounts.SUSPENDED ?? 0}`} color="error" variant="outlined" />
                  <Chip label={`CANCELLED: ${subCounts.CANCELLED ?? 0}`} color="default" variant="outlined" />
                </Stack>
              </CardContent>
            </Card>

            <Card>
              <Toolbar sx={{ gap: 2 }}>
                <SearchIcon color="action" />
                <TextField
                  size="small"
                  placeholder="Search by shop name or agent key"
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  sx={{ flexGrow: 1 }}
                />
                <Button variant="contained" startIcon={<StoreIcon />} onClick={() => { setEditing(null); setFormOpen(true); }}>
                  Add Shop
                </Button>
              </Toolbar>
              <TableContainer component={Paper} elevation={0}>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Shop</TableCell>
                      <TableCell>Plan</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell>Ends On</TableCell>
                      <TableCell>Agent Key</TableCell>
                      <TableCell align="center">Orders / Printers / Users</TableCell>
                      <TableCell align="right">Actions</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {shops.length === 0 && (
                      <TableRow>
                        <TableCell colSpan={7} align="center" sx={{ py: 4, color: 'text.secondary' }}>
                          No shops found
                        </TableCell>
                      </TableRow>
                    )}
                    {shops.map((s) => {
                      const sub = s.subStatus || {};
                      return (
                        <TableRow key={s.id} hover sx={{ cursor: 'pointer' }} onClick={() => navigate(`/superadmin/shops/${s.id}`)}>
                          <TableCell>
                            <Typography fontWeight={600}>{s.name}</Typography>
                            <Typography variant="caption" color="text.secondary">
                              {s.agentKey}
                            </Typography>
                          </TableCell>
                          <TableCell>{sub.plan}</TableCell>
                          <TableCell>
                            <Chip
                              size="small"
                              label={sub.status}
                              color={STATUS_COLORS[sub.status] || 'default'}
                              variant="outlined"
                            />
                          </TableCell>
                          <TableCell>
                            {sub.endDate ? new Date(sub.endDate).toLocaleDateString() : '—'}
                          </TableCell>
                          <TableCell>
                            <Stack direction="row" spacing={1} alignItems="center">
                              <Typography variant="body2" fontFamily="monospace">
                                {s.agentKey}
                              </Typography>
                              <Tooltip title="Copy key">
                                <IconButton size="small" onClick={(e) => { e.stopPropagation(); copyKey(s.agentKey); }}>
                                  <VpnKeyIcon fontSize="small" />
                                </IconButton>
                              </Tooltip>
                              <Tooltip title="Rotate key">
                                <IconButton
                                  size="small"
                                  disabled={keyRegenId === s.id}
                                  onClick={(e) => { e.stopPropagation(); regenerateKey(s); }}
                                >
                                  {keyRegenId === s.id ? <CircularProgress size={14} /> : <RefreshIcon fontSize="small" />}
                                </IconButton>
                              </Tooltip>
                            </Stack>
                          </TableCell>
                          <TableCell align="center">
                            {s._count?.orders} / {s._count?.printers} / {s._count?.users}
                          </TableCell>
                          <TableCell align="right" onClick={(e) => e.stopPropagation()}>
                            <IconButton
                              size="small"
                              onClick={() => { setEditing(s); setFormOpen(true); }}
                            >
                              Edit
                            </IconButton>
                            <IconButton
                              size="small"
                              color="error"
                              onClick={() => setDeleteTarget(s)}
                            >
                              Delete
                            </IconButton>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </TableContainer>
            </Card>
          </>
        )}
      </Container>

      <ShopFormDialog
        open={formOpen}
        shop={editing}
        onClose={() => setFormOpen(false)}
        onSaved={() => { setFormOpen(false); load(); }}
      />

      <ChangePasswordDialog open={pwdOpen} onClose={() => setPwdOpen(false)} />

      <Dialog open={Boolean(deleteTarget)} onClose={() => setDeleteTarget(null)} maxWidth="xs" fullWidth>
        <DialogTitle>Delete shop?</DialogTitle>
        <DialogContent>
          <Alert severity="warning" sx={{ mb: 2 }}>
            This permanently deletes {deleteTarget?.name} and ALL of its orders, printers, users and print jobs. This cannot be undone.
          </Alert>
          <Typography variant="body2" color="text.secondary">
            Are you sure you want to continue?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteTarget(null)}>Cancel</Button>
          <Button color="error" variant="contained" onClick={handleDelete} disabled={deleting}>
            {deleting ? 'Deleting...' : 'Delete'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  MenuItem,
  Grid,
  Stack,
  Typography,
  CircularProgress,
} from '@mui/material';
import toast from 'react-hot-toast';
import api from '../api';

const PLANS = ['FREE', 'STARTER', 'PROFESSIONAL', 'ENTERPRISE'];
const STATUSES = ['ACTIVE', 'SUSPENDED', 'CANCELLED'];

export default function ShopFormDialog({ open, shop, onClose, onSaved }) {
  const isEdit = Boolean(shop);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({
    name: '',
    adminName: '',
    adminEmail: '',
    adminPassword: '',
    plan: 'FREE',
    status: 'ACTIVE',
    price: 0,
    endDate: '',
    maxPrinters: 1,
  });

  useEffect(() => {
    if (shop) {
      const sub = shop.subscription || {};
      setForm({
        name: shop.name || '',
        adminName: '',
        adminEmail: '',
        adminPassword: '',
        plan: sub.plan || 'FREE',
        status: sub.status || 'ACTIVE',
        price: sub.price ?? 0,
        endDate: sub.endDate ? sub.endDate.slice(0, 10) : '',
        maxPrinters: sub.maxPrinters ?? 1,
      });
    } else {
      setForm({
        name: '',
        adminName: '',
        adminEmail: '',
        adminPassword: '',
        plan: 'FREE',
        status: 'ACTIVE',
        price: 0,
        endDate: '',
        maxPrinters: 1,
      });
    }
  }, [shop, open]);

  const set = (k) => (e) => {
    const v = e.target.value;
    setForm((f) => ({ ...f, [k]: k === 'price' || k === 'maxPrinters' ? Number(v) : v }));
  };

  const handleSubmit = async () => {
    if (!form.name) {
      toast.error('Shop name is required');
      return;
    }
    setLoading(true);
    try {
      if (isEdit) {
        const body = {
          name: form.name,
          plan: form.plan,
          status: form.status,
          price: form.price,
          maxPrinters: form.maxPrinters,
          endDate: form.endDate ? `${form.endDate}T00:00:00.000Z` : null,
        };
        await api.put(`/superadmin/shops/${shop.id}`, body);
        toast.success('Shop updated');
      } else {
        if (!form.adminEmail || !form.adminPassword) {
          toast.error('Owner email and password are required');
          setLoading(false);
          return;
        }
        const body = {
          name: form.name,
          adminName: form.adminName || undefined,
          adminEmail: form.adminEmail,
          adminPassword: form.adminPassword,
          plan: form.plan,
          price: form.price,
          maxPrinters: form.maxPrinters,
          endDate: form.endDate ? `${form.endDate}T00:00:00.000Z` : null,
        };
        const res = await api.post('/superadmin/shops', body);
        toast.success('Shop created');
        if (res.data?.agentKey) {
          navigator.clipboard?.writeText(res.data.agentKey);
          toast.success(`Agent key copied: ${res.data.agentKey}`);
        }
      }
      onSaved();
    } catch (err) {
      // interceptor handles
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>{isEdit ? `Edit ${shop?.name}` : 'Add Shop'}</DialogTitle>
      <DialogContent>
        <Stack spacing={2} sx={{ mt: 1 }}>
          <TextField label="Shop name" fullWidth required value={form.name} onChange={set('name')} />
          {!isEdit && (
            <>
              <TextField label="Owner name" fullWidth value={form.adminName} onChange={set('adminName')} />
              <TextField label="Owner email" fullWidth type="email" required value={form.adminEmail} onChange={set('adminEmail')} />
              <TextField
                label="Owner password"
                fullWidth
                type="password"
                required
                value={form.adminPassword}
                onChange={set('adminPassword')}
                helperText="At least 6 characters"
              />
            </>
          )}
          <Grid container spacing={2}>
            <Grid item xs={6}>
              <TextField select label="Plan" fullWidth value={form.plan} onChange={set('plan')}>
                {PLANS.map((p) => (
                  <MenuItem key={p} value={p}>
                    {p}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={6}>
              <TextField
                select
                label="Status"
                fullWidth
                value={form.status}
                onChange={set('status')}
                disabled={!isEdit}
              >
                {STATUSES.map((s) => (
                  <MenuItem key={s} value={s}>
                    {s}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
          </Grid>
          <Grid container spacing={2}>
            <Grid item xs={6}>
              <TextField
                label="Price (INR)"
                fullWidth
                type="number"
                value={form.price}
                onChange={set('price')}
              />
            </Grid>
            <Grid item xs={6}>
              <TextField
                label="Max printers"
                fullWidth
                type="number"
                value={form.maxPrinters}
                onChange={set('maxPrinters')}
              />
            </Grid>
          </Grid>
          <TextField
            label="Subscription end date"
            fullWidth
            type="date"
            value={form.endDate}
            onChange={set('endDate')}
            InputLabelProps={{ shrink: true }}
            helperText="Leave blank for a lifetime plan"
          />
          {isEdit && (
            <Typography variant="caption" color="text.secondary">
              Set status to SUSPENDED or CANCELLED to immediately block the shop's printing.
            </Typography>
          )}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button variant="contained" onClick={handleSubmit} disabled={loading}>
          {loading ? <CircularProgress size={20} /> : isEdit ? 'Save' : 'Create Shop'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  Stack,
  CircularProgress,
} from '@mui/material';
import toast from 'react-hot-toast';
import api from '../api';

export default function ChangePasswordDialog({ open, onClose }) {
  const [loading, setLoading] = useState(false);
  const [current, setCurrent] = useState('');
  const [next, setNext] = useState('');
  const [confirm, setConfirm] = useState('');

  const handleSubmit = async () => {
    if (!current || !next) {
      toast.error('Please fill in all fields');
      return;
    }
    if (next.length < 6) {
      toast.error('New password must be at least 6 characters');
      return;
    }
    if (next !== confirm) {
      toast.error('Passwords do not match');
      return;
    }
    setLoading(true);
    try {
      await api.post('/superadmin/change-password', { currentPassword: current, newPassword: next });
      toast.success('Password updated');
      setCurrent('');
      setNext('');
      setConfirm('');
      onClose();
    } catch (err) {
      // interceptor handles
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="xs" fullWidth>
      <DialogTitle>Change Password</DialogTitle>
      <DialogContent>
        <Stack spacing={2} sx={{ mt: 1 }}>
          <TextField
            label="Current password"
            type="password"
            fullWidth
            value={current}
            onChange={(e) => setCurrent(e.target.value)}
          />
          <TextField
            label="New password"
            type="password"
            fullWidth
            value={next}
            onChange={(e) => setNext(e.target.value)}
          />
          <TextField
            label="Confirm new password"
            type="password"
            fullWidth
            value={confirm}
            onChange={(e) => setConfirm(e.target.value)}
          />
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button variant="contained" onClick={handleSubmit} disabled={loading}>
          {loading ? <CircularProgress size={20} /> : 'Update'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Container,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Grid,
  IconButton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Toolbar,
  Tooltip,
  Typography,
  Alert,
  Paper,
  Divider,
} from '@mui/material';
import {
  ArrowBack as BackIcon,
  Store as StoreIcon,
  VpnKey as VpnKeyIcon,
  Refresh as RefreshIcon,
  ReceiptLong as OrdersIcon,
  Print as PrintersIcon,
  People as UsersIcon,
  Description as JobsIcon,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../api';
import ShopFormDialog from '../components/ShopFormDialog';

const STATUS_COLORS = {
  ACTIVE: 'success',
  EXPIRING: 'warning',
  EXPIRED: 'error',
  SUSPENDED: 'error',
  CANCELLED: 'default',
};

export default function ShopDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [shop, setShop] = useState(null);
  const [loading, setLoading] = useState(true);
  const [editOpen, setEditOpen] = useState(false);
  const [deleteOpen, setDeleteOpen] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [regenerating, setRegenerating] = useState(false);

  const load = async () => {
    setLoading(true);
    try {
      const res = await api.get(`/superadmin/shops/${id}`);
      setShop(res.data);
    } catch (err) {
      // interceptor handles
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const copyKey = () => {
    navigator.clipboard?.writeText(shop.agentKey);
    toast.success('Agent key copied');
  };

  const regenerateKey = async () => {
    setRegenerating(true);
    try {
      const res = await api.post(`/superadmin/shops/${id}/regenerate-key`);
      toast.success('Agent key rotated');
      copyKey(res.data.agentKey);
      load();
    } catch (err) {
      // interceptor handles
    } finally {
      setRegenerating(false);
    }
  };

  const handleDelete = async () => {
    setDeleting(true);
    try {
      await api.delete(`/superadmin/shops/${id}`);
      toast.success('Shop deleted');
      navigate('/superadmin', { replace: true });
    } catch (err) {
      // interceptor handles
    } finally {
      setDeleting(false);
    }
  };

  if (loading && !shop) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 10 }}>
        <CircularProgress />
      </Box>
    );
  }

  if (!shop) return null;

  const sub = shop.subStatus || {};
  const counts = shop._count || {};

  return (
    <Box>
      <Toolbar sx={{ bgcolor: 'background.paper', borderBottom: '1px solid', borderColor: 'divider', gap: 1 }}>
        <IconButton onClick={() => navigate('/superadmin')}>
          <BackIcon />
        </IconButton>
        <Typography variant="h6" sx={{ flexGrow: 1 }}>
          {shop.name}
        </Typography>
        <Button startIcon={<StoreIcon />} onClick={() => setEditOpen(true)}>
          Edit
        </Button>
        <Button color="error" variant="outlined" onClick={() => setDeleteOpen(true)}>
          Delete
        </Button>
      </Toolbar>

      <Container maxWidth="lg" sx={{ py: 3 }}>
        <Grid container spacing={3}>
          <Grid item xs={12} md={7}>
            <Card>
              <CardContent>
                <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 2 }}>
                  <VpnKeyIcon color="primary" />
                  <Typography variant="h6" sx={{ flexGrow: 1 }}>
                    Agent Key
                  </Typography>
                  <Tooltip title="Copy">
                    <IconButton onClick={copyKey}>
                      <VpnKeyIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                  <Tooltip title="Rotate key (old key stops working)">
                    <span>
                      <Button
                        size="small"
                        variant="outlined"
                        startIcon={regenerating ? <CircularProgress size={14} /> : <RefreshIcon />}
                        onClick={regenerateKey}
                        disabled={regenerating}
                      >
                        Regenerate
                      </Button>
                    </span>
                  </Tooltip>
                </Stack>
                <Typography variant="h5" fontFamily="monospace" letterSpacing={1}>
                  {shop.agentKey}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                  Used by the desktop app for one-time activation. Rotating the key disables all existing activations.
                </Typography>
              </CardContent>
            </Card>

            <Card sx={{ mt: 3 }}>
              <CardContent>
                <Typography variant="h6" sx={{ mb: 2 }}>
                  Recent Print Jobs
                </Typography>
                <TableContainer component={Paper} elevation={0}>
                  <Table size="small">
                    <TableHead>
                      <TableRow>
                        <TableCell>ID</TableCell>
                        <TableCell>Status</TableCell>
                        <TableCell>Paper</TableCell>
                        <TableCell>Mode</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {(shop.recentJobs || []).length === 0 && (
                        <TableRow>
                          <TableCell colSpan={4} align="center" sx={{ py: 3, color: 'text.secondary' }}>
                            No print jobs yet
                          </TableCell>
                        </TableRow>
                      )}
                      {(shop.recentJobs || []).map((j) => (
                        <TableRow key={j.id}>
                          <TableCell>
                            <Typography variant="body2" fontFamily="monospace" fontSize={12}>
                              {j.id.slice(0, 8)}
                            </Typography>
                          </TableCell>
                          <TableCell>
                            <Chip size="small" label={j.status} variant="outlined" />
                          </TableCell>
                          <TableCell>{j.paperSize}</TableCell>
                          <TableCell>{j.colorMode}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} md={5}>
            <Card>
              <CardContent>
                <Stack direction="row" alignItems="center" justifyContent="space-between">
                  <Typography variant="h6">Subscription</Typography>
                  <Chip label={sub.plan} color="primary" variant="outlined" />
                </Stack>
                <Stack direction="row" spacing={1} sx={{ mt: 1 }}>
                  <Chip size="small" label={sub.status} color={STATUS_COLORS[sub.status] || 'default'} variant="outlined" />
                  {sub.daysLeft !== null && sub.daysLeft !== undefined && (
                    <Chip size="small" label={`${sub.daysLeft} days left`} color={sub.daysLeft <= 5 ? 'warning' : 'default'} variant="outlined" />
                  )}
                </Stack>
                <Divider sx={{ my: 2 }} />
                <Stack spacing={1}>
                  <Typography variant="body2">
                    <strong>Price:</strong> ₹{sub.price?.toLocaleString?.('en-IN') ?? sub.price ?? 0}
                  </Typography>
                  <Typography variant="body2">
                    <strong>Ends:</strong> {sub.endDate ? new Date(sub.endDate).toLocaleDateString() : 'Lifetime'}
                  </Typography>
                  <Typography variant="body2">
                    <strong>Max printers:</strong> {sub.maxPrinters ?? 1}
                  </Typography>
                </Stack>
                {sub.status !== 'ACTIVE' && (
                  <Alert severity="error" sx={{ mt: 2 }}>
                    {sub.status === 'EXPIRED' && 'Subscription has expired — printing is blocked.'}
                    {sub.status === 'SUSPENDED' && 'Shop is suspended — printing is blocked.'}
                    {sub.status === 'CANCELLED' && 'Subscription cancelled — printing is blocked.'}
                  </Alert>
                )}
                {sub.status === 'ACTIVE' && sub.daysLeft !== null && sub.daysLeft <= 5 && (
                  <Alert severity="warning" sx={{ mt: 2 }}>
                    Expiring soon — {sub.daysLeft} day(s) left.
                  </Alert>
                )}
              </CardContent>
            </Card>

            <Card sx={{ mt: 3 }}>
              <CardContent>
                <Typography variant="h6" sx={{ mb: 2 }}>
                  Usage
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={6}>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <OrdersIcon color="secondary" />
                      <Box>
                        <Typography variant="h6">{counts.orders ?? 0}</Typography>
                        <Typography variant="caption" color="text.secondary">Orders</Typography>
                      </Box>
                    </Stack>
                  </Grid>
                  <Grid item xs={6}>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <JobsIcon color="warning" />
                      <Box>
                        <Typography variant="h6">{counts.printJobs ?? 0}</Typography>
                        <Typography variant="caption" color="text.secondary">Print jobs</Typography>
                      </Box>
                    </Stack>
                  </Grid>
                  <Grid item xs={6}>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <PrintersIcon color="success" />
                      <Box>
                        <Typography variant="h6">{counts.printers ?? 0}</Typography>
                        <Typography variant="caption" color="text.secondary">Printers</Typography>
                      </Box>
                    </Stack>
                  </Grid>
                  <Grid item xs={6}>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <PeopleIcon color="primary" />
                      <Box>
                        <Typography variant="h6">{counts.users ?? 0}</Typography>
                        <Typography variant="caption" color="text.secondary">Users</Typography>
                      </Box>
                    </Stack>
                  </Grid>
                </Grid>
                <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
                  <strong>Customers:</strong> {counts.customers ?? 0} &nbsp;|&nbsp;{' '}
                  <strong>Completed orders:</strong> {shop.completedOrders ?? 0}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>

      <ShopFormDialog
        open={editOpen}
        shop={shop}
        onClose={() => setEditOpen(false)}
        onSaved={() => { setEditOpen(false); load(); }}
      />

      <Dialog open={deleteOpen} onClose={() => setDeleteOpen(false)} maxWidth="xs" fullWidth>
        <DialogTitle>Delete shop?</DialogTitle>
        <DialogContent>
          <Alert severity="warning" sx={{ mb: 2 }}>
            This permanently deletes {shop.name} and ALL of its data. This cannot be undone.
          </Alert>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteOpen(false)}>Cancel</Button>
          <Button color="error" variant="contained" onClick={handleDelete} disabled={deleting}>
            {deleting ? 'Deleting...' : 'Delete'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

