const { PrismaClient } = require('@prisma/client');
const bcrypt = require('bcryptjs');

process.env.DATABASE_URL = 'postgresql://postgres:postgres@localhost:5432/patel_autoprint_legacy?schema=public';
const prisma = new PrismaClient();

async function main() {
  const hash = await bcrypt.hash('admin123', 10);

  const shop = await prisma.shop.create({
    data: {
      name: 'Patel AutoPrint',
      settings: { currency: 'INR', timeZone: 'Asia/Kolkata' },
    },
  });
  console.log('shop', shop.id);

  const u1 = await prisma.user.create({ data: { shopId: shop.id, email: 'admin@patelautoprint.com', passwordHash: hash, name: 'Mayank Patel', role: 'OWNER' } });
  const u2 = await prisma.user.create({ data: { shopId: shop.id, email: 'manager@patelautoprint.com', passwordHash: hash, name: 'Rahul Sharma', role: 'MANAGER' } });
  const u3 = await prisma.user.create({ data: { shopId: shop.id, email: 'operator@patelautoprint.com', passwordHash: hash, name: 'Priya Kumar', role: 'OPERATOR' } });
  console.log('users', u1.email, u2.email, u3.email);

  for (let i = 0; i < 3; i++) {
    await prisma.customer.create({ data: { shopId: shop.id, name: `Customer ${i}`, phone: `98765${i}${i}${i}0` } });
  }

  const p1 = await prisma.printer.create({ data: { shopId: shop.id, name: 'Canon iR-ADV 6575', ip: '192.168.1.100', colorSupport: false, duplexSupport: true, status: 'ONLINE' } });
  const p2 = await prisma.printer.create({ data: { shopId: shop.id, name: 'Konica Bizhub C450i', ip: '192.168.1.101', colorSupport: true, duplexSupport: true, status: 'ONLINE' } });
  console.log('printers', p1.name, p2.name);

  for (let i = 0; i < 3; i++) {
    await prisma.pricingRule.create({ data: { shopId: shop.id, name: `Rule ${i}`, bwPerPage: 1, colorPerPage: 5, colorDuplexPerPage: 10, taxRate: 18 } });
  }

  for (let i = 1; i <= 4; i++) {
    await prisma.order.create({
      data: {
        shopId: shop.id,
        token: i,
        customerName: `Order Customer ${i}`,
        customerPhone: `90000${i}${i}${i}`,
        status: 'COMPLETED',
        totalPrice: 10 + i,
        paymentMethod: 'CASH',
      },
    });
  }
  console.log('orders created');
  console.log('DONE');
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(() => prisma.$disconnect());

