const { PrismaClient } = require('@prisma/client');
const bcrypt = require('bcryptjs');

process.env.DATABASE_URL = 'postgresql://postgres:postgres@localhost:5432/patel_autoprint_legacy?schema=public';
const prisma = new PrismaClient();

async function main() {
  const hash = await bcrypt.hash('admin123', 10);

  const shopId = await prisma.$queryRawUnsafe(
    `INSERT INTO shops (id, name, settings, "createdAt", "updatedAt") VALUES (gen_random_uuid(), 'Patel AutoPrint', '{"currency":"INR","timeZone":"Asia/Kolkata"}'::jsonb, now(), now()) RETURNING id`
  );
  const sid = shopId[0].id;
  console.log('shop', sid);

  await prisma.$queryRawUnsafe(
    `INSERT INTO users (id, "shopId", email, "passwordHash", name, role, "createdAt", "updatedAt") VALUES (gen_random_uuid(), $1, 'admin@patelautoprint.com', $2, 'Mayank Patel', 'OWNER', now(), now())`,
    sid, hash
  );
  await prisma.$queryRawUnsafe(
    `INSERT INTO users (id, "shopId", email, "passwordHash", name, role, "createdAt", "updatedAt") VALUES (gen_random_uuid(), $1, 'manager@patelautoprint.com', $2, 'Rahul Sharma', 'MANAGER', now(), now())`,
    sid, hash
  );
  await prisma.$queryRawUnsafe(
    `INSERT INTO users (id, "shopId", email, "passwordHash", name, role, "createdAt", "updatedAt") VALUES (gen_random_uuid(), $1, 'operator@patelautoprint.com', $2, 'Priya Kumar', 'OPERATOR', now(), now())`,
    sid, hash
  );
  console.log('users inserted');

  for (let i = 0; i < 3; i++) {
    await prisma.$queryRawUnsafe(
      `INSERT INTO customers (id, "shopId", name, phone, "createdAt", "updatedAt") VALUES (gen_random_uuid(), $1, $2, $3, now(), now())`,
      sid, `Customer ${i}`, `98765000${i}`
    );
  }

  await prisma.$queryRawUnsafe(
    `INSERT INTO printers (id, "shopId", name, ip, "colorSupport", "duplexSupport", status, "createdAt", "updatedAt") VALUES (gen_random_uuid(), $1, 'Canon iR-ADV 6575', '192.168.1.100', false, true, 'ONLINE', now(), now())`,
    sid
  );
  await prisma.$queryRawUnsafe(
    `INSERT INTO printers (id, "shopId", name, ip, "colorSupport", "duplexSupport", status, "createdAt", "updatedAt") VALUES (gen_random_uuid(), $1, 'Konica Bizhub C450i', '192.168.1.101', true, true, 'ONLINE', now(), now())`,
    sid
  );

  for (let i = 0; i < 3; i++) {
    await prisma.$queryRawUnsafe(
      `INSERT INTO pricing_rules (id, "shopId", name, "bwPerPage", "colorPerPage", "colorDuplexPerPage", "taxRate", "createdAt", "updatedAt") VALUES (gen_random_uuid(), $1, $2, 1, 5, 10, 18, now(), now())`,
      sid, `Rule ${i}`
    );
  }

  for (let i = 1; i <= 4; i++) {
    const orderId = await prisma.$queryRawUnsafe(
      `INSERT INTO orders (id, "shopId", token, "customerName", "customerPhone", status, "totalPrice", "paymentMethod", "createdAt", "updatedAt") VALUES (gen_random_uuid(), $1, $2, $3, $4, 'COMPLETED', $5, 'CASH', now(), now()) RETURNING id`,
      sid, i, `Order Customer ${i}`, `90000${i}${i}${i}`, 10 + i
    );
    await prisma.$queryRawUnsafe(
      `INSERT INTO print_jobs (id, "orderId", "fileId", "sectionIndex", pages, "colorMode", "printStyle", "paperSize", "pagesPerSheet", "flipDirection", copies, status, "shopId") VALUES (gen_random_uuid(), $1, gen_random_uuid(), 0, '[1]', 'bw', 'single', 'A4', 1, 'long-edge', 1, 'COMPLETED', $2)`,
      orderId[0].id, sid
    );
  }
  console.log('orders + jobs inserted');
  console.log('DONE');
}

main()
  .catch((e) => { console.error(e); process.exit(1); })
  .finally(() => prisma.$disconnect());

