const { PrismaClient } = require('@prisma/client');
process.env.DATABASE_URL = 'postgresql://postgres:postgres@localhost:5432/patel_autoprint_legacy?schema=public';
const prisma = new PrismaClient();
async function main() {
  const shops = await prisma.shop.count();
  const users = await prisma.user.count();
  const customers = await prisma.customer.count();
  const printers = await prisma.printer.count();
  const pricing = await prisma.pricingRule.count();
  const orders = await prisma.order.count();
  const files = await prisma.orderFile.count();
  const jobs = await prisma.printJob.count();
  const subs = await prisma.subscription.count();
  const orphans = await prisma.user.count({ where: { shopId: { not: { equals: undefined } } } });
  const noShopUsers = await prisma.$queryRawUnsafe(`SELECT count(*)::int AS c FROM users WHERE "shopId" IS NULL`);
  const noShopCust = await prisma.$queryRawUnsafe(`SELECT count(*)::int AS c FROM customers WHERE "shopId" IS NULL`);
  const noShopOrders = await prisma.$queryRawUnsafe(`SELECT count(*)::int AS c FROM orders WHERE "shopId" IS NULL`);
  const agentKeyNull = await prisma.shop.count({ where: { agentKey: null } });
  console.log(JSON.stringify({ shops, users, customers, printers, pricing, orders, files, jobs, subs, noShopUsers: noShopUsers[0].c, noShopCust: noShopCust[0].c, noShopOrders: noShopOrders[0].c, agentKeyNull }, null, 2));
  const ordersList = await prisma.order.findMany({ select: { token: true, shopId: true } });
  console.log('order tokens:', ordersList.map(o => o.token).join(','));
}
main().catch(e => { console.error(e); process.exit(1); }).finally(() => prisma.$disconnect());

