import { Routes, Route, Navigate } from 'react-router-dom';
import { Box, Typography } from '@mui/material';
import { useAuth } from './AuthContext';

import LoginPage from './pages/LoginPage';
import ActivationPage from './pages/ActivationPage';
import AdminLayout from './pages/admin/AdminLayout';
import DashboardPage from './pages/admin/DashboardPage';
import OrderQueuePage from './pages/admin/OrderQueuePage';
import OrderDetailPage from './pages/admin/OrderDetailPage';
import PrintersPage from './pages/admin/PrintersPage';
import SettingsPage from './pages/admin/SettingsPage';
import AgentPage from './pages/admin/AgentPage';

function RequireAuth({ children }) {
  const { isAuthenticated, loading } = useAuth();

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', mt: 10 }}>
        <Typography>Loading...</Typography>
      </Box>
    );
  }

  if (!isAuthenticated) {
    return <Navigate to="/activate" replace />;
  }

  return children;
}

export default function App() {
  return (
    <Routes>
      <Route path="/activate" element={<ActivationPage />} />
      <Route path="/login" element={<LoginPage />} />
      <Route
        path="/admin"
        element={
          <RequireAuth>
            <AdminLayout />
          </RequireAuth>
        }
      >
        <Route index element={<DashboardPage />} />
        <Route path="orders" element={<OrderQueuePage />} />
        <Route path="orders/:id" element={<OrderDetailPage />} />
        <Route path="printers" element={<PrintersPage />} />
        <Route path="settings" element={<SettingsPage />} />
        <Route path="agent" element={<AgentPage />} />
      </Route>
      <Route path="/" element={<Navigate to="/admin" replace />} />
      <Route path="*" element={<Navigate to="/admin" replace />} />
    </Routes>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Typography,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Button,
  Chip,
  InputAdornment,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from '@mui/material';
import {
  Search as SearchIcon,
  Refresh as RefreshIcon,
  Visibility as ViewIcon,
  CheckCircle as ApproveIcon,
  Cancel as RejectIcon,
  Print as PrintIcon,
} from '@mui/icons-material';
import toast from 'react-hot-toast';
import api from '../../api';
import OrderStatusBadge from '../../components/OrderStatusBadge';

const statusFilters = [
  { value: '', label: 'All Status' },
  { value: 'PENDING', label: 'Pending' },
  { value: 'APPROVED', label: 'Approved' },
  { value: 'PRINTING', label: 'Printing' },
  { value: 'COMPLETED', label: 'Completed' },
  { value: 'REJECTED', label: 'Rejected' },
];

export default function OrderQueuePage() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [lastRefresh, setLastRefresh] = useState(new Date());
  const navigate = useNavigate();

  // Print dialog state
  const [printDialogOpen, setPrintDialogOpen] = useState(false);
  const [printOrderId, setPrintOrderId] = useState(null);
  const [bwPrinter, setBwPrinter] = useState('');
  const [colorPrinter, setColorPrinter] = useState('');
  const [printers, setPrinters] = useState([]);
  const [printDialogLoading, setPrintDialogLoading] = useState(false);

  const fetchOrders = useCallback(async () => {
    try {
      const params = new URLSearchParams();
      if (search) params.append('search', search);
      if (statusFilter) params.append('status', statusFilter);

      const result = await api.get(`/admin/orders?${params.toString()}`);
      if (result.success) {
        setOrders(result.data?.orders || []);
      }
      setLastRefresh(new Date());
    } catch {
      // Error handled by interceptor
    } finally {
      setLoading(false);
    }
  }, [search, statusFilter]);

  useEffect(() => {
    fetchOrders();
    const interval = setInterval(fetchOrders, 10000);
    return () => clearInterval(interval);
  }, [fetchOrders]);

  const handleStatusChange = async (orderId, newStatus) => {
    try {
      await api.put(`/admin/orders/${orderId}/status`, { status: newStatus });
      toast.success(`Order ${newStatus.toLowerCase()}`);
      fetchOrders();
    } catch {
      toast.error('Failed to update status');
    }
  };

  const handleReprint = async (orderId) => {
    try {
      await api.post(`/admin/orders/${orderId}/reprint`);
      toast.success('Reprint job sent');
    } catch {
      toast.error('Failed to reprint');
    }
  };

  // --- Print Dialog ---
  const openPrintDialog = async (orderId) => {
    setPrintOrderId(orderId);
    setPrintDialogOpen(true);
    setBwPrinter('');
    setColorPrinter('');
    setPrintDialogLoading(true);

    try {
      const [printersRes, settingsRes] = await Promise.all([
        api.get('/printers'),
        api.get('/settings/pricing'),
      ]);
      if (printersRes.success) {
        setPrinters(printersRes.data?.printers || []);
      }
      if (settingsRes.success && settingsRes.data) {
        setBwPrinter(settingsRes.data.defaultBwPrinter || '');
        setColorPrinter(settingsRes.data.defaultColorPrinter || '');
      }
    } catch {
      // ignore
    } finally {
      setPrintDialogLoading(false);
    }
  };

  const handlePrintConfirm = async () => {
    if (!printOrderId) return;
    try {
      const body = { status: 'PRINTING' };
      if (bwPrinter) body.bwPrinterName = bwPrinter;
      if (colorPrinter) body.colorPrinterName = colorPrinter;
      await api.put(`/admin/orders/${printOrderId}/status`, body);
      toast.success('Order approved & sent to print');
      setPrintDialogOpen(false);
      setPrintOrderId(null);
      fetchOrders();
    } catch {
      toast.error('Failed to send to print');
    }
  };

  const closePrintDialog = () => {
    setPrintDialogOpen(false);
    setPrintOrderId(null);
  };

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5">Order Queue</Typography>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Typography variant="caption" color="text.secondary">
            Last refresh: {lastRefresh.toLocaleTimeString()}
          </Typography>
          <IconButton onClick={fetchOrders} size="small">
            <RefreshIcon />
          </IconButton>
        </Box>
      </Box>

      <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
        <TextField
          fullWidth
          size="small"
          placeholder="Search by Token, Name, Phone..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
          }}
        />
        <FormControl sx={{ minWidth: 160 }} size="small">
          <InputLabel>Status</InputLabel>
          <Select
            value={statusFilter}
            label="Status"
            onChange={(e) => setStatusFilter(e.target.value)}
          >
            {statusFilters.map((f) => (
              <MenuItem key={f.value} value={f.value}>{f.label}</MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
          <CircularProgress />
        </Box>
      ) : (
        <Box sx={{ overflowX: 'auto' }}>
          <TableContainer component={Paper}>
            <Table size="small" sx={{ minWidth: 800 }}>
            <TableHead>
              <TableRow>
                <TableCell>Token</TableCell>
                <TableCell>Customer</TableCell>
                <TableCell>Phone</TableCell>
                <TableCell>Files</TableCell>
                <TableCell>Amount</TableCell>
                <TableCell>Payment</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Time</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {orders.map((order) => (
                <TableRow key={order.id} hover>
                  <TableCell sx={{ fontWeight: 700, fontSize: 14 }}>
                    #{order.token || '-'}
                  </TableCell>
                  <TableCell>{order.customer?.name || 'Walk-in'}</TableCell>
                  <TableCell>{order.customer?.phone || '-'}</TableCell>
                  <TableCell>{order.files?.length || 0}</TableCell>
                  <TableCell>₹{order.totalPrice?.toFixed(2)}</TableCell>
                  <TableCell>
                    <Chip
                      label={order.paymentMethod || 'N/A'}
                      size="small"
                      variant="outlined"
                      sx={{ textTransform: 'capitalize' }}
                    />
                  </TableCell>
                  <TableCell><OrderStatusBadge status={order.status} /></TableCell>
                  <TableCell>
                    {new Date(order.createdAt).toLocaleString('en-IN', {
                      hour: '2-digit',
                      minute: '2-digit',
                      hour12: true,
                    })}
                  </TableCell>
                  <TableCell align="right">
                    <IconButton
                      size="small"
                      onClick={() => navigate(`/admin/orders/${order.id}`)}
                      title="View Details"
                    >
                      <ViewIcon fontSize="small" />
                    </IconButton>
                    {order.status === 'PENDING' && (
                      <>
                        <IconButton
                          size="small"
                          color="success"
                          onClick={() => openPrintDialog(order.id)}
                          title="Approve & Print"
                        >
                          <ApproveIcon fontSize="small" />
                        </IconButton>
                        <IconButton
                          size="small"
                          color="error"
                          onClick={() => handleStatusChange(order.id, 'REJECTED')}
                          title="Reject"
                        >
                          <RejectIcon fontSize="small" />
                        </IconButton>
                      </>
                    )}
                    {order.status === 'APPROVED' && (
                      <IconButton
                        size="small"
                        color="primary"
                        onClick={() => openPrintDialog(order.id)}
                        title="Start Printing"
                      >
                        <PrintIcon fontSize="small" />
                      </IconButton>
                    )}
                    {order.status === 'PRINTING' && (
                      <IconButton
                        size="small"
                        color="success"
                        onClick={() => handleStatusChange(order.id, 'COMPLETED')}
                        title="Mark Complete"
                      >
                        <ApproveIcon fontSize="small" />
                      </IconButton>
                    )}
                    {order.status === 'COMPLETED' && (
                      <IconButton
                        size="small"
                        color="warning"
                        onClick={() => handleReprint(order.id)}
                        title="Reprint"
                      >
                        <PrintIcon fontSize="small" />
                      </IconButton>
                    )}
                  </TableCell>
                </TableRow>
              ))}
              {orders.length === 0 && (
                <TableRow>
                  <TableCell colSpan={9} align="center">No orders found</TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
        </Box>
      )}

      {/* Print Dialog — select printers inline, no page redirect */}
      <Dialog open={printDialogOpen} onClose={closePrintDialog} maxWidth="sm" fullWidth>
        <DialogTitle>Select Printers</DialogTitle>
        <DialogContent>
          {printDialogLoading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
              <CircularProgress />
            </Box>
          ) : (
            <Box sx={{ pt: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
              <FormControl fullWidth size="small">
                <InputLabel>B/W Printer</InputLabel>
                <Select
                  value={bwPrinter}
                  label="B/W Printer"
                  onChange={(e) => setBwPrinter(e.target.value)}
                >
                  <MenuItem value=""><em>Auto (any B/W printer)</em></MenuItem>
                  {printers.filter((p) => !p.colorSupport).map((p) => (
                    <MenuItem key={p.id} value={p.name}>{p.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
              <FormControl fullWidth size="small">
                <InputLabel>Color Printer</InputLabel>
                <Select
                  value={colorPrinter}
                  label="Color Printer"
                  onChange={(e) => setColorPrinter(e.target.value)}
                >
                  <MenuItem value=""><em>Auto (any Color printer)</em></MenuItem>
                  {printers.filter((p) => p.colorSupport).map((p) => (
                    <MenuItem key={p.id} value={p.name}>{p.name}</MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={closePrintDialog}>Cancel</Button>
          <Button variant="contained" color="success" onClick={handlePrintConfirm} startIcon={<PrintIcon />}>
            Print
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

