```js
// ============================================
// WHATSAPP WEBHOOK (Meta WhatsApp Cloud API)
// ============================================

const WHATSAPP_ENABLED = !!process.env.WHATSAPP_ACCESS_TOKEN;

app.get('/api/whatsapp/webhook', (req, res) => {
  const mode = req.query['hub.mode'];
  const token = req.query['hub.verify_token'];
  const challenge = req.query['hub.challenge'];
  if (mode === 'subscribe' && token === (process.env.WHATSAPP_VERIFY_TOKEN || '')) {
    return res.status(200).send(challenge);
  }
  res.sendStatus(403);
});

app.post('/api/whatsapp/webhook', async (req, res) => {
  // Always respond 200 fast-ish. We'll process messages.
  if (!WHATSAPP_ENABLED) return res.sendStatus(200);
  // Optional signature verification
  const sig = req.get('X-Hub-Signature-256');
  const appSecret = process.env.WHATSAPP_APP_SECRET;
  if (appSecret && sig) {
    const hmac = crypto.createHmac('sha256', appSecret).update(JSON.stringify(req.body)).digest('hex');
    if (!`sha256=${hmac}`.localeCompare(sig)) {
      console.warn('WhatsApp webhook: signature mismatch, ignoring');
      return res.sendStatus(200);
    }
  }
  try {
    await handleWhatsAppWebhook(req.body);
  } catch (err) {
    console.error('WhatsApp webhook processing error:', err.message);
  }
  res.sendStatus(200);
});
