`handleWhatsAppWebhook(body)`:
```js
async function handleWhatsAppWebhook(body) {
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const value = change.value || {};
      const messages = value.messages || [];
      if (!messages.length) continue;
      const metaPhone = value.metadata?.display_phone_number || '';
      const shop = await prisma.shop.findFirst({ where: { whatsappNumber: normalizePhone(metaPhone) } });
      if (!shop) {
        console.warn(`WhatsApp: no shop configured for number ${metaPhone}`);
        continue;
      }
      for (const message of messages) {
        await handleWhatsAppMessage(shop, value.metadata?.phone_number_id, message);
      }
    }
  }
}
```

`handleWhatsAppMessage(shop, phoneNumberId, message)`:
```js
async function handleWhatsAppMessage(shop, phoneNumberId, message) {
  const from = normalizePhone(message.from);
  if (!from) return;
  const msgId = message.id;

  // Reject unsupported types with a helpful reply
  const media = message.type === 'image' ? message.image
    : message.type === 'document' ? message.document
    : null;

  if (!media) {
    const txt = (message.text?.body || '').trim().toLowerCase();
    if (txt) {
      await sendText(from, '👋 Welcome to ' + shop.name + '! Send me your files (PDF, Word, PPT, Excel, JPG, PNG) and I will send you a link to set print options.');
    }
    return;
  }

  if (!message.type === 'image' && !message.type === 'document') return; // defensive

  // Build/load session
  let session = await prisma.whatsAppSession.findFirst({
    where: { shopId: shop.id, customerPhone: from, status: 'NEW' },
    orderBy: { createdAt: 'desc' },
  });
  if (!session) {
    session = await prisma.whatsAppSession.create({
      data: {
        token: crypto.randomBytes(16).toString('hex'),
        shopId: shop.id,
        customerPhone: from,
        customerName: message.contacts?.[0]?.profile?.name || null,
        files: [],
        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
      },
    });
  }

  const currentFiles = session.files || [];
  if (currentFiles.some((f) => f.messageId === msgId)) {
    return; // duplicate delivery
  }

  const mimeType = media.mime_type || '';
  const originalName = message.type === 'document' && media.filename
    ? media.filename
    : `whatsapp_${Date.now()}.${extFromMime(mimeType)}`;
  if (!isSupportedFileType(originalName)) {
    await sendText(from, `Sorry, I can't print "${originalName}" (${mimeType || 'unknown type'}). Please send PDF, Word, PPT, Excel, JPG or PNG.`);
    return;
  }

  const destDir = path.join(UPLOAD_DIR, 'whatsapp', session.token);
  try {
    const downloaded = await downloadMedia(media.id, destDir, originalName);
    const updatedFiles = [
      ...currentFiles,
      { messageId: msgId, originalName, storagePath: downloaded.path, fileType: getFileType(originalName), size: downloaded.size, mediaId: media.id },
    ];
    await prisma.whatsAppSession.update({ where: { id: session.id }, data: { files: updatedFiles } });

    const link = `${process.env.PUBLIC_URL || 'https://patel-autoprint.onrender.com'}/s/${shop.slug}?wa=${session.token}`;
    const count = updatedFiles.length;
    await sendText(from,
      `✅ Received "${originalName}" (${count} file${count === 1 ? '' : 's'} so far).\n` +
      `When you're done sending, tap this link to set your print options:\n${link}`);
  } catch (err) {
    console.error('WhatsApp media download error:', err.message);
    await sendText(from, 'Something went wrong receiving that file. Please try again.');
  }
}
```

