const fs = require('fs');
const path = require('path');

const GRAPH_URL = process.env.WHATSAPP_GRAPH_URL || 'https://graph.facebook.com/v20.0';
const ACCESS_TOKEN = process.env.WHATSAPP_ACCESS_TOKEN || '';
const PHONE_NUMBER_ID = process.env.WHATSAPP_PHONE_NUMBER_ID || '';

function isEnabled() {
  return !!ACCESS_TOKEN;
}

function normalizePhone(phone) {
  return String(phone || '').replace(/\D/g, '');
}

function extFromMime(mime) {
  const map = {
    'application/pdf': 'pdf',
    'application/msword': 'doc',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
    'application/vnd.ms-powerpoint': 'ppt',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
    'application/vnd.ms-excel': 'xls',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
    'image/jpeg': 'jpg',
    'image/png': 'png',
    'image/webp': 'webp',
  };
  return map[mime] || 'bin';
}

// Download a WhatsApp media file to destDir and return { path, size, mimeType }
async function downloadMedia(mediaId, destDir, filename) {
  if (!ACCESS_TOKEN) throw new Error('WHATSAPP_ACCESS_TOKEN not configured');

  const infoRes = await fetch(`${GRAPH_URL}/${mediaId}`, {
    headers: { Authorization: `Bearer ${ACCESS_TOKEN}` },
  });
  if (!infoRes.ok) {
    const text = await infoRes.text();
    throw new Error(`Media info failed (${infoRes.status}): ${text.slice(0, 200)}`);
  }
  const info = await infoRes.json();
  const url = info.url;
  const mimeType = info.mime_type || '';

  const dlRes = await fetch(url);
  if (!dlRes.ok) throw new Error(`Media download failed (${dlRes.status})`);
  const buffer = Buffer.from(await dlRes.arrayBuffer());

  fs.mkdirSync(destDir, { recursive: true });
  const filePath = path.join(destDir, filename);
  fs.writeFileSync(filePath, buffer);

  return { path: filePath, size: buffer.length, mimeType };
}

// Send a plain text message to a customer's WhatsApp
async function sendText(to, body, phoneNumberId) {
  const numberId = phoneNumberId || PHONE_NUMBER_ID;
  if (!ACCESS_TOKEN || !numberId) throw new Error('WhatsApp not configured');

  const res = await fetch(`${GRAPH_URL}/${numberId}/messages`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${ACCESS_TOKEN}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to,
      type: 'text',
      text: { body },
    }),
  });
  if (!res.ok) {
    const text = await res.text();
    console.error(`WhatsApp send failed (${res.status}):`, text.slice(0, 300));
    return false;
  }
  return true;
}

module.exports = { isEnabled, normalizePhone, extFromMime, downloadMedia, sendText };

