// ============================================
// WHATSAPP WEBHOOK (Meta WhatsApp Cloud API)
// ============================================

// Process a single inbound WhatsApp message: download files into a session,
// then reply with the portal link that pre-loads those files.
async function handleWhatsAppMessage(shop, phoneNumberId, message) {
  const from = whatsapp.normalizePhone(message.from);
  if (!from) return;

  const msgId = message.id;
  const media =
    message.type === 'image'
      ? message.image
      : message.type === 'document'
        ? message.document
        : null;

  if (!media) {
    const text = (message.text?.body || '').trim().toLowerCase();
    if (text) {
      await whatsapp.sendText(
        from,
        `👋 Welcome to ${shop.name}!\nSend me your files (PDF, Word, PPT, Excel, JPG, PNG) and I will send you a link to set your print options.`,
        phoneNumberId
      );
    }
    return;
  }

  const mimeType = media.mime_type || '';
  const originalName =
    message.type === 'document' && media.filename
      ? media.filename
      : `whatsapp_${Date.now()}.${whatsapp.extFromMime(mimeType)}`;

  if (!isSupportedFileType(originalName)) {
    await whatsapp.sendText(
      from,
      `Sorry, I can't print "${originalName}" (${mimeType || 'unknown type'}). Please send PDF, Word, PPT, Excel, JPG or PNG.`,
      phoneNumberId
    );
    return;
  }

  let session = await prisma.whatsAppSession.findFirst({
    where: { shopId: shop.id, customerPhone: from, status: 'NEW' },
    orderBy: { createdAt: 'desc' },
  });

  if (!session) {
    session = await prisma.whatsAppSession.create({
      data: {
        token: crypto.randomBytes(16).toString('hex'),
        shopId: shop.id,
        customerPhone: from,
        customerName: message.contacts?.[0]?.profile?.name || null,
        files: [],
        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
      },
    });
  }

  const currentFiles = session.files || [];
  if (currentFiles.some((f) => f.messageId === msgId)) {
    return; // duplicate delivery
  }

  const destDir = path.join(UPLOAD_DIR, 'whatsapp', session.token);
  try {
    const downloaded = await whatsapp.downloadMedia(media.id, destDir, originalName);
    const updatedFiles = [
      ...currentFiles,
      {
        messageId: msgId,
        originalName,
        storagePath: downloaded.path,
        fileType: getFileType(originalName),
        size: downloaded.size,
        mediaId: media.id,
      },
    ];
    await prisma.whatsAppSession.update({
      where: { id: session.id },
      data: { files: updatedFiles, customerName: message.contacts?.[0]?.profile?.name || session.customerName },
    });

    const link = `${process.env.PUBLIC_URL || 'https://patel-autoprint.onrender.com'}/s/${shop.slug}?wa=${session.token}`;
    const count = updatedFiles.length;
    await whatsapp.sendText(
      from,
      `✅ Received "${originalName}" (${count} file${count === 1 ? '' : 's'} so far).\n` +
        `When you're done sending, tap this link to set your print options:\n${link}`,
      phoneNumberId
    );
  } catch (err) {
    console.error('WhatsApp media download error:', err.message);
    await whatsapp.sendText(from, 'Something went wrong receiving that file. Please try again.', phoneNumberId);
  }
}

async function handleWhatsAppWebhook(body) {
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const value = change.value || {};
      const messages = value.messages || [];
      if (messages.length === 0) continue;

      const metaPhone = value.metadata?.display_phone_number || '';
      const phoneNumberId = value.metadata?.phone_number_id || '';
      const shop = await prisma.shop.findFirst({
        where: { whatsappNumber: whatsapp.normalizePhone(metaPhone) },
      });

      if (!shop) {
        console.warn(`WhatsApp: no shop configured for number ${metaPhone}`);
        continue;
      }

      for (const message of messages) {
        try {
          await handleWhatsAppMessage(shop, phoneNumberId, message);
        } catch (err) {
          console.error('WhatsApp message error:', err.message);
        }
      }
    }
  }
}

// Webhook verification (Meta GET on setup)
app.get('/api/whatsapp/webhook', (req, res) => {
  const mode = req.query['hub.mode'];
  const token = req.query['hub.verify_token'];
  const challenge = req.query['hub.challenge'];
  if (mode === 'subscribe' && token === (process.env.WHATSAPP_VERIFY_TOKEN || '')) {
    return res.status(200).send(challenge);
  }
  res.sendStatus(403);
});

// Inbound message delivery from Meta
app.post('/api/whatsapp/webhook', async (req, res) => {
  const appSecret = process.env.WHATSAPP_APP_SECRET;
  if (appSecret) {
    const sig = req.get('X-Hub-Signature-256') || '';
    const hmac = crypto.createHmac('sha256', appSecret).update(JSON.stringify(req.body)).digest('hex');
    if (sig !== `sha256=${hmac}`) {
      console.warn('WhatsApp webhook: signature mismatch, ignoring');
      return res.sendStatus(200);
    }
  }

  try {
    await handleWhatsAppWebhook(req.body);
  } catch (err) {
    console.error('WhatsApp webhook processing error:', err.message);
  }
  res.sendStatus(200);
});

// Claim a WhatsApp job from the portal (?wa=<token>): creates the order
// and reuses the same analyze pipeline as a normal portal upload.
app.post('/api/guest/whatsapp/:token/claim', asyncHandler(async (req, res) => {
  const session = await prisma.whatsAppSession.findUnique({ where: { token: req.params.token } });
  if (!session) throw new AppError('WhatsApp job not found', 404, 'WA_SESSION_NOT_FOUND');
  if (session.status !== 'NEW') {
    throw new AppError('This WhatsApp job has already been used. Please send your files again.', 409, 'WA_SESSION_USED');
  }
  if (session.expiresAt < new Date()) {
    await prisma.whatsAppSession.update({ where: { id: session.id }, data: { status: 'EXPIRED' } });
    throw new AppError('This WhatsApp job has expired. Please send your files again.', 410, 'WA_SESSION_EXPIRED');
  }

  const sessionFiles = session.files || [];
  if (sessionFiles.length === 0) {
    throw new AppError('No files found in this WhatsApp job', 400, 'WA_NO_FILES');
  }

  const shopId = session.shopId;
  let customer = await prisma.customer.findFirst({
    where: { shopId, phone: session.customerPhone },
  });
  if (!customer) {
    customer = await prisma.customer.create({
      data: {
        shopId,
        name: session.customerName || 'WhatsApp Customer',
        phone: session.customerPhone,
      },
    });
  }

  const token = await getNextToken(shopId);
  const order = await prisma.order.create({
    data: {
      shopId,
      token,
      customerId: customer.id,
      notes: 'Received via WhatsApp',
    },
  });

  let created = 0;
  for (const file of sessionFiles) {
    if (!fs.existsSync(file.storagePath)) continue;
    const fileType = getFileType(file.originalName);
    const analysis = await analyzeFile(file.storagePath, fileType);

    const defaultSettings = {
      paperSize: analysis.suggestedPaperSize || 'A4',
      orientation: analysis.orientation || 'auto',
      colorMode: isImageFileType({ fileType }) ? 'color' : 'bw',
      printStyle: 'single',
      copies: 1,
      pageRange: 'all',
      pagesPerSheet: 1,
      sections: [],
    };

    await prisma.orderFile.create({
      data: {
        orderId: order.id,
        originalName: file.originalName,
        storagePath: file.storagePath,
        fileType,
        size: file.size,
        pageCount: analysis.pageCount,
        colorPageCount: analysis.colorPageCount,
        orientation: analysis.orientation || 'portrait',
        settings: defaultSettings,
        shopId,
      },
    });
    created++;
  }

  if (created === 0) {
    throw new AppError('Could not read the received files. Please send them again.', 400, 'WA_FILES_MISSING');
  }

  await prisma.whatsAppSession.update({
    where: { id: session.id },
    data: { status: 'CLAIMED', claimedAt: new Date() },
  });

  const orderWithFiles = await prisma.order.findUnique({
    where: { id: order.id },
    include: { files: true, customer: true },
  });

  res.json({
    success: true,
    data: {
      order: orderWithFiles,
      customerPhone: session.customerPhone,
      customerName: session.customerName,
    },
  });
}));

// ============================================
// ADMIN ROUTES
// ============================================

