+// Process a single inbound WhatsApp message: download files into a session,
+// then reply with the portal link that pre-loads those files.
+async function handleWhatsAppMessage(shop, phoneNumberId, message) {
+  const from = whatsapp.normalizePhone(message.from);
+  if (!from) return;
+
+  const msgId = message.id;
+  const media =
+    message.type === 'image'
+      ? message.image
+      : message.type === 'document'
+        ? message.document
+        : null;
+
+  if (!media) {
+    const text = (message.text?.body || '').trim().toLowerCase();
+    if (text) {
+      await whatsapp.sendText(
+        from,
+        `👋 Welcome to ${shop.name}!\nSend me your files (PDF, Word, PPT, Excel, JPG, PNG) and I will send you a link to set your print options.`,
+        phoneNumberId
+      );
+    }
+    return;
+  }
+
+  const mimeType = media.mime_type || '';
+  const originalName =
+    message.type === 'document' && media.filename
+      ? media.filename
+      : `whatsapp_${Date.now()}.${whatsapp.extFromMime(mimeType)}`;
+
+  if (!isSupportedFileType(originalName)) {
+    await whatsapp.sendText(
+      from,
+      `Sorry, I can't print "${originalName}" (${mimeType || 'unknown type'}). Please send PDF, Word, PPT, Excel, JPG or PNG.`,
+      phoneNumberId
+    );
+    return;
+  }
+
+  let session = await prisma.whatsAppSession.findFirst({
+    where: { shopId: shop.id, customerPhone: from, status: 'NEW' },
+    orderBy: { createdAt: 'desc' },
+  });
+
+  if (!session) {
+    session = await prisma.whatsAppSession.create({
+      data: {
+        token: crypto.randomBytes(16).toString('hex'),
+        shopId: shop.id,
+        customerPhone: from,
+        customerName: message.contacts?.[0]?.profile?.name || null,
+        files: [],
+        expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000),
+      },
+    });
+  }
+
+  const currentFiles = session.files || [];
+  if (currentFiles.some((f) => f.messageId === msgId)) {
+    return; // duplicate delivery
+  }
+
+  const destDir = path.join(UPLOAD_DIR, 'whatsapp', session.token);
+  try {
+    const downloaded = await whatsapp.downloadMedia(media.id, destDir, originalName);
+    const updatedFiles = [
+      ...currentFiles,
+      {
+        messageId: msgId,
+        originalName,
+        storagePath: downloaded.path,
+        fileType: getFileType(originalName),
+        size: downloaded.size,
+        mediaId: media.id,
+      },
+    ];
+    await prisma.whatsAppSession.update({
+      where: { id: session.id },
+      data: { files: updatedFiles, customerName: message.contacts?.[0]?.profile?.name || session.customerName },
+    });
+
+    const link = `${process.env.PUBLIC_URL || 'https://patel-autoprint.onrender.com'}/s/${shop.slug}?wa=${session.token}`;
+    const count = updatedFiles.length;
+    await whatsapp.sendText(
+      from,
+      `✅ Received "${originalName}" (${count} file${count === 1 ? '' : 's'} so far).\n` +
+        `When you're done sending, tap this link to set your print options:\n${link}`,
+      phoneNumberId
+    );
+  } catch (err) {
+    console.error('WhatsApp media download error:', err.message);
+    await whatsapp.sendText(from, 'Something went wrong receiving that file. Please try again.', phoneNumberId);
+  }
+}
