Let me implement. Add to CustomerPortal:
- import useSearchParams.
- state: `const [searchParams, setSearchParams] = useSearchParams();` inside component. But `useParams` already imported. Add `useSearchParams`.
- waToken = searchParams.get('wa').
- `const [waError, setWaError] = useState(''); const [waSource, setWaSource] = useState(false);`
- useEffect on mount (once) when waToken && !uploadedOrder:
```js
useEffect(() => {
  if (!waToken) return;
  let cancelled = false;
  setLoading(true);
  api.post(`/guest/whatsapp/${waToken}/claim`)
    .then((result) => {
      if (cancelled) return;
      if (result.success) {
        setUploadedOrder(result.data.order);
        setCustomerInfo((prev) => ({ ...prev, phone: result.data.customerPhone || '', name: result.data.customerName || '' }));
        setWaSource(true);
        setActiveStep(1);
        toast.success('WhatsApp files received!');
      }
    })
    .catch((err) => {
      if (cancelled) return;
      setWaError(err?.message || 'This WhatsApp link is invalid or already used.');
    })
    .finally(() => {
      if (!cancelled) setLoading(false);
      setSearchParams({}, { replace: true });
    });
  return () => { cancelled = true; };
}, [waToken]);
```
