const { PrismaClient } = require('C:/Users/mayank/Documents/New OpenCode Project/patel-autoprint/backend/node_modules/@prisma/client');
const fs = require('fs');
const path = require('path');

const BASE = 'http://localhost:5000';
const prisma = new PrismaClient();

// Minimal valid PDF
const pdf = Buffer.from(
  '%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Kids[3 0 R]/Count 1>>endobj\n3 0 obj<</Type/Page/Parent 2 0 R/MediaBox[0 0 595 842]/Contents 4 0 R>>endobj\n4 0 obj<</Length 44>>stream\nBT /F1 12 Tf 72 720 Td (Hello WhatsApp) Tj ET\nendstream\nendobj\nxref\n0 5\n0000000000 65535 f \n0000000009 00000 n \n0000000058 00000 n \n0000000133 00000 n \n0000000247 00000 n \ntrailer<</Size 5/Root 1 0 R>>\nstartxref\n361\n%%EOF\n'
);

async function main() {
  let shop = await prisma.shop.findFirst({ where: { agentKey: { not: null } } });
  if (!shop) {
    shop = await prisma.shop.create({ data: { name: 'WA Test Shop', agentKey: 'WA-TEST-0001-0001' } });
    await prisma.user.create({ data: { shopId: shop.id, email: 'wa@test.local', passwordHash: 'x', name: 'WA Test', role: 'OWNER' } });
    await prisma.subscription.create({ data: { shopId: shop.id, plan: 'PRO', status: 'ACTIVE', price: 0, maxPrinters: 2 } });
  }
  console.log('shop:', shop.name, shop.agentKey);

  // key-login
  const login = await (await fetch(`${BASE}/api/agent/key-login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ agentKey: shop.agentKey }),
  })).json();
  if (!login.success) throw new Error('key-login failed: ' + JSON.stringify(login));
  const token = login.data.token;
  console.log('login ok, shopId=', login.data.user.shopId);

  // upload files
  const filePath = path.join('C:/Users/mayank/AppData/Local/Temp/opencode', 'wa-test-doc.pdf');
  fs.writeFileSync(filePath, pdf);
  const fd = new FormData();
  fd.append('customerPhone', '919876543210');
  fd.append('customerName', 'WhatsApp Tester');
  fd.append('files', new Blob([fs.readFileSync(filePath)], { type: 'application/pdf' }), 'wa-test-doc.pdf');

  const inbox = await (await fetch(`${BASE}/api/agent/whatsapp/inbox`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: fd,
  })).json();
  if (!inbox.success) throw new Error('inbox failed: ' + JSON.stringify(inbox));
  console.log('inbox ok:', JSON.stringify(inbox.data));

  // claim
  const claim = await (await fetch(`${BASE}/api/guest/whatsapp/${inbox.data.token}/claim`, {
    method: 'POST',
  })).json();
  if (!claim.success) throw new Error('claim failed: ' + JSON.stringify(claim));
  console.log('claim ok: order token=', claim.data.order.token, 'files=', claim.data.order.files.length);

  // re-claim should 409
  const claim2 = await (await fetch(`${BASE}/api/guest/whatsapp/${inbox.data.token}/claim`, { method: 'POST' })).json();
  console.log('re-claim success flag (expect false):', claim2.success);

  await prisma.$disconnect();
}

main().catch((e) => { console.error(e); process.exit(1); });

