const { makeWASocket, useMultiFileAuthState, DisconnectReason, getContentType } = require('@whiskeysockets/baileys');
const QRCode = require('qrcode');
const pino = require('pino');

const ALLOWED_EXT = /\.(pdf|doc|docx|ppt|pptx|xls|xlsx|jpg|jpeg|png)$/i;

class WhatsAppClient extends EventEmitter {
  constructor() {
    super();
    this.socket = null;
    this.connected = false;
    this.phone = null;
    this.state = 'idle'; // idle, connecting, waiting-for-qr, connected, closed, error
    this.qr = null; // data URL
    this.error = null;
    this.logEntries = [];
    this.recentIds = new Set();
    this.tmpDir = null;
    this.lastLink = null; // per-conversation
  }
  ...
}
```

Key methods:
- `start({ apiUrl, token, publicUrl })` — set creds, init socket, resume session if exists.
- `logout()` — close socket + clear session dir.
- `getStatus()` — snapshot.
- Events: 'status' with snapshot.

The Baileys flow:
```
const sessionDir = path.join(app.getPath('userData'), 'whatsapp-session');
const { state, saveCreds } = await useMultiFileAuthState(sessionDir);
this.socket = makeWASocket({
  logger: pino({ level: 'silent' }),
  printQRInTerminal: false,
  auth: state,
  browser: ['Patel AutoPrint', 'Chrome', '1.0'],
  syncFullHistory: false,
  markOnlineOnConnect: false,
});
socket.ev.on('creds.update', saveCreds);
socket.ev.on('connection.update', async (update) => {
  const { connection, lastDisconnect, qr } = update;
  if (qr) {
    // generate data URL
    const dataUrl = await QRCode.toDataURL(qr);
    this.setState('waiting-for-qr', { qr: dataUrl });
  }
  if (connection === 'open') {
    this.connected = true;
    this.phone = this.socket.user?.id?.split(':')[0] || null;
    this.setState('connected');
  }
  if (connection === 'close') {
    const statusCode = lastDisconnect?.error?.output?.statusCode;
    if (statusCode === DisconnectReason.loggedOut) {
      this.setState('idle', { error: 'Logged out' });
      // clear session dir
    } else {
      this.setState('closed', { error: `Disconnected (${statusCode})` });
      // retry after delay
    }
  }
});
socket.ev.on('messages.upsert', async ({ messages, type }) => {
  if (type !== 'notify') return;
  for (const msg of messages) {
    await this.handleMessage(msg);
  }
});
```

