            >
              New Order
            </Button>
          )}
        </Container>
      </Box>
    </Box>
  );
}

function pageCountLabel(order) {
  const files = order?.files || [];
  const pages = files.reduce((sum, f) => sum + (f.pageCount || 0), 0);
  return pages;
}

