function PdfPageThumb({ doc, pageNum, colorMode }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    let cancelled = false;
    let renderTask = null;
    doc
      .getPage(pageNum)
      .then((page) => {
        if (cancelled) return;
        const canvas = canvasRef.current;
        if (!canvas) return;
        const vp1 = page.getViewport({ scale: 1 });
        const scale = 220 / vp1.width;
        const vp = page.getViewport({ scale });
        canvas.width = Math.floor(vp.width);
        canvas.height = Math.floor(vp.height);
        renderTask = page.render({ canvasContext: canvas.getContext('2d'), viewport: vp });
        return renderTask.promise;
      })
      .catch(() => {});
    return () => {
      cancelled = true;
      if (renderTask) {
        try {
          renderTask.cancel();
        } catch {
          // ignore
        }
      }
    };
  }, [doc, pageNum]);

  return (
    <canvas
      ref={canvasRef}
      style={{
        width: '100%',
        height: '100%',
        objectFit: 'contain',
        filter: colorMode === 'bw' ? 'grayscale(1)' : 'none',
      }}
    />
  );
}

function PdfPages({ url, pagesToShow, colorMode }) {
