  if (!doc) {
    return (
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          width: '100%',
          height: '100%',
          bgcolor: '#fff',
        }}
      >
        <CircularProgress size={18} sx={{ color: '#9e9e9e' }} />
      </Box>
    );
  }

  return (
    <>
      {Array.from({ length: pagesToShow }).map((_, i) => {
        const pageNum = i + 1;
        if (pageNum > doc.numPages) return null;
        return (
          <Box
