function useImageDims(urls) {
  const [dims, setDims] = useState({});
  useEffect(() => {
    let cancelled = false;
    const next = {};
    const pending = urls.filter(Boolean);
    let done = 0;
    if (pending.length === 0) {
      setDims({});
      return;
    }
    pending.forEach((url) => {
      const img = new Image();
      img.onload = () => {
        if (cancelled) return;
        next[url] = { w: img.naturalWidth, h: img.naturalHeight };
        done += 1;
        if (done === pending.length) setDims({ ...next });
      };
      img.onerror = () => {
        done += 1;
        if (done === pending.length) setDims({ ...next });
      };
      img.src = url;
    });
    return () => { cancelled = true; };
  }, [urls.join('|')]);
  return dims;
}
```

