  });
  if (!order) throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');

  const breakdowns = [];
  let grandTotal = 0;

  const imageFiles = order.files.filter((f) => isImageFileType(f));
  const docFiles = order.files.filter((f) => !isImageFileType(f));

