  if (imageFiles.length > 0) {
    const s = imageFiles[0].settings || {};
    const nUp = s.pagesPerSheet || 1;
    const colorMode = imageFiles.some((f) => (f.settings?.colorMode || 'color') === 'color') ? 'color' : 'bw';
