        let secColorPages = 0;
        if (secColorMode === 'color') secColorPages = secPages;
        else if (secColorMode === 'auto' && file.pageCount > 0) {
          secColorPages = Math.round(secPages * (file.colorPageCount / file.pageCount));
        }
