function routeJobForMode(mode, printers, paperSize) {
  const isBw = mode === 'bw';
  let candidates = printers.filter(p => (isBw ? !p.colorSupport : p.colorSupport) && p.status === 'ONLINE');

  if (candidates.length === 0) {
