/**
 * Backend API Test Script for Razorpay Payment Integration
 * 
 * Run this after:
 * 1. Setting PAYMENT_ENCRYPTION_KEY in Render dashboard
 * 2. Backend is deployed
 * 3. You have a shop created with agent key
 * 
 * Usage:
 * node test-backend-apis.js
 */

const API_BASE = 'https://patel-autoprint.onrender.com';
const SHOP_SLUG = 'test-shop'; // Change to your shop slug
const AGENT_KEY = 'YOUR_AGENT_KEY'; // Get from superadmin

async function request(method, path, body, token) {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers['Authorization'] = `Bearer ${token}`;

  const res = await fetch(`${API_BASE}${path}`, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined
  });

  const data = await res.json();
  console.log(`${method} ${path} -> ${res.status}`);
  console.log(JSON.stringify(data, null, 2));
  console.log('---');
  return { status: res.status, data };
}

async function testPaymentFlow() {
  console.log('=== Testing Payment Gateway APIs ===\n');

  // 1. First, activate a shop to get a token
  // (You need to do this manually in the desktop app or via /api/agent/activate)
  console.log('Step 1: Get shop auth token');
  console.log('Run this in desktop app or:');
  console.log(`POST ${API_BASE}/api/agent/activate`);
  console.log(`Body: { "agentKey": "${AGENT_KEY}", "apiUrl": "${API_BASE}" }`);
  console.log('Save the returned token as SHOP_TOKEN\n');

  // For now, we'll test public endpoints that don't need auth

  // 2. Test public payment config (no auth needed)
  console.log('Step 2: Get public payment config');
  await request('GET', `/api/guest/shop/${SHOP_SLUG}/payment-config`);

  // 3. Test public shop info
  console.log('Step 3: Get public shop info');
  await request('GET', `/api/guest/shop/${SHOP_SLUG}`);

  console.log('\n=== Authenticated Tests (require SHOP_TOKEN) ===');
  console.log('Set SHOP_TOKEN variable after shop activation\n');

  // These need a valid shop token
  // const SHOP_TOKEN = 'your-token-here';
  // await request('GET', '/api/settings/payment-gateways', null, SHOP_TOKEN);
  // await request('PUT', '/api/settings/payment-gateways/razorpay', {
  //   enabled: true,
  //   mode: 'test',
  //   keyId: 'rzp_test_xxx',
  //   keySecret: 'your_test_secret',
  //   webhookSecret: 'your_webhook_secret'
  // }, SHOP_TOKEN);
  // await request('POST', '/api/settings/payment-gateways/razorpay/test', {
  //   keyId: 'rzp_test_xxx',
  //   keySecret: 'your_test_secret'
  // }, SHOP_TOKEN);

  console.log('To test authenticated endpoints:');
  console.log('1. Activate shop in desktop app');
  console.log('2. Copy token from app storage or logs');
  console.log('3. Uncomment authenticated tests above');
  console.log('4. Add your Razorpay test credentials');
}

// Test webhook endpoint (public, no auth)
async function testWebhook() {
  console.log('\n=== Testing Webhook Endpoint ===');
  console.log('Webhook URL format:');
  console.log(`${API_BASE}/api/webhooks/razorpay/SHOP_ID`);
  console.log('\nTo test webhook locally with ngrok:');
  console.log('1. ngrok http 5000');
  console.log('2. Use ngrok URL in Razorpay dashboard webhook settings');
  console.log('3. Or use Razorpay test webhook CLI tool');
}

// Test payment initiation (requires order)
async function testPaymentInitiation() {
  console.log('\n=== Testing Payment Initiation ===');
  console.log('Requires:');
  console.log('1. Shop with Razorpay configured');
  console.log('2. Order in PENDING status');
  console.log('3. POST /api/guest/orders/ORDER_ID/payment/initiate');
  console.log('   Body: { "method": "razorpay" }');
  console.log('Returns: { orderId, amount, keyId, upiIntent: true }');
}

testPaymentFlow();
testWebhook();
testPaymentInitiation();

