          <img src={upiQrUrl} alt="UPI QR Code" style={{ width: 180, height: 180, objectFit: 'contain' }} />
          <Typography variant="caption" display="block" color="text.secondary">Scan to pay</Typography>
        </Box>
      )}
    </Box>
