  if (this.recentIds.has(dedupeKey)) { this.log('debug', 'skip: dedupe'); return; }
  this.recentIds.add(dedupeKey);
  if (this.recentIds.size > 2000) {
    const first = this.recentIds.values().next().value;
    this.recentIds.delete(first);
  }

