        settings.paperSize || 'A4',
        settings.pagesPerSheet || 1,
        settings.orientation
      ),
      copies: settings.copies || 1,
      shopId: order.shopId,
    };

    const routed = routeJob(job, printers);

    const printJob = await prisma.printJob.create({
      data: routed,
    });

    printJobs.push(printJob);
  }

