Let me implement a clean "classify downloaded file" function in both agents:

```js
function classifyFile(filePath) {
  // returns { type: 'pdf'|'office'|'image'|'unknown', ext: '...' }
  const fd = fs.openSync(filePath, 'r');
  const buf = Buffer.alloc(8);
  fs.readSync(fd, buf, 0, 8, 0);
  fs.closeSync(fd);
  if (buf.subarray(0,4).toString('latin1') === '%PDF') return { type: 'pdf', ext: 'pdf' };
  if (buf.subarray(0,2).equals(Buffer.from([0x50,0x4B])) || buf.subarray(0,2).equals(Buffer.from([0xD0,0xCF])) || buf.subarray(0,2).equals(Buffer.from([0xD0,0xCF])) ) return { type: 'office', ext: 'doc' } // zip-based office: PK
  // office legacy: D0 CF (doc/xls/ppt OLE)
  // images
  if (buf.subarray(0,2).equals(Buffer.from([0xFF,0xD8]))) return { type:'image', ext:'jpg' };
  if (buf.subarray(0,4).equals(Buffer.from([0x89,0x50,0x4E,0x47]))) return { type:'image', ext:'png' };
  if (buf.subarray(0,4).equals(Buffer.from('RIFF')) && buf.subarray(8,12) ... webp) return { type:'image', ext:'webp' };
  return { type:'unknown', ext:'bin' };
}
