const filePath = path.join(this.cacheDir, `${job.id}.${ext}`);
if (filePath !== rawPath) {
  try {
    fs.renameSync(rawPath, filePath);
  } catch {
    fs.copyFileSync(rawPath, filePath);
    fs.unlinkSync(rawPath);
  }
}

// Office files are served as originals (server can't convert on Linux);
