display.text:
const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('patelApp', {
  platform: process.platform,
  versions: {
    electron: process.versions.electron,
    chrome: process.versions.chrome,
    node: process.versions.node,
  },
  agent: {
    setCredentials: (apiUrl, token) => ipcRenderer.invoke('agent:set-credentials', { apiUrl, token }),
    clearCredentials: () => ipcRenderer.invoke('agent:clear-credentials'),
    start: () => ipcRenderer.invoke('agent:start'),
    stop: () => ipcRenderer.invoke('agent:stop'),
    getStatus: () => ipcRenderer.invoke('agent:get-status'),
    getCredentials: () => ipcRenderer.invoke('agent:get-credentials'),
    onStatus: (callback) => {
      const listener = (_e, data) => callback(data);
      ipcRenderer.on('agent:status', listener);
      return () => ipcRenderer.removeListener('agent:status', listener);
    },
    onAuthExpired: (callback) => {
      const listener = () => callback();
      ipcRenderer.on('agent:auth-expired', listener);
      return () => ipcRenderer.removeListener('agent:auth-expired', listener);
    },
  },
  printers: {
    listSystem: () => ipcRenderer.invoke('printers:list-system'),
  },
  whatsapp: {
    getStatus: () => ipcRenderer.invoke('whatsapp:get-status'),
    start: () => ipcRenderer.invoke('whatsapp:start'),
    logout: () => ipcRenderer.invoke('whatsapp:logout'),
    onStatus: (callback) => {
      const listener = (_e, data) => callback(data);
      ipcRenderer.on('whatsapp:status', listener);
      return () => ipcRenderer.removeListener('whatsapp:status', listener);
    },
  },
  updates: {
    check: () => ipcRenderer.invoke('app:check-for-updates'),
    getStatus: () => ipcRenderer.invoke('app:get-update-status'),
    install: () => ipcRenderer.invoke('app:install-update'),
    onStatus: (callback) => {
      const listener = (_e, data) => callback(data);
      ipcRenderer.on('app:update-status', listener);
      return () => ipcRenderer.removeListener('app:update-status', listener);
    },
  },
});

