display.text:
app.put('/api/guest/orders/:id/settings', asyncHandler(async (req, res) => {
  const { id } = req.params;
  const { fileId, settings } = req.body;

  const order = await prisma.order.findUnique({ where: { id } });
  if (!order) throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');

  if (fileId) {
    await prisma.orderFile.update({
      where: { id: fileId },
      data: { settings },
    });
  }

  // Recalculate total
  const files = await prisma.orderFile.findMany({ where: { orderId: id } });
  let totalPages = 0;
  let totalColorPages = 0;

  for (const file of files) {
    totalPages += file.pageCount;
    totalColorPages += file.colorPageCount;
  }

  const avgSettings = settings || { paperSize: 'A4', printStyle: 'single', copies: 1, pagesPerSheet: 1, colorMode: 'auto' };
  const pricing = calculatePrice(totalPages, totalColorPages, avgSettings, await getShopPricingConfig(order.shopId));

  await prisma.order.update({
    where: { id },
    data: { totalPrice: pricing.total },
  });

  const updatedOrder = await prisma.order.findUnique({
    where: { id },
    include: { files: true, customer: true },
  });

  res.json({ success: true, data: updatedOrder });
}));

// Rename a file in a guest order (WhatsApp names are generated, so let customers label files)
app.patch('/api/guest/orders/:id/files/:fileId', asyncHandler(async (req, res) => {
  const { id, fileId } = req.params;
  let name = typeof req.body?.name === 'string' ? req.body.name.trim() : '';
  if (!name) throw new AppError('File name is required', 400, 'NAME_REQUIRED');
  if (name.length > 120) throw new AppError('File name is too long', 400, 'NAME_TOO_LONG');

  const order = await prisma.order.findUnique({ where: { id } });
  if (!order) throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');

  const orderFile = await prisma.orderFile.findFirst({ where: { id: fileId, orderId: id } });
  if (!orderFile) throw new AppError('File not found', 404, 'FILE_NOT_FOUND');

  const ext = path.extname(orderFile.originalName);
  if (ext && !name.toLowerCase().endsWith(ext.toLowerCase())) name += ext;

