app.post('/api/guest/upload', upload.array('files', 20), asyncHandler(async (req, res) => {
  if (!req.files || req.files.length === 0) {
    throw new AppError('No files uploaded', 400, 'NO_FILES');
  }

  // Resolve the target shop from the portal link (/s/:slug) or fall back to the default shop
  const shop = await findShopByRef(req.body.shopId || req.body.shopRef || req.query.shop);
  if (!shop) throw new AppError('No shop configured', 500, 'NO_SHOP');
  const shopId = shop.id;

  let customer = null;
  if (req.body.customerPhone) {
    customer = await prisma.customer.findFirst({
      where: { shopId, phone: req.body.customerPhone },
    });
    if (!customer) {
      customer = await prisma.customer.create({
        data: {
          shopId,
          name: req.body.customerName || 'Walk-in Customer',
          phone: req.body.customerPhone,
          email: req.body.customerEmail || null,
        },
      });
    }
  }

  const token = await getNextToken(shopId);
  const order = await prisma.order.create({
    data: {
      shopId,
      token,
      customerId: customer ? customer.id : null,
      notes: req.body.notes || '',
    },
  });

  const files = [];

  // Parallel FAST analysis for all files (no color scan - instant response)
  const analyses = await Promise.all(
    req.files.map(async (file) => {
      const fileType = getFileType(file.originalname);
      const analysis = await analyzeFileFast(file.path, fileType);
      return { file, fileType, analysis };
    })
  );

  for (const { file, fileType, analysis } of analyses) {
    const defaultSettings = {
      paperSize: analysis.suggestedPaperSize || 'A4',
      orientation: analysis.orientation || 'auto',
      colorMode: 'bw',
      printStyle: 'single',
      copies: 1,
      pageRange: 'all',
      pagesPerSheet: 1,
      sections: [],
    };

    const orderFile = await prisma.orderFile.create({
      data: {
        orderId: order.id,
        originalName: file.originalname,
        storagePath: file.path,
        fileType,
        size: file.size,
        pageCount: analysis.pageCount,
        colorPageCount: analysis.colorPageCount || 0,
        orientation: analysis.orientation || 'portrait',
        settings: defaultSettings,
        shopId,
      },
    });

    files.push({ ...orderFile, analysis });
  }

  const orderWithFiles = await prisma.order.findUnique({
    where: { id: order.id },
    include: { files: true, customer: true },
  });

  // Trigger DEEP analysis in background (non-blocking)
  // This updates colorPageCount, etc. for accurate pricing later
  Promise.all(
    files.map(async ({ orderFile, analysis }) => {
      if (analysis.analysisComplete) return; // Already complete (fast path)
      try {
        const deepAnalysis = await analyzeFile(orderFile.storagePath, orderFile.fileType);
        await prisma.orderFile.update({
          where: { id: orderFile.id },
          data: {
            colorPageCount: deepAnalysis.colorPageCount,
            // Keep other fast-analysis fields (pageCount, orientation) as-is
          },
        });
      } catch (e) {
        console.error('Background deep analysis failed:', e.message);
      }
    })
  ).catch(e => console.error('Background analysis error:', e.message));

  res.json({
    success: true,
    data: orderWithFiles,
  });
}));

