app.post('/api/guest/orders/:id/confirm', asyncHandler(async (req, res) => {
  const { id } = req.params;
  const { paymentMethod } = req.body;

  const order = await prisma.order.findUnique({
    where: { id },
    include: { files: true, printJobs: true, customer: true },
  });
  if (!order) throw new AppError('Order not found', 404, 'ORDER_NOT_FOUND');

  // Idempotency: if already confirmed, return existing order (handles double-click)
  if (order.status !== 'PENDING') {
    return res.json({ success: true, data: order, message: 'Order already confirmed' });
  }

  const shop = await prisma.shop.findUnique({ where: { id: order.shopId } });
  const shopSettings = shop?.settings || {};

  // Respect the shop's accepted payment methods (empty/missing = accept all)
  const accepted = shopSettings.acceptedPaymentMethods || ALL_PAYMENT_METHODS;
  const method = paymentMethod || 'cash';
  if (!accepted.includes(method)) {
    throw new AppError('This shop does not accept this payment method', 400, 'PAYMENT_METHOD_NOT_ACCEPTED');
  }

  const printers = await prisma.printer.findMany({ where: { shopId: order.shopId } });

  // Check auto-print mode
  const printMode = shopSettings.printMode || 'admin_approval';
  const autoPrintPrinterId = shopSettings.autoPrintPrinterId || null;

  // Create print jobs - need printer NAME not ID for pdf-to-printer
  let targetPrinterName = null;
  let shouldAutoPrint = false;

  if (printMode === 'auto_print') {
    const targetPrinter = autoPrintPrinterId
      ? printers.find(p => p.id === autoPrintPrinterId)
      : null;
    // Fallback to first online printer
    targetPrinterName = targetPrinter?.name || printers.find(p => p.status === 'ONLINE')?.name || printers[0]?.name || null;

    // Only auto-print for cash payments; online payments wait for payment confirmation
    shouldAutoPrint = targetPrinterName && method === 'cash';
  }

  // Images are grouped into a single contact-sheet PDF; docs get one job per file.
  // (Printing a raw JPG/PNG as a ".pdf" makes the printer output blank pages.)
  const imageFiles = order.files.filter((f) => isImageFileType(f));
  const docFiles = order.files.filter((f) => !isImageFileType(f));

  if (imageFiles.length > 0) {
    await createContactSheetPrintJob(imageFiles, order, order.shopId, printers, targetPrinterName, targetPrinterName);
  }
  for (const file of docFiles) {
    await createPrintJobsForFile(file, order.id, order.shopId, printers, targetPrinterName, targetPrinterName);
  }

  const initialStatus = shouldAutoPrint ? 'APPROVED' : 'PENDING';
  const initialApprovedAt = shouldAutoPrint ? new Date() : null;
  const initialPaymentStatus = shouldAutoPrint ? 'PAID' : 'UNPAID';

  // Ensure deep analysis is complete & pre-generate print-ready files for PDF jobs (n-up, page ranges)
  // This runs in background so confirm response is fast
  const ensureDeepAnalysisAndPregen = async () => {
    try {
      // 1. Ensure deep analysis for files that need it
      for (const file of order.files) {
        if (file.colorPageCount === 0 && file.fileType === 'pdf' && file.pageCount > 0) {
          try {
            const deepAnalysis = await analyzeFile(file.storagePath, file.fileType);
            await prisma.orderFile.update({
              where: { id: file.id },
              data: { colorPageCount: deepAnalysis.colorPageCount },
            });
          } catch (e) {
            console.warn(`Deep analysis failed for ${file.id}:`, e.message);
          }
        }
      }

      // 2. Pre-generate print-ready files for PDF jobs that need processing (n-up, page ranges)
      for (const file of order.files) {
        if (file.fileType === 'pdf') {
          const settings = file.settings || {};
          const pagesPerSheet = settings.pagesPerSheet || 1;
          let parsedPages = null;
          try { parsedPages = JSON.parse(settings.pageRange || 'all'); } catch {}
          const pageRange = Array.isArray(parsedPages) ? parsedPages : null;

          const needsProcessing = pagesPerSheet > 1 || (pageRange && pageRange.length > 0);
          if (needsProcessing) {
            try {
              const processFile = require('./services/printProcessor').processFile;
              await processFile(file, pageRange, settings, `pregen-${file.id}`);
              console.log(`Pre-generated print-ready file for ${file.id}`);
            } catch (e) {
              console.warn(`Pre-generation failed for ${file.id}:`, e.message);
            }
          }
        }
      }
    } catch (e) {
      console.error('Background pregen outer error:', e.message);
    }
  };

  // Fire and forget - don't block confirm response
  ensureDeepAnalysisAndPregen().catch(e => console.error('Background pregen error:', e.message));

  await prisma.order.update({
    where: { id },
    data: {
      status: initialStatus,
      paymentStatus: initialPaymentStatus,
      paymentMethod: method,
      approvedAt: initialApprovedAt,
    },
  });

// If auto-print (cash only), dispatch to printer
  if (shouldAutoPrint) {
    try {
      const { processAndDispatchOrder } = require('./services/printProcessor');
      await processAndDispatchOrder(order.id, prisma);
    } catch (e) {
      console.error('Auto-print dispatch failed:', e.message);
    }
  }

  const updatedOrder = await prisma.order.findUnique({
    where: { id },
    include: { files: true, printJobs: true, customer: true },
  });

  // Broadcast new jobs to connected agents (real-time notification)
  const broadcastJobNotification = req.app.get('broadcastJobNotification');
  if (broadcastJobNotification) {
    const newJobs = updatedOrder?.printJobs?.filter(j => j.status === 'PRINTING') || [];
    for (const job of newJobs) {
      broadcastJobNotification(order.shopId, { id: job.id, orderId: job.orderId, fileId: job.fileId });
    }
  }

  res.json({ success: true, data: updatedOrder });
}));

