const fs = require('fs');
const path = require('path');

const src = fs.readFileSync(path.join(__dirname, 'index.js'), 'utf8');
const marker = 'function loadConfig()';
const idx = src.indexOf(marker);
if (idx < 0) throw new Error('marker not found');
const modSrc = src.slice(0, idx) + '\nmodule.exports = { createContactSheet, imageGrid, paperDims };\n';
const modPath = path.join(__dirname, '__cs_test_module.js');
fs.writeFileSync(modPath, modSrc);

const { createContactSheet } = require(modPath);
const { PDFDocument, PDFDict, PDFName } = require('pdf-lib');
const sharp = require('sharp');

async function countImages(pdfPath) {
  const doc = await PDFDocument.load(fs.readFileSync(pdfPath));
  const results = { pages: doc.getPageCount(), images: [] };
  for (let i = 0; i < doc.getPageCount(); i++) {
    const page = doc.getPage(i);
    const res = page.node.Resources();
    const xo = res ? res.lookup(PDFName.of('XObject'), PDFDict) : null;
    results.images.push(xo ? xo.keys().length : 0);
  }
  return results;
}

async function main() {
  const tmp = path.join(__dirname, '__cs_test');
  fs.mkdirSync(tmp, { recursive: true });
  const files = [];
  const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];
  for (let i = 0; i < 6; i++) {
    const p = path.join(tmp, `img${i}.png`);
    await sharp({ create: { width: 400, height: 300, channels: 3, background: colors[i] } }).png().toFile(p);
    files.push({ path: p, id: `f${i}` });
  }

  // Test 1: 6-up, 6 images -> 1 page with 6 images
  const out6 = await createContactSheet(files, 6, 'A4', 'test6', 'portrait');
  const r6 = await countImages(out6);
  console.log(`6-up: pages=${r6.pages} images/page=[${r6.images}] (expect pages=1, images=[6])`);

  // Test 2: 4-up, 4 images -> 1 page with 4 images
  const out4 = await createContactSheet(files.slice(0, 4), 4, 'A4', 'test4', 'portrait');
  const r4 = await countImages(out4);
  console.log(`4-up: pages=${r4.pages} images/page=[${r4.images}] (expect pages=1, images=[4])`);

  // Test 3: 1-up, 2 images -> 2 pages, 1 image each
  const out1 = await createContactSheet(files.slice(0, 2), 1, 'A4', 'test1', 'auto');
  const r1 = await countImages(out1);
  console.log(`1-up: pages=${r1.pages} images/page=[${r1.images}] (expect pages=2, images=[1,1])`);

  // Test 4: 9-up with 6 images (partial sheet) -> 1 page, 6 images
  const out9 = await createContactSheet(files, 9, 'A4', 'test9', 'portrait');
  const r9 = await countImages(out9);
  console.log(`9-up partial: pages=${r9.pages} images/page=[${r9.images}] (expect pages=1, images=[6])`);

  const ok =
    r6.pages === 1 && r6.images[0] === 6 &&
    r4.pages === 1 && r4.images[0] === 4 &&
    r1.pages === 2 && r1.images[0] === 1 && r1.images[1] === 1 &&
    r9.pages === 1 && r9.images[0] === 6;

  // Cleanup
  fs.rmSync(tmp, { recursive: true, force: true });
  const readyDir = path.join(tmp, 'print-ready');
  fs.rmSync(path.dirname(out6), { recursive: true, force: true });
  fs.unlinkSync(modPath);

  if (!ok) { console.error('TEST FAILED'); process.exit(1); }
  console.log('ALL TESTS PASSED');
}

main().catch((e) => { console.error('TEST ERROR:', e); try { fs.unlinkSync(path.join(__dirname, '__cs_test_module.js')); } catch {} process.exit(1); });

