const fs = require('fs');
const path = require('path');

const src = fs.readFileSync(path.join(__dirname, 'index.js'), 'utf8');
const idx = src.indexOf('function loadConfig()');
if (idx < 0) throw new Error('marker not found');
const modPath = path.join(__dirname, '__cs_test_module.js');
fs.writeFileSync(modPath, src.slice(0, idx) + '\nmodule.exports = { createContactSheet, imageGrid, paperDims };\n');

const { createContactSheet, imageGrid } = require(modPath);
const { PDFDocument, PDFDict, PDFName } = require('pdf-lib');
const sharp = require('sharp');

async function pageInfo(pdfPath) {
  const doc = await PDFDocument.load(fs.readFileSync(pdfPath));
  const pages = [];
  for (let i = 0; i < doc.getPageCount(); i++) {
    const p = doc.getPage(i);
    const res = p.node.Resources();
    const xo = res ? res.lookup(PDFName.of('XObject'), PDFDict) : null;
    pages.push({ w: Math.round(p.getWidth()), h: Math.round(p.getHeight()), imgs: xo ? xo.keys().length : 0 });
  }
  return pages;
}

async function main() {
  const tmp = path.join(__dirname, '__cs_test');
  fs.mkdirSync(tmp, { recursive: true });
  const files = [];
  const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];
  for (let i = 0; i < 6; i++) {
    const p = path.join(tmp, `img${i}.png`);
    // landscape 4:3 like typical photos
    await sharp({ create: { width: 800, height: 600, channels: 3, background: colors[i] } }).png().toFile(p);
    files.push({ path: p, id: `f${i}` });
  }

  let pass = true;
  const check = (name, cond, got) => {
    console.log(`${cond ? 'PASS' : 'FAIL'} ${name} -> ${JSON.stringify(got)}`);
    if (!cond) pass = false;
  };

  // 1) auto orientation 6-up => landscape A4, 1 page, 6 images (3 cols x 2 rows)
  const outAuto = await createContactSheet(files, 6, 'A4', 't_auto', 'auto');
  const pAuto = await pageInfo(outAuto);
  check('6-up auto = landscape A4 + 6 imgs', pAuto.length === 1 && pAuto[0].w > pAuto[0].h && pAuto[0].imgs === 6, pAuto);

  // 2) explicit portrait 6-up => portrait A4 (2 cols x 3 rows), 6 images
  const outP = await createContactSheet(files, 6, 'A4', 't_port', 'portrait');
  const pP = await pageInfo(outP);
  check('6-up portrait = portrait A4 + 6 imgs', pP.length === 1 && pP[0].w < pP[0].h && pP[0].imgs === 6, pP);

  // 3) explicit landscape 6-up => landscape A4
  const outL = await createContactSheet(files, 6, 'A4', 't_land', 'landscape');
  const pL = await pageInfo(outL);
  check('6-up landscape = landscape A4 + 6 imgs', pL.length === 1 && pL[0].w > pL[0].h && pL[0].imgs === 6, pL);

  // 4) grid sanity
  const g6l = imageGrid(6, 'landscape');
  const g6p = imageGrid(6, 'portrait');
  check('grid 6 landscape = 3x2', g6l.cols === 3 && g6l.rows === 2, g6l);
  check('grid 6 portrait = 2x3', g6p.cols === 2 && g6p.rows === 3, g6p);

  // 5) 1-up unchanged: 2 images => 2 pages, image-oriented pages (landscape img => landscape page)
  const out1 = await createContactSheet(files.slice(0, 2), 1, 'A4', 't_1up', 'auto');
  const p1 = await pageInfo(out1);
  check('1-up auto = 2 pages (landscape imgs => landscape pages)', p1.length === 2 && p1.every((p) => p.w > p.h && p.imgs === 1), p1);

  fs.rmSync(tmp, { recursive: true, force: true });
  fs.unlinkSync(modPath);

  if (!pass) { console.error('TEST FAILED'); process.exit(1); }
  console.log('ALL TESTS PASSED');
}

main().catch((e) => { console.error('TEST ERROR:', e); try { fs.unlinkSync(path.join(__dirname, '__cs_test_module.js')); } catch {} process.exit(1); });

