input.content:
const fs = require('fs');
const path = require('path');

const src = fs.readFileSync(path.join(__dirname, 'index.js'), 'utf8');
const idx = src.indexOf('function loadConfig()');
if (idx < 0) throw new Error('marker not found');
const modPath = path.join(__dirname, '__cs_test_module.js');
fs.writeFileSync(modPath, src.slice(0, idx) + '\nmodule.exports = { createContactSheet };\n');

const { createContactSheet } = require(modPath);
const { PDFDocument, PDFDict, PDFName } = require('pdf-lib');
const sharp = require('sharp');

async function pageInfo(pdfPath) {
  const doc = await PDFDocument.load(fs.readFileSync(pdfPath));
  const pages = [];
  for (let i = 0; i < doc.getPageCount(); i++) {
    const p = doc.getPage(i);
    const res = p.node.Resources();
    const xo = res ? res.lookup(PDFName.of('XObject'), PDFDict) : null;
    pages.push({ w: Math.round(p.getWidth()), h: Math.round(p.getHeight()), imgs: xo ? xo.keys().length : 0 });
  }
  return pages;
}

async function main() {
  const tmp = path.join(__dirname, '__cs_test');
  fs.mkdirSync(tmp, { recursive: true });
  const files = [];
  const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];
  for (let i = 0; i < 6; i++) {
    const p = path.join(tmp, `img${i}.png`);
    // 4:3 landscape, like typical photos -> must be cover-cropped in 6-up
    await sharp({ create: { width: 800, height: 600, channels: 3, background: colors[i] } }).png().toFile(p);
    files.push({ path: p, id: `f${i}` });
  }

  let pass = true;
  const check = (name, cond, got) => {
    console.log(`${cond ? 'PASS' : 'FAIL'} ${name} -> ${JSON.stringify(got)}`);
    if (!cond) pass = false;
  };

  // 6-up auto: landscape A4, 6 images
  const out = await createContactSheet(files, 6, 'A4', 't_fill', 'auto');
  const pages = await pageInfo(out);
  check('6-up auto = landscape + 6 imgs', pages.length === 1 && pages[0].w > pages[0].h && pages[0].imgs === 6, pages);

  // Content stream must contain clipping paths (W n) - one per image
  const bytes = fs.readFileSync(out).toString('latin1');
  const clipCount = (bytes.match(/W n/g) || []).length;
  check('clip paths present (cover-crop active)', clipCount >= 6, { clipCount });

  // Verify cover math: parse the content stream for image draw sizes.
  // pdf-lib writes ops uncompressed: find "q m ... W n ... W n ... cm WxH ... Do Q" style.
  // Simpler: reconstruct expected geometry here and compare with cm matrices.
  const A4LW = 841.89, A4LH = 595.28, cols = 3, rows = 2, margin = 6;
  const cellW = A4LW / cols, cellH = A4LH / rows;
  const boxW = cellW - margin * 2, boxH = cellH - margin * 2;
  const scale = Math.max(boxW / 800, boxH / 600); // cover for 800x600
  const expectW = 800 * scale, expectH = 600 * scale;
  check('cover scale makes image overflow box (gets cropped)', expectW > boxW + 1 && expectH >= boxH - 0.01, {
    drawW: Math.round(expectW), boxW: Math.round(boxW), drawH: Math.round(expectH), boxH: Math.round(boxH),
  });

  // Ensure a drawImage cm matrix with expected width appears in stream (pdf-lib emits "w 0 0 h x y cm")
  const cmRe = new RegExp(`${expectW.toFixed(2)} 0 0 ${expectH.toFixed(2)} -?\\d+(\\.\\d+)? -?\\d+(\\.\\d+)? cm`, 'g');
  const cmMatches = bytes.match(cmRe) || [];
  // tolerate formatting differences: fall back to searching for the width value
  const widthHits = bytes.split(expectW.toFixed(2)).length - 1;
  check('cover draw size found in content stream', cmMatches.length >= 6 || widthHits >= 6, {
    cmMatches: cmMatches.length, widthHits, expectW: expectW.toFixed(2),
  });

  fs.rmSync(tmp, { recursive: true, force: true });
  fs.unlinkSync(modPath);

  if (!pass) { console.error('TEST FAILED'); process.exit(1); }
  console.log('ALL TESTS PASSED');
}

main().catch((e) => { console.error('TEST ERROR:', e); try { fs.unlinkSync(path.join(__dirname, '__cs_test_module.js')); } catch {} process.exit(1); });

const fs = require('fs');
const path = require('path');

const src = fs.readFileSync(path.join(__dirname, 'index.js'), 'utf8');
const idx = src.indexOf('function loadConfig()');
if (idx < 0) throw new Error('marker not found');
const modPath = path.join(__dirname, '__cs_test_module.js');
fs.writeFileSync(modPath, src.slice(0, idx) + '\nmodule.exports = { createContactSheet };\n');

const { createContactSheet } = require(modPath);
const { PDFDocument, PDFDict, PDFName } = require('pdf-lib');
const sharp = require('sharp');

function contentStreamText(page) {
  const contents = page.node.normalizedEntries().Contents;
  if (!contents) return '';
  const streams = Array.isArray(contents) ? contents : [contents];
  let out = '';
  for (const s of streams) {
    const raw = typeof s.getContents === 'function' ? s.getContents() : null;
    if (raw) out += Buffer.from(raw).toString('latin1');
    else if (typeof s.getContentsAsString === 'function') out += s.getContentsAsString();
  }
  return out;
}

async function main() {
  const tmp = path.join(__dirname, '__cs_test');
  fs.mkdirSync(tmp, { recursive: true });
  const files = [];
  const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];
  for (let i = 0; i < 6; i++) {
    const p = path.join(tmp, `img${i}.png`);
    await sharp({ create: { width: 800, height: 600, channels: 3, background: colors[i] } }).png().toFile(p);
    files.push({ path: p, id: `f${i}` });
  }

  let pass = true;
  const check = (name, cond, got) => {
    console.log(`${cond ? 'PASS' : 'FAIL'} ${name} -> ${JSON.stringify(got)}`);
    if (!cond) pass = false;
  };

  const out = await createContactSheet(files, 6, 'A4', 't_fill', 'auto');
  const doc = await PDFDocument.load(fs.readFileSync(out));
  const page = doc.getPage(0);
  const res = page.node.Resources();
  const xo = res ? res.lookup(PDFName.of('XObject'), PDFDict) : null;
  const imgCount = xo ? xo.keys().length : 0;
  check('landscape A4, 6 images', page.getWidth() > page.getHeight() && imgCount === 6, {
    w: Math.round(page.getWidth()), h: Math.round(page.getHeight()), imgCount,
  });

  const text = contentStreamText(page);
  check('content stream readable', text.length > 100, { len: text.length });

  const clips = (text.match(/\bW\s+n\b/g) || []).length;
  check('one clip path per image (cover-crop)', clips >= 6, { clips });

  // 4:3 photo in ~1.04 cell must overflow -> drawW > boxW (cropped by clip)
  const cellW = 841.89 / 3, cellH = 595.28 / 2;
  const boxW = cellW - 12, boxH = cellH - 12;
  const scale = Math.max(boxW / 800, boxH / 600);
  const drawW = 800 * scale;
  check('cover scale overflows cell width (will be cropped)', drawW > boxW + 1, {
    drawW: Math.round(drawW), boxW: Math.round(boxW),
  });

  // The cm matrices in the stream should use the cover size (~drawW)
  const cmWidths = [...text.matchAll(/(-?\d+(?:\.\d+)?) 0 0 (-?\d+(?:\.\d+)?) /g)]
    .map((m) => parseFloat(m[1]));
