const path = require('path');
const { PDFDocument } = require('pdf-lib');
const sharp = require('sharp');

const src = fs.readFileSync(path.join(__dirname, 'index.js'), 'utf8');
const idx = src.indexOf('function loadConfig()');
if (idx < 0) throw new Error('marker not found');
const modPath = path.join(__dirname, '__test_rot_module_' + Date.now() + '.js');
fs.writeFileSync(modPath, src.slice(0, idx) + '\nmodule.exports = { createContactSheet };\n');

const { createContactSheet } = require(modPath);

async function main() {
  const tmp = path.join(__dirname, '__test_rot');
  fs.mkdirSync(tmp, { recursive: true });
  const files = [];
  for (let i = 0; i < 6; i++) {
    const p = path.join(tmp, `img${i}.png`);
    const w = i < 3 ? 800 : 600;
    const h = i < 3 ? 600 : 800;
    await sharp({ create: { width: w, height: h, channels: 3, background: '#ff0000' } }).png().toFile(p);
    files.push({ path: p, id: `f${i}` });
  }

  const out = await createContactSheet(files, 6, 'A4', 'test_rot', 'auto');
  const doc = await PDFDocument.load(fs.readFileSync(out));
  const page = doc.getPage(0);
  console.log('Page:', page.getWidth(), 'x', page.getHeight());

  const contents = page.node.normalizedEntries().Contents;
  if (contents) {
    const list = contents.asArray ? contents.asArray() : [contents];
    let full = '';
    const zlib = require('zlib');
    for (const el of list) {
      const s = doc.context.lookup(el);
      if (s && typeof s.getContents === 'function') {
        const raw = s.getContents();
        if (raw) {
          let buf = Buffer.from(raw);
          try { buf = zlib.inflateSync(buf); } catch {}
          full += buf.toString('latin1');
        }
      }
    }
    const doCount = (full.match(/ Do\n/g) || []).length;
    console.log('DrawImage (Do) ops:', doCount);
    console.log('Stream length:', full.length);
  }

  fs.rmSync(tmp, { recursive: true, force: true });
  fs.unlinkSync(modPath);
  console.log('TEST OK');
}

main().catch(e => { console.error(e); process.exit(1); });

