// Geometry test for createContactSheet (6-up, mixed orientations).
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const REPO = 'C:\\Users\\mayank\\Documents\\New OpenCode Project\\patel-autoprint';
const { PDFDocument } = require(path.join(REPO, 'agent', 'node_modules', 'pdf-lib'));

// --- slice agent/index.js (everything before loadConfig) into a temp module ---
const src = fs.readFileSync(path.join(REPO, 'agent', 'index.js'), 'utf8');
const cut = src.indexOf('function loadConfig()');
if (cut < 0) throw new Error('loadConfig not found');
const modPath = path.join(REPO, 'agent', `__geo_${Date.now()}.js`);
fs.writeFileSync(modPath, src.slice(0, cut));
const { createContactSheet } = require(modPath);

// --- minimal PNG writer (solid color, RGB 8-bit) ---
function crc32(buf) {
  let table = crc32.t;
  if (!table) {
    table = crc32.t = [];
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      table[n] = c >>> 0;
    }
  }
  let c = 0xffffffff;
  for (const b of buf) c = table[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function chunk(type, data) {
  const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
  const td = Buffer.concat([Buffer.from(type, 'latin1'), data]);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
  return Buffer.concat([len, td, crc]);
}
function makePng(file, w, h, rgb) {
  const sig = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4);
  ihdr[8] = 8; ihdr[9] = 2; // 8-bit RGB
  const row = Buffer.alloc(1 + w * 3);
  for (let x = 0; x < w; x++) { row[1 + x * 3] = rgb[0]; row[2 + x * 3] = rgb[1]; row[3 + x * 3] = rgb[2]; }
  const raw = Buffer.concat(Array.from({ length: h }, () => row));
  const idat = zlib.deflateSync(raw);
  fs.writeFileSync(file, Buffer.concat([sig, chunk('IHDR', ihdr), chunk('IDAT', idat), chunk('IEND', Buffer.alloc(0))]));
}

// --- generate 6 test images: 3 portrait 600x800, 3 landscape 800x600 ---
const imgDir = path.join(REPO, 'agent', '__geo_imgs');
fs.mkdirSync(imgDir, { recursive: true });
const files = [];
for (let i = 0; i < 3; i++) {
  const p = path.join(imgDir, `p${i}.png`); makePng(p, 600, 800, [40, 90, 200]);
  files.push({ path: p });
  const l = path.join(imgDir, `l${i}.png`); makePng(l, 800, 600, [200, 60, 40]);
  files.push({ path: l });
}

(async () => {
  const out = await createContactSheet(files, 6, 'A4', 'geotest', 'auto');
  const doc = await PDFDocument.load(fs.readFileSync(out));
  const page = doc.getPage(0);
  console.log('page:', page.getWidth(), 'x', page.getHeight());

  // extract content stream (inflate if Flate-compressed)
  const contents = page.node.normalizedEntries().Contents.asArray();
  let text = '';
  for (const ref of contents) {
    const stream = doc.context.lookup(ref);
    const bytes = stream.getContents();
    try { text += zlib.inflateSync(Buffer.from(bytes)).toString('latin1'); }
    catch { text += Buffer.from(bytes).toString('latin1'); }
  }
  fs.writeFileSync(path.join(imgDir, 'stream.txt'), text);
  console.log('stream length:', text.length);
  console.log(text.replace(/\n/g, ' | ').slice(0, 3000));

  fs.unlinkSync(modPath);
})().catch((e) => { console.error(e); try { fs.unlinkSync(modPath); } catch {} process.exit(1); });

