(async () => {
  const out = await createContactSheet(files, 6, 'A4', 'geotest', 'auto');
  const doc = await PDFDocument.load(fs.readFileSync(out));
  const page = doc.getPage(0);
  const pw = page.getWidth(), ph = page.getHeight();
  console.log('page:', pw, 'x', ph);

  // extract content stream (inflate if Flate-compressed)
  const contents = page.node.normalizedEntries().Contents.asArray();
  let text = '';
  for (const ref of contents) {
    const stream = doc.context.lookup(ref);
    const bytes = stream.getContents();
    try { text += zlib.inflateSync(Buffer.from(bytes)).toString('latin1'); }
    catch { text += Buffer.from(bytes).toString('latin1'); }
  }

  // Parse: clip block "q x0 y0 m ... h W n q" + "1 0 0 1 tx ty cm" +
  // rotation cm + scale cm + "/Image Do"
  const re = /q\s+([\d.-]+)\s+([\d.-]+)\s+m\s+[\d.-]+\s+[\d.-]+\s+l\s+[\d.-]+\s+[\d.-]+\s+l\s+[\d.-]+\s+[\d.-]+\s+l\s+h\s+W\s+n\s+q\s+1\s+0\s+0\s+1\s+([\d.-]+)\s+([\d.-]+)\s+cm\s+([\d.eE+-\s]+?)\s+cm\s+([\d.-]+)\s+0\s+0\s+([\d.-]+)\s+0\s+0\s+cm[\s\S]*?\/Image-\d+\s+Do/g;
  const ops = [];
  let m;
  while ((m = re.exec(text)) !== null) {
    const rot = m[5].trim().split(/\s+/).map(Number);
    ops.push({
      clip: { x0: +m[1], y0: +m[2] },
      tx: +m[3], ty: +m[4],
      rot,
      sw: +m[6], sh: +m[7],
    });
  }
  console.log('image ops found:', ops.length);

  const cols = 3, rows = 2;
  const cellW = pw / cols, cellH = ph / rows;
  const EPS = 0.02;
  let pass = true;
  const fail = (msg) => { pass = false; console.log('FAIL:', msg); };

  if (ops.length !== 6) fail(`expected 6 image ops, got ${ops.length}`);

  ops.forEach((op, j) => {
    const col = j % cols, row = Math.floor(j / cols);
    const cellCx = col * cellW + cellW / 2;
    const cellCy = ph - (row + 1) * cellH + cellH / 2;
    const rotated = op.rot[1] !== 0; // [0 1 -1 0 0 0] for 90°
    // footprint after rotation: identity → (sw, sh); 90° → (sh, sw)
    const fw = rotated ? op.sh : op.sw;
    const fh = rotated ? op.sw : op.sh;
    const rx0 = rotated ? op.tx - op.sh : op.tx;
    const rx1 = rx0 + fw;
    const ry0 = rotated ? op.ty : op.ty;
    const ry1 = ry0 + fh;
    const cx = (rx0 + rx1) / 2, cy = (ry0 + ry1) / 2;
    const kind = rotated ? 'rot90' : 'upright';
    console.log(`img${j} ${kind} rect=(${rx0.toFixed(2)},${ry0.toFixed(2)})-(${rx1.toFixed(2)},${ry1.toFixed(2)}) center=(${cx.toFixed(2)},${cy.toFixed(2)}) cell=(${cellCx.toFixed(2)},${cellCy.toFixed(2)})`);

    if (Math.abs(cx - cellCx) > EPS || Math.abs(cy - cellCy) > EPS)
      fail(`img${j}: not centered (off by ${(cx - cellCx).toFixed(2)}, ${(cy - cellCy).toFixed(2)})`);
    // must sit inside clip box (clipX = col*cellW + 2, extends cellW-4)
    const clipX0 = op.clip.x0, clipY0 = op.clip.y0;
    const clipX1 = clipX0 + cellW - 4, clipY1 = clipY0 + cellH - 4;
    if (rx0 < clipX0 - EPS || rx1 > clipX1 + EPS || ry0 < clipY0 - EPS || ry1 > clipY1 + EPS)
      fail(`img${j}: overflows clip box`);
    // must fill the cell height (fit should be boxH-bound for these sizes)
    if (Math.abs(fh - (cellH - 4)) > EPS)
      fail(`img${j}: footprint height ${fh.toFixed(2)} != expected ${(cellH - 4).toFixed(2)}`);
  });

  console.log(pass && ops.length === 6 ? 'ALL_GEOMETRY_CHECKS_PASSED' : 'TEST_FAILED');
  fs.unlinkSync(modPath);
  process.exit(pass && ops.length === 6 ? 0 : 1);
})().catch((e) => { console.error(e); try { fs.unlinkSync(modPath); } catch {} process.exit(1); });

