input.newString:
const cols = 3, rows = 2;
const cellW = pw / cols, cellH = ph / rows;
const EPS = 0.02;
let pass = true;
const fail = (msg) => { pass = false; console.log('FAIL:', msg); };

if (ops.length !== 6) fail(`expected 6 image ops, got ${ops.length}`);

ops.forEach((op, j) => {
  const col = j % cols, row = Math.floor(j / cols);
  const cellCx = col * cellW + cellW / 2;
  const cellCy = ph - (row + 1) * cellH + cellH / 2;
  const rotated = op.rot[1] !== 0; // [0 1 -1 0 0 0] for 90°
  // files alternate portrait(0,2,4) / landscape(1,3,5); only landscape rotates
  const expectRot = j % 2 === 1;
  if (rotated !== expectRot) fail(`img${j}: rotated=${rotated}, expected ${expectRot}`);
  const fw = rotated ? op.sh : op.sw;
  const fh = rotated ? op.sw : op.sh;
  const rx0 = rotated ? op.tx - op.sh : op.tx;
  const rx1 = rx0 + fw;
  const ry0 = op.ty;
  const ry1 = ry0 + fh;
  const cx = (rx0 + rx1) / 2, cy = (ry0 + ry1) / 2;
  console.log(`img${j} ${rotated ? 'rot90' : 'upright'} rect=(${rx0.toFixed(2)},${ry0.toFixed(2)})-(${rx1.toFixed(2)},${ry1.toFixed(2)}) center=(${cx.toFixed(2)},${cy.toFixed(2)}) cell=(${cellCx.toFixed(2)},${cellCy.toFixed(2)})`);

  if (Math.abs(cx - cellCx) > EPS || Math.abs(cy - cellCy) > EPS)
    fail(`img${j}: not centered (off by ${(cx - cellCx).toFixed(2)}, ${(cy - cellCy).toFixed(2)})`);
  const clipX0 = op.clip.x0, clipY0 = op.clip.y0;
  const clipX1 = clipX0 + cellW - 4, clipY1 = clipY0 + cellH - 4;
  if (rx0 < clipX0 - EPS || rx1 > clipX1 + EPS || ry0 < clipY0 - EPS || ry1 > clipY1 + EPS)
    fail(`img${j}: overflows clip box`);
  if (Math.abs(fh - (cellH - 4)) > EPS)
    fail(`img${j}: footprint height ${fh.toFixed(2)} != expected ${(cellH - 4).toFixed(2)}`);
});

// --- scenario 2: 2-up explicit landscape — landscape photo must stay
// UPRIGHT (that layout was already approved as perfect) and fill the height
const out2 = await createContactSheet(files.slice(0, 2), 2, 'A4', 'geotest2', 'landscape');
const doc2 = await PDFDocument.load(fs.readFileSync(out2));
const page2 = doc2.getPage(0);
const pw2 = page2.getWidth(), ph2 = page2.getHeight();
let text2 = '';
for (const ref of page2.node.normalizedEntries().Contents.asArray()) {
  const bytes = doc2.context.lookup(ref).getContents();
  try { text2 += zlib.inflateSync(Buffer.from(bytes)).toString('latin1'); }
  catch { text2 += Buffer.from(bytes).toString('latin1'); }
}
const ops2 = [];
while ((m = re.exec(text2)) !== null) {
  ops2.push({ tx: +m[3], ty: +m[4], rot: m[5].trim().split(/\s+/).map(Number), sw: +m[6], sh: +m[7] });
}
console.log(`2-up sheet ${pw2}x${ph2}, ops: ${ops2.length}`);
if (ops2.length !== 2) fail(`2-up: expected 2 ops, got ${ops2.length}`);
ops2.forEach((op, j) => {
  const rotated = op.rot[1] !== 0;
  const fh = rotated ? op.sw : op.sh;
  const fw = rotated ? op.sh : op.sw;
  const rx0 = rotated ? op.tx - op.sh : op.tx;
  const cellCx = pw2 / 2;
  const cellCy = ph2 - (j + 0.5) * (ph2 / 2);
  const cx = rx0 + fw / 2, cy = op.ty + fh / 2;
  console.log(`2up img${j} ${rotated ? 'rot90' : 'upright'} size=${fw.toFixed(1)}x${fh.toFixed(1)} center=(${cx.toFixed(2)},${cy.toFixed(2)}) cell=(${cellCx.toFixed(2)},${cellCy.toFixed(2)})`);
  if (rotated) fail(`2-up img${j}: should NOT rotate (landscape cell fits upright better)`);
  if (j === 1 && Math.abs(fh - (ph2 / 2 - 4)) > EPS) fail(`2-up landscape img: height ${fh} should fill cell ${ph2 / 2 - 4}`);
  if (Math.abs(cx - cellCx) > EPS || Math.abs(cy - cellCy) > EPS) fail(`2-up img${j}: not centered`);
});

console.log(pass ? 'ALL_GEOMETRY_CHECKS_PASSED' : 'TEST_FAILED');
fs.unlinkSync(modPath);
process.exit(pass ? 0 : 1);

