// Report 6-up/9-up layouts for portrait/landscape/auto with typical phone photos.
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const REPO = 'C:\\Users\\mayank\\Documents\\New OpenCode Project\\patel-autoprint';
const { PDFDocument } = require(path.join(REPO, 'agent', 'node_modules', 'pdf-lib'));
const src = fs.readFileSync(path.join(REPO, 'agent', 'index.js'), 'utf8');
const cut = src.indexOf('function loadConfig()');
const modPath = path.join(REPO, 'agent', `__lay_${Date.now()}.js`);
fs.writeFileSync(modPath, src.slice(0, cut) + '\nmodule.exports = { createContactSheet };\n');
const { createContactSheet } = require(modPath);

function crc32(buf) {
  let t = crc32.t; if (!t) { t = crc32.t = []; for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } }
  let c = 0xffffffff; for (const b of buf) c = t[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0;
}
function chunk(type, data) { const l = Buffer.alloc(4); l.writeUInt32BE(data.length); const td = Buffer.concat([Buffer.from(type, 'latin1'), data]); const c = Buffer.alloc(4); c.writeUInt32BE(crc32(td)); return Buffer.concat([l, td, c]); }
function makePng(file, w, h) {
  const sig = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 2;
  const row = Buffer.alloc(1 + w * 3); row.fill(90, 1);
  const raw = Buffer.concat(Array.from({ length: h }, () => row));
  fs.writeFileSync(file, Buffer.concat([sig, chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]));
}

const dir = path.join(REPO, 'agent', '__lay_imgs');
fs.mkdirSync(dir, { recursive: true });
// typical phone photos: portrait 3:4 and a landscape 4:3
const files = [];
for (let i = 0; i < 3; i++) { const p = path.join(dir, `port${i}.png`); makePng(p, 3024, 4032); files.push({ path: p }); }
for (let i = 0; i < 3; i++) { const l = path.join(dir, `land${i}.png`); makePng(l, 4032, 3024); files.push({ path: l }); }

const re = /q\s+([\d.-]+)\s+([\d.-]+)\s+m\s+[\d.-]+\s+[\d.-]+\s+l\s+[\d.-]+\s+[\d.-]+\s+l\s+[\d.-]+\s+[\d.-]+\s+l\s+h\s+W\s+n\s+q\s+1\s+0\s+0\s+1\s+([\d.-]+)\s+([\d.-]+)\s+cm\s+([\d.eE+-\s]+?)\s+cm\s+([\d.-]+)\s+0\s+0\s+([\d.-]+)\s+0\s+0\s+cm[\s\S]*?\/Image-\d+\s+Do/g;

async function report(label, n, orient) {
  const out = await createContactSheet(files.slice(0, n), n, 'A4', `lay_${label}`, orient);
  const doc = await PDFDocument.load(fs.readFileSync(out));
  const page = doc.getPage(0);
  const pw = page.getWidth(), ph = page.getHeight();
  let text = '';
  for (const ref of page.node.normalizedEntries().Contents.asArray()) {
    const b = doc.context.lookup(ref).getContents();
    try { text += zlib.inflateSync(Buffer.from(b)).toString('latin1'); } catch { text += Buffer.from(b).toString('latin1'); }
  }
  const ops = []; let m;
  while ((m = re.exec(text)) !== null) {
    const rot = m[5].trim().split(/\s+/).map(Number);
    const rotated = rot[1] !== 0;
    const w = +m[6], h = +m[7];
    const fw = rotated ? h : w, fh = rotated ? w : h;
    const rx0 = rotated ? (+m[3]) - h : +m[3], ry0 = +m[4];
    ops.push({ x0: rx0, y0: ry0, w: fw, h: fh, rotated });
  }
  const cols = Math.ceil(Math.sqrt(ops.length * pw / ph)) || 1;
  // compute page coverage
  const minX = Math.min(...ops.map(o => o.x0)), maxX = Math.max(...ops.map(o => o.x0 + o.w));
