const { PrismaClient } = require('@prisma/client');
const p = new PrismaClient();

(async () => {
  let orders = await p.order.findMany({ where: { token: { in: [59, 60, 61, 62] } }, select: { id: true, token: true, createdAt: true } });
  if (!orders.length) orders = await p.order.findMany({ orderBy: { createdAt: 'desc' }, take: 6, select: { id: true, token: true, createdAt: true } });
