// Verify: no rotation ever; all upright + centered. Scenarios from user reports.
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const REPO = 'C:\\Users\\mayank\\Documents\\New OpenCode Project\\patel-autoprint';
const { PDFDocument } = require(path.join(REPO, 'agent', 'node_modules', 'pdf-lib'));
const src = fs.readFileSync(path.join(REPO, 'agent', 'index.js'), 'utf8');
const cut = src.indexOf('function loadConfig()');
const modPath = path.join(REPO, 'agent', `__nr_${Date.now()}.js`);
fs.writeFileSync(modPath, src.slice(0, cut) + '\nmodule.exports = { createContactSheet };\n');
const { createContactSheet } = require(modPath);

function crc32(buf) { let t = crc32.t; if (!t) { t = crc32.t = []; for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } } let c = 0xffffffff; for (const b of buf) c = t[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; }
function chunk(type, data) { const l = Buffer.alloc(4); l.writeUInt32BE(data.length); const td = Buffer.concat([Buffer.from(type, 'latin1'), data]); const c = Buffer.alloc(4); c.writeUInt32BE(crc32(td)); return Buffer.concat([l, td, c]); }
function makePng(file, w, h) { const sig = Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]); const ihdr = Buffer.alloc(13); ihdr.writeUInt32BE(w,0); ihdr.writeUInt32BE(h,4); ihdr[8]=8; ihdr[9]=2; const row = Buffer.alloc(1+w*3); row.fill(80,1); const raw = Buffer.concat(Array.from({length:h},()=>row)); fs.writeFileSync(file, Buffer.concat([sig, chunk('IHDR',ihdr), chunk('IDAT',zlib.deflateSync(raw)), chunk('IEND',Buffer.alloc(0))])); }

const dir = path.join(REPO, 'agent', '__nr_imgs');
fs.mkdirSync(dir, { recursive: true });
const land = [], port = [];
for (let i = 0; i < 6; i++) { const f = path.join(dir, `L${i}.png`); makePng(f, 4032, 3024); land.push({ path: f }); }
for (let i = 0; i < 6; i++) { const f = path.join(dir, `P${i}.png`); makePng(f, 3024, 4032); port.push({ path: f }); }

const re = /q\s+([\d.-]+)\s+([\d.-]+)\s+m\s+[\d.-]+\s+[\d.-]+\s+l\s+[\d.-]+\s+[\d.-]+\s+l\s+[\d.-]+\s+[\d.-]+\s+l\s+h\s+W\s+n\s+q\s+1\s+0\s+0\s+1\s+([\d.-]+)\s+([\d.-]+)\s+cm\s+([\d.eE+-\s]+?)\s+cm\s+([\d.-]+)\s+0\s+0\s+([\d.-]+)\s+0\s+0\s+cm[\s\S]*?\/Image-\d+\s+Do/g;

async function check(label, files, n, orient, expectW, expectH) {
  const out = await createContactSheet(files.slice(0, n), n, 'A4', `nr_${label}_${Date.now()}`, orient);
  const doc = await PDFDocument.load(fs.readFileSync(out));
  const page = doc.getPage(0);
  const pw = page.getWidth(), ph = page.getHeight();
  let text = '';
  for (const ref of page.node.normalizedEntries().Contents.asArray()) {
    const b = doc.context.lookup(ref).getContents();
    try { text += zlib.inflateSync(Buffer.from(b)).toString('latin1'); } catch { text += Buffer.from(b).toString('latin1'); }
  }
  const ops = []; let m;
  while ((m = re.exec(text)) !== null) {
    const rot = m[5].trim().split(/\s+/).map(Number);
    const rotated = Math.abs(rot[1]) > 0.01 || Math.abs(rot[0]) > 0.01;
    ops.push({ tx: +m[3], ty: +m[4], w: +m[6], h: +m[7], rotated, clipX: +m[1], clipY: +m[2] });
  }
  let pass = ops.length === n && ops.every(o => !o.rotated);
  ops.forEach((o, j) => {
    const cx = o.tx + o.w / 2, cy = o.ty + o.h / 2;
    if (Math.abs(o.w - expectW) > 1 || Math.abs(o.h - expectH) > 1) { console.log(`  img${j} size ${o.w.toFixed(0)}x${o.h.toFixed(0)} != expected ${expectW}x${expectH}`); pass = false; }
    if (o.rotated) { console.log(`  img${j} ROTATED (bad)`); pass = false; }
  });
  const minX = Math.min(...ops.map(o => o.tx)), maxX = Math.max(...ops.map(o => o.tx + o.w));
  const minY = Math.min(...ops.map(o => o.ty)), maxY = Math.max(...ops.map(o => o.ty + o.h));
  console.log(`${label}: page ${pw.toFixed(0)}x${ph.toFixed(0)} | ${ops.length} imgs ${expectW}x${expectH} upright | width fill ${((maxX-minX)/pw*100).toFixed(0)}% height fill ${((maxY-minY)/ph*100).toFixed(0)}% | ${pass ? 'PASS' : 'FAIL'}`);
  return pass;
}

(async () => {
  let ok = true;
  ok = await check('6-up LANDSCAPE sheet + landscape photos', land, 6, 'landscape', 276, 207) && ok;
  ok = await check('6-up PORTRAIT sheet + landscape photos', land, 6, 'portrait', 293, 220) && ok;
  ok = await check('6-up auto + landscape photos', land, 6, 'auto', 276, 207) && ok;
  ok = await check('6-up LANDSCAPE sheet + portrait photos', port, 6, 'landscape', 220, 294) && ok;
  ok = await check('2-up LANDSCAPE sheet + portrait photos', port, 2, 'landscape', 417, 556) && ok;
  console.log(ok ? 'ALL_PASS' : 'TEST_FAILED');
  fs.unlinkSync(modPath);
  process.exit(ok ? 0 : 1);
})().catch(e => { console.error(e); try { fs.unlinkSync(modPath); } catch {} process.exit(1); });

