const zlib = require('zlib');
const fs = require('fs');
const path = require('path');
const sharp = require(path.join(process.cwd(), '..', 'patel-autoprint', 'backend', 'node_modules', 'sharp'));
const { createContactSheet } = require(path.join(process.env.TEMP, 'opencode', 'contact_test.js'));

async function makeImgs(dir) {
  await fs.promises.mkdir(dir, { recursive: true });
  const land = path.join(dir, 'land.png'); // 800x600 landscape
  const port = path.join(dir, 'port.png'); // 600x800 portrait
  await sharp({ create: { width: 800, height: 600, channels: 3, background: { r: 200, g: 60, b: 60 } } }).png().toFile(land);
  await sharp({ create: { width: 600, height: 800, channels: 3, background: { r: 60, g: 60, b: 200 } } }).png().toFile(port);
  return { land, port };
}

function extractDraws(pdfPath) {
  const { PDFDocument } = require(path.join(process.cwd(), '..', 'patel-autoprint', 'desktop', 'node_modules', 'pdf-lib'));
  return PDFDocument.load(fs.readFileSync(pdfPath)).then((doc) => {
    const page = doc.getPage(0);
    const contents = page.node.normalizedEntries().Contents.asArray().map((r) => doc.context.lookup(r).getContents());
    const stream = zlib.inflateSync(Buffer.concat(contents)).toString('latin1');
    const draws = [];
    const re = /([-\d.]+) ([-\d.]+) ([-\d.]+) ([-\d.]+) ([-\d.]+) ([-\d.]+) cm\s*\/(Image-\d+) Do/g;
    let m;
    while ((m = re.exec(stream))) {
      const sx = Math.hypot(parseFloat(m[1]), parseFloat(m[2]));
      const sy = Math.hypot(parseFloat(m[3]), parseFloat(m[4]));
      draws.push({ w: Math.round(sx * 1000) / 1000, h: Math.round(sy * 1000) / 1000, x: Math.round(parseFloat(m[5])), y: Math.round(parseFloat(m[6])) });
    }
    return { size: [page.getWidth(), page.getHeight()], draws, stream };
  });
}

(async () => {
  const dir = path.join(process.env.TEMP, 'opencode', 'filltest');
  const { land, port } = await makeImgs(dir);
  let pass = true;
  const assert = (name, cond, extra) => { console.log(`${cond ? 'PASS' : 'FAIL'} ${name} ${extra || ''}`); if (!cond) pass = false; };

  // 1. 6-up portrait + portrait photos + fill -> images cover full cell (293x276)
  const p1 = await createContactSheet(
    [{ path: port, id: 'a' }, { path: port, id: 'b' }, { path: port, id: 'c' }, { path: port, id: 'd' }, { path: port, id: 'e' }, { path: port, id: 'f' }],
    6, 'A4', 'fill1', 'portrait', 'fill'
  );
  let r = await extractDraws(p1);
  const cellW = r.size[0] / 2, cellH = r.size[1] / 3;
  assert('fill: portrait photo covers cell width', Math.abs(r.draws[0].w - (cellW - 4)) < 1 && r.draws[0].h > cellH, `draw=${r.draws[0].w}x${r.draws[0].h} page=${r.size}`);
  assert('fill: 6 images drawn', r.draws.length === 6);

  // 2. same + fit -> 207x277 letterbox (unchanged default)
  const p2 = await createContactSheet(
    [{ path: port, id: 'a' }, { path: port, id: 'b' }, { path: port, id: 'c' }, { path: port, id: 'd' }, { path: port, id: 'e' }, { path: port, id: 'f' }],
    6, 'A4', 'fit1', 'portrait', 'fit'
  );
  r = await extractDraws(p2);
  const expW = Math.min((cellW - 4) / 600, (cellH - 4) / 800) * 600;
  assert('fit: letterbox (unchanged)', Math.abs(r.draws[0].w - expW) < 1, `draw=${r.draws[0].w}x${r.draws[0].h} expectedW=${expW}`);

  // 3. default (no photoFit arg) behaves as fit
  const p3 = await createContactSheet(
    [{ path: port, id: 'a' }, { path: port, id: 'b' }, { path: port, id: 'c' }, { path: port, id: 'd' }, { path: port, id: 'e' }, { path: port, id: 'f' }],
    6, 'A4', 'fitdef', 'portrait'
  );
  r = await extractDraws(p3);
  assert('default == fit', Math.abs(r.draws[0].w - expW) < 1, `draw=${r.draws[0].w}x${r.draws[0].h}`);

  // 4. 6-up landscape + landscape photos + fill -> full cell 293x297
  const p4 = await createContactSheet(
    [{ path: land, id: 'a' }, { path: land, id: 'b' }, { path: land, id: 'c' }, { path: land, id: 'd' }, { path: land, id: 'e' }, { path: land, id: 'f' }],
    6, 'A4', 'fillL', 'landscape', 'fill'
  );
  r = await extractDraws(p4);
  const lcellW = r.size[0] / 3, lcellH = r.size[1] / 2;
  assert('fill: landscape photo covers cell fully', Math.abs(r.draws[0].w - (lcellW - 4)) < 1 && Math.abs(r.draws[0].h - (lcellH - 4)) < 1, `draw=${r.draws[0].w}x${r.draws[0].h} cell=${lcellW}x${lcellH}`);

  // 5. upright never rotated: fill sheet of landscape photos is still not rotated (w>h)
  assert('fill: no rotation (w>h)', r.draws.every((d) => d.w >= d.h));

  console.log(pass ? 'ALL_PASS' : 'FAILED');
  process.exit(pass ? 0 : 1);
})().catch((e) => { console.error(e); process.exit(1); });

