input.newString:
const draws = [];
// mini interpreter: track CTM through q/Q/cm, record image placements
const mul = (m, n) => ([
  m[0] * n[0] + m[2] * n[1], m[1] * n[0] + m[3] * n[1],
  m[0] * n[2] + m[2] * n[3], m[1] * n[2] + m[3] * n[3],
  m[0] * n[4] + m[2] * n[5] + m[4], m[1] * n[4] + m[3] * n[5] + m[5],
]);
const stack = [];
let ctm = [1, 0, 0, 1, 0, 0];
const toks = contents.split(/\s+/).filter(Boolean);
for (let i = 0; i < toks.length; i++) {
  if (toks[i] === 'q') { stack.push([...ctm]); }
  else if (toks[i] === 'Q') { ctm = stack.pop() || [1, 0, 0, 1, 0, 0]; }
  else if (toks[i] === 'cm') {
    const n = toks.slice(i - 6, i).map(parseFloat);
    if (n.length === 6 && n.every((v) => Number.isFinite(v))) ctm = mul(ctm, n);
  }
  else if (/^\/Image-\d+$/.test(toks[i]) && toks[i + 1] === 'Do') {
    const sx = Math.hypot(ctm[0], ctm[1]);
    const sy = Math.hypot(ctm[2], ctm[3]);
    draws.push({ w: Math.round(sx * 1000) / 1000, h: Math.round(sy * 1000) / 1000, x: Math.round(ctm[4]), y: Math.round(ctm[5]) });
  }
}
return { size: [page.getWidth(), page.getHeight()], draws, stream: contents };

